window.DAILY_ENGLISH_EXPRESSIONS=[{"id":"idiom_0001","en":"by/in leaps and bounds","definition":"very quickly; at a rapid pace or rate, especially in terms of progress or improvement.","ko":"아주 빠르게, 특히 발전이나 개선이 빠른 속도로 진행됨.","cefr":"B2","type":"idiom"},{"id":"idiom_0002","en":"get a move on","definition":"hurry (often used as an order)","ko":"서둘러(명령으로 자주 사용됨)","cefr":"B2","type":"idiom"},{"id":"idiom_0003","en":"be on the run","definition":"try to avoid being caught (especially by the police)","ko":"잡히지 않으려고 도망치다 (특히 경찰에게서)","cefr":"B2","type":"idiom"},{"id":"idiom_0004","en":"fast and furious","definition":"full of speed and excitement","ko":"속도감과 긴장감이 넘치는","cefr":"B2","type":"idiom"},{"id":"idiom_0005","en":"step by step","definition":"slowly; gradually, progressing in small stages rather than all at once.","ko":"천천히; 점진적으로, 한 번에 다 하지 않고 조금씩 나아가는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0006","en":"drag your feet/heels","definition":"To deal with something slowly or delay taking action because you don’t really want to do it.","ko":"내키지 않아 일부러 천천히 하거나 미루다","cefr":"B2","type":"idiom"},{"id":"idiom_0007","en":"the word spread","definition":"the news went from one person to the next","ko":"소식이 사람들 사이에 퍼졌다","cefr":"B2","type":"idiom"},{"id":"idiom_0008","en":"keep track","definition":"continue to know what is happening to someone or something","ko":"누구나 무엇에 대해 무슨 일이 일어나는지 계속 알아차리다","cefr":"B2","type":"idiom"},{"id":"idiom_0009","en":"get off to a flying start","definition":"To begin an activity, project, or event very successfully or with a lot of momentum.","ko":"어떤 활동이나 프로젝트, 이벤트를 매우 성공적이거나 강한 추진력으로 시작하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0010","en":"on the spot","definition":"immediately or in the place where something is happening or has just happened","ko":"즉시 또는 일이 일어난 그 자리에서","cefr":"B2","type":"idiom"},{"id":"idiom_0011","en":"all over the place","definition":"in or to many places; scattered or disorganized","ko":"여기저기에; 흩어져 있거나 정돈되지 않은 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0012","en":"left, right and centre","definition":"happening in a lot of places or to a lot of people","ko":"많은 곳에서, 많은 사람들에게 일어남","cefr":"B2","type":"idiom"},{"id":"idiom_0013","en":"reach / be at fever pitch","definition":"(used of emotions) to get so strong that people can’t control them","ko":"감정이 너무 강해져서 통제할 수 없게 됨","cefr":"B2","type":"idiom"},{"id":"idiom_0014","en":"be in full swing","definition":"to be at the most lively or active stage; when an event or activity is happening with maximum energy and participation.","ko":"가장 활기차거나 활동적인 단계에 있다; 행사나 활동이 최대의 에너지와 참여로 진행되고 있을 때.","cefr":"B2","type":"idiom"},{"id":"idiom_0015","en":"get/go beyond a joke","definition":"To become so serious or problematic that it is no longer funny or acceptable.","ko":"너무 심각하거나 문제가 돼서 더 이상 웃을 수 없는 상황.","cefr":"B2","type":"idiom"},{"id":"idiom_0016","en":"roll up your sleeves","definition":"to get ready to work hard, usually by preparing to tackle a difficult task or situation.","ko":"어려운 과제나 상황에 대비해 본격적으로 열심히 일할 준비를 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0017","en":"come at the drop of a hat","definition":"To do something immediately, without any hesitation or delay.","ko":"망설임이나 지체 없이 즉시 어떤 일을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0018","en":"have big shoes to fill","definition":"to try to do your job as well as the person who did it before you; especially when that person was very successful","ko":"특히 전임자가 매우 성공적이었을 때, 그만큼 잘 하려고 노력하다","cefr":"B2","type":"idiom"},{"id":"idiom_0019","en":"wear lots of different hats","definition":"to do many different roles or tasks","ko":"다양한 역할이나 업무를 맡다","cefr":"B2","type":"idiom"},{"id":"idiom_0020","en":"have it in the bag","definition":"to be in a situation where you are certain to succeed","ko":"성공이 확실한 상황에 있다","cefr":"B2","type":"idiom"},{"id":"idiom_0021","en":"bored the pants off","definition":"was extremely boring","ko":"정말 지루했다","cefr":"B2","type":"idiom"},{"id":"idiom_0022","en":"wears the trousers","definition":"is the person who makes decisions or is in control in a relationship, especially in a family or couple.","ko":"관계에서, 특히 가족이나 부부 관계에서 결정권을 가지고 주도하는 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_0023","en":"keep your shirt on","definition":"Don’t get angry or upset; stay calm and patient.","ko":"화내거나 흥분하지 말고 침착하고 인내심을 가져라.","cefr":"B2","type":"idiom"},{"id":"idiom_0024","en":"take my hat off to her","definition":"To express admiration or respect for her achievements or actions.","ko":"그녀의 성취나 행동에 대해 감탄이나 존경을 표하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0025","en":"give you the shirt off his back","definition":"is willing to do anything to help another person, even at their own expense","ko":"자신을 희생해서라도 기꺼이 남을 도와주는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0026","en":"in pocket","definition":"having more money than when you started","ko":"처음보다 돈이 더 있는 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0027","en":"out of pocket","definition":"having less money than when you started","ko":"처음보다 돈이 더 적게 남은 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0028","en":"pocketed","definition":"to take money from someone in a dishonest way","ko":"부정직한 방법으로 남의 돈을 가져가다","cefr":"B2","type":"idiom"},{"id":"idiom_0029","en":"dig deep into his pockets","definition":"to spend a lot of money, or give a lot of money away","ko":"많은 돈을 쓰거나 아낌없이 내다","cefr":"B2","type":"idiom"},{"id":"idiom_0030","en":"the salt of the earth","definition":"a very good and honest person","ko":"아주 선하고 정직한 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0031","en":"go to the ends of the earth","definition":"To do anything possible or make any effort necessary, no matter how difficult, to achieve something or help someone.","ko":"무슨 수를 써서라도, 아무리 힘들어도 무언가를 이루거나 누군가를 돕기 위해 최선을 다하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0032","en":"run to ground","definition":"discovered after a lot of searching","ko":"오랜 수색 끝에 발견된","cefr":"B2","type":"idiom"},{"id":"idiom_0033","en":"fall on stony ground","definition":"To be ignored, disregarded, or have no effect, especially when referring to advice, requests, or ideas.","ko":"특히 조언이나 요청, 아이디어가 무시되거나 아무런 효과가 없는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0034","en":"pluck a number out of the air","definition":"To choose or give a number or figure without any real basis, often just guessing or inventing it.","ko":"실제 근거 없이 아무 숫자나 그냥 추측하거나 즉석에서 만드는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0035","en":"blow hot and cold","definition":"Sometimes seem to like someone or something and sometimes don’t, so that others are confused about how they really feel.","ko":"어떤 사람이나 사물을 때로는 좋아하고 때로는 그렇지 않아, 다른 사람들이 그들의 진짜 감정을 헷갈려 함.","cefr":"B2","type":"idiom"},{"id":"idiom_0036","en":"get wind of something","definition":"hear information that others hoped to keep secret","ko":"남들이 비밀로 하고 싶었던 정보를 알게 되다","cefr":"B2","type":"idiom"},{"id":"idiom_0037","en":"see how / which way the wind is blowing","definition":"To observe how a situation is developing before making a decision or taking action.","ko":"결정이나 행동을 취하기 전에 상황이 어떻게 전개되는지 지켜보다.","cefr":"B2","type":"idiom"},{"id":"idiom_0038","en":"playing with fire","definition":"doing something that could be dangerous","ko":"위험할 수 있는 일을 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0039","en":"spreading like wildfire","definition":"Going around or becoming known very quickly and widely, often uncontrollably.","ko":"아주 빠르고 널리, 통제할 수 없이 퍼지는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0040","en":"in the heat of the moment","definition":"To do or say something impulsively, without thinking, because you are overwhelmed by strong emotions such as anger or excitement.","ko":"분노나 흥분 등 강한 감정에 휩싸여 충동적으로 말하거나 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0041","en":"there’s no smoke without fire","definition":"If people are saying something is true and you don’t know whether it is true or not, it probably is true.","ko":"많은 사람이 말하면, 뭔가 사실이 있을 때가 많다.","cefr":"B2","type":"idiom"},{"id":"idiom_0042","en":"add fuel to the flames/fire","definition":"do something to make a bad situation worse","ko":"상황을 악화시키다, 불에 기름을 붓다","cefr":"B2","type":"idiom"},{"id":"idiom_0043","en":"in deep water","definition":"in a difficult situation which is hard to deal with","ko":"감당하기 힘든 어려운 상황에 있는","cefr":"B2","type":"idiom"},{"id":"idiom_0044","en":"out of your depth","definition":"in a situation that you do not have the knowledge or skills to deal with","ko":"지식이나 능력이 부족해 감당하기 힘든 상황에 처한","cefr":"B2","type":"idiom"},{"id":"idiom_0045","en":"jump / throw someone in at the deep end","definition":"To do something or make someone do something difficult without being given or giving them any help or preparation.","ko":"아무런 도움이나 준비 없이 어려운 일을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0046","en":"in hot water","definition":"in a situation where people are angry with you or you are in trouble, especially because of something you have done.","ko":"무언가 잘못해서 곤경이나 난처한 상황에 처하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0047","en":"be between the devil and the deep blue sea","definition":"To be in a situation where you have to choose between two equally difficult or unpleasant options.","ko":"두 가지 모두 어려운 또는 불쾌한 선택지 사이에서 선택을 해야 하는 상황에 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0048","en":"be a drop in the ocean","definition":"be a very small amount in comparison to what is needed","ko":"필요한 것에 비해 아주 적은 양임","cefr":"B2","type":"idiom"},{"id":"idiom_0049","en":"kill two birds with one stone","definition":"to achieve two things with a single action","ko":"일석이조","cefr":"B2","type":"idiom"},{"id":"idiom_0050","en":"let the cat out of the bag","definition":"to reveal a secret, often by accident","ko":"비밀을 무심코 누설하다","cefr":"B2","type":"idiom"},{"id":"idiom_0051","en":"drive/send sb round the bend","definition":"to make someone very annoyed or frustrated","ko":"누군가를 매우 짜증나고 화나게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0052","en":"feel it in my bones","definition":"to sense or feel something instinctively, without needing proof","ko":"증거 없이 본능적으로 무언가를 느끼다","cefr":"B2","type":"idiom"},{"id":"idiom_0053","en":"loud and clear","definition":"clearly and very definitely; easy to understand without any ambiguity.","ko":"아주 명확하고 확실하게; 혼동의 여지가 없이 쉽게 이해됨.","cefr":"B2","type":"idiom"},{"id":"idiom_0054","en":"speak your mind","definition":"state your opinion very clearly and openly","ko":"자신의 의견을 분명하고 솔직하게 밝히다","cefr":"B2","type":"idiom"},{"id":"idiom_0055","en":"matter-of-fact","definition":"without any feeling or emotion; showing no emotion when describing something, especially something surprising or upsetting.","ko":"감정 없이; 놀랍거나 속상한 일을 {담담하게}, 감정 없이 이야기하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0056","en":"won’t take no for an answer","definition":"refuses to accept refusal","ko":"거절을 받아들이지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_0057","en":"get a word in edgeways","definition":"manage to say something in a conversation","ko":"대화 중에 말할 기회를 얻다","cefr":"B2","type":"idiom"},{"id":"idiom_0058","en":"beside the point","definition":"not relevant to the subject you are talking about","ko":"이야기하고 있는 주제와 관련이 없음","cefr":"B2","type":"idiom"},{"id":"idiom_0059","en":"missed the point","definition":"failed to understand the main thing","ko":"핵심을 이해하지 못하다","cefr":"B2","type":"idiom"},{"id":"idiom_0060","en":"doesn’t know the meaning of the word","definition":"It is pointless to talk to someone about a certain quality or behavior because it is not in their character; they are completely unfamiliar with it.","ko":"누군가에게 그 사람과는 전혀 관련 없는 성향이나 행동에 대해 말해봤자 소용없다.","cefr":"B2","type":"idiom"},{"id":"idiom_0061","en":"word for word","definition":"using exactly the same words as were originally spoken or written; verbatim.","ko":"바꾸지 않고 똑같이, 한 글자도 다르지 않게라는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_0062","en":"small/fine print","definition":"the rules, restrictions, and conditions, which are often written in very small letters, especially in contracts or agreements, and may contain important information that is easy to overlook.","ko":"계약서 등에서 아주 작은 글씨로 쓰여 있어 놓치기 쉬운, 중요한 규정과 조건.","cefr":"B2","type":"idiom"},{"id":"idiom_0063","en":"a tall order","definition":"a task, request, or favor that is difficult to accomplish or is unreasonable to expect.","ko":"달성하기 어렵거나 무리한 과제나 부탁.","cefr":"B2","type":"idiom"},{"id":"idiom_0064","en":"a matter of opinion","definition":"Something that people can have different opinions about; it suggests that the answer or viewpoint is subjective and not universally agreed upon.","ko":"사람마다 의견이 다를 수 있는 것; 주관적인 문제임을 나타냄","cefr":"B2","type":"idiom"},{"id":"idiom_0065","en":"a question mark (hanging) over","definition":"Nobody knows if it will continue to exist or not; there is uncertainty about the future or outcome of something.","ko":"계속 존재할지 아무도 모른다; 미래나 결과에 대한 불확실성이 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0066","en":"lingua franca","definition":"a language used for day-to-day public communication, which is not the speakers’ own language","ko":"사용자의 모국어가 아닌, 일상적으로 쓰이는 공용어","cefr":"B2","type":"idiom"},{"id":"idiom_0067","en":"wouldn't go amiss","definition":"Would be very useful or welcome; something that is needed or would improve the situation.","ko":"매우 유용하거나 환영받을 것; 상황을 개선하거나 필요한 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0068","en":"if push comes to shove","definition":"If the situation becomes very difficult or desperate, this is what I can do or what will happen.","ko":"상황이 정말 어렵거나 절박해지면, 이것이 내가 할 수 있는 일 또는 일어날 일이다.","cefr":"B2","type":"idiom"},{"id":"idiom_0069","en":"if need be","definition":"if it is really necessary; if there is no other option; if required.","ko":"필요하다면; 다른 선택지가 없다면.","cefr":"B2","type":"idiom"},{"id":"idiom_0070","en":"duty bound","definition":"Feeling morally or legally obligated to do something; believing that it is your responsibility to act.","ko":"도덕적 또는 법적으로 무언가를 해야 한다는 의무감을 느끼다; 자신이 행동해야 할 책임이 있다고 믿는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0071","en":"need like I need a hole in the head","definition":"I don’t need it at all, and don’t want it","ko":"전혀 필요 없고, 원하지도 않는다","cefr":"B2","type":"idiom"},{"id":"idiom_0072","en":"dying to","definition":"really looking forward to or wanting something very much","ko":"무언가를 정말 간절히 고대하거나 매우 원하다","cefr":"B2","type":"idiom"},{"id":"idiom_0073","en":"wouldn't be seen dead","definition":"would never do something (because you dislike it very much or think it is not appropriate)","ko":"매우 싫어하거나 적절하지 않다고 생각해서 절대 하지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_0074","en":"do my own thing","definition":"do what I want without worrying about what others think","ko":"남의 시선을 신경 쓰지 않고 내가 하고 싶은 대로 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0075","en":"give anything","definition":"Be willing to do anything or make any sacrifice to achieve or obtain something.","ko":"무엇이든 하거나 어떤 희생도 감수할 각오가 되어 있는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0076","en":"in keeping with","definition":"appropriate or consistent with","ko":"…에 부합하는, …와 일치하는","cefr":"B2","type":"idiom"},{"id":"idiom_0077","en":"wouldn't touch it with a barge pole","definition":"would never consider or get involved with something","ko":"절대 고려하거나 관여하지 않을 것","cefr":"B2","type":"idiom"},{"id":"idiom_0078","en":"you're in luck","definition":"said when you get something good that you were not expecting","ko":"예상치 못한 좋은 일이 생겼을 때 하는 말","cefr":"B2","type":"idiom"},{"id":"idiom_0079","en":"not worth my while","definition":"Doing something is not beneficial or rewarding enough to justify the time or effort required.","ko":"무언가를 하는 것이 시간이나 노력을 들일 만큼 가치 있지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_0080","en":"take your pick","definition":"choose whichever you want","ko":"원하는 것을 고르다","cefr":"B2","type":"idiom"},{"id":"idiom_0081","en":"has seen better days","definition":"is old and not working so well","ko":"오래되어서 잘 작동하지 않는다","cefr":"B2","type":"idiom"},{"id":"idiom_0082","en":"out of date","definition":"old and not useful or correct any more","ko":"낡고 더 이상 쓸모없거나 올바르지 않은","cefr":"B2","type":"idiom"},{"id":"idiom_0083","en":"making up for lost time","definition":"Doing now what you did not have the opportunity to do previously; trying to catch up on missed experiences or opportunities.","ko":"예전에 놓친 경험이나 기회를 지금 만회하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0084","en":"since/from the year dot","definition":"from the very beginning; for as long as anyone can remember; since a very long time ago.","ko":"아주 오래전부터; 예전부터 쭉.","cefr":"B2","type":"idiom"},{"id":"idiom_0085","en":"be the shape of things to come","definition":"an indication of what is likely to become popular or standard in the future","ko":"미래에 인기를 끌거나 표준이 될 것으로 예상되는 징후","cefr":"B2","type":"idiom"},{"id":"idiom_0086","en":"for the time being","definition":"temporarily; for now; until something changes or a permanent solution is found","ko":"임시로; 당분간; 변하거나 영구적인 해결책이 생길 때까지","cefr":"B2","type":"idiom"},{"id":"idiom_0087","en":"on the threshold of","definition":"something is likely to happen very soon","ko":"무엇인가 곧 일어날 것이다","cefr":"B2","type":"idiom"},{"id":"idiom_0088","en":"in the short/medium/long term","definition":"for a short, medium, or long period of time in the future; considering the effects or results over a specified duration.","ko":"미래의 짧거나 중간, 또는 긴 기간 동안을 두고; 특정 기간의 영향이나 결과를 고려하여.","cefr":"B2","type":"idiom"},{"id":"idiom_0089","en":"only a matter of time","definition":"It will definitely happen, even though we cannot say exactly when.","ko":"반드시 일어나지만, 정확히 언제인지 모른다는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_0090","en":"early days yet","definition":"It’s too soon to say or decide; the outcome is not clear because not enough time has passed.","ko":"아직 말하거나 결정하기에는 너무 이르다; 시간이 충분히 지나지 않아 결과가 명확하지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_0091","en":"in the long run","definition":"a long time from now; eventually, after a long period has passed","ko":"장기적으로 보면; 오랜 시간이 지난 후에","cefr":"B2","type":"idiom"},{"id":"idiom_0092","en":"like there’s no tomorrow","definition":"To do something eagerly, intensely, or very quickly, as if there is no future or no chance to do it again.","ko":"두 번 다시 기회가 없는 것처럼 열정적으로 또는 빠르게 무언가를 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0093","en":"as if there was/were no tomorrow","definition":"To do something eagerly, quickly, or with great intensity, as though it is the last chance to do it.","ko":"마치 이번이 마지막인 것처럼 매우 열정적이거나 빠르게 무언가를 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0094","en":"at the end of the day","definition":"something you say before stating a very important fact or idea","ko":"아주 중요한 사실이나 생각을 말하기 전에 쓰는 표현","cefr":"B2","type":"idiom"},{"id":"idiom_0095","en":"a sign of the times","definition":"something that shows that society now is worse than it was in the past","ko":"사회가 예전보다 나빠졌다는 것을 보여주는 현상","cefr":"B2","type":"idiom"},{"id":"idiom_0096","en":"drive someone round the bend","definition":"to make someone very annoyed, frustrated, or angry, often because of repeated or irritating behavior.","ko":"반복적이거나 짜증나는 행동 때문에 누군가를 매우 짜증나게 하거나 화나게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0097","en":"in the blink of an eye","definition":"in an extremely short time","ko":"눈 깜짝할 사이에","cefr":"B2","type":"idiom"},{"id":"idiom_0098","en":"a bone of contention","definition":"something which people argue and disagree over","ko":"사람들이 다투거나 의견이 갈리는 문제","cefr":"B2","type":"idiom"},{"id":"idiom_0099","en":"as dry as a bone","definition":"very dry indeed","ko":"물기 하나 없이 완전히 마르다.","cefr":"B2","type":"idiom"},{"id":"idiom_0100","en":"rough and ready","definition":"crude and lacking sophistication","ko":"조잡하고 세련되지 않은","cefr":"B2","type":"idiom"},{"id":"idiom_0101","en":"cool, calm and collected","definition":"relaxed, in control, not nervous","ko":"침착하고, 통제하며, 긴장하지 않음","cefr":"B2","type":"idiom"},{"id":"idiom_0102","en":"to cut a long story short","definition":"to tell the main points, but not all the fine details","ko":"주요 요점만 말하고 세부 내용은 생략하는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0103","en":"pass the buck","definition":"to shift responsibility or blame to someone else instead of accepting it oneself.","ko":"책임이나 잘못을 자신이 아닌 다른 사람에게 넘기다.","cefr":"B2","type":"idiom"},{"id":"idiom_0104","en":"buck-passing","definition":"the act of blaming someone else or refusing to accept responsibility","ko":"다른 사람에게 책임을 전가하거나 책임을 지지 않으려는 행동","cefr":"B2","type":"idiom"},{"id":"idiom_0105","en":"give me a hard/rough/tough time","definition":"To make things difficult, unpleasant, or challenging for someone, often by criticizing, teasing, or causing trouble.","ko":"누군가에게 일이 어렵거나 불쾌하게 만들거나, 주로 비판하거나 괴롭혀서 곤란하게 한다.","cefr":"B2","type":"idiom"},{"id":"idiom_0106","en":"makes all the difference (to something)","definition":"has a very good effect on a situation or a thing","ko":"상황이나 사물에 아주 큰 영향을 주다","cefr":"B2","type":"idiom"},{"id":"idiom_0107","en":"works/goes/runs like a dream","definition":"To function, operate, or proceed extremely well, smoothly, or successfully.","ko":"매우 잘, 순조롭게, 성공적으로 작동하거나 진행되다.","cefr":"B2","type":"idiom"},{"id":"idiom_0108","en":"works like magic","definition":"works immediately and very well indeed","ko":"즉시 효과가 나타나고 매우 잘 작동하다","cefr":"B2","type":"idiom"},{"id":"idiom_0109","en":"goes from strength to strength","definition":"gets better and better","ko":"점점 더 좋아지다, 연이어 성공하다","cefr":"B2","type":"idiom"},{"id":"idiom_0110","en":"does the trick","definition":"solves a problem very well","ko":"문제를 아주 잘 해결하다","cefr":"B2","type":"idiom"},{"id":"idiom_0111","en":"is the be-all-and-end-all (of something)","definition":"is the most important thing (often used in the negative: not the be-all-and-end-all)","ko":"가장 중요한 것 (보통 부정적으로 사용: 전부가 아니다)","cefr":"B2","type":"idiom"},{"id":"idiom_0112","en":"is / turns out to be a blessing in disguise","definition":"has a good effect even though at first it seemed it would be bad","ko":"처음엔 나쁜 일처럼 보여도 결국 좋은 결과를 가져옴","cefr":"B2","type":"idiom"},{"id":"idiom_0113","en":"someone/something is a victim of their/its own success","definition":"Their or its success has negative effects as well as or instead of positive ones.","ko":"성공이 부정적인 결과를 낳기도 함을 뜻함.","cefr":"B2","type":"idiom"},{"id":"idiom_0114","en":"someone doesn’t have the ghost of a chance (of doing something)","definition":"They have no chance at all; it is extremely unlikely or impossible for them to succeed.","ko":"그들에게는 전혀 가능성이 없다; 성공할 가망이 극히 희박하거나 불가능하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0115","en":"someone/something gives up the ghost","definition":"To stop working, functioning, or trying, often because of exhaustion, failure, or the realization that success is impossible.","ko":"지쳐서, 실패해서, 혹은 성공이 불가능하다고 느껴 더 이상 일하거나 시도하지 않게 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_0116","en":"someone/something leaves their/its mark (on someone/something)","definition":"They have or it has an effect (usually negative) that changes someone or something forever.","ko":"영원히 누군가나 무언가를 바꿔 놓는 (보통 부정적인) 영향을 끼쳤다.","cefr":"B2","type":"idiom"},{"id":"idiom_0117","en":"would go places","definition":"would be successful; is likely to achieve great things or advance in life or career","ko":"성공할 것이다; 인생이나 경력에서 큰 성과를 낼 가능성이 크다","cefr":"B2","type":"idiom"},{"id":"idiom_0118","en":"hit the big time","definition":"To become very successful, especially on a national or international scale, often resulting in fame and wealth.","ko":"전국적 또는 국제적으로 매우 성공하여 명성과 부를 얻는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0119","en":"made a go of","definition":"been very successful with","ko":"성공을 거두다","cefr":"B2","type":"idiom"},{"id":"idiom_0120","en":"work against the clock","definition":"To work very quickly because there is a limited amount of time to complete something.","ko":"제한된 시간 안에 일을 끝내기 위해 매우 빠르게 일하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0121","en":"in no time at all","definition":"To do something very quickly; almost instantly.","ko":"아주 빠르게 무언가를 하다; 거의 즉시.","cefr":"B2","type":"idiom"},{"id":"idiom_0122","en":"call it a day","definition":"To decide to stop working on something, usually because enough has been done or it's time to finish.","ko":"충분히 했거나 마칠 시간이 되어 일을 멈추기로 결정하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0123","en":"haven't had a minute to call my own","definition":"To be extremely busy, with no free time for oneself.","ko":"너무 바빠서 자신을 위한 시간이 전혀 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_0124","en":"there and then (or then and there)","definition":"To do something immediately, without any delay, at that exact moment.","ko":"즉시, 지체 없이 어떤 일을 하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0125","en":"at the crack of dawn","definition":"start very early in the morning","ko":"아주 이른 아침에 시작하다","cefr":"B2","type":"idiom"},{"id":"idiom_0126","en":"once in a lifetime","definition":"never likely to happen again","ko":"다시 일어나기 힘든 일","cefr":"B2","type":"idiom"},{"id":"idiom_0127","en":"once in a blue moon","definition":"very rarely","ko":"아주 드물게","cefr":"B2","type":"idiom"},{"id":"idiom_0128","en":"once and for all","definition":"finally and definitely; to do something completely and decisively so that it does not have to be dealt with again","ko":"완전히, 단번에; 한 번에 확실하게 끝내서 다시는 다룰 필요가 없게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0129","en":"off and on / on and off","definition":"sometimes, but not regularly or continuously","ko":"가끔씩, 하지만 규칙적이거나 계속적으로는 아님","cefr":"B2","type":"idiom"},{"id":"idiom_0130","en":"from time to time","definition":"sometimes, but not regularly","ko":"가끔씩 하지만 정기적으로는 아님","cefr":"B2","type":"idiom"},{"id":"idiom_0131","en":"nine times out of ten","definition":"almost always; in nearly every case or situation","ko":"거의 항상; 거의 모든 경우에","cefr":"B2","type":"idiom"},{"id":"idiom_0132","en":"goes/works/runs like clockwork","definition":"happens exactly as planned and without problems","ko":"계획대로 완벽하게 진행되고 문제가 없음","cefr":"B2","type":"idiom"},{"id":"idiom_0133","en":"from scratch","definition":"to start from the very beginning, without using anything that already exists or any previous preparation.","ko":"아무것도 없는 상태에서 처음부터 시작하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0134","en":"put it down to experience","definition":"Learn from something bad that has happened instead of being upset by it.","ko":"일어난 나쁜 일을 슬퍼하기보다 교훈을 얻다.","cefr":"B2","type":"idiom"},{"id":"idiom_0135","en":"know where I stand","definition":"To understand your position or situation, especially in relation to someone else or a particular issue.","ko":"특정 상황이나 다른 사람과의 관계에서 자신의 위치나 상황을 이해하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0136","en":"get a kick out of something","definition":"to enjoy something very much or find it amusing","ko":"무언가를 아주 즐기거나 재미있어하다","cefr":"B2","type":"idiom"},{"id":"idiom_0137","en":"learnt my lesson","definition":"To realize, usually after a negative experience, that you should not repeat the same mistake.","ko":"대개 부정적인 경험 후에 같은 실수를 반복하면 안 된다는 것을 깨닫다.","cefr":"B2","type":"idiom"},{"id":"idiom_0138","en":"teach him/her a lesson","definition":"To punish or show someone the consequences of their actions so that they will not repeat the same mistake.","ko":"다시는 같은 실수를 반복하지 않도록 누군가를 벌하거나 결과를 보여주다.","cefr":"B2","type":"idiom"},{"id":"idiom_0139","en":"got the message","definition":"someone finally becomes aware of a fact (often used with unpleasant facts)","ko":"누군가 마침내 사실을 깨닫다 (주로 불쾌한 사실)","cefr":"B2","type":"idiom"},{"id":"idiom_0140","en":"set/put the record straight","definition":"Tell the true facts to someone who has believed a different set of facts up to that moment.","ko":"다른 사실을 믿고 있던 이에게 진실을 바로잡아주다.","cefr":"B2","type":"idiom"},{"id":"idiom_0141","en":"heard it on/through the grapevine","definition":"To hear news or information indirectly, often through gossip or rumors, rather than from an official or direct source.","ko":"소문이나 풍문 등 공식적이거나 직접적인 출처가 아닌 간접적으로 소식을 듣다.","cefr":"B2","type":"idiom"},{"id":"idiom_0142","en":"a figment of your imagination","definition":"something you have imagined which is not true","ko":"상상에 불과한, 실제로 존재하지 않는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0143","en":"lost sight of","definition":"forgotten a central, important fact or truth about something","ko":"어떤 일에 대해 중요한 사실이나 본질을 잊어버리다","cefr":"B2","type":"idiom"},{"id":"idiom_0144","en":"what beats me","definition":"what I cannot understand","ko":"이해할 수 없는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0145","en":"having second thoughts about","definition":"Decided something, but now am no longer sure about it.","ko":"결정했지만 다시 망설이거나 확신이 없어짐","cefr":"B2","type":"idiom"},{"id":"idiom_0146","en":"the ins and outs of","definition":"the details of something; all the intricacies or specific information about how something works or is done.","ko":"어떤 일의 모든 세부사항과 작동 방식.","cefr":"B2","type":"idiom"},{"id":"idiom_0147","en":"make it big","definition":"To achieve great success or become famous, especially in one's career or chosen field.","ko":"특히 자신의 분야에서 큰 성공을 거두거나 유명해지다.","cefr":"B2","type":"idiom"},{"id":"idiom_0148","en":"make a big thing of","definition":"To treat something as very important or special, often by celebrating it or giving it a lot of attention.","ko":"어떤 일을 매우 중요하거나 특별하게 여기고, 종종 축하하거나 많은 관심을 주는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0149","en":"think big","definition":"have ambitious plans and ideas, and be keen to achieve a lot","ko":"야심찬 계획과 아이디어를 가지고 많은 것을 이루고자 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0150","en":"big deal","definition":"Said when something happens but you are not impressed or excited, even if others are.","ko":"다른 사람들은 감탄하거나 기대할 일이라도 당신은 별로 감흥이 없을 때 쓰는 표현.","cefr":"B2","type":"idiom"},{"id":"idiom_0151","en":"larger than life","definition":"Much more exciting and interesting than average people; having a personality or appearance that is very impressive or exaggerated.","ko":"평범한 사람들보다 훨씬 더 흥미롭고 인상적인; 아주 독특하거나 과장된 성격 또는 외모를 가진.","cefr":"B2","type":"idiom"},{"id":"idiom_0152","en":"looms large","definition":"Said of something which could happen and which is a huge worry for people.","ko":"언젠가 일어날 수 있고 사람들에게 큰 걱정거리가 되는 것을 말함.","cefr":"B2","type":"idiom"},{"id":"idiom_0153","en":"budge an inch","definition":"To change one's position or opinion even a little bit; to yield or compromise, even slightly.","ko":"자신의 입장이나 의견을 조금도 바꾸지 않다; 조금도 양보하거나 타협하지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_0154","en":"miles away","definition":"not concentrating, but thinking about something else","ko":"딴생각을 하다, 정신이 딴 데 있다","cefr":"B2","type":"idiom"},{"id":"idiom_0155","en":"see/spot that a mile off","definition":"It's very easy to see or recognize; something is extremely obvious.","ko":"아주 쉽게 보이거나 인식된다; 매우 명백한 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0156","en":"sticks/stands out a mile","definition":"It's very easy to see or is extremely obvious.","ko":"아주 눈에 띄거나 너무나 뚜렷하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0157","en":"a far cry from","definition":"very different from","ko":"~와는 완전히 다르다","cefr":"B2","type":"idiom"},{"id":"idiom_0158","en":"in small doses","definition":"You like someone or something, but only for short periods of time; too much of them can be overwhelming or annoying.","ko":"누군가나 무언가를 좋아하지만, 너무 오래나 많이 함께하면 부담스럽거나 짜증날 수 있다는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_0159","en":"a small fortune","definition":"a huge amount of money","ko":"생각보다 아주 많은 돈","cefr":"B2","type":"idiom"},{"id":"idiom_0160","en":"in all shapes and sizes","definition":"a wide variety of types, forms, or sizes; used to emphasize diversity.","ko":"다양한 종류, 형태, 크기; 다양성을 강조할 때 사용.","cefr":"B2","type":"idiom"},{"id":"idiom_0161","en":"an unknown quantity","definition":"A person or thing whose abilities, qualities, or potential are not yet known or have not been revealed.","ko":"능력이나 가능성이 아직 드러나지 않은 사람이나 사물","cefr":"B2","type":"idiom"},{"id":"idiom_0162","en":"taking the law into their own hands","definition":"taking action which should be taken by the police or the courts","ko":"경찰이나 법원 대신 스스로 법을 집행하다","cefr":"B2","type":"idiom"},{"id":"idiom_0163","en":"have become a law unto themselves","definition":"are completely out of control and simply ignore the law","ko":"통제에서 완전히 벗어나 법을 무시하다","cefr":"B2","type":"idiom"},{"id":"idiom_0164","en":"lay down the law","definition":"To be very firm and clear about rules or expectations, and to enforce them strictly.","ko":"규칙이나 기대에 대해 매우 단호하고 명확하게 하고 엄격히 지키게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0165","en":"bending the rules","definition":"making special exceptions; letting some people disobey the rules/laws","ko":"특별히 예외를 두다; 일부 사람들에게 규칙이나 법을 어기게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0166","en":"carry the can","definition":"accept the blame or responsibility alone, even though other people were also responsible","ko":"다른 사람들도 책임이 있음에도 혼자서 책임이나 비난을 짊어지다","cefr":"B2","type":"idiom"},{"id":"idiom_0167","en":"get / let someone off the hook","definition":"To be freed or to free someone from responsibility, blame, or a difficult situation.","ko":"책임이나 비난, 어려운 상황에서 벗어나게 해주다.","cefr":"B2","type":"idiom"},{"id":"idiom_0168","en":"leave someone to their own devices","definition":"Allow someone to act independently, without supervision or interference.","ko":"누군가를 간섭이나 감독 없이 독립적으로 하게 두다.","cefr":"B2","type":"idiom"},{"id":"idiom_0169","en":"are at/on the receiving end (of something, for example, a person’s anger/criticism)","definition":"To be the person who suffers from or is the target of someone else's anger, criticism, or other negative actions.","ko":"다른 사람의 화, 비난, 부정적인 행동의 대상이 되는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0170","en":"are at someone’s beck and call","definition":"do everything they tell you to do, whenever they tell you to do it","ko":"시키는 대로 언제든지 다 해준다","cefr":"B2","type":"idiom"},{"id":"idiom_0171","en":"get your own way","definition":"persuade other people to let you do what you want","ko":"자신이 원하는 대로 하도록 다른 사람을 설득하다","cefr":"B2","type":"idiom"},{"id":"idiom_0172","en":"go to the polls","definition":"vote in a general election","ko":"총선거에서 투표하다","cefr":"B2","type":"idiom"},{"id":"idiom_0173","en":"spin doctors","definition":"public relations officers who meet the press/media and present events in a way that suits them","ko":"자신들에게 유리하게 사건을 포장해 언론에 알리는 홍보 전문가","cefr":"B2","type":"idiom"},{"id":"idiom_0174","en":"hidden agenda","definition":"An undisclosed plan or motive behind someone's actions, often implying deceit or manipulation.","ko":"누군가의 행동 뒤에 숨겨진 계획이나 의도, 종종 속임수나 조작을 암시함.","cefr":"B2","type":"idiom"},{"id":"idiom_0175","en":"I've come up against a brick wall.","definition":"Something is blocking me from doing what I want to do.","ko":"무언가가 내가 하고 싶은 것을 방해하고 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0176","en":"I put my foot in it.","definition":"Said something tactless and embarrassing.","ko":"눈치 없거나 민망한 말을 했다.","cefr":"B2","type":"idiom"},{"id":"idiom_0177","en":"I'm in dire straits.","definition":"In a very difficult or dangerous situation.","ko":"매우 어렵거나 위험한 상황에 처한 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0178","en":"I've dug myself into a hole.","definition":"Have myself caused a problem that will be difficult to escape from (informal).","ko":"스스로 빠져나오기 힘든 문제를 자초하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0179","en":"I've spread myself too thin.","definition":"Am trying to do too many things at the same time, with the result that I can't give any of them the attention they need.","ko":"동시에 너무 많은 일을 하려고 해서 어느 하나에도 제대로 집중할 수 없는 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_0180","en":"I've been left holding the baby.","definition":"Others have left me to deal with a problem alone.","ko":"다른 사람들이 나를 남겨두고 문제를 혼자 떠맡게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0181","en":"They've got me over a barrel.","definition":"They have put me in a situation where I have no choice or control over what I can do.","ko":"제가 선택권이나 통제권이 없는 상황에 놓이게 되었습니다.","cefr":"B2","type":"idiom"},{"id":"idiom_0182","en":"I'm clutching at straws now.","definition":"Am in such a difficult situation that I will try anything.","ko":"너무 어려운 상황이라 뭐든 시도한다.","cefr":"B2","type":"idiom"},{"id":"idiom_0183","en":"I've drawn a blank.","definition":"Am unable to find information or to achieve something I'd hoped for.","ko":"정보를 찾지 못하거나 바랐던 것을 이루지 못함.","cefr":"B2","type":"idiom"},{"id":"idiom_0184","en":"face the music","definition":"Accept criticism or punishment for what you have done.","ko":"자신이 한 일에 대한 비판이나 벌을 감수하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0185","en":"Fact of life","definition":"An unpleasant situation which has to be accepted because it cannot be changed.","ko":"바꿀 수 없어 받아들여야 하는 불쾌한 상황.","cefr":"B2","type":"idiom"},{"id":"idiom_0186","en":"Easier said than done","definition":"Something you say when something seems like a good idea, but is difficult to actually do.","ko":"말은 쉽지 행동은 어렵다","cefr":"B2","type":"idiom"},{"id":"idiom_0187","en":"fed up (to the back teeth)","definition":"very annoyed or bored with something that has been happening for a long time","ko":"오랫동안 계속된 일에 매우 짜증나거나 지겨운 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0188","en":"at my wits' end","definition":"So worried, confused, or annoyed that you do not know what to do next.","ko":"너무 걱정하거나 혼란스럽거나 짜증나서 다음에 무엇을 해야 할지 모르는 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0189","en":"had it up to here","definition":"Have reached the limit of your patience or endurance with something.","ko":"더 이상 참을 수 없는 상태에 이르다.","cefr":"B2","type":"idiom"},{"id":"idiom_0190","en":"have/throw a fit","definition":"react very angrily","ko":"매우 화나게 반응하다","cefr":"B2","type":"idiom"},{"id":"idiom_0191","en":"go off the deep end","definition":"suddenly become very angry or emotional","ko":"갑자기 매우 화를 내거나 감정적으로 변하다","cefr":"B2","type":"idiom"},{"id":"idiom_0192","en":"go spare","definition":"to become very angry or lose one's temper","ko":"몹시 화가 나서 통제 못 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0193","en":"do his nut","definition":"become very angry","ko":"몹시 화나다","cefr":"B2","type":"idiom"},{"id":"idiom_0194","en":"blow a fuse","definition":"suddenly become very angry","ko":"갑자기 몹시 화를 내다","cefr":"B2","type":"idiom"},{"id":"idiom_0195","en":"if someone's blood is up","definition":"They are very angry and may react in a violent way.","ko":"아주 화가 나서 폭력적으로 반응할 수 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0196","en":"after someone's blood","definition":"want to catch someone in order to hurt or punish them","ko":"누군가를 잡아서 혼내거나 해치고 싶어함","cefr":"B2","type":"idiom"},{"id":"idiom_0197","en":"out for blood","definition":"determined to find someone to attack or blame for something bad that has happened","ko":"누군가를 탓하거나 공격하려는 마음이 불타 있다","cefr":"B2","type":"idiom"},{"id":"idiom_0198","en":"drive someone up the wall","definition":"To make someone very angry, irritated, or sometimes extremely bored.","ko":"누군가를 매우 화나게 하거나 짜증나게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0199","en":"drive/send someone round the bend/twist","definition":"To make someone very angry, annoyed, or sometimes extremely bored.","ko":"누군가를 매우 화나게 하거나 짜증나게 하거나 지루하게 만들다.","cefr":"B2","type":"idiom"},{"id":"idiom_0200","en":"rub someone up the wrong way","definition":"To annoy or irritate someone, often unintentionally.","ko":"누군가를 종종 의도치 않게 짜증나게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0201","en":"get/put someone's back up","definition":"To make someone annoyed or irritated.","ko":"누군가를 짜증나게 하거나 화나게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0202","en":"ruffle someone's feathers","definition":"To make someone annoyed or upset, often by disturbing their routine or offending them.","ko":"누군가의 기분을 상하게 하거나 불쾌하게 만들다, 종종 그들의 일상을 방해하거나 불쾌하게 하는 경우.","cefr":"B2","type":"idiom"},{"id":"idiom_0203","en":"put/send the cat among the pigeons","definition":"To do or say something that causes a lot of people to become angry, worried, or agitated.","ko":"많은 사람들을 화나게 하거나 불안하게 만드는 말을 하거나 행동을 함","cefr":"B2","type":"idiom"},{"id":"idiom_0204","en":"not be on speaking terms","definition":"be so angry with each other that they refuse to speak to each other","ko":"서로 너무 화가 나 말도 안 하는 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0205","en":"give someone an earful","definition":"Tell someone how angry you are with them, usually in a loud or forceful way (informal).","ko":"누군가에게 화가 났다는 것을 크고 강하게 표현하다","cefr":"B2","type":"idiom"},{"id":"idiom_0206","en":"give someone a piece of your mind","definition":"To angrily tell someone what you really think, especially to express your disapproval or annoyance.","ko":"불만이나 짜증을 강하게 표현하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0207","en":"You could’ve fooled me!","definition":"You do not believe what someone says about something that you saw or experienced yourself.","ko":"직접 보고 경험한 것과 다르게 누군가가 말할 때 믿지 않는다는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_0208","en":"There’s no accounting for taste(s)!","definition":"You can’t understand why someone likes or doesn’t like something.","ko":"누군가가 왜 어떤 것을 좋아하거나 싫어하는지 이해할 수 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_0209","en":"If all else fails","definition":"If all other plans do not work.","ko":"다른 모든 방법이 실패할 경우.","cefr":"B2","type":"idiom"},{"id":"idiom_0210","en":"The lesser of two evils","definition":"It is the less unpleasant of two bad options.","ko":"두 가지 나쁜 선택 중 덜 나쁜 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0211","en":"One thing just led to another","definition":"A series of events happened, each caused by the previous one.","ko":"이전 일 때문에 일련의 사건들이 연쇄적으로 일어남.","cefr":"B2","type":"idiom"},{"id":"idiom_0212","en":"I’ll never live it down!","definition":"You think that you have done something bad or embarrassing that people will never forget.","ko":"사람들이 절대 잊지 않을 부끄러운 일을 저질렀다고 생각한다.","cefr":"B2","type":"idiom"},{"id":"idiom_0213","en":"Strike while the iron is hot","definition":"Do something immediately while you have a good chance of success.","ko":"좋은 성공 기회가 있을 때 즉시 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0214","en":"One way or another","definition":"You are not sure exactly how yet, but it will happen.","ko":"어떻게 될지는 정확히 모르지만, 일어날 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_0215","en":"Over the top","definition":"More extreme than is necessary or appropriate.","ko":"필요하거나 적절한 수준보다 지나친.","cefr":"B2","type":"idiom"},{"id":"idiom_0216","en":"In your shoes","definition":"In your position; if I were you.","ko":"네 입장이라면; 내가 너라면.","cefr":"B2","type":"idiom"},{"id":"idiom_0217","en":"At the top of my agenda","definition":"The most important priority for me.","ko":"나에게 가장 중요한 우선순위.","cefr":"B2","type":"idiom"},{"id":"idiom_0218","en":"It’s just not on!","definition":"Not an appropriate way of behaving.","ko":"적절하지 않은 행동 방식.","cefr":"B2","type":"idiom"},{"id":"idiom_0219","en":"knows inside out","definition":"knows every detail of it","ko":"모든 세부 사항을 꿰뚫고 있다","cefr":"B2","type":"idiom"},{"id":"idiom_0220","en":"knows his stuff","definition":"has a very good knowledge of it","ko":"그 분야에 대해 아주 잘 알고 있다","cefr":"B2","type":"idiom"},{"id":"idiom_0221","en":"has a familiar ring to it","definition":"It sounds familiar; it seems like something you have heard or experienced before.","ko":"익숙하게 들린다; 예전에 들어봤거나 경험한 것 같다.","cefr":"B2","type":"idiom"},{"id":"idiom_0222","en":"rings a bell","definition":"To sound familiar or remind someone of something, even if they can't remember the details.","ko":"익숙하게 들리거나, 자세한 내용은 기억이 안 나도 뭔가를 떠올리게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0223","en":"haven’t (got) / don’t have a clue","definition":"To not know or understand something at all; to have no idea.","ko":"전혀 모르거나 이해하지 못하다; 전혀 감이 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_0224","en":"haven’t (got) / don’t have the faintest idea","definition":"I really don’t know at all.","ko":"전혀 모르겠다.","cefr":"B2","type":"idiom"},{"id":"idiom_0225","en":"haven’t (got) / don’t have the foggiest (idea)","definition":"To have absolutely no knowledge or understanding about something; to not know at all.","ko":"무언가에 대해 전혀 알지 못하거나 이해하지 못함; 전혀 모른다.","cefr":"B2","type":"idiom"},{"id":"idiom_0226","en":"can’t for the life of me","definition":"I can’t remember at all; used to emphasize that you are completely unable to recall or do something.","ko":"전혀 기억이 나지 않다; 아무리 해도 기억하거나 할 수 없음을 강조할 때 사용함.","cefr":"B2","type":"idiom"},{"id":"idiom_0227","en":"a bit out of touch","definition":"Not being aware of the latest information, trends, or developments in a particular area.","ko":"어떤 분야의 최근 정보나 트렌드를 잘 모르는 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0228","en":"doesn’t ring any bells with me","definition":"I don’t think I’ve ever heard it before; it is unfamiliar.","ko":"들어본 적 없는 것 같아요; 낯설어요.","cefr":"B2","type":"idiom"},{"id":"idiom_0229","en":"put two and two together","definition":"To figure something out or draw a logical conclusion from the information available.","ko":"주어진 정보를 바탕으로 무언가를 알아내거나 논리적으로 결론을 내리다.","cefr":"B2","type":"idiom"},{"id":"idiom_0230","en":"got (hold of) the wrong end of the stick","definition":"came to the wrong conclusion","ko":"잘못된 결론에 도달했다","cefr":"B2","type":"idiom"},{"id":"idiom_0231","en":"be on the breadline","definition":"To be very poor; to have very little money and be close to poverty.","ko":"아주 가난하다; 빈곤선에 가까운 생활을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0232","en":"live in the lap of luxury","definition":"To live an extremely comfortable and extravagant life, usually because of having a lot of money.","ko":"매우 많은 돈으로 극도의 편안함과 사치를 누리면서 사는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0233","en":"well off / well-to-do / well-heeled","definition":"having plenty of money","ko":"부유한, 돈이 많은","cefr":"B2","type":"idiom"},{"id":"idiom_0234","en":"spend money like water","definition":"spend too much, often without thinking about it","ko":"생각 없이 돈을 마구 쓰다","cefr":"B2","type":"idiom"},{"id":"idiom_0235","en":"tighten your belt","definition":"spend less than you did before, because you have less money","ko":"돈이 줄어서 지출을 줄이다","cefr":"B2","type":"idiom"},{"id":"idiom_0236","en":"make a killing","definition":"earn a lot of money very easily","ko":"아주 쉽게 큰돈을 벌다","cefr":"B2","type":"idiom"},{"id":"idiom_0237","en":"be a money spinner","definition":"be a successful way of making money","ko":"수익을 많이 내는 사업이 되다","cefr":"B2","type":"idiom"},{"id":"idiom_0238","en":"pay through the nose","definition":"To pay much more than a fair price; to pay an excessive amount of money for something.","ko":"공정한 가격보다 훨씬 비싸게 지불하다","cefr":"B2","type":"idiom"},{"id":"idiom_0239","en":"a rip-off","definition":"something that is not worth the money that you paid for it","ko":"지불한 돈에 비해 가치가 없는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0240","en":"spend a small fortune","definition":"To spend a large amount of money, often more than expected or considered reasonable.","ko":"예상보다 많거나 합리적이지 않을 정도로 큰돈을 쓰다.","cefr":"B2","type":"idiom"},{"id":"idiom_0241","en":"cost a small fortune","definition":"to cost a lot of money; to be very expensive","ko":"돈이 많이 들다; 매우 비싸다","cefr":"B2","type":"idiom"},{"id":"idiom_0242","en":"make a small fortune","definition":"to earn or acquire a large amount of money, often more than expected","ko":"예상보다 많은 돈을 벌거나 획득하다","cefr":"B2","type":"idiom"},{"id":"idiom_0243","en":"lose a small fortune","definition":"to lose a large amount of money, often unexpectedly or through bad luck or poor decisions.","ko":"예상치 못하게 혹은 잘못된 결정 등으로 많은 돈을 잃다.","cefr":"B2","type":"idiom"},{"id":"idiom_0244","en":"pick up the tab/bill","definition":"pay for something, often something that is not your responsibility (informal)","ko":"보통 내 책임이 아닌 것을 대신 계산하다 (비공식적 표현)","cefr":"B2","type":"idiom"},{"id":"idiom_0245","en":"at a considerable price","definition":"by sacrificing a lot or by doing something unpleasant in order to get it","ko":"많은 희생이나 불쾌한 일을 감수해서 얻는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0246","en":"work put paid to","definition":"Stopped someone from doing something that they were planning to do.","ko":"누군가의 계획을 망치거나 막다.","cefr":"B2","type":"idiom"},{"id":"idiom_0247","en":"paying the price for","definition":"experiencing the unpleasant consequences of something you have done","ko":"자신이 한 일의 불쾌한 결과를 겪게 되다","cefr":"B2","type":"idiom"},{"id":"idiom_0248","en":"commit something to memory","definition":"make yourself remember something","ko":"무엇인가를 기억하려 애쓰다","cefr":"B2","type":"idiom"},{"id":"idiom_0249","en":"take a stroll/trip down memory lane","definition":"To remember or reminisce about happy or significant events from the past.","ko":"과거의 행복하거나 의미 있는 순간을 떠올리거나 회상하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0250","en":"jog someone’s memory","definition":"To help someone remember something they may have forgotten.","ko":"누군가가 잊었을 수도 있는 것을 기억하도록 도와주다.","cefr":"B2","type":"idiom"},{"id":"idiom_0251","en":"in/within living memory","definition":"can be remembered by people still alive","ko":"살아있는 이들의 기억 속에 있는","cefr":"B2","type":"idiom"},{"id":"idiom_0252","en":"come/spring to mind","definition":"to immediately think of something or someone when a particular topic is mentioned","ko":"특정 주제가 언급될 때 바로 어떤 것 또는 누군가가 떠오르다","cefr":"B2","type":"idiom"},{"id":"idiom_0253","en":"slip your mind","definition":"to forget about something, often unintentionally or by accident","ko":"무심코 혹은 실수로 무언가를 잊어버리다","cefr":"B2","type":"idiom"},{"id":"idiom_0254","en":"bear/keep something in mind","definition":"To remember or consider something when making a decision or thinking about a situation.","ko":"결정하거나 상황을 생각할 때 무언가를 기억하거나 고려하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0255","en":"your mind goes blank","definition":"You suddenly cannot remember or think of anything, especially when you are expected to speak or act.","ko":"특히 말하거나 행동해야 할 때 갑자기 아무 생각도 나지 않을 때.","cefr":"B2","type":"idiom"},{"id":"idiom_0256","en":"cross your mind","definition":"To briefly think about something or have a thought occur to you, often unexpectedly or for a short moment.","ko":"어떤 생각이 잠깐 스쳐 지나가거나, 예상치 못하게 떠오르는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0257","en":"out of sight, out of mind","definition":"If you do not see someone or something, you are likely to forget about them or stop thinking about them.","ko":"누군가나 무언가를 보지 않으면 쉽게 잊게 된다.","cefr":"B2","type":"idiom"},{"id":"idiom_0258","en":"something is on the tip of your tongue","definition":"You know something but can’t quite remember it or say it at the moment.","ko":"무언가를 알고 있지만 순간적으로 기억이 안 나거나 말이 안 나올 때.","cefr":"B2","type":"idiom"},{"id":"idiom_0259","en":"ring a bell","definition":"To sound familiar or remind you of something you have heard or seen before.","ko":"들어본 적이 있거나 본 적이 있어 익숙하게 느껴지는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0260","en":"a train of thought","definition":"a series of connected ideas or thoughts that follow one another in a logical sequence.","ko":"논리적으로 이어지는 일련의 생각이나 아이디어.","cefr":"B2","type":"idiom"},{"id":"idiom_0261","en":"rack your brains","definition":"To think very hard or make a great effort to remember or solve something.","ko":"무언가를 기억하거나 해결하려고 매우 열심히 생각하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0262","en":"toffee-nosed","definition":"Thinks he is of a high social class and looks down on people of lower class (negative)","ko":"자신이 상류층이라고 생각하며 다른 사람을 깔보는 태도 (부정적)","cefr":"B2","type":"idiom"},{"id":"idiom_0263","en":"putting on / giving yourself airs and graces","definition":"acting as if you were someone of a higher social class than you really are","ko":"자신보다 더 높은 사회적 계층인 척 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_0264","en":"pillar of society","definition":"a solid, respectable and respected member of society","ko":"사회에서 존경받고 신뢰받는 인물","cefr":"B2","type":"idiom"},{"id":"idiom_0265","en":"rough diamond","definition":"a person who seems impolite or unrefined at first, but who is actually of good character or has hidden qualities.","ko":"처음에는 무례하거나 거칠어 보이지만, 실제로는 좋은 성격이나 숨겨진 장점을 가진 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_0266","en":"down-and-outs","definition":"people who have no home, no money and no job, who live on the streets","ko":"집, 돈, 일자리가 없어 거리에서 사는 사람들","cefr":"B2","type":"idiom"},{"id":"idiom_0267","en":"keep up appearances","definition":"To continue to maintain an outward show of prosperity or normalcy, even when facing difficulties or financial problems.","ko":"어려움이나 경제적 문제를 겪고 있어도 겉으로만 평상시처럼 보이려고 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0268","en":"high-flyer","definition":"A person who rises very quickly to a successful position, especially in their career or studies.","ko":"경력이나 학업에서 매우 빠르게 성공을 이루는 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_0269","en":"made a name for himself","definition":"became well-known or famous, usually through one's own efforts or achievements.","ko":"자신의 노력이나 성취로 유명해지거나 널리 알려짐.","cefr":"B2","type":"idiom"},{"id":"idiom_0270","en":"on his way up","definition":"rising to better and better positions","ko":"더 좋은 자리로 계속 오르다","cefr":"B2","type":"idiom"},{"id":"idiom_0271","en":"up-and-coming","definition":"becoming more and more popular or famous","ko":"점점 더 유명해지거나 인기를 얻는","cefr":"B2","type":"idiom"},{"id":"idiom_0272","en":"new blood","definition":"a new person from outside the company, often brought in to bring fresh ideas or energy.","ko":"회사 외부에서 온 새로운 사람으로, 신선한 아이디어나 에너지를 불어넣기 위해 영입됨.","cefr":"B2","type":"idiom"},{"id":"idiom_0273","en":"keep a low profile","definition":"not draw attention to oneself; to remain unnoticed or avoid attracting attention.","ko":"자신에게 주목이 가지 않게 하다; 눈에 띄지 않거나 주의를 피하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0274","en":"anybody who is anybody","definition":"all the important people","ko":"모든 중요 인물들","cefr":"B2","type":"idiom"},{"id":"idiom_0275","en":"the odd one out","definition":"Someone or something that is different from the others in a group.","ko":"집단 속에서 다른 사람들과 다른 사람이나 사물.","cefr":"B2","type":"idiom"},{"id":"idiom_0276","en":"politically correct name","definition":"An acceptable and non-offensive way of referring to particular social groups; often used with a hint of criticism, suggesting that being overly careful with language to avoid offending anyone can be excessive or unnecessary.","ko":"특정 사회 집단을 지칭할 때 받아들여지고 비하하지 않는 표현; 때론 과도한 언어적 배려가 불필요하다는 비판적 뉘앙스로 사용됨.","cefr":"B2","type":"idiom"},{"id":"idiom_0277","en":"out of this world","definition":"extremely good or impressive","ko":"매우 훌륭하거나 인상적인","cefr":"B2","type":"idiom"},{"id":"idiom_0278","en":"second to none","definition":"the best; better than anything else","ko":"최고의; 뛰어나다","cefr":"B2","type":"idiom"},{"id":"idiom_0279","en":"a hard act to follow","definition":"So good or impressive that it is difficult for anyone else to match or surpass.","ko":"너무 뛰어나거나 인상적이어서 다른 사람이 따라잡기 힘듦.","cefr":"B2","type":"idiom"},{"id":"idiom_0280","en":"made for this room","definition":"perfectly suited for this room","ko":"이 방을 위해 딱 맞게 만들어진 듯한","cefr":"B2","type":"idiom"},{"id":"idiom_0281","en":"he gave as good as he got","definition":"He responded to criticism or attack with equal force.","ko":"비판이나 공격에 같은 강도로 대응했다.","cefr":"B2","type":"idiom"},{"id":"idiom_0282","en":"like gold dust","definition":"very rare and valuable","ko":"매우 드물고 소중한","cefr":"B2","type":"idiom"},{"id":"idiom_0283","en":"ground-breaking work","definition":"work that is innovative and introduces new ideas or methods","ko":"혁신적이며 새로운 아이디어나 방법을 도입하는 작업","cefr":"B2","type":"idiom"},{"id":"idiom_0284","en":"all sweetness and light","definition":"friendly and pleasant, but in a false or insincere way","ko":"친절하고 상냥하지만, 거짓되거나 진실하지 않은 방식으로","cefr":"B2","type":"idiom"},{"id":"idiom_0285","en":"getting on my nerves","definition":"irritating or annoying me","ko":"짜증나거나 신경을 거슬리게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0286","en":"give me a hard time","definition":"To criticize, tease, or make things difficult for someone, often in a way that causes discomfort or guilt.","ko":"누군가를 비난하거나 놀리거나 일부러 곤란하게 하여 불편함이나 죄책감을 유발하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0287","en":"poke fun at","definition":"to tease or mock someone, often in a playful or lighthearted way","ko":"장난스럽거나 가볍게 누군가를 놀리다","cefr":"B2","type":"idiom"},{"id":"idiom_0288","en":"to add insult to injury","definition":"to make a bad situation even worse","ko":"나쁜 상황을 더욱 악화시키다","cefr":"B2","type":"idiom"},{"id":"idiom_0289","en":"cast aspersions on","definition":"To criticize someone or something unfairly or suggest that they are not honest or trustworthy, often in a subtle or indirect way (formal).","ko":"누군가의 정직함이나 신뢰성을 부당하게 혹은 간접적으로 의심하거나 비난함.","cefr":"B2","type":"idiom"},{"id":"idiom_0290","en":"out-and-out","definition":"completely or totally, especially used to emphasize negative qualities of people.","ko":"완전히, 특히 부정적인 특성을 강조할 때 사용.","cefr":"B2","type":"idiom"},{"id":"idiom_0291","en":"asking for trouble","definition":"Doing something that is likely to cause problems or lead to negative consequences.","ko":"문제나 부정적인 결과를 초래할 가능성이 있는 행동을 하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0292","en":"give something your all","definition":"use all your energy and effort to do something","ko":"최선을 다하다, 모든 힘을 쏟다","cefr":"B2","type":"idiom"},{"id":"idiom_0293","en":"go all out","definition":"use a lot of energy and effort to do something","ko":"무엇인가를 하려고 모든 힘과 노력을 쏟다","cefr":"B2","type":"idiom"},{"id":"idiom_0294","en":"go out of your way to do something","definition":"try very hard to do something, usually something nice","ko":"무언가를 (특히 좋은 일을) 위해 상당히 애쓰다","cefr":"B2","type":"idiom"},{"id":"idiom_0295","en":"pull your weight","definition":"work as hard as other people in a group","ko":"팀의 다른 사람들처럼 열심히 일하다","cefr":"B2","type":"idiom"},{"id":"idiom_0296","en":"by hook or by crook","definition":"using whatever methods are necessary","ko":"수단과 방법을 가리지 않고","cefr":"B2","type":"idiom"},{"id":"idiom_0297","en":"pull your finger out","definition":"make more of an effort (very informal)","ko":"더 노력하다 (매우 비격식적 표현)","cefr":"B2","type":"idiom"},{"id":"idiom_0298","en":"at a push","definition":"Probably possible, but it will be difficult.","ko":"아마도 가능하지만, 어렵다.","cefr":"B2","type":"idiom"},{"id":"idiom_0299","en":"have a go","definition":"try to do something","ko":"무언가를 시도하다","cefr":"B2","type":"idiom"},{"id":"idiom_0300","en":"have a bash at","definition":"try to do something (more informal way of saying have a go)","ko":"무언가를 시도하다","cefr":"B2","type":"idiom"},{"id":"idiom_0301","en":"went through the motions","definition":"Did something because you are expected to do it, not because you want to do it. In other words, you do it but without putting much effort or enthusiasm into it.","ko":"원해서가 아니라 해야 하니까, 열정이나 노력 없이 하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0302","en":"child's play","definition":"extremely easy","ko":"매우 쉬움","cefr":"B2","type":"idiom"},{"id":"idiom_0303","en":"as easy as pie","definition":"extremely easy (informal)","ko":"아주 쉬운 (비격식적)","cefr":"B2","type":"idiom"},{"id":"idiom_0304","en":"a piece of cake","definition":"extremely easy (informal)","ko":"매우 쉬움 (비격식적)","cefr":"B2","type":"idiom"},{"id":"idiom_0305","en":"as easy as taking candy from a baby","definition":"Extremely easy; something that can be done with little or no effort.","ko":"매우 쉬움; 거의 노력 없이 할 수 있는 일.","cefr":"B2","type":"idiom"},{"id":"idiom_0306","en":"a doddle","definition":"extremely easy (informal)","ko":"엄청 쉽다 (비격식적)","cefr":"B2","type":"idiom"},{"id":"idiom_0307","en":"heavy-going","definition":"difficult and needing a lot of effort","ko":"어렵고 많은 노력이 필요한","cefr":"B2","type":"idiom"},{"id":"idiom_0308","en":"making do","definition":"managing with something that isn’t as good as you would like","ko":"마음에 들지 않지만 주어진 것으로 견디다","cefr":"B2","type":"idiom"},{"id":"idiom_0309","en":"give it a shot/whirl","definition":"To try something, especially for the first time, often without being sure of success (informal).","ko":"특히 처음 해보는 일에, 성공할지 확신이 없지만 시도해보다.","cefr":"B2","type":"idiom"},{"id":"idiom_0310","en":"get to grips with","definition":"make an effort to understand or to deal with a problem or situation","ko":"문제나 상황을 이해하거나 다루려고 노력하다","cefr":"B2","type":"idiom"},{"id":"idiom_0311","en":"to be on the safe side","definition":"to take extra precautions or do something to avoid possible problems, even if it might not be strictly necessary.","ko":"필요하지 않을 수도 있지만 혹시 모를 문제를 예방하기 위해 추가로 조심하는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0312","en":"get to the bottom of","definition":"try to discover the truth about something","ko":"무언가의 진실을 밝히려고 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0313","en":"shed a great deal of light on","definition":"make something clearer; help people understand a situation","ko":"무엇을 더 명확하게 하다; 상황을 이해하는 데 도움을 주다","cefr":"B2","type":"idiom"},{"id":"idiom_0314","en":"brought to light","definition":"make unknown facts become known","ko":"알려지지 않은 사실을 밝혀내다","cefr":"B2","type":"idiom"},{"id":"idiom_0315","en":"come to light","definition":"unknown facts becoming known","ko":"알려지지 않았던 사실이 드러남","cefr":"B2","type":"idiom"},{"id":"idiom_0316","en":"bring something to light","definition":"to reveal or make known facts or information that were previously hidden or unknown","ko":"이전에 숨겨지거나 알려지지 않았던 사실이나 정보를 드러내거나 알리다","cefr":"B2","type":"idiom"},{"id":"idiom_0317","en":"shed/throw light on something","definition":"To help people understand a situation by providing new information or making something clearer.","ko":"새로운 정보 제공이나 더 명확하게 만들어 사람들에게 상황을 이해하도록 돕다.","cefr":"B2","type":"idiom"},{"id":"idiom_0318","en":"light at the end of the tunnel","definition":"something makes you believe that a difficult and unpleasant situation is coming to an end","ko":"힘든 상황 끝에 희망이 보임","cefr":"B2","type":"idiom"},{"id":"idiom_0319","en":"in the bag","definition":"certain to be achieved (informal)","ko":"확실히 이룰 수 있는 (비공식적)","cefr":"B2","type":"idiom"},{"id":"idiom_0320","en":"the answer to my prayers","definition":"something or someone that you have needed or hoped for for a long time, often appearing just when you need it most.","ko":"오랫동안 원하거나 필요했던 것이 가장 필요한 순간에 나타나는 것 또는 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_0321","en":"wave a magic wand","definition":"to find or wish for an easy and immediate solution to a difficult problem, as if by magic","ko":"어려운 문제에 대해 마치 마법처럼 쉽고 즉각적인 해결책을 찾거나 바라다","cefr":"B2","type":"idiom"},{"id":"idiom_0322","en":"tie up a few loose ends","definition":"deal with the last few things that need to be done before something is completed","ko":"완성하기 전에 남은 자잘한 일들을 처리하다","cefr":"B2","type":"idiom"},{"id":"idiom_0323","en":"fall into place","definition":"To become clear, understandable, or organized; to happen in a satisfactory or desired way.","ko":"명확하고 이해하기 쉽거나 정리되다; 바라는 대로 일이 풀리다.","cefr":"B2","type":"idiom"},{"id":"idiom_0324","en":"pick up the pieces","definition":"to try to return to normal or recover after something bad has happened","ko":"나쁜 일이 있은 후 정상으로 돌아가거나 회복하려고 노력하다","cefr":"B2","type":"idiom"},{"id":"idiom_0325","en":"be in someone's good books","definition":"To be liked or approved of by someone, often because you have done something to please them.","ko":"누군가의 호감을 사거나, 누군가에게 좋은 인상을 주는 것, 주로 그들을 기쁘게 해준 행동 때문에.","cefr":"B2","type":"idiom"},{"id":"idiom_0326","en":"get on like a house on fire","definition":"To become very friendly with someone very quickly and get along extremely well.","ko":"누군가와 매우 빠르게 친해지고 잘 지내는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0327","en":"keep/get/be/stay in touch with someone","definition":"To maintain communication or contact with someone.","ko":"누군가와 연락이나 소통을 유지하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0328","en":"make it up to someone","definition":"do something good for someone you have done something bad to in the past","ko":"과거에 잘못한 사람에게 좋은 일을 해주다","cefr":"B2","type":"idiom"},{"id":"idiom_0329","en":"take a shine to someone","definition":"To like someone immediately or develop a fondness for them, often without a clear reason (informal).","ko":"이유 없이 누군가를 바로 마음에 들어 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0330","en":"have a soft spot for someone","definition":"feel a lot of affection for one particular person, often without knowing why","ko":"특별한 이유 없이 누군가에게 유난히 애정을 느끼다","cefr":"B2","type":"idiom"},{"id":"idiom_0331","en":"be at loggerheads","definition":"to disagree strongly with each other, often in a way that cannot be easily resolved","ko":"쉽게 해결되지 않는 심각한 의견 충돌이 있다","cefr":"B2","type":"idiom"},{"id":"idiom_0332","en":"be (talking) at cross-purposes (of two people or groups)","definition":"not understand each other because they are trying to do or say different things","ko":"서로 다른 말을 하거나 다른 일을 하려다 보니 이해하지 못함","cefr":"B2","type":"idiom"},{"id":"idiom_0333","en":"have it in for someone","definition":"To be determined to criticize, harm, or treat someone unfairly, often due to a personal grudge.","ko":"개인적인 감정 때문에 일부러 비난하거나 불공평하게 대하려 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0334","en":"have it out with someone","definition":"To confront someone directly in order to discuss and resolve a disagreement or problem.","ko":"갈등이나 문제를 논의하고 해결하기 위해 직접 상대와 맞닥뜨리다.","cefr":"B2","type":"idiom"},{"id":"idiom_0335","en":"two-time someone","definition":"have a romantic or sexual relationship with two people at the same time","ko":"두 사람과 동시에 연애나 성관계를 맺다","cefr":"B2","type":"idiom"},{"id":"idiom_0336","en":"keep someone/something at bay","definition":"prevent someone or something from coming near you or causing harm or trouble","ko":"누군가나 무언가가 가까이 오거나 해를 끼치는 것을 막다","cefr":"B2","type":"idiom"},{"id":"idiom_0337","en":"keep yourself to yourself","definition":"prefer to be on your own and avoid talking with or doing things with other people","ko":"혼자 있기를 선호하고 다른 사람과 어울리거나 말을 하는 것을 피함","cefr":"B2","type":"idiom"},{"id":"idiom_0338","en":"caught napping","definition":"got into trouble because they were not paying enough attention","ko":"주의를 기울이지 않아 곤란에 처하다","cefr":"B2","type":"idiom"},{"id":"idiom_0339","en":"going out on a limb","definition":"stating an opinion or doing something different from anyone else","ko":"다른 사람들과는 다르게 의견을 내거나 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_0340","en":"out on a limb","definition":"You are alone and lacking support from anyone else.","ko":"당신은 혼자이고 다른 사람의 지지가 없습니다.","cefr":"B2","type":"idiom"},{"id":"idiom_0341","en":"led astray","definition":"Influenced so that someone does bad things or moves away from the correct or intended path.","ko":"누군가 나쁜 행동을 하거나 올바른 길에서 벗어나도록 영향을 받는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0342","en":"leave well alone","definition":"try not to change or improve something because this might make things worse","ko":"무언가를 바꾸거나 고치려다 오히려 더 나빠질 수 있으니 그냥 두다","cefr":"B2","type":"idiom"},{"id":"idiom_0343","en":"panic stations","definition":"a time or situation where you feel very anxious and have to act quickly (informal)","ko":"매우 불안하고 신속하게 행동해야 하는 상황 (비공식)","cefr":"B2","type":"idiom"},{"id":"idiom_0344","en":"necessary evil","definition":"something you do not like, but you agree that it must exist or happen","ko":"싫지만 반드시 필요하거나 피할 수 없는 일","cefr":"B2","type":"idiom"},{"id":"idiom_0345","en":"safe and sound","definition":"To be completely unharmed and in good health, especially after being in danger or a risky situation.","ko":"다치거나 위험하지 않게 어떤 곳에 도착하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0346","en":"have a narrow escape","definition":"just manage to avoid danger or trouble","ko":"위험이나 곤란을 간신히 피하다","cefr":"B2","type":"idiom"},{"id":"idiom_0347","en":"do something by the skin of your teeth","definition":"only just succeed in doing something","ko":"간신히 해내다","cefr":"B2","type":"idiom"},{"id":"idiom_0348","en":"rather/too close for comfort","definition":"So close in distance or similar in amount that you are worried or frightened.","ko":"거리가 너무 가깝거나 수치가 비슷해 걱정되거나 두려운 상황.","cefr":"B2","type":"idiom"},{"id":"idiom_0349","en":"cut things fine","definition":"leave yourself only just enough time to do something","ko":"무언가를 하기에 꼭 필요한 시간만 남겨두다","cefr":"B2","type":"idiom"},{"id":"idiom_0350","en":"something sets alarm bells ringing","definition":"Something causes you to feel worried or suspicious because it suggests there may be a problem.","ko":"문제가 있을 수 있다는 신호로 걱정이나 의심을 불러일으킨다.","cefr":"B2","type":"idiom"},{"id":"idiom_0351","en":"take your life in(to) your hands","definition":"To do something very risky or dangerous, often with the possibility of serious harm.","ko":"심각한 피해를 입을 수 있는 매우 위험한 일을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0352","en":"your life is in someone's hands","definition":"That person can affect whether you live or die; you are completely dependent on their actions or decisions for your safety or survival.","ko":"누군가의 행동이나 결정에 전적으로 생사가 달려 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0353","en":"hanging by a thread","definition":"in a very precarious or risky situation; likely to fail or collapse soon","ko":"매우 불안정하거나 위험한 상황에 있음; 곧 실패하거나 무너질 것 같은 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0354","en":"on a knife-edge","definition":"in a very difficult situation and there are worries about the future","ko":"아주 어려운 상황에 있고 미래에 대한 걱정이 있는 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0355","en":"red tape","definition":"official rules and bureaucracy that make it difficult to do something","ko":"어떤 일을 어렵게 만드는 공식 규칙과 관료주의","cefr":"B2","type":"idiom"},{"id":"idiom_0356","en":"be in the red","definition":"To have a negative amount in your bank balance; to owe more money than you have.","ko":"은행 잔고가 마이너스이다; 가진 돈보다 빚이 더 많다.","cefr":"B2","type":"idiom"},{"id":"idiom_0357","en":"catch someone red-handed","definition":"To catch someone in the act of doing something wrong or illegal.","ko":"누군가가 잘못하거나 불법적인 일을 하는 현장을 붙잡다.","cefr":"B2","type":"idiom"},{"id":"idiom_0358","en":"a red herring","definition":"something unimportant that takes attention away from the main subject","ko":"본질에서 관심을 돌리게 하는 중요하지 않은 것","cefr":"B2","type":"idiom"},{"id":"idiom_0359","en":"till I was blue in the face","definition":"Say the same thing repeatedly, but someone refuses to listen or nothing changes.","ko":"같은 말을 아무리 반복해도 소용이 없는 상황","cefr":"B2","type":"idiom"},{"id":"idiom_0360","en":"blue blood","definition":"belonging to the highest social class or being of aristocratic descent","ko":"최상류층에 속하거나 귀족 혈통임을 나타냄","cefr":"B2","type":"idiom"},{"id":"idiom_0361","en":"blue-collar workers","definition":"workers who do physical work, especially in factories","ko":"특히 공장에서 신체 노동을 하는 근로자들","cefr":"B2","type":"idiom"},{"id":"idiom_0362","en":"green with envy","definition":"very envious","ko":"매우 부럽다","cefr":"B2","type":"idiom"},{"id":"idiom_0363","en":"got green fingers","definition":"is a very good gardener","ko":"정원 가꾸기에 매우 능숙하다","cefr":"B2","type":"idiom"},{"id":"idiom_0364","en":"given the green light","definition":"given permission for something to start","ko":"무언가 시작할 수 있는 허가를 받음","cefr":"B2","type":"idiom"},{"id":"idiom_0365","en":"in the green belt","definition":"countryside around a town or city which is protected from building development","ko":"도시 주변의 개발이 제한된 녹지지역","cefr":"B2","type":"idiom"},{"id":"idiom_0366","en":"white-collar workers","definition":"workers who work in offices, not doing physical work","ko":"사무실에서 일하는 육체노동이 아닌 직장인","cefr":"B2","type":"idiom"},{"id":"idiom_0367","en":"in black and white","definition":"Written down or printed, not just spoken; something that is officially documented.","ko":"구두가 아닌 문서로 공식적으로 기록된 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0368","en":"grey area","definition":"something that is a problem, and is not very clear because there are no rules","ko":"문제가 있지만 규정이 명확하지 않아 애매한 상황","cefr":"B2","type":"idiom"},{"id":"idiom_0369","en":"black hole","definition":"something which has no bottom, and everything put into it just disappears","ko":"바닥이 없어 뭐든지 넣으면 사라지는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0370","en":"I'm thrilled to bits","definition":"extremely happy","ko":"몹시 행복하다","cefr":"B2","type":"idiom"},{"id":"idiom_0371","en":"get a (real) kick out of something","definition":"To greatly enjoy or find amusement in something; to take pleasure in an activity or situation (informal).","ko":"무엇인가를 아주 즐기거나 재미있게 느끼다","cefr":"B2","type":"idiom"},{"id":"idiom_0372","en":"do something for kicks","definition":"do something because it is exciting, usually something dangerous (informal)","ko":"스릴이나 짜릿함 때문에 (보통 위험한) 일을 하다 (비격식)","cefr":"B2","type":"idiom"},{"id":"idiom_0373","en":"jump for joy","definition":"be very happy and excited about something that has happened","ko":"무언가가 일어난 일에 매우 행복하고 신이 남","cefr":"B2","type":"idiom"},{"id":"idiom_0374","en":"be floating/walking on air","definition":"To be extremely happy or elated, usually because something very good has happened.","ko":"무척 행복하거나 들떠 있는 상태, 보통 매우 좋은 일이 생겼을 때.","cefr":"B2","type":"idiom"},{"id":"idiom_0375","en":"something makes your day","definition":"something that happens which makes you feel very happy or improves your mood significantly.","ko":"매우 기쁘게 하거나 기분을 확 바꿔 주는 일.","cefr":"B2","type":"idiom"},{"id":"idiom_0376","en":"out of sorts","definition":"slightly unhappy or slightly ill","ko":"조금 기분이 안 좋거나 몸이 살짝 아픈 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0377","en":"down in the dumps","definition":"unhappy (informal)","ko":"아주 우울하고 희망이 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_0378","en":"it's not the end of the world","definition":"What has happened won’t cause any serious problems; things are not as bad as they seem.","ko":"일어난 일이 심각한 문제를 일으키지 않는다; 상황이 생각만큼 나쁘지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_0379","en":"grin and bear it","definition":"accept a situation you don’t like because you can’t change it","ko":"싫지만 어쩔 수 없이 받아들이는 상황","cefr":"B2","type":"idiom"},{"id":"idiom_0380","en":"a misery guts","definition":"someone who complains all the time and is never happy (very informal)","ko":"항상 불평하고 절대 만족하지 않는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0381","en":"sour grapes","definition":"being jealous about something you can’t have","ko":"가질 수 없는 것에 대해 질투하는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0382","en":"puts a damper on","definition":"To make an event or situation less enjoyable, exciting, or successful.","ko":"행사나 상황을 덜 즐겁거나 성공적으로 만들다","cefr":"B2","type":"idiom"},{"id":"idiom_0383","en":"on the one hand","definition":"used to present one of two opposite facts or different ways of looking at the same issue","ko":"같은 문제에 대해 상반되는 사실이나 다른 관점을 제시할 때 사용","cefr":"B2","type":"idiom"},{"id":"idiom_0384","en":"on the other hand","definition":"used to present the opposite fact or a different way of looking at the same issue","ko":"같은 문제에 대해 반대 사실이나 다른 시각을 제시할 때 사용함","cefr":"B2","type":"idiom"},{"id":"idiom_0385","en":"be that as it may","definition":"An expression which means you accept that something is true, but it still does not change your opinion.","ko":"어떤 사실을 인정해도 자신의 의견은 변하지 않는다는 뜻의 표현.","cefr":"B2","type":"idiom"},{"id":"idiom_0386","en":"to put it in a nutshell","definition":"indicates that you’re describing something as briefly as you can","ko":"간단히 말해서, 한마디로","cefr":"B2","type":"idiom"},{"id":"idiom_0387","en":"pros and cons","definition":"advantages and disadvantages","ko":"장단점","cefr":"B2","type":"idiom"},{"id":"idiom_0388","en":"vicious circle","definition":"a problem that cannot be solved because it causes another problem that causes the first problem again","ko":"문제가 또 다른 문제를 불러와서 결국 해결되지 않는 상황","cefr":"B2","type":"idiom"},{"id":"idiom_0389","en":"can of worms","definition":"a problem which you do not want to deal with because it will cause trouble (informal)","ko":"문제를 건드리면 더 큰 문제가 생길 것 같아 다루고 싶지 않은 상황","cefr":"B2","type":"idiom"},{"id":"idiom_0390","en":"acid test","definition":"a key test which will prove the value, quality or truth of something","ko":"무엇의 가치나 진실, 품질을 입증하는 결정적인 시험","cefr":"B2","type":"idiom"},{"id":"idiom_0391","en":"the other side of the coin","definition":"A different perspective or aspect of a situation, often one that contrasts with or opposes the original view.","ko":"상황에 대한 다른 시각이나 관점, 종종 기존과 반대되는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0392","en":"tie yourself (up) in knots","definition":"To become very confused or anxious, especially when trying to explain or deal with something complicated.","ko":"특히 복잡한 일을 설명하거나 처리하려고 할 때 매우 혼란스럽거나 불안해지다.","cefr":"B2","type":"idiom"},{"id":"idiom_0393","en":"be brought/called to account","definition":"Be forced to explain your actions and (probably) punished.","ko":"자신의 행동에 대해 설명을 요구받고, 아마도 처벌받게 된다.","cefr":"B2","type":"idiom"},{"id":"idiom_0394","en":"give someone the benefit of the doubt","definition":"To choose to believe or trust someone, even though you are not sure if what they are saying or doing is true or honest.","ko":"확실하지 않아도 누군가의 말을 믿고 신뢰하기로 선택하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0395","en":"go round in circles","definition":"To make no progress in an argument or discussion; to keep talking about the same things without reaching a conclusion.","ko":"논쟁이나 토론에서 아무런 진전이 없이 같은 이야기만 반복하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0396","en":"won’t budge/give an inch","definition":"Won’t modify an opinion or agree to even small changes that another person wants.","ko":"의견을 결코 바꾸지 않거나, 남이 원하는 작은 변화도 허락하지 않음.","cefr":"B2","type":"idiom"},{"id":"idiom_0397","en":"Absence makes the heart grow fonder","definition":"Being apart from someone you love makes you love them more.","ko":"사랑하는 사람과 떨어져 있으면 더 그리워지게 된다.","cefr":"B2","type":"idiom"},{"id":"idiom_0398","en":"Actions speak louder than words","definition":"What people do is more important than what they say.","ko":"말보다 행동이 중요하다","cefr":"B2","type":"idiom"},{"id":"idiom_0399","en":"There’s no point / It’s no good crying over spilt milk","definition":"There’s no point in getting upset over something bad that’s happened when you can’t change it.","ko":"이미 일어난 일, 바꿀 수 없는 일에 속상해해도 소용없다는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_0400","en":"Don’t put all your eggs in one basket","definition":"It is not a good idea to put all your efforts or all your money into one project as, if it fails, you may lose everything.","ko":"노력이나 자본을 한 프로젝트에만 쏟으면 실패할 때 모두 잃을 수 있으니 주의해야 한다는 의미입니다.","cefr":"B2","type":"idiom"},{"id":"idiom_0401","en":"Many hands make light work","definition":"A job is done quickly and easily if plenty of people help.","ko":"많은 사람이 도우면 일이 빠르고 쉽게 끝난다.","cefr":"B2","type":"idiom"},{"id":"idiom_0402","en":"Blood is thicker than water","definition":"Family relationships are stronger than any other relationships.","ko":"가족 간의 관계는 다른 어떤 관계보다도 강하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0403","en":"Too many cooks spoil the broth","definition":"If too many people work on something, they will spoil it.","ko":"너무 많은 사람이 참여하면 일이 망친다.","cefr":"B2","type":"idiom"},{"id":"idiom_0404","en":"People who live in glass houses shouldn’t throw stones","definition":"People shouldn’t criticise other people for faults that they have themselves.","ko":"자신도 가진 잘못으로 남을 비난해서는 안 된다.","cefr":"B2","type":"idiom"},{"id":"idiom_0405","en":"It’s the last straw that breaks the camel’s back","definition":"Something is the last in a series of unpleasant events, and which finally makes you feel that the situation cannot continue.","ko":"불쾌한 일련의 사건 중 더는 참을 수 없게 만드는 마지막 사건.","cefr":"B2","type":"idiom"},{"id":"idiom_0406","en":"While the cat’s away, the mice will play","definition":"When the person in authority is not there, other people will not do what they should do.","ko":"권위자가 없을 때 누군가가 제멋대로 행동하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0407","en":"Take care of the pennies and the pounds will take care of themselves","definition":"If you don’t waste small sums of money, you’ll end up with plenty of money.","ko":"작은 금액도 아끼면 결국 큰 돈이 된다.","cefr":"B2","type":"idiom"},{"id":"idiom_0408","en":"Birds of a feather flock together","definition":"People who have similar characters or interests will often choose to spend time together.","ko":"성격이나 관심사가 비슷한 사람들은 함께 어울려 다닌다.","cefr":"B2","type":"idiom"},{"id":"idiom_0409","en":"A bird in the hand is worth two in the bush","definition":"It’s better to keep what you have rather than to risk losing it by trying to get more.","ko":"더 많은 것을 얻으려다 지금 가진 것을 잃는 위험을 무릅쓰는 것보다, 현재 가진 것을 지키는 것이 낫다.","cefr":"B2","type":"idiom"},{"id":"idiom_0410","en":"The grass is always greener on the other side of the fence","definition":"Other people always seem to be in a better situation than you.","ko":"남의 처지가 항상 더 좋아 보인다.","cefr":"B2","type":"idiom"},{"id":"idiom_0411","en":"All work and no play makes Jack a dull boy","definition":"Someone who spends all their time working becomes a boring person.","ko":"일만 하고 노는 시간이 없으면 사람이 지루해진다.","cefr":"B2","type":"idiom"},{"id":"idiom_0412","en":"No such luck!","definition":"You’re disappointed you were not able to do something.","ko":"무언가를 하지 못해서 실망함.","cefr":"B2","type":"idiom"},{"id":"idiom_0413","en":"The more, the merrier.","definition":"You’re happy for others to join your group or activity.","ko":"사람이 많을수록 더 좋아요","cefr":"B2","type":"idiom"},{"id":"idiom_0414","en":"You can say that again!","definition":"Used to express strong agreement with what someone has just said.","ko":"누군가의 말에 강하게 동의할 때 사용함.","cefr":"B2","type":"idiom"},{"id":"idiom_0415","en":"There’s nothing to it!","definition":"Used to say that something is very easy to do or understand.","ko":"무언가가 매우 쉽다는 뜻으로 사용됨.","cefr":"B2","type":"idiom"},{"id":"idiom_0416","en":"Don’t make me laugh!","definition":"Used to express disbelief or skepticism, especially when someone suggests something that you think is unlikely, ridiculous, or impossible.","ko":"믿기 어렵거나 터무니없을 때, 상대의 말을 비웃거나 의심할 때 쓰는 표현.","cefr":"B2","type":"idiom"},{"id":"idiom_0417","en":"How time flies!","definition":"You are surprised at how quickly time has passed.","ko":"시간이 얼마나 빨리 지나갔는지 놀라다.","cefr":"B2","type":"idiom"},{"id":"idiom_0418","en":"It’s a small world.","definition":"You are surprised at a coincidence, e.g. meeting someone unexpectedly or discovering mutual friends.","ko":"우연의 일치나 예상치 못한 만남, 혹은 공통된 지인을 발견했을 때 놀라는 경우.","cefr":"B2","type":"idiom"},{"id":"idiom_0419","en":"It’s neither here nor there.","definition":"It is not very important.","ko":"그다지 중요하지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_0420","en":"It’s six of one and half a dozen of the other.","definition":"There is no real difference between two choices or situations; both options are essentially the same.","ko":"두 가지 선택지 모두 사실상 큰 차이가 없다; 본질적으로 같다.","cefr":"B2","type":"idiom"},{"id":"idiom_0421","en":"I can take it or leave it.","definition":"You do not hate something, but you don’t particularly like it either.","ko":"싫어하지는 않지만, 딱히 좋아하지도 않는다.","cefr":"B2","type":"idiom"},{"id":"idiom_0422","en":"You name it.","definition":"Used to indicate that anything you can think of or mention is included; whatever you say or choose.","ko":"생각할 수 있는 모든 것이 다 포함된다는 의미로 사용됨.","cefr":"B2","type":"idiom"},{"id":"idiom_0423","en":"This is the life!","definition":"It’s great to relax and not to be at work.","ko":"일하지 않고 쉬는 것이 정말 좋다.","cefr":"B2","type":"idiom"},{"id":"idiom_0424","en":"You haven’t lived!","definition":"Used humorously to say that someone has not experienced something enjoyable or exciting, and they should try it.","ko":"누군가 재미있거나 신나는 일을 아직 경험하지 못했다며, 꼭 해보라고 웃으면서 말할 때 씀.","cefr":"B2","type":"idiom"},{"id":"idiom_0425","en":"It’s/That’s the story of my life!","definition":"Bad things always seem to be happening to me. (humorous)","ko":"나쁜 일이 항상 나에게 일어나는 것 같아요 (농담조로).","cefr":"B2","type":"idiom"},{"id":"idiom_0426","en":"Such is/That’s life!","definition":"Bad things happen and you cannot prevent them.","ko":"안 좋은 일이 생기기도 하고, 그건 막을 수 없어요.","cefr":"B2","type":"idiom"},{"id":"idiom_0427","en":"a pack of lies","definition":"completely untrue statements.","ko":"전혀 사실이 아닌 말.","cefr":"B2","type":"idiom"},{"id":"idiom_0428","en":"a slip of the tongue","definition":"a small mistake in speaking, usually when you say something you did not intend to.","ko":"말을 하다가 무심코 실수로 다른 말을 하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0429","en":"That's a likely story!","definition":"Used to express disbelief or skepticism about what someone has said, implying that you think they are lying or exaggerating.","ko":"누군가의 말을 믿지 않거나 의심할 때 사용되며, 상대가 거짓말을 하거나 과장한다고 여길 때 쓴다.","cefr":"B2","type":"idiom"},{"id":"idiom_0430","en":"off-the-cuff remark","definition":"something said without preparation or thought.","ko":"아무런 준비나 생각 없이 말하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0431","en":"in the same breath","definition":"Say two things that contradict each other at the same time.","ko":"서로 모순되는 말을 동시에 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0432","en":"small talk","definition":"conversation about unimportant or non-serious topics.","ko":"중요하지 않거나 심각하지 않은 주제에 대한 대화.","cefr":"B2","type":"idiom"},{"id":"idiom_0433","en":"didn't ring true","definition":"did not seem to be true or believable.","ko":"진실하거나 믿을 만하지 않았다.","cefr":"B2","type":"idiom"},{"id":"idiom_0434","en":"couldn't think of anything to say","definition":"Unable to respond or speak, often due to being overwhelmed.","ko":"압도되어 말문이 막히거나 반응을 못하는 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_0435","en":"lost for words","definition":"unable to speak because of surprise or emotion.","ko":"놀라거나 감동해서 말을 잃다.","cefr":"B2","type":"idiom"},{"id":"idiom_0436","en":"he was on about","definition":"What he was talking about (very informal).","ko":"무슨 말을 하는지 (아주 비격식적인 표현).","cefr":"B2","type":"idiom"},{"id":"idiom_0437","en":"in a word","definition":"used to sum up your opinion in a short, direct way.","ko":"의견을 짧고 직접적으로 요약할 때 사용함.","cefr":"B2","type":"idiom"},{"id":"idiom_0438","en":"for want of a better word","definition":"Not the exact or best word, but good enough for the situation.","ko":"정확하거나 가장 적절한 단어는 아니지만, 상황에 맞는 말.","cefr":"B2","type":"idiom"},{"id":"idiom_0439","en":"to coin a phrase","definition":"used when you use a phrase that is not original or sounds clichéd, often to acknowledge that what you are saying is a common expression.","ko":"진부하거나 흔히 쓰이는 표현을 사용할 때, 그것이 뻔한 말임을 인정하는 말.","cefr":"B2","type":"idiom"},{"id":"idiom_0440","en":"taking the mick/mickey out of","definition":"Laughing at someone by copying funny things they do or say, often in a playful or teasing way.","ko":"장난스럽거나 놀리듯이 누군가의 재미있는 행동이나 말을 흉내 내며 웃는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0441","en":"make light of","definition":"To treat something serious as if it were not important or as a joke.","ko":"심각한 일을 중요하지 않거나 농담처럼 여기는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0442","en":"no laughing matter","definition":"not something to laugh at, quite serious.","ko":"가벼이 여길 일이 아니라, 매우 심각한 일이다.","cefr":"B2","type":"idiom"},{"id":"idiom_0443","en":"It's no joke","definition":"Used to emphasize that a situation is serious, difficult, or not to be taken lightly.","ko":"상황이 심각하거나 어려워서 가볍게 여겨선 안 됨을 강조할 때 사용함.","cefr":"B2","type":"idiom"},{"id":"idiom_0444","en":"on the off-chance","definition":"because you hope you will do or find something or someone even if you do not think success is very likely","ko":"성공 가능성은 낮지만 혹시나 하는 마음에","cefr":"B2","type":"idiom"},{"id":"idiom_0445","en":"against all the odds","definition":"despite a lot of problems making it unlikely that you will succeed","ko":"성공할 확률이 낮음에도 불구하고","cefr":"B2","type":"idiom"},{"id":"idiom_0446","en":"take someone close to you for granted","definition":"Not to show you’re grateful to someone because they are with you so often.","ko":"누군가가 항상 함께 있어서 감사함을 표현하지 않는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0447","en":"a foregone conclusion","definition":"the result is obvious to everyone even before it happens","ko":"결과가 일어나기도 전에 모두에게 뻔한 상황","cefr":"B2","type":"idiom"},{"id":"idiom_0448","en":"coming a mile off","definition":"To be able to see or predict that something, usually something bad or obvious, is going to happen well in advance.","ko":"대개 나쁘거나 명백한 일이 미리 일어날 것임을 쉽게 알아채다.","cefr":"B2","type":"idiom"},{"id":"idiom_0449","en":"touch-and-go","definition":"A situation that is uncertain or risky, where the outcome is not clear and could go either way.","ko":"결과가 불확실하고 어느 쪽으로든 갈 수 있는 위험한 상황.","cefr":"B2","type":"idiom"},{"id":"idiom_0450","en":"no prizes for guessing","definition":"It is very easy to figure out or predict something; the answer is obvious.","ko":"무언가를 알아내거나 예측하는 것이 매우 쉽다; 답이 뻔하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0451","en":"the cards are stacked against you","definition":"You are not likely to succeed because there are so many obstacles in your way.","ko":"너무 많은 장애물이 있어서 성공 가능성이 낮다.","cefr":"B2","type":"idiom"},{"id":"idiom_0452","en":"chancing your arm","definition":"taking a risk to achieve what you want (informal)","ko":"원하는 것을 얻기 위해 위험을 감수하다","cefr":"B2","type":"idiom"},{"id":"idiom_0453","en":"in the lap of the gods","definition":"is not something that you can control yourself","ko":"자신이 통제할 수 없는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0454","en":"Don’t push your luck!","definition":"Don’t try too hard to get what you want and risk losing what you have achieved.","ko":"지나치게 욕심부리다가 이미 이룬 것을 잃지 마라.","cefr":"B2","type":"idiom"},{"id":"idiom_0455","en":"We’ll take pot luck.","definition":"We’ll take whatever is available without knowing if it will be good or not.","ko":"좋을지 아닐지 모른 채로 있는 것을 받아들인다.","cefr":"B2","type":"idiom"},{"id":"idiom_0456","en":"It’s the luck of the draw.","definition":"It’s a matter of chance and you have no control over it.","ko":"운에 달린 것이고, 당신이 통제할 수 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_0457","en":"Just my luck!","definition":"You say this, usually humorously, to mean that you are always unlucky.","ko":"항상 운이 없을 때 농담 삼아 하는 말.","cefr":"B2","type":"idiom"},{"id":"idiom_0458","en":"You should be so lucky!","definition":"Used to express doubt or disbelief that something desired or hoped for will actually happen; implies that the thing is very unlikely.","ko":"원하는 일이 실제로 일어날 것 같지 않음을 표현하는 말; 아주 가능성이 낮음을 의미함.","cefr":"B2","type":"idiom"},{"id":"idiom_0459","en":"have a lot to answer for","definition":"To be responsible for causing many problems or negative situations.","ko":"많은 문제나 부정적인 상황을 일으킨 데 대해 책임이 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0460","en":"something is not all it’s cracked up to be","definition":"is not as good as people say it is","ko":"사람들이 말하는 것만큼 좋지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_0461","en":"someone/something has the edge over someone/something","definition":"is slightly better than","ko":"조금 더 낫다","cefr":"B2","type":"idiom"},{"id":"idiom_0462","en":"leave a lot to be desired","definition":"is not as good as it should be or as we might expect; lacking in quality or satisfactory aspects.","ko":"기대에 미치지 못하거나 충분히 좋지 않다; 품질이나 만족스러운 요소가 부족하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0463","en":"have all the makings of","definition":"are likely to develop into; possess all the necessary qualities or ingredients for something to happen or succeed","ko":"무언가가 이루어지거나 성공하는 데 필요한 모든 자질이나 요소를 갖추고 있다","cefr":"B2","type":"idiom"},{"id":"idiom_0464","en":"on the big/expensive, etc. side","definition":"Slightly more than desired or expected in terms of size, cost, weight, or another quality.","ko":"원하거나 기대한 것보다 약간 크거나, 비싸거나, 무겁거나 한 경우.","cefr":"B2","type":"idiom"},{"id":"idiom_0465","en":"a dead loss","definition":"completely useless","ko":"완전히 쓸모없음","cefr":"B2","type":"idiom"},{"id":"idiom_0466","en":"throws the baby out with the bathwater","definition":"To eliminate or discard something valuable or important while trying to get rid of something unwanted.","ko":"불필요한 것을 없애려다 귀중한 것까지 함께 버림.","cefr":"B2","type":"idiom"},{"id":"idiom_0467","en":"gets/jumps/leaps on the bandwagon","definition":"To join others in doing something that is currently popular or successful, often in order to gain some benefit.","ko":"이득을 얻기 위해 유행이나 성공하는 일에 동참하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0468","en":"plays devil’s advocate","definition":"To pretend to be against an idea or argument, often for the sake of debate or to encourage discussion.","ko":"토론을 촉진하거나 논의를 위해 일부러 반대 입장을 취하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0469","en":"drives someone to distraction","definition":"To make someone extremely annoyed, irritated, or bored.","ko":"누군가를 몹시 짜증나거나 지루하게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0470","en":"makes an exhibition of themselves","definition":"To behave in a way in public that attracts attention and makes one look foolish or silly.","ko":"공공장소에서 주목을 받으면서 어리석거나 우습게 보이게 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0471","en":"does something under false pretences","definition":"To do something by lying about your identity, intentions, or reasons, usually to deceive others.","ko":"신분이나 의도, 이유를 속여 남을 기만해서 어떤 일을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0472","en":"never does anything by halves","definition":"always makes a great effort and does things very well, never only partially or carelessly.","ko":"항상 최선을 다해 완벽하게 일을 처리하고, 대충하거나 소홀하게 하지 않는다.","cefr":"B2","type":"idiom"},{"id":"idiom_0473","en":"is a laughing stock","definition":"are laughed at or mocked by everyone; someone who is ridiculed by others.","ko":"모두에게 조롱 혹은 비웃음거리가 됨","cefr":"B2","type":"idiom"},{"id":"idiom_0474","en":"bottom of the career ladder","definition":"in a low position in a work organisation or hierarchy","ko":"조직이나 직장 내에서 가장 낮은 위치에 있음","cefr":"B2","type":"idiom"},{"id":"idiom_0475","en":"dead-end job","definition":"A job that offers little or no chance of advancement or improvement in position, salary, or skills.","ko":"승진이나 발전 가능성이 없는 직업.","cefr":"B2","type":"idiom"},{"id":"idiom_0476","en":"run-of-the-mill","definition":"ordinary, average, or not special in any way; boring or routine.","ko":"평범하거나 특별하지 않은; 지루하거나 일상적인.","cefr":"B2","type":"idiom"},{"id":"idiom_0477","en":"get out of a rut","definition":"escape from a monotonous, boring situation","ko":"단조롭고 지루한 상황에서 벗어나다","cefr":"B2","type":"idiom"},{"id":"idiom_0478","en":"pulled out all the stops","definition":"made a great effort to do something well","ko":"무언가를 잘 해내기 위해 최선을 다했다","cefr":"B2","type":"idiom"},{"id":"idiom_0479","en":"got the sack","definition":"was dismissed from his job","ko":"직장에서 해고당했다","cefr":"B2","type":"idiom"},{"id":"idiom_0480","en":"stepped into his shoes","definition":"took over his job or responsibilities, especially after he left or was unable to continue.","ko":"그가 떠나거나 더 이상 계속할 수 없게 되었을 때 그의 일이나 책임을 맡다.","cefr":"B2","type":"idiom"},{"id":"idiom_0481","en":"rushed off his feet","definition":"Very busy; having too much to do in a short period of time.","ko":"매우 바쁨; 짧은 시간에 할 일이 너무 많음.","cefr":"B2","type":"idiom"},{"id":"idiom_0482","en":"had his work cut out","definition":"had something very difficult to do","ko":"매우 힘든 일을 맡았다","cefr":"B2","type":"idiom"},{"id":"idiom_0483","en":"headhunted","definition":"invited to join a new workplace which had noticed his talents","ko":"능력을 인정받아 새로운 일터에 스카웃됨","cefr":"B2","type":"idiom"},{"id":"idiom_0484","en":"climbed to the top of the career ladder","definition":"got to a top position in a work organisation or hierarchy","ko":"조직이나 직장에서 최고 위치에 오르다","cefr":"B2","type":"idiom"},{"id":"idiom_0485","en":"rushed off your feet","definition":"to be extremely busy, with too much to do and not enough time","ko":"할 일이 너무 많아 정신없이 바쁜 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0486","en":"snowed under","definition":"To be extremely busy, with too much work to do.","ko":"할 일이 너무 많아 매우 바쁜 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_0487","en":"got my hands full","definition":"To be very busy or occupied with tasks, often to the point of being unable to take on anything else.","ko":"일이 너무 많거나 바빠서 더 이상 아무 것도 할 수 없는 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_0488","en":"up to my eyes/ears in work","definition":"Extremely busy or overwhelmed with a large amount of work or tasks.","ko":"일이나 할 일이 너무 많아 매우 바쁘거나 벅찬 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_0489","en":"on the go","definition":"very busy, always active","ko":"아주 바쁘고 항상 활동적인","cefr":"B2","type":"idiom"},{"id":"idiom_0490","en":"put on hold","definition":"left until a later date (usually used in the passive)","ko":"나중으로 미뤄지다","cefr":"B2","type":"idiom"},{"id":"idiom_0491","en":"look great on paper","definition":"Describes something that seems perfect or impressive when considered theoretically or in writing, but may not work as well in real life.","ko":"이론적으로나 문서상으로는 완벽해 보이지만, 실제로는 잘 작동하지 않을 수 있음을 나타냅니다.","cefr":"B2","type":"idiom"},{"id":"idiom_0492","en":"behind the scenes","definition":"out of sight, hidden, or in a way that people are not aware of, often when something else is happening publicly","ko":"눈에 띄지 않게, 숨겨져서 혹은 사람들이 의식하지 못하는 방식으로, 종종 공개적으로 무언가가 일어날 때","cefr":"B2","type":"idiom"},{"id":"idiom_0493","en":"talk shop","definition":"talk about work when you are not at work","ko":"근무시간이 아닐 때 일에 대해 이야기하다","cefr":"B2","type":"idiom"},{"id":"idiom_0494","en":"look right/straight through someone","definition":"Behave as if you do not see someone, either because you do not notice them or because you are deliberately ignoring them.","ko":"누군가를 못 본 척하거나 일부러 무시하는 행동을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0495","en":"leave someone in the lurch","definition":"To abandon someone in a difficult situation when they need your help or support.","ko":"누군가가 도움이 필요할 때 곤경에 빠진 그들을 버리는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0496","en":"give someone a hard/rough/tough time","definition":"to make things difficult or unpleasant for someone, often by criticizing, teasing, or challenging them.","ko":"누군가를 비난하거나 놀리거나 도전하여 곤란하게 하거나 힘들게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0497","en":"keep a lid on something","definition":"To control or limit the level of something, especially to prevent it from increasing or becoming worse.","ko":"증가하거나 악화되는 것을 막기 위해 무언가를 통제하거나 제한하다","cefr":"B2","type":"idiom"},{"id":"idiom_0498","en":"let (yourself) go","definition":"either take less care of your appearance or relax completely and enjoy yourself","ko":"외모를 신경 쓰지 않거나 완전히 자유롭게 즐기다","cefr":"B2","type":"idiom"},{"id":"idiom_0499","en":"blow something out of (all) proportion","definition":"Behave as if something that has happened is much worse than it really is.","ko":"일어난 일이 실제보다 훨씬 더 나쁘다고 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0500","en":"thought nothing of it","definition":"Did something that other people found difficult very easily.","ko":"다른 사람들이 어렵다고 느끼는 일을 아주 쉽게 해냈다.","cefr":"B2","type":"idiom"},{"id":"idiom_0501","en":"it brought a lump to my throat","definition":"moved me so much that I wanted to cry","ko":"감동해서 울컥하다","cefr":"B2","type":"idiom"},{"id":"idiom_0502","en":"make the most of","definition":"take full advantage of something because it may not last long","ko":"무언가를 최대한 활용하다, 왜냐하면 오래가지 않을 수 있으니까","cefr":"B2","type":"idiom"},{"id":"idiom_0503","en":"hanging in the balance","definition":"No one knows what will happen to it in the future; its outcome is uncertain.","ko":"미래에 어떤 일이 일어날지 아무도 모른다; 결과가 불확실하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0504","en":"faded/paled into insignificance","definition":"did not seem at all important when compared to something else","ko":"다른 것에 비해 전혀 중요하지 않게 보였다","cefr":"B2","type":"idiom"},{"id":"idiom_0505","en":"wouldn’t dream of","definition":"would never do something because we think it is wrong","ko":"옳지 않다고 생각해서 절대 하지 않을 것이다","cefr":"B2","type":"idiom"},{"id":"idiom_0506","en":"come to terms with","definition":"start to accept emotionally and to deal with a difficult situation","ko":"어려운 상황을 감정적으로 받아들이고 대처하기 시작하다","cefr":"B2","type":"idiom"},{"id":"idiom_0507","en":"a dark horse","definition":"someone who is clever or skilful in a way that no one knew or expected","ko":"아무도 예상하지 못한 방식으로 재능이나 실력을 드러내는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0508","en":"a lone wolf","definition":"someone who does not mix socially with other people","ko":"다른 사람들과 어울리지 않는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0509","en":"a cold fish","definition":"someone who is not very friendly and does not show their feelings","ko":"별로 친절하지 않고 감정을 잘 드러내지 않는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0510","en":"a guinea pig","definition":"someone who acts as a subject in an experiment or trial of something","ko":"실험이나 시험 대상으로 쓰이는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0511","en":"a party animal","definition":"someone who loves parties and socialising","ko":"파티와 사교를 좋아하는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0512","en":"a fly on the wall","definition":"someone who would love to be present to see or hear something private or secret without being noticed","ko":"몰래 숨어서 비밀스러운 이야기를 듣고 싶은 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0513","en":"fly-on-the-wall","definition":"A documentary or style of filming that observes real-life situations as they happen, often unobtrusively or with hidden cameras, to capture authentic behavior.","ko":"실제 상황을 자연스럽게 관찰하고 기록하는 다큐멘터리 또는 촬영 방식으로, 종종 몰래카메라처럼 자연스러운 행동을 포착함.","cefr":"B2","type":"idiom"},{"id":"idiom_0514","en":"bark is worse than his bite","definition":"He may seem fierce or tough, but he is not really as bad or as harsh as he appears.","ko":"무섭거나 거칠어 보여도 실제로는 그렇지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_0515","en":"wouldn't hurt a fly","definition":"is totally harmless and would never hurt anyone","ko":"전혀 해가 없으며 누구에게도 해를 끼치지 않는다","cefr":"B2","type":"idiom"},{"id":"idiom_0516","en":"travel bug","definition":"a strong desire to travel","ko":"여행에 대한 강한 욕구","cefr":"B2","type":"idiom"},{"id":"idiom_0517","en":"got/taken the bit between her teeth","definition":"started to work or act in a very determined and energetic way, often after being hesitant or slow at first.","ko":"처음에는 망설이거나 느렸지만, 이후 매우 결연하고 활기차게 행동하거나 일하기 시작하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0518","en":"given me free rein","definition":"given me complete freedom to act or make decisions as I see fit.","ko":"제가 원하는 대로 행동하거나 결정할 수 있도록 완전한 자유를 줌.","cefr":"B2","type":"idiom"},{"id":"idiom_0519","en":"a little bird told me","definition":"Said when someone has told you a secret, but you do not want to say who.","ko":"누군가가 당신에게 비밀을 말했지만, 누군지 밝히고 싶지 않을 때 쓰는 말.","cefr":"B2","type":"idiom"},{"id":"idiom_0520","en":"made a beeline for","definition":"went quickly and directly to","ko":"빠르고 곧장 ~로 향하다","cefr":"B2","type":"idiom"},{"id":"idiom_0521","en":"butterflies in my stomach","definition":"to feel very nervous or anxious, usually because you are about to do something important or exciting","ko":"중요하거나 신나는 일을 앞두고 매우 긴장하거나 불안해하다","cefr":"B2","type":"idiom"},{"id":"idiom_0522","en":"made a real pig of myself","definition":"ate too much; overindulged in food, often to the point of feeling uncomfortable or embarrassed.","ko":"너무 많이 먹어서 불편하거나 창피함을 느낌","cefr":"B2","type":"idiom"},{"id":"idiom_0523","en":"chasing my tail","definition":"Doing a lot of activity or work but achieving little or making no real progress; being busy with unproductive tasks.","ko":"많은 활동을 하지만 실질적인 진전이 없는 상태; 비생산적인 일에 바쁘다.","cefr":"B2","type":"idiom"},{"id":"idiom_0524","en":"start the ball rolling","definition":"to begin an activity or process and encourage others to participate or continue it","ko":"활동이나 과정을 시작하고 다른 사람들이 참여하거나 계속하도록 격려하다","cefr":"B2","type":"idiom"},{"id":"idiom_0525","en":"the ball is in your court","definition":"You have to do something now before any progress can be made.","ko":"진전을 이루려면 이제 당신이 행동해야 한다는 뜻입니다.","cefr":"B2","type":"idiom"},{"id":"idiom_0526","en":"on the ball","definition":"quick to understand and react","ko":"빠르게 이해하고 반응하는","cefr":"B2","type":"idiom"},{"id":"idiom_0527","en":"do something off our own bat","definition":"on our own initiative, without being asked to by anyone else","ko":"자신의 주도적으로, 아무도 시키지 않았는데","cefr":"B2","type":"idiom"},{"id":"idiom_0528","en":"throw us a curveball","definition":"surprise us with an unexpected problem","ko":"예상치 못한 문제로 우리를 놀라게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0529","en":"play ball","definition":"co-operate in order to achieve something (usually used in a negative context)","ko":"무언가를 이루기 위해 협조하다 (주로 부정적 맥락에서 사용)","cefr":"B2","type":"idiom"},{"id":"idiom_0530","en":"on a level playing field","definition":"in a situation where everyone has the same opportunities and advantages; a fair situation","ko":"모두가 같은 기회와 이점을 가지는 상황; 공정한 상황","cefr":"B2","type":"idiom"},{"id":"idiom_0531","en":"play your cards right","definition":"Behave in a smart or strategic way to achieve your desired outcome.","ko":"원하는 결과를 얻기 위해 똑똑하게 또는 전략적으로 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0532","en":"put/lay your cards on the table","definition":"Tell someone honestly what you think or what you plan to do.","ko":"솔직하게 생각이나 계획을 말하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0533","en":"follow suit","definition":"do the same as everyone else has just done","ko":"다른 사람들이 한 대로 따라하다","cefr":"B2","type":"idiom"},{"id":"idiom_0534","en":"call someone's bluff","definition":"make someone prove that what they are saying is true or prove that they will really do what they say they will do","ko":"상대가 말한 것을 증명하게 하거나 정말로 행동하게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0535","en":"take the plunge","definition":"do something important or difficult that you’ve been thinking of doing for a long time","ko":"오랫동안 고민해 온 중요한 일이나 어려운 일을 실행하다","cefr":"B2","type":"idiom"},{"id":"idiom_0536","en":"go back to square one","definition":"to return to the starting point of a process or project because previous efforts have failed or produced no results.","ko":"이전의 노력이 실패하거나 결과가 없어서 처음으로 돌아가다.","cefr":"B2","type":"idiom"},{"id":"idiom_0537","en":"be wide of the mark","definition":"to be incorrect, inaccurate, or far from the intended target or answer","ko":"정확하지 않거나 완전히 빗나간 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0538","en":"do something on the spur of the moment","definition":"do something suddenly, without planning","ko":"계획 없이 갑자기 무언가를 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0539","en":"be on the cards","definition":"be likely to happen","ko":"일어날 가능성이 높다","cefr":"B2","type":"idiom"},{"id":"idiom_0540","en":"your best bet","definition":"the best thing you can do to achieve the result you want","ko":"원하는 결과를 얻기 위한 가장 좋은 방법","cefr":"B2","type":"idiom"},{"id":"idiom_0541","en":"when the chips are down","definition":"when you are in a difficult situation, especially one which tests whether you can trust people","ko":"신뢰를 시험하는 어려운 상황에 처했을 때","cefr":"B2","type":"idiom"},{"id":"idiom_0542","en":"makes your mouth water","definition":"Describes something, usually food, that looks, smells, or sounds so delicious that it makes you want to eat it immediately.","ko":"음식 등이 너무 맛있어 보여서 당장 먹고 싶어지는 것을 말함.","cefr":"B2","type":"idiom"},{"id":"idiom_0543","en":"has a sweet tooth","definition":"particularly likes sweet things","ko":"단 것을 매우 좋아하다","cefr":"B2","type":"idiom"},{"id":"idiom_0544","en":"whet your appetite","definition":"awaken a desire (for food or something else)","ko":"욕구(음식이나 다른 것에 대한)을 자극하다","cefr":"B2","type":"idiom"},{"id":"idiom_0545","en":"the icing on the cake","definition":"something that makes a good situation even better","ko":"좋은 상황을 더 좋게 만들어 주는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0546","en":"you can’t have your cake and eat it / you want to have your cake and eat it","definition":"Two good things are impossible to do or have at the same time; you can't enjoy both benefits without giving up one.","ko":"두 가지 좋은 것을 동시에 가질 수 없다는 뜻; 하나를 얻으려면 다른 하나를 포기해야 한다.","cefr":"B2","type":"idiom"},{"id":"idiom_0547","en":"leaves a sour taste in your mouth","definition":"To have an unpleasant memory or lingering bad feeling about something that happened.","ko":"무언가가 일어난 후 불쾌한 기억이나 감정이 남다.","cefr":"B2","type":"idiom"},{"id":"idiom_0548","en":"to the bitter end","definition":"see something through to the end even though it takes a long time and is difficult","ko":"힘들고 오래 걸리더라도 끝까지 해내다","cefr":"B2","type":"idiom"},{"id":"idiom_0549","en":"have egg on your face","definition":"be left feeling stupid or embarrassed because of something you did","ko":"무언가를 잘못해서 창피하거나 당황하다","cefr":"B2","type":"idiom"},{"id":"idiom_0550","en":"be the best/greatest thing since sliced bread","definition":"To be considered excellent, innovative, or extremely useful (informal).","ko":"아주 훌륭하거나 혁신적이거나 매우 유용하다고 여겨지는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0551","en":"be your bread and butter","definition":"Be an activity or job you do to get the money you need.","ko":"주로 생계를 이어가는 일 또는 활동","cefr":"B2","type":"idiom"},{"id":"idiom_0552","en":"bear fruit","definition":"produce a positive result","ko":"긍정적인 결과를 내다","cefr":"B2","type":"idiom"},{"id":"idiom_0553","en":"flavour of the month","definition":"something or someone that is very popular at the moment","ko":"지금 매우 인기 있는 것 또는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0554","en":"be past or pass your sell-by date","definition":"not wanted or used anymore because they are too old","ko":"너무 오래되어 더 이상 원하거나 사용하지 않는","cefr":"B2","type":"idiom"},{"id":"idiom_0555","en":"caught in the act","definition":"seen doing something wrong or forbidden while actually doing it","ko":"잘못하거나 금지된 일을 하는 중에 현장에서 들키다","cefr":"B2","type":"idiom"},{"id":"idiom_0556","en":"get her act together","definition":"organize herself more effectively","ko":"자신을 더 효과적으로 정리하다","cefr":"B2","type":"idiom"},{"id":"idiom_0557","en":"get in on the act","definition":"to take part in something exciting or profitable, often after seeing others benefit from it","ko":"다른 사람들이 이익을 보는 것을 보고 신나거나 이익이 되는 일에 참여하다","cefr":"B2","type":"idiom"},{"id":"idiom_0558","en":"putting on an act","definition":"pretending, not being genuine","ko":"가식적으로 행동하다, 진실하지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_0559","en":"balancing act","definition":"A situation where you try to give equal attention or importance to two or more different things, often with difficulty.","ko":"여러 가지를 동시에 신경 써야 하여 어려움을 겪는 상황.","cefr":"B2","type":"idiom"},{"id":"idiom_0560","en":"clean up their act","definition":"To start behaving in a more acceptable or responsible way, especially by stopping bad habits or actions that others disapprove of.","ko":"더 책임감 있고 바람직하게 행동하기 시작하다, 특히 나쁜 습관을 그만두면서.","cefr":"B2","type":"idiom"},{"id":"idiom_0561","en":"act your age","definition":"Don’t behave in a childish way; behave in a manner appropriate for your age.","ko":"유치하게 굴지 말고 나이에 맞게 행동하세요.","cefr":"B2","type":"idiom"},{"id":"idiom_0562","en":"acting the fool/goat","definition":"Behaving in a silly or playful way, often to make others laugh or to avoid being serious.","ko":"다른 사람을 웃기거나 진지함을 피하기 위해 바보처럼 혹은 장난스럽게 행동하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0563","en":"hive of activity","definition":"a very busy place (like a beehive) with people working hard all the time","ko":"사람들이 항상 바쁘게 일하는 매우 분주한 곳","cefr":"B2","type":"idiom"},{"id":"idiom_0564","en":"out of action","definition":"Not working or unable to participate in normal activities, often due to illness, injury, or malfunction.","ko":"질병, 부상, 고장 등으로 인해 정상적인 활동이나 일을 할 수 없는 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_0565","en":"back in action","definition":"To be able to work, perform, or participate again after a break, injury, or pause.","ko":"쉬거나 부상, 일시 중단 후 다시 일하거나 참여할 수 있게 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_0566","en":"get a slice/piece of the action","definition":"To take part in something exciting or profitable, often because others are already benefiting from it.","ko":"다른 사람들이 이미 이득을 보고 있는 일에 참여하다","cefr":"B2","type":"idiom"},{"id":"idiom_0567","en":"all talk and no action","definition":"Be someone who promises or says they will do a lot of exciting things, but doesn’t actually do them.","ko":"말은 번지르르하게 하지만 행동으로는 옮기지 않는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0568","en":"course of action","definition":"A way of acting or a plan that someone decides to take, especially in a formal or considered manner.","ko":"누군가가 공식적이거나 신중하게 선택한 행동 방법이나 계획.","cefr":"B2","type":"idiom"},{"id":"idiom_0569","en":"goes to the dogs","definition":"It goes from a good situation or condition to a bad one; deteriorates or declines in quality.","ko":"좋은 상태에서 나빠지거나 품질이 저하됨.","cefr":"B2","type":"idiom"},{"id":"idiom_0570","en":"put the cat among the pigeons","definition":"To do or say something that is likely to cause trouble, controversy, or a strong reaction among a group of people.","ko":"문제를 일으키거나 논란, 강한 반응을 불러일으킬 만한 일을 하거나 말하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0571","en":"not (enough) room to swing a cat","definition":"there is very little room or space somewhere","ko":"공간이 매우 협소함","cefr":"B2","type":"idiom"},{"id":"idiom_0572","en":"law of the jungle","definition":"a situation where people do whatever they want without caring about others, often in a selfish or ruthless way","ko":"사람들이 다른 이들을 신경 쓰지 않고 자기 멋대로 행동하는, 종종 이기적이거나 냉혹한 상황","cefr":"B2","type":"idiom"},{"id":"idiom_0573","en":"a real can of worms","definition":"a very complicated, difficult, or problematic situation","ko":"매우 복잡하고 어려운 혹은 문제투성이인 상황","cefr":"B2","type":"idiom"},{"id":"idiom_0574","en":"like water off a duck’s back","definition":"having no effect on someone, especially criticism or insults","ko":"누군가에게 전혀 영향이 없는, 특히 비판이나 모욕에 대해","cefr":"B2","type":"idiom"},{"id":"idiom_0575","en":"running round like headless chickens","definition":"being very busy and active but not achieving anything useful or effective","ko":"몹시 바쁘고 부산하지만 실질적으로 아무것도 이루지 못함","cefr":"B2","type":"idiom"},{"id":"idiom_0576","en":"snail mail","definition":"traditional postal mail (as opposed to email), often used humorously","ko":"전통적인 우편(이메일과 대비돼, 흔히 농담으로 사용됨)","cefr":"B2","type":"idiom"},{"id":"idiom_0577","en":"put out feelers","definition":"make informal enquiries; talk to people unofficially to see if someone is interested","ko":"비공식적으로 알아보다; 누군가 관심이 있는지 조심스럽게 타진하다","cefr":"B2","type":"idiom"},{"id":"idiom_0578","en":"bite the bullet","definition":"To face a difficult or unpleasant situation with courage and determination, instead of avoiding it.","ko":"해야 하니까 어렵거나 싫은 일을 억지로 하는 거예요.","cefr":"B2","type":"idiom"},{"id":"idiom_0579","en":"jump the gun","definition":"do something too soon, before you should do it","ko":"너무 서둘러서 시기상조로 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_0580","en":"stick to your guns","definition":"Don’t let other people change your mind, ideas, or principles; to remain firm in your beliefs or decisions even when others try to persuade you otherwise.","ko":"다른 사람이 생각이나 원칙을 바꾸게 두지 않고, 자신의 신념을 끝까지 지키다.","cefr":"B2","type":"idiom"},{"id":"idiom_0581","en":"look daggers at someone","definition":"To look at someone in a very angry or hateful way.","ko":"누군가를 매우 화난 또는 증오스럽게 바라보다.","cefr":"B2","type":"idiom"},{"id":"idiom_0582","en":"put the knife in","definition":"deliberately do or say something really hurtful to someone","ko":"일부러 누군가에게 정말 상처 주는 말을 하거나 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_0583","en":"twist the knife","definition":"do or say something which makes a bad or hurtful situation even worse","ko":"나쁜 상황을 더욱 악화시키다","cefr":"B2","type":"idiom"},{"id":"idiom_0584","en":"have a shot at","definition":"to try (something), especially something new or challenging","ko":"특히 새롭거나 도전적인 일을 시도하다","cefr":"B2","type":"idiom"},{"id":"idiom_0585","en":"in the firing line","definition":"in a position where people can criticize or blame you","ko":"비난이나 책임의 대상이 되는 위치에 있는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0586","en":"call the shots","definition":"be the person who makes all the important decisions","ko":"모든 중요한 결정을 내리는 사람이다","cefr":"B2","type":"idiom"},{"id":"idiom_0587","en":"caught in the crossfire","definition":"Involved in a situation where people around you are arguing or fighting, often unintentionally becoming affected by their conflict.","ko":"주변 사람들이 다투거나 싸우는 상황에 자신도 모르게 휘말려 영향을 받는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0588","en":"hold fire","definition":"wait and not take action yet","ko":"잠시 기다리고 아직 행동하지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_0589","en":"up in arms","definition":"angry and protesting loudly","ko":"화가 나서 크게 항의하는","cefr":"B2","type":"idiom"},{"id":"idiom_0590","en":"his own worst enemy","definition":"His own attitude or behavior will prevent him from reaching his goal.","ko":"자신의 태도나 행동이 목표 달성을 방해한다.","cefr":"B2","type":"idiom"},{"id":"idiom_0591","en":"fighting a losing battle","definition":"trying to achieve something that you will probably fail to achieve","ko":"아마도 실패할 일에 도전하다","cefr":"B2","type":"idiom"},{"id":"idiom_0592","en":"burn your bridges","definition":"do something that makes it impossible to go back to a situation you were in before","ko":"예전의 상황으로 돌아갈 수 없게 만들다","cefr":"B2","type":"idiom"},{"id":"idiom_0593","en":"have an axe to grind","definition":"To have a strong personal opinion, bias, or selfish motive that one wants to promote, often in a way that is not entirely objective.","ko":"자신의 이익이나 편견, 목적이 있는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0594","en":"when it comes to the crunch","definition":"when a situation becomes serious or difficult","ko":"상황이 진지하거나 어려워질 때","cefr":"B2","type":"idiom"},{"id":"idiom_0595","en":"a chink in his armour","definition":"a weak point in someone's character, argument, or defenses that can be exploited or taken advantage of.","ko":"누군가의 성격, 논리, 방어에서 이용될 수 있는 약점.","cefr":"B2","type":"idiom"},{"id":"idiom_0596","en":"have something on the brain","definition":"You can’t stop thinking or talking about one particular thing.","ko":"한 가지 생각이나 말을 멈추지 못한다.","cefr":"B2","type":"idiom"},{"id":"idiom_0597","en":"pick someone's brains","definition":"ask for information or advice from a person who knows more about something than you do.","ko":"나보다 더 잘 아는 사람에게 정보나 조언을 구하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0598","en":"brain drain","definition":"the movement of highly skilled and educated people from their own country to another one where they are paid more.","ko":"인재 유출: 높은 학력과 기술을 가진 사람들이 더 나은 보상을 위해 다른 나라로 이동하는 현상.","cefr":"B2","type":"idiom"},{"id":"idiom_0599","en":"be a load/weight off your mind","definition":"To feel relieved because a worry or concern has been removed.","ko":"걱정이나 근심이 사라져 안도감을 느끼다.","cefr":"B2","type":"idiom"},{"id":"idiom_0600","en":"have/keep an open mind","definition":"Wait until you have all the facts before forming an opinion.","ko":"모든 사실을 알기 전에는 판단을 내리지 마세요.","cefr":"B2","type":"idiom"},{"id":"idiom_0601","en":"have a mind of its own","definition":"Used to describe a machine or object that seems to act independently or unpredictably, not following the user's intentions.","ko":"기계나 물건이 사용자의 의도와 다르게, 마치 스스로 움직이는 것처럼 예측 불가능하게 동작함을 뜻함.","cefr":"B2","type":"idiom"},{"id":"idiom_0602","en":"make up your mind","definition":"To decide; to choose between options or come to a conclusion.","ko":"결정하다; 선택지들 중에서 고르거나 결론을 내리다.","cefr":"B2","type":"idiom"},{"id":"idiom_0603","en":"put/set someone's mind at rest","definition":"To help someone stop worrying or feeling anxious by providing reassurance or information.","ko":"안심시키거나 정보를 제공해 상대의 걱정이나 불안을 덜어주다.","cefr":"B2","type":"idiom"},{"id":"idiom_0604","en":"at the back of your mind","definition":"Always in your mind although you don’t spend too much time thinking about it.","ko":"자주 생각하지 않더라도 항상 마음 한 켠에 있는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0605","en":"in your mind’s eye","definition":"in your imagination or memory.","ko":"상상이나 기억 속에서.","cefr":"B2","type":"idiom"},{"id":"idiom_0606","en":"blood and guts","definition":"very violent (used to describe films, stories, or situations with a lot of graphic violence).","ko":"매우 폭력적인 (잔인한 장면이 많이 나오는 영화, 이야기, 상황 등에서 사용함).","cefr":"B2","type":"idiom"},{"id":"idiom_0607","en":"in cold blood / in a cold-blooded way","definition":"done in a cruelly planned and unemotional way.","ko":"잔인하게 계획적이고 감정 없이 행해진.","cefr":"B2","type":"idiom"},{"id":"idiom_0608","en":"like getting blood out of a stone","definition":"Very difficult to do, especially when trying to make someone give you information or something they don't want to give.","ko":"매우 하기 어렵고, 누군가가 주고 싶지 않은 정보를 얻으려 할 때 특히 어렵다.","cefr":"B2","type":"idiom"},{"id":"idiom_0609","en":"gut feeling/reaction","definition":"An instinctive feeling or reaction that is not based on logical reasoning but rather on intuition.","ko":"논리적 사고가 아니라 직감에서 비롯된 본능적인 느낌이나 반응.","cefr":"B2","type":"idiom"},{"id":"idiom_0610","en":"slog/sweat/work your guts out","definition":"To work extremely hard, often with great effort and determination.","ko":"엄청난 노력과 결심으로 매우 열심히 일하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0611","en":"relief in the air","definition":"A feeling or sense of relief that is noticeable or shared by a group of people in a particular place or situation.","ko":"특정 장소나 상황에서 여러 사람이 함께 느끼는 안도감","cefr":"B2","type":"idiom"},{"id":"idiom_0612","en":"up in the air","definition":"Not yet decided or settled; uncertain.","ko":"아직 결정되지 않았거나 불확실함.","cefr":"B2","type":"idiom"},{"id":"idiom_0613","en":"clear the air","definition":"To resolve misunderstandings or bad feelings between people, usually by talking openly about the issue.","ko":"clear the air는 나쁜 감정이나 오해를 없애려고 솔직하게 이야기하는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_0614","en":"a breath of fresh air","definition":"something or someone that is new, different, and exciting, often bringing a refreshing change to a situation.","ko":"새롭고 색다르며 흥미로운 사람이나 것, 상황에 활기를 불어넣는 존재.","cefr":"B2","type":"idiom"},{"id":"idiom_0615","en":"out of the blue","definition":"completely unexpectedly","ko":"완전히 예상치 못하게","cefr":"B2","type":"idiom"},{"id":"idiom_0616","en":"down-to-earth","definition":"very practical, realistic, and unpretentious; having a sensible and straightforward attitude.","ko":"매우 현실적이고 겸손하며 실속 있는 태도를 가진.","cefr":"B2","type":"idiom"},{"id":"idiom_0617","en":"come (back) down to earth with a bang","definition":"To suddenly return to reality after being excited, happy, or distracted, often in a way that is disappointing or sobering.","ko":"기쁨이나 들뜬 상태에서 실망스럽게도 갑자기 현실로 돌아오다.","cefr":"B2","type":"idiom"},{"id":"idiom_0618","en":"bites the dust","definition":"To fail, break down, or die; to come to an end or be defeated.","ko":"망가지다, 실패하다, 끝나다, 패배하다","cefr":"B2","type":"idiom"},{"id":"idiom_0619","en":"living on another planet","definition":"To be completely unaware of what is happening in the real world; to be out of touch with reality.","ko":"현실과 동떨어져 있는 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_0620","en":"over the moon","definition":"You are extremely happy or delighted about something.","ko":"무언가에 대해 매우 행복하거나 들떠 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0621","en":"hits rock bottom","definition":"To reach the lowest or worst possible point in a situation.","ko":"상황에서 최저점이나 최악의 상태에 이르다.","cefr":"B2","type":"idiom"},{"id":"idiom_0622","en":"find out how the land lies","definition":"To assess or investigate a situation before becoming involved or making a decision.","ko":"관여하거나 결정을 내리기 전에 상황을 파악하거나 조사하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0623","en":"upper-crust","definition":"They belong to a very high social class.","ko":"그들은 매우 높은 사회적 계층에 속한다.","cefr":"B2","type":"idiom"},{"id":"idiom_0624","en":"in the dark","definition":"not told important things that other people know","ko":"다른 사람들이 아는 중요한 사항을 알지 못함","cefr":"B2","type":"idiom"},{"id":"idiom_0625","en":"keeps you in the dark","definition":"not told important things that other people know","ko":"다른 사람들이 아는 중요한 것을 알지 못하다","cefr":"B2","type":"idiom"},{"id":"idiom_0626","en":"in your element","definition":"You are happy and relaxed in a situation because you are good at the things it involves.","ko":"상황에서 자신이 잘하는 일을 하므로 행복하고 편안하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0627","en":"out of your element","definition":"You feel unhappy or uncomfortable because you are not familiar with or good at the tasks or environment involved.","ko":"과제나 환경에 익숙하지 않아 불편하거나 어색하게 느끼는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0628","en":"long time no see","definition":"Used as a greeting when you meet someone you haven't seen for a long period.","ko":"오랜만에 만나는 사람에게 쓰는 인사말.","cefr":"B2","type":"idiom"},{"id":"idiom_0629","en":"it's a long story","definition":"It’s complicated or takes too long to explain.","ko":"복잡하거나 설명하기에 시간이 오래 걸린다.","cefr":"B2","type":"idiom"},{"id":"idiom_0630","en":"how long is a piece of string?","definition":"That’s an impossible question to answer.","ko":"답할 수 없는 질문이다.","cefr":"B2","type":"idiom"},{"id":"idiom_0631","en":"a list as long as your arm","definition":"A very long list indeed.","ko":"매우 긴 목록.","cefr":"B2","type":"idiom"},{"id":"idiom_0632","en":"long-winded","definition":"Too long and boring (about a story, lecture, or speech).","ko":"너무 길고 지루한 (이야기나 강의, 연설 등에 대해).","cefr":"B2","type":"idiom"},{"id":"idiom_0633","en":"a long haul","definition":"A task or process that is not going to be easy and will take a long time.","ko":"쉽지 않고 오랜 시간이 걸리는 일이나 과정.","cefr":"B2","type":"idiom"},{"id":"idiom_0634","en":"have a long face","definition":"To look sad, depressed, or disappointed.","ko":"슬프거나 실망한 표정을 짓다","cefr":"B2","type":"idiom"},{"id":"idiom_0635","en":"go to great lengths","definition":"To make a very big effort to achieve something, often more than what is expected or necessary.","ko":"기대한 것보다 훨씬 더 큰 노력을 기울여 무언가를 성취하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0636","en":"go to any lengths","definition":"To do whatever is necessary, even if it is difficult or extreme, to achieve a goal.","ko":"목표를 이루기 위해 어렵거나 극단적인 일도 서슴지 않는다.","cefr":"B2","type":"idiom"},{"id":"idiom_0637","en":"go a long way","definition":"To be very successful or make significant progress, often rising to a high level in one's profession or endeavors.","ko":"매우 성공하거나 큰 발전을 이루어 자신의 분야에서 높은 수준에 오르는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0638","en":"go back a long way","definition":"Have known each other for many years.","ko":"누군가를 아주 오래전부터 알고 지내다","cefr":"B2","type":"idiom"},{"id":"idiom_0639","en":"come a long way","definition":"To have made significant progress or improvement over time.","ko":"시간이 지나면서 큰 발전이나 향상을 이루다.","cefr":"B2","type":"idiom"},{"id":"idiom_0640","en":"take a long, hard look","definition":"To examine or consider something very carefully and thoroughly, often in order to make an important decision or judgment.","ko":"어떤 것을 매우 신중하고 꼼꼼하게 검토하다, 주로 중요한 결정을 내리기 위해.","cefr":"B2","type":"idiom"},{"id":"idiom_0641","en":"be on someone's back","definition":"constantly ask someone to do something or criticise them in an annoying way","ko":"누군가에게 끊임없이 잔소리하거나 귀찮게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0642","en":"you wouldn't be sorry / you'd be pleased/glad/happy to see the back of someone/something","definition":"You'd be glad when someone leaves or something ends because you don't like that person or thing.","ko":"누군가 떠나거나 무언가가 끝나서 기쁜(좋아하지 않았기 때문).","cefr":"B2","type":"idiom"},{"id":"idiom_0643","en":"could do something with one arm/hand tied behind your back","definition":"To be able to do something very easily, without much effort.","ko":"아주 쉽게, 별다른 노력 없이 무언가를 할 수 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0644","en":"stab someone in the back","definition":"do something harmful to a person who trusted you, especially by betraying them secretly","ko":"믿었던 사람에게 해를 끼치다, 특히 몰래 배신하는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0645","en":"do something when/while someone's back is turned","definition":"do something while someone can't see what you are doing (usually something that person would not approve of)","ko":"누군가가 못 볼 때 무언가를 하다 (보통 상대가 반대할 만한 일)","cefr":"B2","type":"idiom"},{"id":"idiom_0646","en":"you scratch my back and I'll scratch yours","definition":"If you help me, I'll help you; mutual assistance for mutual benefit.","ko":"서로 돕고 이익을 주고받는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0647","en":"know a place/person/thing like the back of your hand","definition":"To know a place, person, or thing extremely well; to be very familiar with it.","ko":"장소, 사람, 사물을 매우 잘 알다; 매우 익숙하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0648","en":"on the back burner","definition":"isn't being dealt with now but hasn't been totally forgotten","ko":"지금은 다루지 않지만 완전히 잊힌 것은 아님","cefr":"B2","type":"idiom"},{"id":"idiom_0649","en":"at/in the back of beyond","definition":"A place that is extremely remote or far away from any town or civilization.","ko":"도시나 문명과 아주 멀리 떨어진 외딴 곳.","cefr":"B2","type":"idiom"},{"id":"idiom_0650","en":"take a back seat","definition":"to allow someone or something else to become more important or prominent while you become less involved or less important.","ko":"다른 사람이나 일이 더 중요해지도록 자신의 역할을 줄이다","cefr":"B2","type":"idiom"},{"id":"idiom_0651","en":"came/fell off the back of a lorry","definition":"Used humorously to suggest that something was probably stolen, especially when its origin is suspicious or unclear.","ko":"출처가 수상하거나 훔친 것임을 농담 삼아 암시할 때 사용함.","cefr":"B2","type":"idiom"},{"id":"idiom_0652","en":"by/through the back door","definition":"It comes in a way that is not honest or official.","ko":"정직하거나 공식적이지 않은 방식으로 이루어진다.","cefr":"B2","type":"idiom"},{"id":"idiom_0653","en":"leant/bent over backwards","definition":"tried very hard to help or please someone, often more than is expected or necessary","ko":"누군가를 도와주거나 기쁘게 하려고 기대 이상으로 매우 애썼다","cefr":"B2","type":"idiom"},{"id":"idiom_0654","en":"left without a backward glance","definition":"left with no regrets or sad feelings","ko":"아쉬움이나 슬픔 없이 떠나다","cefr":"B2","type":"idiom"},{"id":"idiom_0655","en":"make yourself at home","definition":"To relax and behave as if you were in your own house; to feel comfortable and at ease in someone else's place.","ko":"남의 집에서도 내 집처럼 편안하게 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0656","en":"as safe as houses","definition":"extremely safe","ko":"매우 안전한","cefr":"B2","type":"idiom"},{"id":"idiom_0657","en":"come home to me","definition":"To become fully understood, realized, or appreciated, often after some time has passed.","ko":"시간이 지난 후에야 완전히 이해하거나 깨닫게 되다","cefr":"B2","type":"idiom"},{"id":"idiom_0658","en":"brought home to me","definition":"made me understand, usually something unpleasant","ko":"보통 불쾌한 무언가를 깨닫게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0659","en":"got my foot in the door","definition":"started working at a low level in an organisation because you want to get a better job in the same organisation later on","ko":"조직에서 더 나은 직업을 얻기 위해 낮은 직급에서 시작한 것","cefr":"B2","type":"idiom"},{"id":"idiom_0660","en":"hold the key to","definition":"to provide the explanation for something you could not previously understand; to be the crucial factor in solving a problem or mystery.","ko":"문제나 수수께끼를 푸는 데 결정적인 요소","cefr":"B2","type":"idiom"},{"id":"idiom_0661","en":"flew off the handle","definition":"reacted in a very angry way (informal)","ko":"매우 화나게 반응하다(비격식적 표현)","cefr":"B2","type":"idiom"},{"id":"idiom_0662","en":"sit on the fence","definition":"delay making a decision or fail to choose between two alternatives","ko":"어느 편을 들지, 결정을 할지 미루다","cefr":"B2","type":"idiom"},{"id":"idiom_0663","en":"come down on one side or the other","definition":"To make a decision or choose between two options or opinions.","ko":"두 가지 선택지나 의견 중 하나를 결정하거나 선택하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0664","en":"hit the ceiling/roof","definition":"To react with sudden and intense anger.","ko":"갑작스럽고 격렬하게 화를 내다.","cefr":"B2","type":"idiom"},{"id":"idiom_0665","en":"got out of bed on the wrong side","definition":"got up in a bad mood and stayed in a bad mood all day","ko":"기분이 나쁘게 일어나 하루 종일 그랬다","cefr":"B2","type":"idiom"},{"id":"idiom_0666","en":"burning the candle at both ends","definition":"To overwork yourself by doing too many things, especially by staying up late and getting up early, which can lead to exhaustion.","ko":"아침부터 밤늦게까지 너무 무리해서 일하다","cefr":"B2","type":"idiom"},{"id":"idiom_0667","en":"put me in the picture","definition":"explained the situation to me; gave me the necessary information to understand what is happening","ko":"상황을 설명해주다; 무슨 일이 일어나는지 이해할 수 있도록 필요한 정보를 주다","cefr":"B2","type":"idiom"},{"id":"idiom_0668","en":"take a leaf out of his girlfriend’s book","definition":"To copy or imitate something that someone else does, often because it has brought them success or advantage.","ko":"누군가가 성공하거나 이익을 본 것을 따라 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0669","en":"keep someone in the picture","definition":"To keep someone informed or updated about a situation or development.","ko":"누군가에게 상황이나 발전에 대해 계속 알려주다.","cefr":"B2","type":"idiom"},{"id":"idiom_0670","en":"open your heart","definition":"To share your deepest feelings, thoughts, or emotions honestly and openly with someone.","ko":"누군가에게 자신의 깊은 감정이나 생각을 솔직하게 털어놓다.","cefr":"B2","type":"idiom"},{"id":"idiom_0671","en":"bare your heart/soul","definition":"To share your deepest, most personal or secret feelings, often of an emotional or dramatic nature, with someone else.","ko":"자신의 가장 깊고 개인적인 감정을 누군가에게 털어놓다.","cefr":"B2","type":"idiom"},{"id":"idiom_0672","en":"pour your heart out","definition":"To share your deepest feelings, worries, or secrets with someone, often in an emotional way.","ko":"마음속 깊은 감정이나 걱정, 비밀을 누군가에게 감정적으로 털어놓다.","cefr":"B2","type":"idiom"},{"id":"idiom_0673","en":"your heart misses/skips a beat","definition":"You suddenly feel so excited, surprised, or frightened that your heart seems to stop or beat faster for a moment.","ko":"갑자기 너무 흥분하거나 놀라거나 무서워서 순간 심장이 멎거나 더 빨리 뛰는 것처럼 느낄 때.","cefr":"B2","type":"idiom"},{"id":"idiom_0674","en":"someone’s heart is in the right place","definition":"someone is good even if they sometimes behave the wrong way","ko":"가끔 잘못된 행동을 해도 본래 착한 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0675","en":"have a change of heart","definition":"To change your opinion or the way you feel about something.","ko":"무엇인가에 대한 생각이나 감정을 바꾸다.","cefr":"B2","type":"idiom"},{"id":"idiom_0676","en":"break someone’s heart","definition":"make someone very sad (often someone who loves you)","ko":"누군가를 매우 슬프게 하다 (주로 당신을 사랑하는 사람)","cefr":"B2","type":"idiom"},{"id":"idiom_0677","en":"your heart sinks","definition":"You start to feel sad, disappointed, or worried, often because something bad or unexpected has happened.","ko":"뭔가 나쁘거나 예상치 못한 일이 생겨 슬프거나 실망하거나 걱정되기 시작하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0678","en":"a man/woman after my own heart","definition":"someone who you admire because they do or believe the same as you","ko":"나와 같은 생각이나 취향을 가진 사람이어서 존경하는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0679","en":"talk to someone heart-to-heart / have a heart-to-heart","definition":"have a serious conversation and express your feelings openly","ko":"진지하게 대화하며 자신의 감정을 솔직하게 표현하다","cefr":"B2","type":"idiom"},{"id":"idiom_0680","en":"take something to heart","definition":"To take something (usually criticism or advice) seriously and be deeply affected by it.","ko":"무언가(주로 비판이나 조언)을 진지하게 받아들이고 깊이 영향을 받다","cefr":"B2","type":"idiom"},{"id":"idiom_0681","en":"lose heart","definition":"To stop believing that you can succeed; to become discouraged or lose confidence.","ko":"희망이나 자신감을 잃다, 낙담하다","cefr":"B2","type":"idiom"},{"id":"idiom_0682","en":"to your heart’s content","definition":"You do something as much as you want to because you enjoy it.","ko":"즐거워서 원하는 만큼 무엇인가를 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0683","en":"put your heart and soul into something","definition":"To put a great deal of effort, passion, and determination into something; to be fully committed and dedicated.","ko":"무언가에 온 힘과 열정, 노력을 다하다; 전적으로 헌신하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0684","en":"set your heart on something / have your heart set on something","definition":"To be very determined to achieve or obtain something; to strongly desire something.","ko":"무언가를 강하게 원하거나 이루려는 결심이 굳다.","cefr":"B2","type":"idiom"},{"id":"idiom_0685","en":"know something by heart / learn something off by heart","definition":"memorise something so that you can recite it perfectly","ko":"완벽하게 외워서 암송할 수 있다","cefr":"B2","type":"idiom"},{"id":"idiom_0686","en":"paths cross","definition":"to meet someone, often unexpectedly or by chance","ko":"누군가를 우연히 만나다","cefr":"B2","type":"idiom"},{"id":"idiom_0687","en":"stuck in a rut","definition":"in a boring situation, with no hope of excitement, or future prospects","ko":"지루하고 희망 없는 상황에 빠진 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0688","en":"driving me round the bend","definition":"making me angry and frustrated","ko":"나를 화나고 좌절하게 한다","cefr":"B2","type":"idiom"},{"id":"idiom_0689","en":"right up your street/alley","definition":"perfect for you; exactly what interests you","ko":"딱 네 스타일; 네 관심사에 꼭 맞는","cefr":"B2","type":"idiom"},{"id":"idiom_0690","en":"middle-of-the-road","definition":"neither left-wing nor right-wing, has no radical views","ko":"좌파도 아니고 우파도 아닌, 극단적인 견해가 없는","cefr":"B2","type":"idiom"},{"id":"idiom_0691","en":"on the right/wrong track","definition":"Thinking or acting in a way that is likely to lead to success or the correct result (right track), or in a way that is likely to lead to failure or an incorrect result (wrong track).","ko":"성공이나 올바른 결과로 이어질 가능성이 높은 방식으로 생각하거나 행동하는 것(올바른 길을 가다), 또는 실패나 잘못된 결과로 이어질 가능성이 높은 방식(잘못된 길을 가다).","cefr":"B2","type":"idiom"},{"id":"idiom_0692","en":"an uphill battle/fight/struggle","definition":"a very difficult task","ko":"매우 어려운 일","cefr":"B2","type":"idiom"},{"id":"idiom_0693","en":"gone downhill","definition":"Something that used to be good has become worse over time.","ko":"한때는 좋았던 것이 시간이 지나면서 나빠졌다.","cefr":"B2","type":"idiom"},{"id":"idiom_0694","en":"off the beaten track","definition":"in a very isolated place","ko":"매우 외진 곳에서","cefr":"B2","type":"idiom"},{"id":"idiom_0695","en":"at a crossroads","definition":"At a decisive or critical point where an important decision must be made that will have significant consequences.","ko":"중요한 결정을 내려야 하는 중대한 순간에 있음.","cefr":"B2","type":"idiom"},{"id":"idiom_0696","en":"a dead end","definition":"It has no future or prospects; a situation, job, or path that leads nowhere.","ko":"미래나 전망이 없는, 더 이상 나아갈 수 없는 상황이나 직업, 길.","cefr":"B2","type":"idiom"},{"id":"idiom_0697","en":"go/get from A to B","definition":"to make simple or typical journeys, usually referring to the basic act of traveling from one place to another without complications.","ko":"복잡함 없이 단순히 한 장소에서 다른 장소로 이동하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0698","en":"put the village on the map","definition":"To make the village well-known or famous, especially when it was previously unknown.","ko":"이전에는 잘 알려지지 않았던 마을을 유명하게 만들다.","cefr":"B2","type":"idiom"},{"id":"idiom_0699","en":"hit the road","definition":"to start a journey or leave a place, especially by car or on a trip.","ko":"여행을 시작하거나 특히 자동차로 어딘가를 출발하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0700","en":"road rage","definition":"violent incidents resulting from traffic disputes","ko":"교통 다툼에서 발생하는 폭력적 사건","cefr":"B2","type":"idiom"},{"id":"idiom_0701","en":"keep your head","definition":"keep calm, especially in a difficult or dangerous situation","ko":"어려운 상황이나 위험한 상황에서 침착함을 유지하다","cefr":"B2","type":"idiom"},{"id":"idiom_0702","en":"lose your head","definition":"To panic or lose control of your emotions, especially in a stressful situation.","ko":"스트레스를 받을 때 당황하거나 감정 통제를 잃다","cefr":"B2","type":"idiom"},{"id":"idiom_0703","en":"laugh/scream/shout your head off","definition":"To laugh, scream, or shout very loudly and energetically, often in an uncontrolled or exaggerated way (informal).","ko":"아주 크고 에너지 넘치게 웃거나, 소리치거나, 외치는 것. 종종 과장되고 통제되지 않은 방식으로 사용됨.","cefr":"B2","type":"idiom"},{"id":"idiom_0704","en":"be banging or hitting your head against a brick wall","definition":"To keep trying to achieve something that is very difficult or impossible, especially because other people are not cooperating or listening.","ko":"다른 사람이 협조하지 않거나 듣지 않아서 매우 어렵거나 불가능한 일을 계속 시도하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0705","en":"bring something to a head / something comes to a head","definition":"An unpleasant situation becomes so bad or intense that it must be addressed or resolved immediately.","ko":"불쾌한 상황이 너무 심해져 즉각적으로 해결해야 하는 단계에 이르다.","cefr":"B2","type":"idiom"},{"id":"idiom_0706","en":"shouting their heads off","definition":"To shout very much and very loudly.","ko":"목청껏 소리치다","cefr":"B2","type":"idiom"},{"id":"idiom_0707","en":"banging your head against a brick wall","definition":"To keep trying to achieve something that is very difficult or impossible, especially when your efforts are ignored or not successful.","ko":"매우 어렵거나 불가능한 일을 계속 시도하지만, 노력은 무시되거나 성공하지 못하는 경우.","cefr":"B2","type":"idiom"},{"id":"idiom_0708","en":"came to a head","definition":"An unpleasant situation became so bad or intense that it had to be dealt with immediately.","ko":"불쾌한 상황이 너무 심각해져 즉시 처리해야만 했다.","cefr":"B2","type":"idiom"},{"id":"idiom_0709","en":"put ideas into someone’s head","definition":"make someone want to do something they had not wanted to do before (usually something foolish or unwise)","ko":"원래 하고 싶지 않던 일을 하도록 만들다 (대개 어리석거나 경솔한 일)","cefr":"B2","type":"idiom"},{"id":"idiom_0710","en":"get your head (a)round (usually – can’t get (my) head (a)round)","definition":"come to fully accept or understand something (informal)","ko":"완전히 받아들이거나 이해하다","cefr":"B2","type":"idiom"},{"id":"idiom_0711","en":"off the top of your head","definition":"without thinking about it for very long or looking at something that has been written about it","ko":"깊이 생각하거나 찾아보지 않고","cefr":"B2","type":"idiom"},{"id":"idiom_0712","en":"turns heads","definition":"people notice that person because they look interesting or attractive","ko":"흥미롭거나 매력적인 외모로 사람들의 시선을 끌다","cefr":"B2","type":"idiom"},{"id":"idiom_0713","en":"knock that on the head","definition":"put a stop to it (informal)","ko":"즉시 중단시키다 (비공식적)","cefr":"B2","type":"idiom"},{"id":"idiom_0714","en":"keep his head above water","definition":"To manage to survive or cope, especially with work or financial difficulties, often just barely.","ko":"특히 경제적이나 일과 관련된 어려움 속에서도 간신히 버티다.","cefr":"B2","type":"idiom"},{"id":"idiom_0715","en":"bites/snaps their heads off","definition":"speaks to them angrily, often suddenly or without clear reason","ko":"화가 난 어조로, 종종 갑자기 혹은 명확한 이유 없이 말하다","cefr":"B2","type":"idiom"},{"id":"idiom_0716","en":"keep my head down","definition":"say as little as possible in order to avoid arguments","ko":"말을 최대한 아껴서 논쟁을 피하다","cefr":"B2","type":"idiom"},{"id":"idiom_0717","en":"jazz it up","definition":"make something more lively or interesting","ko":"무언가를 더 활기차거나 흥미롭게 만들다","cefr":"B2","type":"idiom"},{"id":"idiom_0718","en":"sang her heart out","definition":"sang with great passion or effort","ko":"온 마음을 다해 열정적으로 노래했다","cefr":"B2","type":"idiom"},{"id":"idiom_0719","en":"sound like a broken record","definition":"To keep repeating the same thing over and over, often to the annoyance of others.","ko":"같은 말을 계속 반복해서 남을 짜증나게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0720","en":"music to my ears","definition":"something that is very pleasant or gratifying to hear","ko":"듣기에 매우 기분 좋은 말","cefr":"B2","type":"idiom"},{"id":"idiom_0721","en":"struck a chord","definition":"caused someone to feel sympathy, emotion, or enthusiasm","ko":"누군가에게 공감, 감정, 또는 열정을 불러일으켰다","cefr":"B2","type":"idiom"},{"id":"idiom_0722","en":"changed his tune","definition":"changed his opinion or attitude","ko":"의견이나 태도를 바꾸다","cefr":"B2","type":"idiom"},{"id":"idiom_0723","en":"fine-tuning","definition":"making small improvements to something to make it as good as possible","ko":"더 나은 결과를 위해 세밀하게 조정함","cefr":"B2","type":"idiom"},{"id":"idiom_0724","en":"making a song and dance about","definition":"making an unnecessary fuss about something","ko":"별일 아닌 일에 유난을 떨다","cefr":"B2","type":"idiom"},{"id":"idiom_0725","en":"set the stage for","definition":"create a situation that allows something else to happen","ko":"무언가가 일어날 수 있는 기반을 마련하다","cefr":"B2","type":"idiom"},{"id":"idiom_0726","en":"making a spectacle of yourself","definition":"behaving in a way that attracts other people’s attention, usually because you are doing something stupid or silly","ko":"주로 어리석거나 우스꽝스러운 행동으로 다른 사람들의 관심을 끌다","cefr":"B2","type":"idiom"},{"id":"idiom_0727","en":"been in the spotlight","definition":"been the centre of attention, often in public media","ko":"언론 등에서 주목을 받다","cefr":"B2","type":"idiom"},{"id":"idiom_0728","en":"the curtain has fallen on","definition":"Used to indicate that something, such as a career, event, or period, has come to an end.","ko":"경력, 사건, 시기 등이 끝났음을 나타내는 데 사용됨.","cefr":"B2","type":"idiom"},{"id":"idiom_0729","en":"the show must go on","definition":"No matter what difficulties or setbacks occur, an activity or event must continue as planned.","ko":"어떠한 어려움이나 방해가 있어도, 활동이나 행사는 계획대로 계속되어야 한다.","cefr":"B2","type":"idiom"},{"id":"idiom_0730","en":"in line for","definition":"likely to get (used about something good)","ko":"좋은 것을 받을 가능성이 있음","cefr":"B2","type":"idiom"},{"id":"idiom_0731","en":"out of line","definition":"not suitable, that should not have been said (or sometimes done)","ko":"부적절하거나 해서는 안 될 말이나 행동","cefr":"B2","type":"idiom"},{"id":"idiom_0732","en":"along the lines of","definition":"similar to; in a way that is like or resembles something else","ko":"비슷한; 다른 것과 유사한 방식으로","cefr":"B2","type":"idiom"},{"id":"idiom_0733","en":"step out of line","definition":"behave in a way that is not what is expected of you","ko":"기대와 다르게 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_0734","en":"line of work","definition":"the type of job or profession someone has","ko":"누군가가 가진 직업이나 직종","cefr":"B2","type":"idiom"},{"id":"idiom_0735","en":"go along/on the right lines","definition":"be doing something in a way that will bring good results","ko":"좋은 결과를 가져올 방식으로 무언가를 하고 있다","cefr":"B2","type":"idiom"},{"id":"idiom_0736","en":"along/on the same lines","definition":"of a similar kind (sometimes in a similar way)","ko":"비슷한 종류의 (때때로 비슷한 방식으로)","cefr":"B2","type":"idiom"},{"id":"idiom_0737","en":"draw the line","definition":"To set a limit on what one is willing to do or accept; to distinguish between acceptable and unacceptable behavior.","ko":"자신이 할 수 있는 일이나 받아들일 수 있는 것에 한계를 두는 것; 허용 가능한 행동과 허용할 수 없는 행동을 구분하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0738","en":"draw the line at something","definition":"not do something because you think it is wrong or too extreme","ko":"너무 극단적이거나 옳지 않다고 생각해서 어떤 행동은 하지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_0739","en":"draw a line under something","definition":"decide that something is finished and you are not going to think about it again","ko":"무엇인가 끝났다고 결정하고 더 이상 생각하지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_0740","en":"there is a fine/thin line between one thing and another","definition":"Two things are very similar, although the second thing is bad while the first is not.","ko":"두 가지가 매우 비슷하지만 두 번째는 나쁜 것이고 첫 번째는 그렇지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_0741","en":"drop me a line","definition":"send me a short letter, postcard or e-mail","ko":"짧은 편지, 엽서 또는 이메일을 보내다","cefr":"B2","type":"idiom"},{"id":"idiom_0742","en":"reading between the lines","definition":"To understand the hidden or unspoken meaning in something that is said or written.","ko":"말이나 글에 숨겨진 의미나 속뜻을 이해하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0743","en":"sign on the dotted line","definition":"To formally agree to something, usually by signing a legal or official document.","ko":"대개 공식 문서나 법적 서류에 서명함으로써 무언가에 공식적으로 동의하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0744","en":"the bottom line","definition":"the most important fact or the final outcome of a situation, especially after considering all the details.","ko":"모든 세부 사항을 고려한 후의 가장 중요한 사실이나 최종 결론.","cefr":"B2","type":"idiom"},{"id":"idiom_0745","en":"stand on your own two feet","definition":"be independent; look after yourself","ko":"독립하다; 스스로를 돌보다","cefr":"B2","type":"idiom"},{"id":"idiom_0746","en":"rushed off my feet","definition":"Extremely busy or overwhelmed with work or tasks; having a lot to do in a short amount of time.","ko":"일이나 할 일이 너무 많아 매우 바쁘거나 압도당한 상태; 짧은 시간 안에 해야 할 일이 많은 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0747","en":"kept both feet on the ground","definition":"remained normal and realistic","ko":"겸손하고 현실적으로 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_0748","en":"got cold feet","definition":"became afraid to do something, especially at the last moment","ko":"특히 마지막 순간에 뭔가를 할 용기가 없어짐","cefr":"B2","type":"idiom"},{"id":"idiom_0749","en":"find your feet","definition":"To become comfortable in a new situation or environment; to adjust and feel confident or capable.","ko":"새로운 환경에 적응하고 자신감을 가지게 되다","cefr":"B2","type":"idiom"},{"id":"idiom_0750","en":"got off on the wrong foot","definition":"Our relationship started badly; to begin a relationship or activity in an unfavorable or awkward way.","ko":"우리 관계는 좋지 않게 시작했다; 관계나 활동을 불리하거나 어색하게 시작하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0751","en":"under my feet","definition":"in my way, disturbing my activities","ko":"방해가 되는, 내 활동을 방해하는","cefr":"B2","type":"idiom"},{"id":"idiom_0752","en":"landed/fallen on his feet","definition":"been very lucky or successful in a difficult situation","ko":"어려운 상황에서 매우 운이 좋았거나 성공한 경우","cefr":"B2","type":"idiom"},{"id":"idiom_0753","en":"got itchy feet","definition":"got a desire to travel","ko":"여행을 하고 싶은 마음이 생기는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0754","en":"put my foot in it","definition":"accidentally said or did something very embarrassing or tactless, often without realizing it at the time.","ko":"본의 아니게 매우 민망하거나 무례한 말을 하거나 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_0755","en":"put your foot down","definition":"to assert your authority or make a firm decision, especially when refusing to allow something","ko":"권위를 내세우거나 단호한 결정을 내리다, 특히 거절할 때","cefr":"B2","type":"idiom"},{"id":"idiom_0756","en":"followed in his father’s footsteps","definition":"took the same course of action as somebody else","ko":"누구의 길을 따르다","cefr":"B2","type":"idiom"},{"id":"idiom_0757","en":"dragging her heels","definition":"deliberately being slow","ko":"일부러 천천히 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0758","en":"digging their heels in","definition":"refusing to change their position or opinion, especially when others are trying to persuade them to do so.","ko":"다른 사람이 설득해도 자신의 의견이나 입장을 고수함.","cefr":"B2","type":"idiom"},{"id":"idiom_0759","en":"keeps us on our toes","definition":"keeps us busy; makes us give our full energy to our work","ko":"우리를 바쁘게 하다; 일에 온 힘을 쏟게 만든다","cefr":"B2","type":"idiom"},{"id":"idiom_0760","en":"go one better","definition":"do more or do something better than it has been done before","ko":"이전보다 더 잘하거나 더 많이 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0761","en":"against our better judgement","definition":"although we did not think it was a sensible thing to do","ko":"합리적이지 않다고 생각했음에도 불구하고","cefr":"B2","type":"idiom"},{"id":"idiom_0762","en":"stand her in good stead","definition":"To be useful or beneficial to her in the future, especially in a way that helps her handle new situations or challenges.","ko":"미래에 도움이 되거나 유익하게 작용함, 특히 새로운 상황이나 도전에 대처하는 데.","cefr":"B2","type":"idiom"},{"id":"idiom_0763","en":"thought better of","definition":"Decided not to do something after reconsidering, usually because it might not be a good idea.","ko":"재고 끝에 그 일이 좋은 생각이 아닐 것 같아 하지 않기로 결정하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0764","en":"second best","definition":"not as good as the thing you really want","ko":"정말 원하는 것만큼 좋지 않은 것","cefr":"B2","type":"idiom"},{"id":"idiom_0765","en":"get the best of both worlds","definition":"have the advantages of two different things at the same time","ko":"두 가지의 장점을 동시에 누리다","cefr":"B2","type":"idiom"},{"id":"idiom_0766","en":"for the best","definition":"unpleasant now but will turn out well in the future","ko":"지금은 힘들지만 미래에는 좋게 될 일","cefr":"B2","type":"idiom"},{"id":"idiom_0767","en":"make the best of a bad job","definition":"Be positive about a situation that you do not like but cannot change.","ko":"싫지만 바꿀 수 없는 상황을 긍정적으로 받아들이다.","cefr":"B2","type":"idiom"},{"id":"idiom_0768","en":"be on your best behaviour","definition":"make an effort to behave as well as possible","ko":"최선을 다해 예의 바르게 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_0769","en":"in a bad way","definition":"in a poor condition","ko":"상태가 안 좋다","cefr":"B2","type":"idiom"},{"id":"idiom_0770","en":"gone from bad to worse","definition":"got even worse than it was before","ko":"상황이 더 악화되었다","cefr":"B2","type":"idiom"},{"id":"idiom_0771","en":"given it up as a bad job","definition":"Stopped trying to do something because it seemed pointless or too difficult to continue.","ko":"계속하는 것이 무의미하거나 너무 어렵다고 느껴서 그만두었다.","cefr":"B2","type":"idiom"},{"id":"idiom_0772","en":"if the worst comes to the worst","definition":"if the situation becomes very difficult or serious","ko":"상황이 정말 심각해지거나 힘들어질 때","cefr":"B2","type":"idiom"},{"id":"idiom_0773","en":"I have a bone to pick with you","definition":"You have done something that has annoyed me, and we must discuss it.","ko":"네가 나를 화나게 한 일이 있어서 꼭 얘기해야 해.","cefr":"B2","type":"idiom"},{"id":"idiom_0774","en":"bare bones","definition":"The most basic, essential, or fundamental aspects of something, without any extras or details.","ko":"어떤 것의 가장 기본적이고 필수적인 부분, 추가적인 내용이나 세부사항 없이.","cefr":"B2","type":"idiom"},{"id":"idiom_0775","en":"a chip on her shoulder","definition":"Blames other people for something negative that has happened to her and goes on carrying these feelings for ever.","ko":"자신에게 일어난 부정적인 일을 남 탓으로 돌리며 그 감정을 계속 간직한다.","cefr":"B2","type":"idiom"},{"id":"idiom_0776","en":"a shoulder to cry on","definition":"Sympathy or support in time of trouble.","ko":"어려울 때 동정이나 위로를 받는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0777","en":"stand shoulder to shoulder with you","definition":"Support you in a difficult time.","ko":"힘든 시기에 당신을 지지하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0778","en":"gave me the cold shoulder","definition":"Reacted to me in an unfriendly or cold way for no obvious reason.","ko":"아무 이유 없이 나에게 차갑거나 무뚝뚝하게 대했다","cefr":"B2","type":"idiom"},{"id":"idiom_0779","en":"twisted my arm","definition":"Persuaded me to do something I didn’t really want to do.","ko":"마지못해 하고 싶지 않은 일을 하게 설득당했다.","cefr":"B2","type":"idiom"},{"id":"idiom_0780","en":"keep/hold her at arm’s length","definition":"To maintain a distance or avoid becoming too close or involved with her.","ko":"거리를 두거나 너무 가까워지거나 깊이 관여하지 않는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0781","en":"pulling your leg","definition":"Joking or teasing someone by telling them something that is not true, usually in a playful way.","ko":"장난스럽게 사실이 아닌 말을 하며 누군가를 놀리는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0782","en":"hasn’t (got) a leg to stand on","definition":"Has nothing to support his claim or position.","ko":"주장이나 입장을 뒷받침할 근거가 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_0783","en":"push the boat out","definition":"spend a lot of money, usually because you are celebrating","ko":"축하를 위해 많은 돈을 쓰다","cefr":"B2","type":"idiom"},{"id":"idiom_0784","en":"rock the boat","definition":"do or say something that causes problems, usually when you try to change a situation that other people do not want to change","ko":"다른 사람들이 변화를 원하지 않는 상황에서 문제를 일으키거나 말을 해서 상황을 흔들다","cefr":"B2","type":"idiom"},{"id":"idiom_0785","en":"miss the boat","definition":"be too late to get something you want","ko":"원하는 것을 얻기에는 너무 늦다","cefr":"B2","type":"idiom"},{"id":"idiom_0786","en":"burn your boats/bridges","definition":"do something that makes it impossible for you to go back to the situation you were in before","ko":"되돌릴 수 없는 일을 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0787","en":"be in the same boat","definition":"To be in the same, usually difficult, situation as someone else.","ko":"다른 사람들과 같은, 대체로 어려운 상황에 처해 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0788","en":"steer clear of","definition":"avoid someone or something because it is dangerous for you","ko":"누군가 또는 무언가가 위험해서 피하다","cefr":"B2","type":"idiom"},{"id":"idiom_0789","en":"sail close to the wind","definition":"to do something that is risky or almost illegal; to behave in a way that is nearly improper or dangerous.","ko":"위험하거나 거의 불법적인 일을 하다; 거의 부적절하거나 위험하게 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0790","en":"be plain sailing","definition":"To be very easy or straightforward, without any difficulties.","ko":"아주 쉽거나 아무런 어려움이 없는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0791","en":"be in the doldrums","definition":"(of a business) be not very successful; (of a person) feel sad and without energy","ko":"침체기에 있거나 우울한 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0792","en":"put/stick your oar in","definition":"Join a discussion or give your opinion when it is not wanted or when you are not invited (informal).","ko":"원하지 않거나 초대받지 않았을 때 대화에 끼어들거나 의견을 내는 것 (비공식적).","cefr":"B2","type":"idiom"},{"id":"idiom_0793","en":"show someone the ropes","definition":"To teach someone how to do a particular job or activity, especially by explaining the basic procedures and rules.","ko":"누군가에게 일이나 활동의 기본적인 절차와 규칙을 가르쳐 주는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0794","en":"be a nervous wreck","definition":"To be extremely anxious, worried, or stressed, often to the point of being unable to function normally.","ko":"극도로 불안하고 걱정하거나 스트레스를 받아 정상적으로 행동할 수 없는 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_0795","en":"clear the decks","definition":"To finish or remove all unnecessary tasks or obstacles in order to prepare for something important or to be ready for action.","ko":"중요한 일을 위해 모든 불필요한 일이나 장애물을 정리하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0796","en":"be (all) at sea","definition":"To be confused or unsure about what to do; to feel lost or bewildered.","ko":"무엇을 해야 할지 몰라 혼란스럽거나 어리둥절한 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_0797","en":"as blind as a bat","definition":"Unable to see well; having very poor eyesight.","ko":"시력이 매우 나쁨; 거의 보지 못함.","cefr":"B2","type":"idiom"},{"id":"idiom_0798","en":"like a bat out of hell","definition":"moving very fast indeed","ko":"빛의 속도로","cefr":"B2","type":"idiom"},{"id":"idiom_0799","en":"like a bear with a sore head","definition":"Very bad-tempered or irritable; acting in a grumpy or angry manner.","ko":"아주 화가 나 있고 기분이 나쁜 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_0800","en":"as free as a bird","definition":"To feel or be completely free, without any worries, restrictions, or responsibilities.","ko":"근심, 제약, 책임 없이 완전히 자유롭다고 느끼다.","cefr":"B2","type":"idiom"},{"id":"idiom_0801","en":"like a red rag to a bull","definition":"Something that is likely to make someone very angry or provoke a strong, negative reaction.","ko":"누군가를 매우 화나게 하거나 강한 부정적 반응을 유발할 만한 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0802","en":"like something the cat brought/dragged in","definition":"Looking very scruffy, untidy, or messy, as if one has been through a rough experience.","ko":"매우 흐트러지고 지저분해 보여 힘든 일을 겪은 것처럼 보인다.","cefr":"B2","type":"idiom"},{"id":"idiom_0803","en":"as slippery as an eel","definition":"Describes someone who is difficult to catch, control, or pin down, often because they are evasive or constantly changing their position or attitude.","ko":"누군가를 붙잡거나 통제하거나 딱 잡아내기 어려운 사람을 묘사함. 주로 교묘하게 빠져나가거나 입장을 자주 바꾸는 경우.","cefr":"B2","type":"idiom"},{"id":"idiom_0804","en":"like a fish out of water","definition":"uncomfortable because you are different from other people","ko":"다른 사람들과 달라서 불편함을 느끼는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0805","en":"as sly/cunning as a fox","definition":"Very clever, crafty, or deceitful, especially in achieving one's goals.","ko":"매우 영리하고 교활하거나 속임수가 능란한, 특히 자신의 목적을 이룰 때.","cefr":"B2","type":"idiom"},{"id":"idiom_0806","en":"has eyes like a hawk","definition":"sees everything; never misses anything","ko":"모든 것을 본다; 놓치는 것이 없다","cefr":"B2","type":"idiom"},{"id":"idiom_0807","en":"as strong as an ox","definition":"very strong","ko":"아주 힘이 세다","cefr":"B2","type":"idiom"},{"id":"idiom_0808","en":"as far as the eye could see","definition":"Extending over a vast area; visible for a great distance, often so far that the end cannot be seen.","ko":"광대한 지역에 걸쳐 펼쳐져 끝이 보이지 않을 정도로 멀리까지 보이는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0809","en":"as plain as the nose on your face","definition":"very easy to see or obvious to everyone","ko":"모두에게 너무도 뚜렷하고 분명한","cefr":"B2","type":"idiom"},{"id":"idiom_0810","en":"as ugly as sin","definition":"very ugly indeed","ko":"엄청나게 못생긴","cefr":"B2","type":"idiom"},{"id":"idiom_0811","en":"as light as a feather","definition":"Extremely light in weight; almost weightless.","ko":"매우 가벼워서 거의 무게가 없는.","cefr":"B2","type":"idiom"},{"id":"idiom_0812","en":"as heavy as lead","definition":"very heavy","ko":"아주 무거운","cefr":"B2","type":"idiom"},{"id":"idiom_0813","en":"like the plague","definition":"To avoid someone or something completely because it is unpleasant or undesirable.","ko":"불쾌하거나 원하지 않는 사람이나 사물을 완전히 피하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0814","en":"a memory like a sieve","definition":"a very bad memory; the tendency to forget things easily.","ko":"아주 잘 잊어버리는 나쁜 기억력.","cefr":"B2","type":"idiom"},{"id":"idiom_0815","en":"like greased lightning","definition":"very quickly indeed","ko":"아주 빠르게","cefr":"B2","type":"idiom"},{"id":"idiom_0816","en":"play it by ear","definition":"respond to the situation as it occurs, don’t decide what to do beforehand","ko":"상황에 따라 즉각적으로 반응하고, 미리 정하지 않는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0817","en":"play by ear","definition":"To do something without a plan, improvising as you go; in music, to play a tune by listening rather than reading sheet music.","ko":"계획 없이 즉흥적으로 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0818","en":"couldn’t believe my ears","definition":"To be extremely surprised or shocked by what one hears.","ko":"들을 때 매우 놀라거나 충격을 받다.","cefr":"B2","type":"idiom"},{"id":"idiom_0819","en":"goes in one ear and out the other","definition":"Said when someone doesn’t listen or pay attention, or forgets things immediately.","ko":"누군가가 말을 귀담아듣지 않거나 바로 잊어버릴 때 쓰는 표현.","cefr":"B2","type":"idiom"},{"id":"idiom_0820","en":"I’m all ears","definition":"I’m very keen to hear what you have to tell me.","ko":"네가 해줄 이야기를 정말 듣고 싶어.","cefr":"B2","type":"idiom"},{"id":"idiom_0821","en":"lip service","definition":"To express support or agreement for something verbally, but not follow through with actions.","ko":"말로만 지지나 동의를 표현하고 실제 행동은 하지 않음.","cefr":"B2","type":"idiom"},{"id":"idiom_0822","en":"my lips are sealed","definition":"I shall keep the secret / tell no one","ko":"비밀을 지키다 / 아무에게도 말하지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_0823","en":"word of mouth","definition":"Information or recommendations passed from person to person through conversation rather than through written or formal means.","ko":"공식적이거나 문서화된 방법이 아닌, 사람들이 대화로 서로 전하는 정보나 추천.","cefr":"B2","type":"idiom"},{"id":"idiom_0824","en":"mouth-watering / making my mouth water","definition":"Describes food that looks or smells so delicious that it makes you want to eat it immediately.","ko":"음식이 너무 맛있어 보이거나 냄새가 좋아서 당장 먹고 싶게 만드는 상태를 설명함.","cefr":"B2","type":"idiom"},{"id":"idiom_0825","en":"poking/sticking your nose into other people’s business","definition":"To interfere in matters that do not concern you; to be nosy or meddlesome.","ko":"자신과 상관없는 일에 간섭하다; 참견하거나 오지랖이 넓다.","cefr":"B2","type":"idiom"},{"id":"idiom_0826","en":"turn your nose up at","definition":"To refuse something because you think it is not good enough for you; to show disdain or contempt for something.","ko":"자신에게 충분하지 않다고 생각해서 거절하거나, 경멸을 드러내다.","cefr":"B2","type":"idiom"},{"id":"idiom_0827","en":"gets right up everybody’s nose","definition":"annoys or irritates everyone","ko":"모두를 짜증나게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0828","en":"in the teeth of","definition":"despite; in direct opposition to something or facing strong difficulty or resistance","ko":"…에도 불구하고; 강한 어려움이나 저항을 무릅쓰고","cefr":"B2","type":"idiom"},{"id":"idiom_0829","en":"by the skin of my teeth","definition":"To barely succeed at something or narrowly escape a disaster.","ko":"간신히 성공하거나 아슬아슬하게 위기를 모면함.","cefr":"B2","type":"idiom"},{"id":"idiom_0830","en":"grit our teeth","definition":"To accept a difficult or unpleasant situation and deal with it with determination and perseverance.","ko":"어려운 상황이나 불쾌한 상황을 받아들이고 결연한 의지와 인내심으로 극복하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0831","en":"lying through his teeth","definition":"telling a deliberate lie","ko":"뻔뻔하게 거짓말하다","cefr":"B2","type":"idiom"},{"id":"idiom_0832","en":"bit my tongue","definition":"remained silent; didn’t react","ko":"침묵했다; 반응하지 않았다","cefr":"B2","type":"idiom"},{"id":"idiom_0833","en":"on the tip of my tongue","definition":"I know it and will be able to remember it very soon.","ko":"나는 알고 있고 곧 기억해낼 수 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0834","en":"common ground","definition":"things we agree on; similar opinions and experience","ko":"공통점, 공감대","cefr":"B2","type":"idiom"},{"id":"idiom_0835","en":"gaining ground","definition":"becoming more popular or accepted; making progress or advancing in a particular area.","ko":"점점 더 대중적이거나 받아들여짐; 특정 분야에서 진전을 보임","cefr":"B2","type":"idiom"},{"id":"idiom_0836","en":"cut the ground from under the feet of","definition":"To make someone's position or argument weaker by doing or saying something more effective.","ko":"더 효과적인 행동이나 말로 상대의 입장이나 주장을 약화시키다.","cefr":"B2","type":"idiom"},{"id":"idiom_0837","en":"hold/stand her ground","definition":"refuse to change her opinion or behaviour, especially when under pressure or in a difficult situation.","ko":"특히 압력을 받거나 어려운 상황에서도 의견이나 행동을 바꾸기를 거부하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0838","en":"on dangerous ground","definition":"To hold a view or opinion that will probably offend or upset people, or to be in a risky or sensitive situation.","ko":"사람들을 불쾌하게 하거나 위험하거나 민감한 상황에 처해 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0839","en":"give ground","definition":"to change your opinion or accept the other side’s position, especially in an argument or negotiation","ko":"특히 논쟁이나 협상에서 자신의 입장을 바꾸거나 상대방의 입장을 받아들이다","cefr":"B2","type":"idiom"},{"id":"idiom_0840","en":"shifting her ground","definition":"changing her opinion or argument, especially in a discussion or debate.","ko":"토론이나 논쟁에서 자주 입장이나 의견을 바꾸는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0841","en":"gets a project/idea off the ground","definition":"To help a project or idea begin successfully or to get it started.","ko":"프로젝트나 아이디어가 성공적으로 시작하도록 돕다","cefr":"B2","type":"idiom"},{"id":"idiom_0842","en":"gets in on the ground floor","definition":"become involved in something right at the beginning (and which is often successful later)","ko":"처음부터 어떤 일에 참여하다 (나중에 종종 성공하는 일에)","cefr":"B2","type":"idiom"},{"id":"idiom_0843","en":"prepares the ground","definition":"create a good or suitable situation for something to take place","ko":"무언가가 일어날 수 있도록 좋은 환경을 만들다","cefr":"B2","type":"idiom"},{"id":"idiom_0844","en":"wished the ground would swallow me up","definition":"Wished I could just disappear, usually because of embarrassment or shame.","ko":"창피하거나 부끄러워서 사라지고 싶다는 마음.","cefr":"B2","type":"idiom"},{"id":"idiom_0845","en":"thick/thin on the ground","definition":"To be present in large numbers (thick) or very few (thin); used to describe the abundance or scarcity of something.","ko":"매우 많거나 매우 적다; 어떤 것이 풍부하거나 드물다는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_0846","en":"suits me down to the ground","definition":"suits me perfectly; is exactly what I want or need.","ko":"나에게 딱 맞는다; 내가 원하는 것이나 필요한 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_0847","en":"gone to ground","definition":"To hide or disappear, especially to avoid being found or to escape attention.","ko":"특히 들키거나 주목받지 않으려고 숨거나 사라지다.","cefr":"B2","type":"idiom"},{"id":"idiom_0848","en":"stamping/stomping ground","definition":"A place where someone spent a lot of time, especially in their youth or earlier years; a familiar or favorite place.","ko":"젊었을 때 등 오랜 시간을 보내던 친숙하거나 좋아하던 장소.","cefr":"B2","type":"idiom"},{"id":"idiom_0849","en":"at her fingertips","definition":"immediately available or accessible","ko":"즉시 사용할 수 있거나 접근 가능한","cefr":"B2","type":"idiom"},{"id":"idiom_0850","en":"keep your fingers crossed","definition":"To hope that things will happen in the way you want; to wish for good luck.","ko":"모든 일이 원하는 대로 되길 바란다; 행운을 빈다.","cefr":"B2","type":"idiom"},{"id":"idiom_0851","en":"put his finger on","definition":"to identify or pinpoint exactly what is wrong or the cause of a problem","ko":"정확히 무엇이 문제인지 또는 원인인지 짚어내다","cefr":"B2","type":"idiom"},{"id":"idiom_0852","en":"lifts a finger","definition":"to make any effort to help, usually used in the negative to indicate someone is not helping at all","ko":"도움을 주기 위해 어떤 노력을 하다(주로 부정적으로, 전혀 도와주지 않을 때 씀)","cefr":"B2","type":"idiom"},{"id":"idiom_0853","en":"got his fingers burnt","definition":"Suffered as a result of an action; lost money or was hurt, often due to taking a risk or making a mistake.","ko":"위험을 감수하거나 실수로 인해 손해를 보거나 피해를 입음.","cefr":"B2","type":"idiom"},{"id":"idiom_0854","en":"given the thumbs up/down","definition":"To approve (thumbs up) or reject (thumbs down) something or someone.","ko":"무엇인가를 승인하거나 거절하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0855","en":"sticks/stands out like a sore thumb","definition":"looks different from everything else in its environment (in a negative sense)","ko":"주변과 확연히 다르게, 부정적으로 눈에 띈다","cefr":"B2","type":"idiom"},{"id":"idiom_0856","en":"as a rule of thumb","definition":"a general, useful rule or guideline based on experience rather than a strict law.","ko":"경험을 바탕으로 한 일반적인 유용한 기준, 엄격한 법칙은 아님","cefr":"B2","type":"idiom"},{"id":"idiom_0857","en":"given me a free hand","definition":"Allows me to take whatever action I want to; gives me complete freedom to make decisions or act as I see fit.","ko":"내가 원하는 대로 자유롭게 행동할 수 있도록 완전한 권한을 줌.","cefr":"B2","type":"idiom"},{"id":"idiom_0858","en":"turn his hand to","definition":"has the skill or ability to do unfamiliar jobs without any previous experience","ko":"사전 경험 없이도 새로운 일을 잘 해낼 수 있는 능력이 있다","cefr":"B2","type":"idiom"},{"id":"idiom_0859","en":"got out of hand","definition":"got out of control","ko":"통제에서 벗어나다","cefr":"B2","type":"idiom"},{"id":"idiom_0860","en":"first-hand","definition":"Directly experienced or obtained personally, rather than through another person or source.","ko":"직접 경험하거나 본인의 힘으로 얻은 것, 다른 사람이나 출처를 통하지 않음.","cefr":"B2","type":"idiom"},{"id":"idiom_0861","en":"changed hands","definition":"been sold to a new owner","ko":"새로운 소유주에게 팔렸다","cefr":"B2","type":"idiom"},{"id":"idiom_0862","en":"have my hands full","definition":"am very busy / have a lot of things to do","ko":"매우 바쁘다 / 할 일이 많다","cefr":"B2","type":"idiom"},{"id":"idiom_0863","en":"try my hand at","definition":"To attempt to do something for the first time, especially as an experiment or to see if one enjoys or is good at it.","ko":"무엇인가를 처음 시도해보는 것, 특히 자신이 좋아하거나 잘하는지 보기 위해.","cefr":"B2","type":"idiom"},{"id":"idiom_0864","en":"keep my hand in","definition":"to continue practicing something so as not to lose skill or knowledge in it","ko":"실력이나 지식을 잃지 않도록 계속 연습하다","cefr":"B2","type":"idiom"},{"id":"idiom_0865","en":"to hand","definition":"available; nearby","ko":"이용 가능함; 가까이에 있음","cefr":"B2","type":"idiom"},{"id":"idiom_0866","en":"give me a hand","definition":"help me, for example to carry or lift something","ko":"무언가를 들거나 옮기는 데 도와주세요","cefr":"B2","type":"idiom"},{"id":"idiom_0867","en":"washed my hands of","definition":"stopped being involved in or took no further responsibility for something","ko":"어떤 일에 더 이상 관여하거나 책임지지 않게 되다","cefr":"B2","type":"idiom"},{"id":"idiom_0868","en":"get into gear","definition":"start working effectively or with energy","ko":"효율적이거나 에너지가 넘치게 일을 시작하다","cefr":"B2","type":"idiom"},{"id":"idiom_0869","en":"real back-seat driver","definition":"someone who gives unwanted advice or criticism, especially when someone else is doing something","ko":"남이 무언가를 할 때 원치 않는 조언이나 비판을 하는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0870","en":"put the brakes on","definition":"To slow down or stop something that is happening, especially to prevent it from continuing or getting out of control.","ko":"너무 빨리 가는 것을 늦추거나 멈추다","cefr":"B2","type":"idiom"},{"id":"idiom_0871","en":"ticking over","definition":"working quietly and smoothly, without problems","ko":"조용하고 순조롭게, 문제 없이 진행되는 상태","cefr":"B2","type":"idiom"},{"id":"idiom_0872","en":"let off steam","definition":"express strong emotions or energy by doing something active or noisy","ko":"강한 감정이나 에너지를 활동적이거나 시끄러운 것으로 표출하다","cefr":"B2","type":"idiom"},{"id":"idiom_0873","en":"programmed","definition":"always doing the same thing in the same way, like a computer","ko":"컴퓨터처럼 항상 같은 방식으로 똑같은 일을 한다","cefr":"B2","type":"idiom"},{"id":"idiom_0874","en":"get your lines/wires crossed","definition":"to have a misunderstanding or miscommunication with someone, often resulting in confusion or mistakes.","ko":"누군가와 오해나 의사소통 착오가 생겨 혼란이나 실수를 초래하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0875","en":"are on the same wavelength as someone","definition":"You view the world or think in the same way as them.","ko":"누군가와 생각이나 관점이 같다","cefr":"B2","type":"idiom"},{"id":"idiom_0876","en":"blow a fuse/gasket","definition":"To lose your temper and react very angrily to an event.","ko":"어떤 일로 인해 화를 참지 못하고 크게 분노하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0877","en":"give someone a buzz","definition":"To phone or call someone, usually in an informal or casual way.","ko":"누군가에게 가볍게 전화하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0878","en":"back-pedalling","definition":"beginning to say the opposite of what was said before; reversing a previous position","ko":"이전에 한 말을 번복하거나 입장을 바꾸기 시작하다","cefr":"B2","type":"idiom"},{"id":"idiom_0879","en":"put/throw a spanner in the works","definition":"To spoil something, such as a plan, or prevent it from succeeding.","ko":"계획과 같은 무언가를 망치거나 성공을 방해하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0880","en":"meltdown","definition":"a complete failure; a situation where everything goes wrong","ko":"완전한 실패; 모든 것이 엉망이 되는 상황","cefr":"B2","type":"idiom"},{"id":"idiom_0881","en":"in the pipeline","definition":"being discussed, prepared, or planned but not public yet","ko":"논의되거나 준비 또는 기획 중이지만 아직 공개되지 않은","cefr":"B2","type":"idiom"},{"id":"idiom_0882","en":"make/pull a face","definition":"show that you do not like something by making an unpleasant expression","ko":"불쾌한 표정을 지어 싫어함을 표현하다","cefr":"B2","type":"idiom"},{"id":"idiom_0883","en":"keep a straight face","definition":"not laugh or change your expression even though you want to laugh","ko":"웃고 싶어도 표정을 바꾸지 않고 참다","cefr":"B2","type":"idiom"},{"id":"idiom_0884","en":"put a brave face on something","definition":"pretend you are happy about something when you are not happy","ko":"기쁘지 않으면서도 기쁜 척하다","cefr":"B2","type":"idiom"},{"id":"idiom_0885","en":"take something at face value","definition":"Accept something as it appears, without questioning or doubting its truth or considering any hidden meaning.","ko":"의심하거나 숨은 의미를 생각하지 않고 겉모습 그대로 받아들이다.","cefr":"B2","type":"idiom"},{"id":"idiom_0886","en":"on the face of it","definition":"according to the appearance of something; as something seems at first glance, without deeper investigation","ko":"겉보기에는, 처음 보기에는, 깊이 따지지 않고","cefr":"B2","type":"idiom"},{"id":"idiom_0887","en":"face to face","definition":"with another person in their presence rather than, say, by phone or letter","ko":"전화나 편지가 아닌, 직접 다른 사람을 만나서","cefr":"B2","type":"idiom"},{"id":"idiom_0888","en":"keep your hair on","definition":"Stay calm; don't get angry or upset.","ko":"침착해라; 화내거나 흥분하지 마라.","cefr":"B2","type":"idiom"},{"id":"idiom_0889","en":"tearing/pulling her hair out","definition":"To be extremely anxious, frustrated, or stressed, often because of a difficult or overwhelming situation.","ko":"어려운 상황 때문에 매우 불안하거나 스트레스를 받는 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_0890","en":"didn't turn a hair","definition":"showed no reaction at all","ko":"아무런 반응을 보이지 않았다","cefr":"B2","type":"idiom"},{"id":"idiom_0891","en":"at each other's throats","definition":"arguing in a very angry way","ko":"격하게 다투다","cefr":"B2","type":"idiom"},{"id":"idiom_0892","en":"make a clean breast of it","definition":"To confess fully and honestly, especially about something one has done wrong, in order to relieve guilt.","ko":"자신이 저지른 잘못을 완전히 솔직하게 털어놓아 죄책감을 덜다.","cefr":"B2","type":"idiom"},{"id":"idiom_0893","en":"breathing down his neck","definition":"paying close attention to what he is doing in an annoying or threatening way","ko":"귀찮거나 위협적인 방식으로 지켜보다","cefr":"B2","type":"idiom"},{"id":"idiom_0894","en":"a real pain in the neck","definition":"Someone or something that is very annoying or bothersome.","ko":"매우 성가시거나 짜증나는 사람 또는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0895","en":"got it off his chest","definition":"told someone about something that was bothering him, usually a secret or worry, in order to feel relieved","ko":"마음을 괴롭히던 일을 털어놓아 마음이 홀가분해지다","cefr":"B2","type":"idiom"},{"id":"idiom_0896","en":"ramming it down his throat","definition":"Forcing someone to accept or listen to your opinions or beliefs, often in an aggressive or insistent way.","ko":"자신의 의견이나 신념을 강압적으로 또는 집요하게 강요하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0897","en":"giving him the cold shoulder","definition":"ignoring him in a deliberate way","ko":"일부러 무시하다","cefr":"B2","type":"idiom"},{"id":"idiom_0898","en":"couldn't believe my eyes","definition":"To be extremely surprised or shocked by what one is seeing; to find something visually unbelievable.","ko":"눈으로 본 것이 믿기 어려울 정도로 매우 놀라다.","cefr":"B2","type":"idiom"},{"id":"idiom_0899","en":"couldn't keep my eyes off","definition":"couldn't stop looking at someone or something because they are very attractive, interesting, or captivating.","ko":"매우 매력적이거나 흥미로워서 누군가나 무언가에게서 시선을 뗄 수 없었다.","cefr":"B2","type":"idiom"},{"id":"idiom_0900","en":"catch her eye","definition":"get her attention; make her look at me","ko":"그녀의 관심을 끌다","cefr":"B2","type":"idiom"},{"id":"idiom_0901","en":"keep an eye on","definition":"To watch or monitor something or someone carefully.","ko":"무엇이나 누구를 주의 깊게 지켜보다.","cefr":"B2","type":"idiom"},{"id":"idiom_0902","en":"turn a blind eye","definition":"ignore behaviour which you know is wrong","ko":"옳지 않다는 것을 알면서 행동을 무시하다","cefr":"B2","type":"idiom"},{"id":"idiom_0903","en":"with your eyes open","definition":"aware of all the problems or difficulties that could arise in a situation; fully informed before making a decision","ko":"상황에서 발생할 수 있는 모든 문제나 어려움을 충분히 인식하고 있음; 결정을 내리기 전에 완전히 파악함","cefr":"B2","type":"idiom"},{"id":"idiom_0904","en":"see eye to eye","definition":"to agree with someone or have the same opinion as them","ko":"누군가와 의견이 같다.","cefr":"B2","type":"idiom"},{"id":"idiom_0905","en":"raised a few eyebrows","definition":"To cause surprise, shock, or mild disapproval among people.","ko":"사람들에게 놀람, 충격 또는 약간의 불만을 불러일으키다.","cefr":"B2","type":"idiom"},{"id":"idiom_0906","en":"run/cast your eye over","definition":"To have a quick look at something, usually to check or review it briefly.","ko":"무언가를 빠르게 확인하거나 검토하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0907","en":"on the blink","definition":"beginning to break down and go wrong, probably because it is old","ko":"오래되어 고장이 나기 시작하다","cefr":"B2","type":"idiom"},{"id":"idiom_0908","en":"have/keep one eye on","definition":"To observe or monitor something or someone carefully, often while doing something else.","ko":"무언가를 하면서 동시에 다른 것 또는 누군가를 주의 깊게 지켜보다.","cefr":"B2","type":"idiom"},{"id":"idiom_0909","en":"didn't bat an eyelid","definition":"didn't react at all; showed no surprise, emotion, or concern in response to something unexpected or shocking.","ko":"전혀 반응하지 않다; 예상치 못한 일이 일어나도 놀라거나 감정을 드러내지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_0910","en":"caught my eye","definition":"Something that attracted my attention or made me notice it.","ko":"내 관심을 끌거나 내가 주목하게 만든 것.","cefr":"B2","type":"idiom"},{"id":"idiom_0911","en":"opened my eyes to","definition":"made me understand or realize something for the first time; made me aware of something I hadn't noticed before.","ko":"처음으로 무언가를 깨닫게 해주다","cefr":"B2","type":"idiom"},{"id":"idiom_0912","en":"a real eye-opener","definition":"an event or situation that I unexpectedly learnt something from","ko":"예상치 못하게 무언가를 배운 사건이나 상황","cefr":"B2","type":"idiom"},{"id":"idiom_0913","en":"know sth inside out","definition":"to know something very well, with all the details","ko":"어떤 것을 아주 잘 알고, 세부 내용까지 다 아는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0914","en":"be a bolt from the blue","definition":"to be a complete surprise","ko":"완전히 뜻밖의 일, 큰 놀라움","cefr":"B2","type":"idiom"},{"id":"idiom_0915","en":"fall over oneself to do sth","definition":"to be very eager to do something for someone","ko":"누군가를 위해 무언가를 아주 하고 싶어 하며 앞다투어 하는 것","cefr":"B2","type":"idiom"},{"id":"idiom_0916","en":"make good headway","definition":"to make good progress","ko":"좋은 진전을 이루다, 잘 진행되다","cefr":"B2","type":"idiom"},{"id":"idiom_0917","en":"there's no time like the present","definition":"it is best to do it now, not later","ko":"지금 하는 게 가장 좋다, 나중으로 미루지 말자","cefr":"B2","type":"idiom"},{"id":"idiom_0918","en":"it's not cricket","definition":"it is not fair or honest behavior","ko":"공정하지 않거나 정직하지 않은 행동이다","cefr":"B2","type":"idiom"},{"id":"idiom_0919","en":"keep one's cards close to one's chest","definition":"to keep your plans or information secret","ko":"자기 계획이나 정보를 비밀로 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0920","en":"a love rat","definition":"a man who lies to women and has relationships with many women","ko":"여자들에게 거짓말을 하고 여러 여자와 사귀는 남자","cefr":"B2","type":"idiom"},{"id":"idiom_0921","en":"fly the nest","definition":"to leave your parents' home to live independently","ko":"부모님 집을 떠나 독립해서 살다","cefr":"B2","type":"idiom"},{"id":"idiom_0922","en":"in the final analysis","definition":"when you think carefully at the end, this is the true result","ko":"마지막에 곰곰이 생각해 보면, 결국 이런 결론이 나온다","cefr":"B2","type":"idiom"},{"id":"idiom_0923","en":"a death blow","definition":"an event that ends something or makes it fail completely","ko":"무언가를 끝장내거나 완전히 실패하게 만드는 결정적인 타격","cefr":"B2","type":"idiom"},{"id":"idiom_0924","en":"as smooth as silk","definition":"very smooth and soft, or very easy and calm","ko":"아주 매끄럽고 부드럽거나, 아주 순조롭고 평온한","cefr":"B2","type":"idiom"},{"id":"idiom_0925","en":"face-saving","definition":"done to avoid embarrassment and protect your public image","ko":"창피를 피하고 체면을 지키기 위해 하는","cefr":"B2","type":"idiom"},{"id":"idiom_0926","en":"wear one's heart on one's sleeve","definition":"to show your feelings openly","ko":"감정을 숨기지 않고 겉으로 드러내다","cefr":"B2","type":"idiom"},{"id":"idiom_0927","en":"donkey work","definition":"boring, hard work that someone has to do","ko":"지루하고 힘든 일, 누군가는 해야 하는 고된 일","cefr":"B2","type":"idiom"},{"id":"idiom_0928","en":"in the offing","definition":"likely to happen soon","ko":"곧 일어날 것 같은, 곧 다가오는","cefr":"B2","type":"idiom"},{"id":"idiom_0929","en":"like the cat that ate the canary","definition":"looking very pleased with yourself, often because you did something wrong","ko":"스스로 아주 만족한 표정, 보통 나쁜 일을 해놓고","cefr":"B2","type":"idiom"},{"id":"idiom_0930","en":"an all-time high","definition":"the highest level ever recorded","ko":"역대 최고치, 지금까지 기록된 가장 높은 수준","cefr":"B2","type":"idiom"},{"id":"idiom_0931","en":"see the writing on the wall","definition":"to see clear signs that something bad will happen soon","ko":"나쁜 일이 곧 일어날 뚜렷한 징조를 보다","cefr":"B2","type":"idiom"},{"id":"idiom_0932","en":"eat like a bird","definition":"To eat very little.","ko":"아주 조금 먹다.","cefr":"B2","type":"idiom"},{"id":"idiom_0933","en":"give one's right arm for","definition":"To want something very much.","ko":"무언가를 정말 아주 갖고 싶다.","cefr":"B2","type":"idiom"},{"id":"idiom_0934","en":"be no oil painting","definition":"To not be very attractive.","ko":"별로 잘생기거나 예쁘지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_0935","en":"save one's own skin","definition":"To do something only to protect yourself.","ko":"자기만 살려고 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0936","en":"know no bounds","definition":"To have no limit; to be very great.","ko":"한계가 없다; 아주 크다.","cefr":"B2","type":"idiom"},{"id":"idiom_0937","en":"the rat race","definition":"Busy, stressful competition for money and success.","ko":"돈과 성공을 위한 바쁘고 스트레스 많은 경쟁.","cefr":"B2","type":"idiom"},{"id":"idiom_0938","en":"every tom, dick and harry","definition":"Any ordinary person; everyone.","ko":"아무나; 평범한 모든 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_0939","en":"on the hoof","definition":"While moving or without stopping to sit down.","ko":"이동하면서; 앉아서 쉬지 않고.","cefr":"B2","type":"idiom"},{"id":"idiom_0940","en":"receive a windfall","definition":"To get an unexpected amount of money or a big benefit.","ko":"뜻밖의 큰돈이나 큰 이득을 얻다.","cefr":"B2","type":"idiom"},{"id":"idiom_0941","en":"play second fiddle","definition":"To be less important than someone else; to be in second place.","ko":"다른 사람보다 덜 중요하다; 2인자 역할을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0942","en":"at the wheel","definition":"to be driving a vehicle","ko":"차를 운전하고 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0943","en":"nook and cranny","definition":"every small place, even hidden corners","ko":"숨은 구석까지 모든 작은 곳.","cefr":"B2","type":"idiom"},{"id":"idiom_0944","en":"one's heart isn't in sth","definition":"you do something without real interest or love","ko":"마음이 없어서 하다; 진짜 관심이 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_0945","en":"a half-baked scheme","definition":"a plan that is not thought about well","ko":"제대로 생각하지 않은 계획.","cefr":"B2","type":"idiom"},{"id":"idiom_0946","en":"a wet blanket","definition":"a person who stops others from having fun","ko":"분위기를 깨는 사람; 재미를 못 하게 하는 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_0947","en":"be a casualty of","definition":"to be harmed or lost because of something bad","ko":"나쁜 일 때문에 피해를 보거나 잃게 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_0948","en":"cheap and cheerful","definition":"low in price and good enough","ko":"싸고 괜찮다.","cefr":"B2","type":"idiom"},{"id":"idiom_0949","en":"give sb the hard sell","definition":"to try very hard to persuade someone to buy something","ko":"무언가를 사게 하려고 아주 강하게 설득하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0950","en":"be at a crossroads","definition":"to be at an important point where you must choose what to do next","ko":"중요한 갈림길에 서서 다음 선택을 해야 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0951","en":"have sth up one's sleeve","definition":"to have a secret plan or surprise ready","ko":"비밀 계획이나 깜짝 놀랄 일을 준비해 두다.","cefr":"B2","type":"idiom"},{"id":"idiom_0952","en":"sink like a stone","definition":"to fail or drop very quickly and badly","ko":"아주 빠르고 크게 실패하거나 떨어지다","cefr":"B2","type":"idiom"},{"id":"idiom_0953","en":"be rolling in it","definition":"to have a lot of money","ko":"돈이 아주 많다","cefr":"B2","type":"idiom"},{"id":"idiom_0954","en":"engulfed in flames","definition":"burning strongly with big flames","ko":"큰 불길로 세게 타고 있는","cefr":"B2","type":"idiom"},{"id":"idiom_0955","en":"a chip off the old block","definition":"a person who is very similar to their parent","ko":"부모와 아주 닮은 사람","cefr":"B2","type":"idiom"},{"id":"idiom_0956","en":"to say nothing of","definition":"used to add another thing that is also true or important","ko":"게다가 ~도 그렇다(또한 중요한 점을 더할 때)","cefr":"B2","type":"idiom"},{"id":"idiom_0957","en":"be centre-stage","definition":"to be the main focus of attention","ko":"가장 큰 관심의 중심이 되다","cefr":"B2","type":"idiom"},{"id":"idiom_0958","en":"tread the boards","definition":"to perform as an actor on stage","ko":"무대에서 배우로 연기하다","cefr":"B2","type":"idiom"},{"id":"idiom_0959","en":"my heart bleeds","definition":"used to show you do not feel sorry for someone","ko":"(비꼬며) 전혀 안 불쌍하다","cefr":"B2","type":"idiom"},{"id":"idiom_0960","en":"as stubborn as a mule","definition":"very stubborn and not willing to change your mind","ko":"아주 고집이 세고 마음을 잘 안 바꾸는","cefr":"B2","type":"idiom"},{"id":"idiom_0961","en":"cast one's mind back","definition":"to try to remember something from the past","ko":"과거를 떠올리며 기억해 보다","cefr":"B2","type":"idiom"},{"id":"idiom_0962","en":"off one's hands","definition":"to get rid of something or someone so you do not have to deal with it anymore.","ko":"더 이상 처리하지 않도록 없애거나 떠넘기다","cefr":"B2","type":"idiom"},{"id":"idiom_0963","en":"bring the house down","definition":"to make everyone laugh or clap a lot at a show.","ko":"공연에서 모두를 크게 웃기거나 박수치게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0964","en":"be all smiles","definition":"to look very happy and keep smiling.","ko":"아주 행복해 보이고 계속 웃다","cefr":"B2","type":"idiom"},{"id":"idiom_0965","en":"all hot and bothered","definition":"to feel upset, nervous, or angry and not calm.","ko":"속상하거나 긴장하거나 화가 나서 진정하지 못하다","cefr":"B2","type":"idiom"},{"id":"idiom_0966","en":"last but not least","definition":"used to say the last person or thing is also important.","ko":"마지막이지만 똑같이 중요하다는 뜻","cefr":"B2","type":"idiom"},{"id":"idiom_0967","en":"two can play at that game","definition":"used to say you can do the same bad thing back to someone.","ko":"너도 그렇게 하면 나도 똑같이 할 수 있다는 뜻","cefr":"B2","type":"idiom"},{"id":"idiom_0968","en":"pour oil on troubled waters","definition":"to try to calm people down and stop an argument.","ko":"사람들을 진정시키고 다툼을 멈추게 하려고 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0969","en":"bone of contention","definition":"a subject that people argue about a lot.","ko":"사람들이 자주 다투는 문제","cefr":"B2","type":"idiom"},{"id":"idiom_0970","en":"be at death's door","definition":"to be very sick and close to dying.","ko":"아주 아프고 죽기 직전이다","cefr":"B2","type":"idiom"},{"id":"idiom_0971","en":"a recipe for disaster","definition":"A situation that will likely end badly.","ko":"아마 나쁘게 끝날 상황.","cefr":"B2","type":"idiom"},{"id":"idiom_0972","en":"be one's own person","definition":"To think and act independently, not just follow others.","ko":"남을 따라가기만 하지 않고, 스스로 생각하고 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0973","en":"in leaps and bounds","definition":"Very quickly and by a lot.","ko":"아주 빠르게, 크게.","cefr":"B2","type":"idiom"},{"id":"idiom_0974","en":"chalk and cheese","definition":"Very different from each other.","ko":"서로 아주 다르다.","cefr":"B2","type":"idiom"},{"id":"idiom_0975","en":"every cloud has a silver lining","definition":"Even in a bad situation, there is something good.","ko":"나쁜 상황에서도 좋은 점이 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_0976","en":"be no picnic","definition":"Not easy; very difficult or unpleasant.","ko":"쉽지 않다; 아주 힘들거나 불쾌하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0977","en":"a fate worse than death","definition":"Something extremely bad, even worse than dying.","ko":"죽는 것보다 더 나쁘다고 느낄 만큼 아주 끔찍한 일.","cefr":"B2","type":"idiom"},{"id":"idiom_0978","en":"there's no such thing as a free lunch","definition":"Nothing is truly free; you always pay in some way.","ko":"세상에 진짜 공짜는 없다; 어떤 방식으로든 대가를 치른다.","cefr":"B2","type":"idiom"},{"id":"idiom_0979","en":"play hardball","definition":"To be very tough and aggressive in a negotiation or competition.","ko":"협상이나 경쟁에서 아주 강하게 나오다.","cefr":"B2","type":"idiom"},{"id":"idiom_0980","en":"as fresh as a daisy","definition":"Feeling full of energy and healthy.","ko":"기운이 넘치고 건강해 보이다.","cefr":"B2","type":"idiom"},{"id":"idiom_0981","en":"i beg to differ","definition":"You say this when you politely disagree with someone.","ko":"정중하게 반대할 때 하는 말.","cefr":"B2","type":"idiom"},{"id":"idiom_0982","en":"fight for one's life","definition":"To fight very hard to stay alive.","ko":"살기 위해 아주 필사적으로 싸우다.","cefr":"B2","type":"idiom"},{"id":"idiom_0983","en":"do me a favour","definition":"Used to ask someone to help you.","ko":"누군가에게 도움을 부탁할 때 쓰는 말.","cefr":"B2","type":"idiom"},{"id":"idiom_0984","en":"a back-seat driver","definition":"A person who tells the driver what to do too much.","ko":"운전하는 사람에게 너무 많이 지시하는 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_0985","en":"as quick as a flash","definition":"Very fast, with almost no delay.","ko":"거의 지체 없이 아주 빠르게.","cefr":"B2","type":"idiom"},{"id":"idiom_0986","en":"an ivory tower","definition":"A place or situation where people are separated from real life and real problems.","ko":"현실과 현실 문제에서 떨어져 있는 곳이나 상황.","cefr":"B2","type":"idiom"},{"id":"idiom_0987","en":"parting shot","definition":"A final remark, often rude, said as you leave.","ko":"떠나면서 하는 마지막 말(종종 무례한 말).","cefr":"B2","type":"idiom"},{"id":"idiom_0988","en":"run a tight ship","definition":"To manage a group or business in a strict, organized way.","ko":"엄격하고 체계적으로 관리하다.","cefr":"B2","type":"idiom"},{"id":"idiom_0989","en":"go up in the world","definition":"To become more successful or have a better life.","ko":"더 성공하거나 더 나은 삶을 살게 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_0990","en":"pull the wool over sb's eyes","definition":"to trick someone so they do not see the truth","ko":"누군가가 진실을 보지 못하게 속이다","cefr":"B2","type":"idiom"},{"id":"idiom_0991","en":"rattle sb's cage","definition":"to annoy or upset someone on purpose","ko":"일부러 누군가를 짜증 나게 하거나 화나게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_0992","en":"a page-turner","definition":"a book that is so exciting you want to keep reading","ko":"너무 재미있어서 계속 읽고 싶어지는 책","cefr":"B2","type":"idiom"},{"id":"idiom_0993","en":"get one's own back","definition":"to get revenge on someone for something they did to you","ko":"누가 나에게 한 일에 대해 복수하다","cefr":"B2","type":"idiom"},{"id":"idiom_0994","en":"all told","definition":"when you count everything, the total is this number","ko":"전부 다 합쳐서 말하면","cefr":"B2","type":"idiom"},{"id":"idiom_0995","en":"get-up and go","definition":"energy and enthusiasm to start doing things","ko":"무언가를 시작할 힘과 의욕","cefr":"B2","type":"idiom"},{"id":"idiom_0996","en":"like the cat that got the cream","definition":"looking very pleased and proud, like you got what you wanted","ko":"원하는 걸 얻어서 아주 만족하고 뿌듯해 보이는","cefr":"B2","type":"idiom"},{"id":"idiom_0997","en":"truth will out","definition":"the truth will be discovered sooner or later","ko":"진실은 언젠가 드러난다","cefr":"B2","type":"idiom"},{"id":"idiom_0998","en":"first come, first served","definition":"people are helped or served in the order they arrive","ko":"먼저 온 사람이 먼저 받는다","cefr":"B2","type":"idiom"},{"id":"idiom_0999","en":"a lone voice","definition":"one person speaking an opinion that most people do not agree with","ko":"대부분이 동의하지 않는데 혼자 의견을 말하는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_1000","en":"as bright as a button","definition":"very smart and quick to understand things.","ko":"아주 똑똑하고 이해가 빠한","cefr":"B2","type":"idiom"},{"id":"idiom_1001","en":"sb's days are numbered","definition":"someone will soon lose their job, power, or life.","ko":"곧 자리나 힘을 잃거나, 목숨이 위험해지다","cefr":"B2","type":"idiom"},{"id":"idiom_1002","en":"razor-sharp","definition":"extremely sharp or very quick and clear in thinking.","ko":"아주 날카롭거나 생각이 매우 빠르고 분명한","cefr":"B2","type":"idiom"},{"id":"idiom_1003","en":"a pyrrhic victory","definition":"a win that costs so much that it feels like a loss.","ko":"이기긴 했지만 대가가 너무 커서 진 것 같은 승리","cefr":"B2","type":"idiom"},{"id":"idiom_1004","en":"until the cows come home","definition":"for a very long time.","ko":"아주 오랫동안","cefr":"B2","type":"idiom"},{"id":"idiom_1005","en":"a sth and a half","definition":"used to say something is more than usual or very strong.","ko":"보통보다 훨씬 더 강하거나 대단하다는 뜻","cefr":"B2","type":"idiom"},{"id":"idiom_1006","en":"take it easy","definition":"relax and do not worry or hurry.","ko":"긴장을 풀고 걱정하거나 서두르지 말다","cefr":"B2","type":"idiom"},{"id":"idiom_1007","en":"not pull any punches","definition":"to speak or act very directly, without being gentle.","ko":"돌려 말하지 않고 아주 직설적으로 말하거나 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_1008","en":"dig one's own grave","definition":"to cause your own failure by your own actions.","ko":"자기 행동 때문에 스스로 실패하게 되다","cefr":"B2","type":"idiom"},{"id":"idiom_1009","en":"mind one's back","definition":"Be careful because danger may be behind you.","ko":"뒤에 위험이 있을 수 있으니 조심하라는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1010","en":"have a bad hair day","definition":"Have a day when your hair looks bad and you feel messy.","ko":"머리가 엉망으로 보여서 기분도 지저분한 날이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1011","en":"at sixes and sevens","definition":"In a state of confusion and not organized.","ko":"혼란스럽고 정리가 안 된 상태예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1012","en":"all or nothing","definition":"You do something completely or you do not do it at all.","ko":"완전히 하거나, 아예 안 하거나 둘 중 하나예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1013","en":"in all but name","definition":"Almost the same as something, but not officially called that.","ko":"공식 이름만 아닐 뿐, 거의 똑같은 거예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1014","en":"two heads are better than one","definition":"Working with another person gives better ideas than working alone.","ko":"혼자 하는 것보다 둘이 하면 더 좋은 아이디어가 나온다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1015","en":"have sb eating out of the palm of one's hand","definition":"Control someone easily and make them do what you want.","ko":"누군가를 쉽게 조종해서 내 뜻대로 하게 만드는 거예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1016","en":"a second-class citizen","definition":"A person who is treated as less important than others.","ko":"다른 사람보다 덜 중요하게 대우받는 사람이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1017","en":"no pain no gain","definition":"You must work hard and accept pain to get good results.","ko":"좋은 결과를 얻으려면 열심히 하고 고통도 참아야 한다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1018","en":"cut both ways","definition":"Something can have both good and bad results.","ko":"좋은 결과도 나쁜 결과도 둘 다 있을 수 있다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1019","en":"put sb in their place","definition":"To tell someone firmly to stop being rude or acting too important.","ko":"무례하게 굴거나 잘난 척하는 사람에게 단호하게 말해서 멈추게 하는 거예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1020","en":"ad hoc","definition":"Made for a special situation, not planned in advance.","ko":"미리 계획한 게 아니라, 특별한 상황을 위해 급히 만든 거예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1021","en":"play the game","definition":"To follow the rules and behave fairly, especially to succeed.","ko":"특히 성공하려고 규칙을 따르고 공정하게 행동하는 거예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1022","en":"reduce to tears","definition":"To make someone cry.","ko":"누군가를 울게 만드는 거예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1023","en":"argue the toss","definition":"To argue about a decision and refuse to accept it.","ko":"결정을 받아들이지 않고 계속 따지는 거예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1024","en":"lay it on with a trowel","definition":"To praise or describe something too much in an obvious way.","ko":"티 나게 칭찬이나 말을 너무 과하게 하는 거예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1025","en":"throw the book at","definition":"To punish someone as strongly as possible using the law or rules.","ko":"법이나 규칙을 최대한 써서 아주 강하게 처벌하는 거예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1026","en":"be given one's marching orders","definition":"To be told to leave a job because you are fired.","ko":"해고돼서 직장을 그만두라고 통보받는 거예요.","cefr":"B2","type":"idiom"},{"id":"idiom_1027","en":"hindsight is a wonderful thing","definition":"It is easy to see what was right only after something happens.","ko":"일이 지나고 나서야 뭐가 맞았는지 쉽게 알 수 있다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1028","en":"be light years away from sth","definition":"To be very far from something in level or progress.","ko":"수준이나 발전 면에서 어떤 것과 아주 멀리 떨어져 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_1029","en":"better safe than sorry","definition":"It is better to be careful now than to have problems later.","ko":"나중에 문제가 생기는 것보다 지금 조심하는 게 더 낫다.","cefr":"B2","type":"idiom"},{"id":"idiom_1030","en":"be a tower of strength","definition":"To be very strong and helpful when others need support.","ko":"다른 사람이 도움이 필요할 때 아주 든든하고 큰 힘이 되어 주다.","cefr":"B2","type":"idiom"},{"id":"idiom_1031","en":"get one's skates on","definition":"To hurry up and start moving or doing something.","ko":"서둘러서 움직이거나 일을 시작하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1032","en":"can count sth on the fingers of one hand","definition":"To have only a very small number of something.","ko":"어떤 것이 아주 조금밖에 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_1033","en":"lose the plot","definition":"To become confused and stop thinking clearly or acting sensibly.","ko":"헷갈려서 제대로 생각하지 못하거나 말이 안 되게 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1034","en":"like there's no tomorrow","definition":"Very fast and with a lot of energy, as if time is running out.","ko":"시간이 없는 것처럼 아주 빠르고 힘차게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1035","en":"go belly up","definition":"To fail completely, especially for a business or plan.","ko":"완전히 실패하다(특히 회사나 계획이).","cefr":"B2","type":"idiom"},{"id":"idiom_1036","en":"put two fingers up at sth","definition":"To show rude refusal or disrespect toward something.","ko":"무례하게 거부하거나 무시하는 태도를 보이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1037","en":"get off one's backside","definition":"Stop being lazy and start doing something.","ko":"게으름을 그만두고 뭔가를 하기 시작하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1038","en":"do anything for a quiet life","definition":"Do whatever you can to avoid trouble and keep things calm.","ko":"문제를 피하고 조용히 지내려고 뭐든 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1039","en":"be taken aback","definition":"Feel surprised and not ready for something.","ko":"깜짝 놀라서 준비가 안 된 느낌이 들다.","cefr":"B2","type":"idiom"},{"id":"idiom_1040","en":"wax and wane","definition":"Increase and decrease over time.","ko":"시간이 지나면서 늘었다 줄었다 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1041","en":"through thick and thin","definition":"Stay loyal and support someone in good times and bad times.","ko":"좋을 때나 힘들 때나 변함없이 곁에서 돕다.","cefr":"B2","type":"idiom"},{"id":"idiom_1042","en":"be in two minds","definition":"Be unsure and unable to decide between two choices.","ko":"두 가지 중에서 결정을 못 하고 망설이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1043","en":"hard-and-fast rules","definition":"Fixed rules that do not change.","ko":"바뀌지 않는 딱 정해진 규칙들.","cefr":"B2","type":"idiom"},{"id":"idiom_1044","en":"squeaky-clean","definition":"Completely clean and with no sign of wrongdoing.","ko":"아주 깨끗하고, 나쁜 짓을 한 흔적도 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_1045","en":"poker-faced","definition":"Showing no emotion on your face.","ko":"얼굴에 감정을 드러내지 않는.","cefr":"B2","type":"idiom"},{"id":"idiom_1046","en":"on a weekly basis","definition":"Happening every week.","ko":"매주 일어나는.","cefr":"B2","type":"idiom"},{"id":"idiom_1047","en":"out of one's own pocket","definition":"Pay for something with your own money, not someone else's.","ko":"다른 사람 돈이 아니라, 내 돈으로 무언가를 사거나 내는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1048","en":"if one can't beat 'em, join 'em","definition":"If you cannot win against others, do what they do instead.","ko":"다른 사람들을 이길 수 없으면, 대신 그들이 하는 대로 하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1049","en":"look out for number one","definition":"Think only about yourself and your own needs.","ko":"자기 자신과 자기 필요만 생각하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1050","en":"new kid on the block","definition":"A person or thing that is new in a place or group.","ko":"어떤 장소나 모임에 새로 온 사람이나 새로 생긴 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1051","en":"the tip of the iceberg","definition":"A small, visible part of a much bigger problem or situation.","ko":"훨씬 더 큰 문제나 상황의 작고 눈에 보이는 일부.","cefr":"B2","type":"idiom"},{"id":"idiom_1052","en":"have the time of one's life","definition":"Enjoy yourself very much.","ko":"아주 많이 즐기다.","cefr":"B2","type":"idiom"},{"id":"idiom_1053","en":"i thought as much","definition":"I expected that, and I am not surprised.","ko":"그럴 줄 알았고, 놀랍지 않다는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_1054","en":"two's company, three's a crowd","definition":"Two people are fine together, but a third person makes it uncomfortable.","ko":"두 사람은 괜찮지만, 세 번째 사람이 끼면 불편해진다는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_1055","en":"go in one ear and out the other","definition":"Hear something but not remember it or pay attention to it.","ko":"무언가를 듣기는 하지만 기억하지 못하거나 신경 쓰지 않는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1056","en":"sleep on it","definition":"Wait until tomorrow before you decide.","ko":"결정하기 전에 내일까지 기다리다.","cefr":"B2","type":"idiom"},{"id":"idiom_1057","en":"go to the wall","definition":"to fail or be destroyed because of strong competition or pressure.","ko":"강한 경쟁이나 압박 때문에 망하거나 무너지다.","cefr":"B2","type":"idiom"},{"id":"idiom_1058","en":"a hard nut to crack","definition":"a person or problem that is very difficult to understand or solve.","ko":"이해하거나 해결하기가 아주 어려운 사람이나 문제.","cefr":"B2","type":"idiom"},{"id":"idiom_1059","en":"black and white","definition":"clear and simple, with no middle choice.","ko":"분명하고 단순해서, 중간 선택이 없는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1060","en":"stone cold","definition":"completely cold or without any warmth.","ko":"완전히 차갑고 따뜻함이 전혀 없는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1061","en":"hopping mad","definition":"extremely angry.","ko":"아주 화가 난 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_1062","en":"ad infinitum","definition":"continuing for a very long time, with no end.","ko":"끝이 없이 아주 오랫동안 계속되는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1063","en":"be all things to all men","definition":"to try to please everyone, even when it is impossible.","ko":"불가능한데도 모두를 만족시키려고 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1064","en":"get one's act together","definition":"to start behaving in a more organized and responsible way.","ko":"더 정리되고 책임감 있게 행동하기 시작하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1065","en":"fall on one's sword","definition":"to accept blame or punishment to protect others or the group.","ko":"다른 사람이나 팀을 지키려고, 스스로 책임을 지고 벌을 받다.","cefr":"B2","type":"idiom"},{"id":"idiom_1066","en":"shoot sky-high","definition":"to rise very quickly.","ko":"아주 빠르게 오르다.","cefr":"B2","type":"idiom"},{"id":"idiom_1067","en":"make hard work of","definition":"To make a task seem harder than it really is.","ko":"일이 실제보다 더 어렵게 느껴지게 만들다.","cefr":"B2","type":"idiom"},{"id":"idiom_1068","en":"bloody confrontations","definition":"Violent fights or clashes where people get hurt or killed.","ko":"사람들이 다치거나 죽는 폭력적인 싸움이나 충돌.","cefr":"B2","type":"idiom"},{"id":"idiom_1069","en":"make one's hair stand on end","definition":"To feel very scared or shocked.","ko":"아주 무섭거나 충격을 받다.","cefr":"B2","type":"idiom"},{"id":"idiom_1070","en":"a storm in a teacup","definition":"A big fuss about something small and not important.","ko":"작고 중요하지 않은 일로 크게 소란을 피우는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1071","en":"turn the other cheek","definition":"To not fight back when someone is unkind to you.","ko":"누가 나쁘게 대해도 맞서 싸우지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1072","en":"war-torn country","definition":"A country badly damaged by war.","ko":"전쟁으로 심하게 망가진 나라.","cefr":"B2","type":"idiom"},{"id":"idiom_1073","en":"fall into one's lap","definition":"To get something easily without trying, as if it comes to you by luck.","ko":"노력하지 않았는데도 운 좋게 쉽게 얻다.","cefr":"B2","type":"idiom"},{"id":"idiom_1074","en":"fit like a glove","definition":"To fit perfectly.","ko":"완벽하게 딱 맞다.","cefr":"B2","type":"idiom"},{"id":"idiom_1075","en":"it never rains but it pours","definition":"Bad things often happen all at once, not one by one.","ko":"나쁜 일은 하나씩이 아니라 한꺼번에 일어나는 경우가 많다.","cefr":"B2","type":"idiom"},{"id":"idiom_1076","en":"be no spring chicken","definition":"To not be young anymore.","ko":"더 이상 젊지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1077","en":"at a loss for words","definition":"You cannot think of anything to say.","ko":"할 말을 찾지 못하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1078","en":"two sides of the same coin","definition":"They seem different, but they are closely connected.","ko":"겉으로는 달라 보이지만 서로 아주 밀접하게 연결되어 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_1079","en":"laugh all the way to the bank","definition":"To make a lot of money and feel happy about it.","ko":"돈을 많이 벌고 아주 기뻐하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1080","en":"one is not wrong","definition":"Someone is correct about something.","ko":"그 말이 맞다.","cefr":"B2","type":"idiom"},{"id":"idiom_1081","en":"a matter of life and death","definition":"It is extremely serious and could decide if someone lives or dies.","ko":"아주 심각해서 누가 살지 죽을지에 영향을 줄 수 있는 일.","cefr":"B2","type":"idiom"},{"id":"idiom_1082","en":"star-crossed lovers","definition":"Two people love each other, but bad luck or problems keep them apart.","ko":"서로 사랑하지만 불운이나 문제 때문에 함께할 수 없는 두 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_1083","en":"a dream come true","definition":"Something you really wanted has happened.","ko":"정말 바라던 일이 이루어진 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1084","en":"play cat and mouse","definition":"To trick someone by being friendly, then unfriendly, to control them.","ko":"친한 척했다가 차갑게 굴면서 상대를 속이고 조종하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1085","en":"no news is good news","definition":"If you have not heard anything bad, you think everything is fine.","ko":"나쁜 소식이 없으면 괜찮다고 생각한다.","cefr":"B2","type":"idiom"},{"id":"idiom_1086","en":"knock sb for six","definition":"To shock or upset someone a lot.","ko":"누군가를 크게 충격 주거나 마음을 아주 상하게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1087","en":"girl friday","definition":"a woman who helps a boss with many different jobs.","ko":"상사를 여러 가지 일로 도와주는 여자.","cefr":"B2","type":"idiom"},{"id":"idiom_1088","en":"at first glance","definition":"when you first look at something, before thinking more.","ko":"처음 봤을 때, 더 생각하기 전.","cefr":"B2","type":"idiom"},{"id":"idiom_1089","en":"in the cold light of day","definition":"when you think clearly about something the next day.","ko":"다음 날에 차분하게 생각해 보면.","cefr":"B2","type":"idiom"},{"id":"idiom_1090","en":"a world of difference","definition":"a very big difference between two things.","ko":"두 가지 사이에 아주 큰 차이.","cefr":"B2","type":"idiom"},{"id":"idiom_1091","en":"an own goal","definition":"a mistake that hurts you or your own side.","ko":"자기 자신이나 자기 편에 해가 되는 실수.","cefr":"B2","type":"idiom"},{"id":"idiom_1092","en":"crème de la crème","definition":"the very best people or things in a group.","ko":"그 무리에서 가장 최고인 사람이나 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1093","en":"take the biscuit","definition":"be the most surprising or annoying thing of all.","ko":"가장 놀랍거나 가장 짜증 나는 일이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1094","en":"at this moment in time","definition":"right now, at the present time.","ko":"바로 지금, 현재.","cefr":"B2","type":"idiom"},{"id":"idiom_1095","en":"get one's mind round","definition":"understand something difficult after thinking about it.","ko":"생각해 보고 어려운 것을 이해하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1096","en":"big brother","definition":"a person or group that watches and controls what others do.","ko":"다른 사람을 감시하고 통제하는 사람이나 단체.","cefr":"B2","type":"idiom"},{"id":"idiom_1097","en":"life in the fast lane","definition":"a busy, exciting life with lots of activity and risk.","ko":"활동과 위험이 많은 바쁘고 신나는 삶.","cefr":"B2","type":"idiom"},{"id":"idiom_1098","en":"slog one's guts out","definition":"to work extremely hard for a long time.","ko":"오랫동안 아주 열심히 일하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1099","en":"stand out from the crowd","definition":"to be clearly different and easy to notice.","ko":"눈에 띄게 달라서 쉽게 알아볼 수 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_1100","en":"huff and puff","definition":"to breathe loudly because you are tired or angry.","ko":"피곤하거나 화가 나서 크게 숨을 쉬다.","cefr":"B2","type":"idiom"},{"id":"idiom_1101","en":"it doesn't float my boat","definition":"I don't like it or it doesn't interest me.","ko":"나는 그게 별로 좋지 않거나 관심이 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_1102","en":"take the flak","definition":"to accept blame or criticism for something.","ko":"어떤 일에 대해 비난이나 책임을 받아들이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1103","en":"a case in point","definition":"an example that shows what you mean.","ko":"네 말이 맞다는 걸 보여 주는 예.","cefr":"B2","type":"idiom"},{"id":"idiom_1104","en":"fingers and thumbs","definition":"clumsy and awkward with your hands.","ko":"손을 서툴게 써서 어색하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1105","en":"money to burn","definition":"having so much money that you can spend it easily.","ko":"돈이 아주 많아서 쉽게 쓸 수 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_1106","en":"be on a high","definition":"to feel very happy and excited for a short time.","ko":"잠깐 동안 아주 행복하고 신이 나다.","cefr":"B2","type":"idiom"},{"id":"idiom_1107","en":"like a deer caught in the headlights","definition":"to look frozen and scared because you are surprised.","ko":"놀라서 겁이 나서 얼어붙은 것처럼 보이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1108","en":"hard to swallow","definition":"difficult to accept or believe because it is unpleasant.","ko":"기분이 나빠서 받아들이거나 믿기 어렵다.","cefr":"B2","type":"idiom"},{"id":"idiom_1109","en":"the green-eyed monster","definition":"jealousy that makes someone angry or unhappy.","ko":"사람을 화나고 불행하게 만드는 질투.","cefr":"B2","type":"idiom"},{"id":"idiom_1110","en":"across the board","definition":"for everyone or for all parts of a group in the same way.","ko":"모든 사람이나 모든 부분에 똑같이.","cefr":"B2","type":"idiom"},{"id":"idiom_1111","en":"bored out of one's mind","definition":"extremely bored.","ko":"엄청 지루하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1112","en":"nice work if one can get it","definition":"a job that is easy and pleasant, but hard to find.","ko":"쉽고 즐겁지만 구하기는 힘든 일.","cefr":"B2","type":"idiom"},{"id":"idiom_1113","en":"full stop","definition":"used to say something is final and will not change.","ko":"이건 최종이고 바뀌지 않는다는 뜻으로 말함.","cefr":"B2","type":"idiom"},{"id":"idiom_1114","en":"fall into line","definition":"to start obeying the rules or doing what others want.","ko":"규칙을 따르기 시작하거나 다른 사람이 원하는 대로 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1115","en":"here, there and everywhere","definition":"in many different places, not in one place.","ko":"한곳이 아니라 여러 곳에 여기저기.","cefr":"B2","type":"idiom"},{"id":"idiom_1116","en":"help sb no end","definition":"To help someone a lot.","ko":"누군가에게 큰 도움이 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_1117","en":"in no uncertain terms","definition":"In a very clear and strong way.","ko":"아주 분명하고 강하게.","cefr":"B2","type":"idiom"},{"id":"idiom_1118","en":"ignorance is bliss","definition":"Not knowing something can make you feel happier.","ko":"어떤 걸 모르면 더 마음이 편할 때가 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_1119","en":"fight like cat and dog","definition":"To argue a lot and not get along.","ko":"자주 싸우고 사이가 안 좋다.","cefr":"B2","type":"idiom"},{"id":"idiom_1120","en":"the brainchild of sb","definition":"An idea or invention made by someone.","ko":"누군가가 만든 아이디어나 발명품.","cefr":"B2","type":"idiom"},{"id":"idiom_1121","en":"hard going","definition":"Difficult and slow to do.","ko":"하기 어렵고 진행이 느리다.","cefr":"B2","type":"idiom"},{"id":"idiom_1122","en":"play one's cards close to one's chest","definition":"To keep your plans or feelings secret.","ko":"계획이나 감정을 비밀로 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1123","en":"on a roll","definition":"Having a lot of success again and again.","ko":"계속해서 잘하고 성공하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1124","en":"take a rain check","definition":"To say no now but accept later.","ko":"지금은 못 하지만 나중에 하겠다고 말하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1125","en":"the course of true love never did run smooth","definition":"Love relationships often have problems and are not easy.","ko":"진짜 사랑은 보통 문제도 있고 쉽지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1126","en":"play games","definition":"to behave in a dishonest or silly way instead of being serious","ko":"진지하게 하지 않고, 정직하지 않거나 바보처럼 행동하는 것","cefr":"B2","type":"idiom"},{"id":"idiom_1127","en":"step on it","definition":"to go faster or hurry up","ko":"더 빨리 가거나 서두르다","cefr":"B2","type":"idiom"},{"id":"idiom_1128","en":"in one's heart of hearts","definition":"what you really feel deep inside, even if you do not say it","ko":"말로는 안 해도, 마음속 깊이 진짜로 느끼는 것","cefr":"B2","type":"idiom"},{"id":"idiom_1129","en":"achilles heel","definition":"a person's weak point or biggest weakness","ko":"사람의 약점, 가장 큰 약점","cefr":"B2","type":"idiom"},{"id":"idiom_1130","en":"put sb's nose out of joint","definition":"to make someone feel upset or offended","ko":"누군가를 기분 나쁘게 하거나 화나게 만들다","cefr":"B2","type":"idiom"},{"id":"idiom_1131","en":"do a stretch","definition":"to spend time in prison","ko":"감옥에서 시간을 보내다","cefr":"B2","type":"idiom"},{"id":"idiom_1132","en":"a cloud on the horizon","definition":"a sign that trouble may happen in the future","ko":"앞으로 문제가 생길 수 있다는 신호","cefr":"B2","type":"idiom"},{"id":"idiom_1133","en":"be half the battle","definition":"to be an important part of success","ko":"성공에 중요한 부분이 되다","cefr":"B2","type":"idiom"},{"id":"idiom_1134","en":"take a shine to sb","definition":"to start liking someone quickly","ko":"누군가를 금방 좋아하게 되다","cefr":"B2","type":"idiom"},{"id":"idiom_1135","en":"fly by the seat of one's pants","definition":"to do something without a plan, using guesswork","ko":"계획 없이, 대충 짐작으로 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1136","en":"in next to no time","definition":"very quickly, with almost no delay.","ko":"아주 빨리, 거의 기다리지 않고","cefr":"B2","type":"idiom"},{"id":"idiom_1137","en":"pack a punch","definition":"to have a strong effect, even if it is small.","ko":"작아도 효과가 강하다","cefr":"B2","type":"idiom"},{"id":"idiom_1138","en":"the cat's whiskers","definition":"someone or something thought to be the best or very special.","ko":"최고이거나 아주 특별하다고 여겨지는 사람이나 것","cefr":"B2","type":"idiom"},{"id":"idiom_1139","en":"run like the wind","definition":"to run very fast.","ko":"아주 빠르게 달리다","cefr":"B2","type":"idiom"},{"id":"idiom_1140","en":"burn the midnight oil","definition":"to work or study late into the night.","ko":"밤늦게까지 일하거나 공부하다","cefr":"B2","type":"idiom"},{"id":"idiom_1141","en":"time after time","definition":"again and again, many times.","ko":"여러 번, 계속해서","cefr":"B2","type":"idiom"},{"id":"idiom_1142","en":"so far, so good","definition":"things are going well up to now.","ko":"지금까지는 잘 되고 있다","cefr":"B2","type":"idiom"},{"id":"idiom_1143","en":"not be short of a bob or two","definition":"to have plenty of money.","ko":"돈이 많다","cefr":"B2","type":"idiom"},{"id":"idiom_1144","en":"rock bottom","definition":"the worst possible level or situation.","ko":"가장 나쁜 상태, 최악의 상황","cefr":"B2","type":"idiom"},{"id":"idiom_1145","en":"uncharted territory","definition":"a new situation that no one has tried before.","ko":"아무도 해 본 적 없는 새로운 상황","cefr":"B2","type":"idiom"},{"id":"idiom_1146","en":"take matters into one's own hands","definition":"to deal with a problem yourself because others will not act","ko":"다른 사람들이 행동하지 않아서 문제를 스스로 해결하다","cefr":"B2","type":"idiom"},{"id":"idiom_1147","en":"set one's sights on","definition":"to choose a goal and aim for it","ko":"목표를 정하고 그것을 이루려고 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1148","en":"bring home the bacon","definition":"to earn money to support your family","ko":"가족을 부양할 돈을 벌다","cefr":"B2","type":"idiom"},{"id":"idiom_1149","en":"a dog's life","definition":"a very hard and unhappy life","ko":"아주 힘들고 불행한 삶","cefr":"B2","type":"idiom"},{"id":"idiom_1150","en":"be flying high","definition":"to feel very happy and successful","ko":"아주 행복하고 성공한 기분이다","cefr":"B2","type":"idiom"},{"id":"idiom_1151","en":"be a nightmare","definition":"to be very difficult and stressful","ko":"아주 어렵고 스트레스가 많다","cefr":"B2","type":"idiom"},{"id":"idiom_1152","en":"go up a gear","definition":"to start working harder or faster","ko":"더 열심히 또는 더 빠르게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1153","en":"the power behind the throne","definition":"a person who secretly has real control while someone else seems to lead","ko":"겉으로는 다른 사람이 이끄는 것 같지만, 뒤에서 실제로 힘을 가진 사람","cefr":"B2","type":"idiom"},{"id":"idiom_1154","en":"not be worth a dime","definition":"to have no value at all","ko":"전혀 가치가 없다","cefr":"B2","type":"idiom"},{"id":"idiom_1155","en":"the frosting on the cake","definition":"an extra nice thing that makes something already good even better","ko":"이미 좋은 것에 더해지는 추가로 좋은 점","cefr":"B2","type":"idiom"},{"id":"idiom_1156","en":"not be one's bag","definition":"It is not something you like or enjoy.","ko":"내가 좋아하거나 즐기는 것이 아니다","cefr":"B2","type":"idiom"},{"id":"idiom_1157","en":"put the cat amongst the pigeons","definition":"To say or do something that causes trouble or strong reactions.","ko":"문제나 큰 반응을 일으키는 말이나 행동을 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1158","en":"go to one's head","definition":"To make someone too proud or too confident.","ko":"누군가를 너무 자만하거나 자신만만하게 만들다","cefr":"B2","type":"idiom"},{"id":"idiom_1159","en":"be hard pressed to","definition":"To find it very difficult to do something.","ko":"무언가를 하기가 매우 어렵다","cefr":"B2","type":"idiom"},{"id":"idiom_1160","en":"hold out an olive branch","definition":"To offer peace or friendship after a disagreement.","ko":"다툰 뒤에 화해나 친해지자고 제안하다","cefr":"B2","type":"idiom"},{"id":"idiom_1161","en":"no expense spared","definition":"People spent as much money as needed to make something very good.","ko":"아주 좋게 만들기 위해 돈을 아끼지 않았다","cefr":"B2","type":"idiom"},{"id":"idiom_1162","en":"not have the heart to","definition":"To feel unable to do something because it would be too unkind.","ko":"너무 매정해서 못 하겠다","cefr":"B2","type":"idiom"},{"id":"idiom_1163","en":"black and blue","definition":"With dark bruises on the skin from being hit or hurt.","ko":"맞거나 다쳐서 피부에 멍이 시퍼렇게 들다","cefr":"B2","type":"idiom"},{"id":"idiom_1164","en":"at all hours","definition":"At many different times, including very late or very early.","ko":"아주 이른 시간이나 아주 늦은 시간을 포함해 여러 시간에","cefr":"B2","type":"idiom"},{"id":"idiom_1165","en":"as clear as mud","definition":"Not clear or easy to understand at all.","ko":"전혀 명확하지 않고 이해하기 어렵다","cefr":"B2","type":"idiom"},{"id":"idiom_1166","en":"drop in on","definition":"to visit someone for a short time, often without planning it","ko":"짧은 시간 동안 누군가를 방문하는 것(보통 미리 계획 없이)","cefr":"B2","type":"idiom"},{"id":"idiom_1167","en":"wear and tear","definition":"damage or change from being used a lot over time","ko":"오랫동안 많이 써서 생기는 손상이나 낡음","cefr":"B2","type":"idiom"},{"id":"idiom_1168","en":"launch a campaign","definition":"to start an organized effort to reach a goal","ko":"목표를 이루기 위한 조직적인 활동을 시작하다","cefr":"B2","type":"idiom"},{"id":"idiom_1169","en":"go with a swing","definition":"to be very successful and enjoyable","ko":"아주 성공적이고 즐겁게 진행되다","cefr":"B2","type":"idiom"},{"id":"idiom_1170","en":"the midas touch","definition":"the ability to make money or succeed easily","ko":"쉽게 돈을 벌거나 쉽게 성공하는 능력","cefr":"B2","type":"idiom"},{"id":"idiom_1171","en":"turn over a new leaf","definition":"to decide to change your life and behave better","ko":"삶을 바꾸기로 결심하고 더 잘 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_1172","en":"fall into the trap of","definition":"to make a common mistake without noticing it","ko":"모르는 사이에 흔한 실수를 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1173","en":"punch-drunk","definition":"confused and weak, like you cannot think clearly","ko":"머리가 멍하고 약해서 제대로 생각할 수 없는 상태","cefr":"B2","type":"idiom"},{"id":"idiom_1174","en":"play dirty","definition":"to behave unfairly to win or get what you want","ko":"원하는 것을 얻거나 이기려고 불공정하게 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_1175","en":"nearly fall off one's chair","definition":"to be extremely surprised or shocked","ko":"너무 놀라거나 충격을 받다","cefr":"B2","type":"idiom"},{"id":"idiom_1176","en":"out and about","definition":"going out and moving around, not staying at home","ko":"집에 있지 않고 밖에 나가서 여기저기 다니다","cefr":"B2","type":"idiom"},{"id":"idiom_1177","en":"hand sth to sb on a plate","definition":"to give someone something very easily, without them working for it","ko":"누군가가 노력하지 않아도 아주 쉽게 무언가를 주다","cefr":"B2","type":"idiom"},{"id":"idiom_1178","en":"be strapped for cash","definition":"to have very little money right now","ko":"지금 돈이 거의 없다","cefr":"B2","type":"idiom"},{"id":"idiom_1179","en":"throw a spanner in the works","definition":"to cause a problem that stops a plan from working","ko":"계획이 잘 안 되게 만드는 문제를 일으키다","cefr":"B2","type":"idiom"},{"id":"idiom_1180","en":"dog eat dog","definition":"a situation where people compete hard and are not kind to each other","ko":"사람들이 심하게 경쟁하고 서로 친절하지 않은 상황","cefr":"B2","type":"idiom"},{"id":"idiom_1181","en":"run in the family","definition":"to be common in a family, passed from parents to children","ko":"가족에게 흔하고 부모에게서 자녀에게 이어지다","cefr":"B2","type":"idiom"},{"id":"idiom_1182","en":"take each day as it comes","definition":"to deal with life one day at a time and not worry too much about the future","ko":"미래를 너무 걱정하지 않고 하루하루를 받아들이며 살다","cefr":"B2","type":"idiom"},{"id":"idiom_1183","en":"no ifs and buts","definition":"no excuses or arguments are accepted","ko":"변명이나 반박은 안 된다","cefr":"B2","type":"idiom"},{"id":"idiom_1184","en":"play one's ace card","definition":"to use your best advantage at the best time to win","ko":"이기기 위해 가장 좋은 장점을 가장 좋은 때에 쓰다","cefr":"B2","type":"idiom"},{"id":"idiom_1185","en":"filthy rich","definition":"extremely rich","ko":"엄청나게 부자다","cefr":"B2","type":"idiom"},{"id":"idiom_1186","en":"eat sb out of house and home","definition":"To eat so much food that it costs a family a lot of money.","ko":"너무 많이 먹어서 한 가족이 음식값으로 돈이 많이 들게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1187","en":"silent majority","definition":"The large group of people who do not speak loudly but have strong opinions.","ko":"크게 말하지는 않지만 의견이 강한 많은 사람들.","cefr":"B2","type":"idiom"},{"id":"idiom_1188","en":"ahead of the game","definition":"Doing better than others because you are prepared or have started early.","ko":"미리 준비했거나 일찍 시작해서 다른 사람들보다 더 잘하고 있는 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_1189","en":"throw a lifeline","definition":"To give help to someone in serious trouble.","ko":"큰 어려움에 있는 사람에게 도움을 주다.","cefr":"B2","type":"idiom"},{"id":"idiom_1190","en":"no-go area","definition":"A place that is too dangerous to enter or is not allowed.","ko":"너무 위험해서 들어가면 안 되거나, 들어가는 것이 금지된 곳.","cefr":"B2","type":"idiom"},{"id":"idiom_1191","en":"status quo","definition":"The current situation that people want to keep the same.","ko":"사람들이 그대로 유지하고 싶어 하는 현재의 상황.","cefr":"B2","type":"idiom"},{"id":"idiom_1192","en":"see sense","definition":"To start thinking in a reasonable way and make a better choice.","ko":"이성적으로 생각하기 시작해서 더 나은 선택을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1193","en":"look on the bright side","definition":"To try to think about the good parts of a bad situation.","ko":"나쁜 상황에서도 좋은 면을 생각하려고 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1194","en":"a paper tiger","definition":"Someone or something that seems strong but is actually weak.","ko":"강해 보이지만 실제로는 약한 사람이나 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1195","en":"spirit of adventure","definition":"A strong desire to explore new places and try new things.","ko":"새로운 곳을 탐험하고 새 일을 해 보고 싶은 강한 마음.","cefr":"B2","type":"idiom"},{"id":"idiom_1196","en":"for a split second","definition":"It happened very quickly, for a very short time.","ko":"아주 짧은 순간에, 아주 빠르게.","cefr":"B2","type":"idiom"},{"id":"idiom_1197","en":"would sell one's own grandmother","definition":"Someone will do anything for money, even hurt their family.","ko":"돈을 위해서라면 가족에게 해가 되는 일도 뭐든지 할 사람이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1198","en":"play gooseberry","definition":"To be the third person with a couple and feel awkward.","ko":"커플과 함께 있는 세 번째 사람이 되어 어색해하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1199","en":"win hands down","definition":"To win very easily.","ko":"아주 쉽게 이기다.","cefr":"B2","type":"idiom"},{"id":"idiom_1200","en":"a heart of stone","definition":"A person is very cold and has no sympathy.","ko":"매우 차갑고 동정심이 없는 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_1201","en":"be no fool","definition":"Someone is smart and not easy to trick.","ko":"똑똑해서 쉽게 속지 않는 사람이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1202","en":"come clean","definition":"To tell the truth after hiding it.","ko":"숨기던 일을 그만 숨기고 진실을 말하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1203","en":"do sth on autopilot","definition":"To do something automatically without thinking much.","ko":"많이 생각하지 않고 자동으로 어떤 일을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1204","en":"on the house","definition":"Free, paid for by the business.","ko":"가게나 회사가 내서 무료인 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1205","en":"all's fair in love and war","definition":"In love or war, people think any action is acceptable to win.","ko":"사랑이나 전쟁에서는 이기기 위해 어떤 행동이든 괜찮다고 여긴다.","cefr":"B2","type":"idiom"},{"id":"idiom_1206","en":"pound of flesh","definition":"something you demand from someone, even if it is unfair or too much.","ko":"불공평하거나 너무 많은데도, 누군가에게서 꼭 받아내려고 요구하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1207","en":"mind over matter","definition":"using your mind to control your body or feelings.","ko":"마음으로 몸이나 감정을 조절하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1208","en":"dice with death","definition":"to take a very dangerous risk that could kill you.","ko":"죽을 수도 있는 아주 위험한 일을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1209","en":"show one's hand","definition":"to show your plans or secrets to others.","ko":"자기 계획이나 비밀을 남들에게 드러내다.","cefr":"B2","type":"idiom"},{"id":"idiom_1210","en":"an aladdin's cave","definition":"a place full of many interesting and valuable things.","ko":"재미있고 값진 것들이 많이 있는 곳.","cefr":"B2","type":"idiom"},{"id":"idiom_1211","en":"have a sinking feeling","definition":"to suddenly feel worried that something bad will happen.","ko":"갑자기 나쁜 일이 생길 것 같아 걱정되다.","cefr":"B2","type":"idiom"},{"id":"idiom_1212","en":"beat sb hands down","definition":"to beat someone very easily.","ko":"누군가를 아주 쉽게 이기다.","cefr":"B2","type":"idiom"},{"id":"idiom_1213","en":"creature comforts","definition":"small things that make life easier and more pleasant.","ko":"생활을 더 편하고 즐겁게 해 주는 작은 것들.","cefr":"B2","type":"idiom"},{"id":"idiom_1214","en":"gravy train","definition":"an easy way to make a lot of money with little work.","ko":"일은 적게 하고 돈은 쉽게 많이 버는 방법.","cefr":"B2","type":"idiom"},{"id":"idiom_1215","en":"as thick as thieves","definition":"very close friends who do everything together.","ko":"아주 친해서 늘 함께 다니는 친구들.","cefr":"B2","type":"idiom"},{"id":"idiom_1216","en":"stark naked","definition":"completely naked, with no clothes on.","ko":"옷을 하나도 안 입은, 완전히 알몸인.","cefr":"B2","type":"idiom"},{"id":"idiom_1217","en":"do a roaring trade","definition":"sell a lot of things and make a lot of money.","ko":"물건을 아주 많이 팔아서 돈을 많이 벌다.","cefr":"B2","type":"idiom"},{"id":"idiom_1218","en":"a man of many parts","definition":"a man who can do many different things well.","ko":"여러 가지 일을 잘하는 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_1219","en":"run out of patience","definition":"stop being able to stay calm because you are tired of waiting or problems.","ko":"기다리거나 문제가 계속돼서 더 이상 참지 못하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1220","en":"it's easy to be wise after the event","definition":"it is easy to say what was right only after something has happened.","ko":"일이 끝난 뒤에는 뭐가 맞았는지 말하기 쉽다.","cefr":"B2","type":"idiom"},{"id":"idiom_1221","en":"a short sharp shock","definition":"a quick, strong punishment or lesson that stops bad behavior.","ko":"빠르고 강한 벌이나 교훈으로 나쁜 행동을 멈추게 하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1222","en":"a death trap","definition":"a place or thing that is very dangerous and could kill someone.","ko":"아주 위험해서 사람을 죽게 할 수도 있는 곳이나 물건.","cefr":"B2","type":"idiom"},{"id":"idiom_1223","en":"call a spade a spade","definition":"say the truth in a direct way, even if it sounds rude.","ko":"무례하게 들려도 돌려 말하지 않고 사실을 말하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1224","en":"a glass ceiling","definition":"an unfair hidden barrier that stops some people, often women, from getting top jobs.","ko":"특정 사람들, 특히 여성들이 높은 자리로 올라가지 못하게 막는 보이지 않는 불공평한 벽.","cefr":"B2","type":"idiom"},{"id":"idiom_1225","en":"take centre stage","definition":"become the main focus of attention.","ko":"가장 큰 관심을 받는 중심이 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_1226","en":"tie the knot","definition":"to get married","ko":"결혼하다","cefr":"B2","type":"idiom"},{"id":"idiom_1227","en":"first and foremost","definition":"most importantly, before anything else","ko":"무엇보다도, 가장 중요하게","cefr":"B2","type":"idiom"},{"id":"idiom_1228","en":"be at odds with","definition":"to disagree with someone or something","ko":"~와 의견이 다르다, ~와 맞지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_1229","en":"it's not over till the fat lady sings","definition":"the result is not decided until the very end","ko":"끝날 때까지 결과는 모른다","cefr":"B2","type":"idiom"},{"id":"idiom_1230","en":"raise one's game","definition":"to start doing better than before","ko":"더 잘하다, 실력을 끌어올리다","cefr":"B2","type":"idiom"},{"id":"idiom_1231","en":"big time","definition":"very much; a lot","ko":"아주 많이; 크게","cefr":"B2","type":"idiom"},{"id":"idiom_1232","en":"fall on deaf ears","definition":"to be ignored and not listened to","ko":"무시당하다, 아무도 듣지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_1233","en":"risk life and limb","definition":"to do something very dangerous that could hurt or kill you","ko":"목숨을 걸다","cefr":"B2","type":"idiom"},{"id":"idiom_1234","en":"a face like thunder","definition":"a very angry look on someone's face","ko":"아주 화난 얼굴","cefr":"B2","type":"idiom"},{"id":"idiom_1235","en":"shrouded in mystery","definition":"hidden and hard to understand or explain","ko":"비밀에 싸여 있다, 알기 어렵다","cefr":"B2","type":"idiom"},{"id":"idiom_1236","en":"clip sb's wings","definition":"to limit someone's freedom or power so they cannot do what they want","ko":"누군가의 자유나 힘을 제한하다","cefr":"B2","type":"idiom"},{"id":"idiom_1237","en":"gas-guzzler","definition":"a car that uses a lot of fuel","ko":"기름을 많이 먹는 차","cefr":"B2","type":"idiom"},{"id":"idiom_1238","en":"be on the same wavelength","definition":"to think the same way and understand each other well","ko":"생각이 잘 통하다","cefr":"B2","type":"idiom"},{"id":"idiom_1239","en":"put one's foot in it","definition":"to say or do something embarrassing by mistake","ko":"실수로 민망한 말을 하다/행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_1240","en":"one's heart goes out sb","definition":"to feel very sorry for someone","ko":"~가 정말 안쓰럽다, 마음이 아프다","cefr":"B2","type":"idiom"},{"id":"idiom_1241","en":"hand over the reins","definition":"to give control or responsibility to someone else","ko":"권한/책임을 넘기다","cefr":"B2","type":"idiom"},{"id":"idiom_1242","en":"if one put one's mind to it","definition":"if you really try, you can do it","ko":"정말 마음먹고 노력하면 할 수 있다","cefr":"B2","type":"idiom"},{"id":"idiom_1243","en":"fall short of","definition":"to be less than what is needed or expected","ko":"~에 못 미치다","cefr":"B2","type":"idiom"},{"id":"idiom_1244","en":"fall for sb hook, line and sinker","definition":"to believe something completely, even if it is a trick","ko":"완전히 속다, 그대로 믿다","cefr":"B2","type":"idiom"},{"id":"idiom_1245","en":"rein in spending","definition":"to control costs and spend less money","ko":"비용을 통제하고 돈을 덜 쓰는 것","cefr":"B2","type":"idiom"},{"id":"idiom_1246","en":"fall into the wrong hands","definition":"to be taken by bad people who may use it for harm","ko":"나쁜 사람들이 가져가서 해롭게 사용할 수 있게 되는 것","cefr":"B2","type":"idiom"},{"id":"idiom_1247","en":"by and large","definition":"generally; in most cases","ko":"대체로; 대부분의 경우에","cefr":"B2","type":"idiom"},{"id":"idiom_1248","en":"bring sb down a peg or two","definition":"to make someone less proud by showing they are not so important","ko":"누군가가 그렇게 대단하지 않다는 것을 보여 주어 거만함을 줄이게 하는 것","cefr":"B2","type":"idiom"},{"id":"idiom_1249","en":"put one's shoulder to the wheel","definition":"to work hard and help with a difficult job","ko":"열심히 일해서 어려운 일을 돕는 것","cefr":"B2","type":"idiom"},{"id":"idiom_1250","en":"any port in a storm","definition":"in a bad situation, any help or place is good enough","ko":"상황이 나쁠 때는 어떤 도움이나 장소든 충분하다는 뜻","cefr":"B2","type":"idiom"},{"id":"idiom_1251","en":"shut up shop","definition":"to close a business or stop operating","ko":"가게나 사업을 닫고 운영을 멈추는 것","cefr":"B2","type":"idiom"},{"id":"idiom_1252","en":"to put it mildly","definition":"used to say something is less bad than it really is","ko":"실제로는 더 나쁜데, 덜 심하게 말할 때 쓰는 표현","cefr":"B2","type":"idiom"},{"id":"idiom_1253","en":"to say the least","definition":"used to add that something is even more true or serious than said","ko":"말한 것보다 실제로는 더 심하다는 뜻을 덧붙일 때 쓰는 표현","cefr":"B2","type":"idiom"},{"id":"idiom_1254","en":"the game's up","definition":"it is finished; someone has been caught and cannot continue","ko":"끝났다; 들켜서 더는 계속할 수 없다","cefr":"B2","type":"idiom"},{"id":"idiom_1255","en":"push the right buttons","definition":"to say or do the right thing to make someone react the way you want","ko":"원하는 반응이 나오게 딱 맞는 말이나 행동을 하는 것","cefr":"B2","type":"idiom"},{"id":"idiom_1256","en":"a glutton for punishment","definition":"a person who keeps doing hard or painful things, even when they do not need to","ko":"굳이 안 해도 되는데도 힘들거나 괴로운 일을 계속 하는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_1257","en":"keep one's finger on the pulse","definition":"to stay very aware of what is happening now","ko":"지금 무슨 일이 일어나는지 아주 잘 알고 있는 것","cefr":"B2","type":"idiom"},{"id":"idiom_1258","en":"a whole new ball game","definition":"a completely different situation from before","ko":"이전과 완전히 다른 상황","cefr":"B2","type":"idiom"},{"id":"idiom_1259","en":"for all sb cares","definition":"used to say someone does not care at all","ko":"전혀 상관없다는 뜻으로 쓰는 표현","cefr":"B2","type":"idiom"},{"id":"idiom_1260","en":"a fair-weather friend","definition":"a friend who is only friendly when things are going well for you","ko":"내가 잘될 때만 친한 척하는 친구","cefr":"B2","type":"idiom"},{"id":"idiom_1261","en":"fall through the floor","definition":"to feel extremely embarrassed and want to disappear","ko":"너무 창피해서 사라지고 싶다","cefr":"B2","type":"idiom"},{"id":"idiom_1262","en":"go out like a light","definition":"to fall asleep very quickly","ko":"아주 빨리 잠들다","cefr":"B2","type":"idiom"},{"id":"idiom_1263","en":"lick one's wounds","definition":"to take time to recover after a loss or bad experience","ko":"패배나 나쁜 일을 겪은 뒤 회복할 시간을 갖다","cefr":"B2","type":"idiom"},{"id":"idiom_1264","en":"the first lady of sth","definition":"the most important and respected woman in a particular area","ko":"어떤 분야에서 가장 중요하고 존경받는 여성","cefr":"B2","type":"idiom"},{"id":"idiom_1265","en":"be on the warpath","definition":"To be very angry and ready to argue or fight.","ko":"아주 화가 나서 말다툼이나 싸움을 할 준비가 된 상태이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1266","en":"debt of honour","definition":"A promise to pay someone back because it is the right thing to do.","ko":"옳은 일이기 때문에 누군가에게 갚겠다고 하는 약속이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1267","en":"the plot thickens","definition":"Things are getting more complicated and interesting.","ko":"일이 더 복잡해지고 더 흥미로워지고 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_1268","en":"in the twinkling of an eye","definition":"Very quickly, in a very short time.","ko":"아주 빨리, 아주 짧은 시간에.","cefr":"B2","type":"idiom"},{"id":"idiom_1269","en":"wouldn't give sth house room","definition":"To dislike something so much you would not allow it in your home.","ko":"너무 싫어서 집 안에 들이지도 않으려 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1270","en":"i'll believe it when i see it","definition":"I will only believe it after I have proof.","ko":"증거를 보기 전에는 믿지 않겠다는 뜻이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1271","en":"in sb's wake","definition":"Following behind someone or something, as a result of what they did.","ko":"누군가나 무언가가 한 일의 결과로, 그 뒤를 따라.","cefr":"B2","type":"idiom"},{"id":"idiom_1272","en":"behind sb's back","definition":"Without someone knowing, secretly.","ko":"상대가 모르게, 몰래.","cefr":"B2","type":"idiom"},{"id":"idiom_1273","en":"put one's money where one's mouth is","definition":"To take action and support your words with real effort or money.","ko":"말만 하지 말고 실제 행동이나 돈으로 보여 주다.","cefr":"B2","type":"idiom"},{"id":"idiom_1274","en":"point the finger at","definition":"To blame someone for a problem.","ko":"문제의 책임을 누군가에게 돌리다.","cefr":"B2","type":"idiom"},{"id":"idiom_1275","en":"nothing ventured, nothing gained","definition":"If you do not take a risk, you cannot get a reward.","ko":"위험을 감수하지 않으면 얻는 것도 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_1276","en":"one have to hand it to sb","definition":"To say someone deserves praise or credit.","ko":"누군가가 칭찬받을 만하다고 말하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1277","en":"footloose and fancy-free","definition":"Free to do what you want, with no family or work ties.","ko":"가족이나 일에 얽매이지 않고 하고 싶은 대로 할 수 있는 상태이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1278","en":"as straight as a ramrod","definition":"Very straight and upright.","ko":"아주 똑바르고 꼿꼿하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1279","en":"more by luck than judgement","definition":"Successful mostly because of luck, not skill.","ko":"실력보다 운이 좋아서 성공한 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1280","en":"feel hard done by","definition":"To feel you were treated unfairly.","ko":"부당하게 대우받았다고 느끼다.","cefr":"B2","type":"idiom"},{"id":"idiom_1281","en":"happy-go-lucky","definition":"Cheerful and not worried about problems.","ko":"밝고 걱정을 잘 안 하는 성격이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1282","en":"as thin as a rake","definition":"Very thin.","ko":"아주 마르다.","cefr":"B2","type":"idiom"},{"id":"idiom_1283","en":"be fresh out of sth","definition":"To have none left of something.","ko":"어떤 것이 하나도 남아 있지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1284","en":"fall foul of","definition":"to get into trouble or conflict with a rule, law, or person","ko":"규칙, 법, 또는 어떤 사람과 문제나 갈등에 빠지다","cefr":"B2","type":"idiom"},{"id":"idiom_1285","en":"neck and neck","definition":"at the same speed, with no one ahead","ko":"속도가 같아서 아무도 앞서지 않는 상태","cefr":"B2","type":"idiom"},{"id":"idiom_1286","en":"have one's name in lights","definition":"to be famous and get a lot of public attention","ko":"유명해져서 많은 사람들의 관심을 받다","cefr":"B2","type":"idiom"},{"id":"idiom_1287","en":"move the goalposts","definition":"to change the rules to make it harder for someone to succeed","ko":"누군가 성공하기 어렵게 규칙을 바꾸다","cefr":"B2","type":"idiom"},{"id":"idiom_1288","en":"a slap in the face","definition":"something that makes you feel insulted or hurt","ko":"모욕적이거나 상처가 되는 일","cefr":"B2","type":"idiom"},{"id":"idiom_1289","en":"lay a hand on","definition":"to touch or hurt someone, usually in a violent way","ko":"보통 폭력적으로 누군가를 만지거나 해치다","cefr":"B2","type":"idiom"},{"id":"idiom_1290","en":"one has got me there","definition":"you are right and I have no answer","ko":"네 말이 맞고 나는 할 말이 없다","cefr":"B2","type":"idiom"},{"id":"idiom_1291","en":"be au fait with","definition":"to be familiar with and understand something well","ko":"어떤 것에 익숙하고 잘 이해하다","cefr":"B2","type":"idiom"},{"id":"idiom_1292","en":"bite off more than one can chew","definition":"to try to do too much and fail or struggle","ko":"너무 많은 일을 하려고 해서 힘들어지거나 실패하다","cefr":"B2","type":"idiom"},{"id":"idiom_1293","en":"a lot of ground to make up","definition":"to need to catch up because you are behind","ko":"뒤처져서 따라잡아야 할 것이 많다","cefr":"B2","type":"idiom"},{"id":"idiom_1294","en":"any friend of yours is a friend of mine","definition":"If you like someone, you will also like their friends.","ko":"네가 좋아하는 사람의 친구도 나도 좋아한다는 뜻","cefr":"B2","type":"idiom"},{"id":"idiom_1295","en":"in the dead of night","definition":"Very late at night, when it is darkest and quietest.","ko":"밤이 가장 늦고 가장 어둡고 조용할 때","cefr":"B2","type":"idiom"},{"id":"idiom_1296","en":"have the ear of sb","definition":"To be able to talk to an important person and influence them.","ko":"중요한 사람과 쉽게 이야기할 수 있고 그에게 영향을 줄 수 있다","cefr":"B2","type":"idiom"},{"id":"idiom_1297","en":"blue-sky thinking","definition":"Thinking of big, new ideas without worrying about limits.","ko":"제한을 걱정하지 않고 큰 새 아이디어를 생각하는 것","cefr":"B2","type":"idiom"},{"id":"idiom_1298","en":"beat a retreat","definition":"To move back or leave because it is safer or better to stop.","ko":"더 안전하거나 그만두는 게 나아서 뒤로 물러나거나 떠나다","cefr":"B2","type":"idiom"},{"id":"idiom_1299","en":"enough is as good as a feast","definition":"Having enough is just as good as having a lot.","ko":"충분히 있으면 많이 있는 것만큼 좋다","cefr":"B2","type":"idiom"},{"id":"idiom_1300","en":"the shit hits the fan","definition":"When a bad situation suddenly becomes much worse and everyone finds out.","ko":"나쁜 일이 갑자기 더 크게 터지고 모두가 알게 되다","cefr":"B2","type":"idiom"},{"id":"idiom_1301","en":"lose one's touch","definition":"To not be as good at something as you used to be.","ko":"예전만큼 잘하지 못하게 되다","cefr":"B2","type":"idiom"},{"id":"idiom_1302","en":"pull the rug from under one's feet","definition":"To suddenly take away someone's support or plans and leave them shocked.","ko":"갑자기 지원이나 계획을 빼앗아 충격을 주다","cefr":"B2","type":"idiom"},{"id":"idiom_1303","en":"between a rock and a hard place","definition":"You must choose between two bad options.","ko":"두 가지 나쁜 선택 중에서 하나를 골라야 한다.","cefr":"B2","type":"idiom"},{"id":"idiom_1304","en":"under cover of darkness","definition":"Secretly at night, when it is dark.","ko":"어두운 밤에 몰래.","cefr":"B2","type":"idiom"},{"id":"idiom_1305","en":"it will all end in tears","definition":"It will end badly and make people very upset.","ko":"결국 나쁘게 끝나서 사람들이 아주 속상해질 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1306","en":"put our heads together","definition":"Work together to think of a solution.","ko":"함께 머리를 맞대고 해결책을 생각하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1307","en":"hold one's own","definition":"Do well in a difficult situation without being beaten.","ko":"어려운 상황에서도 지지 않고 잘 해내다.","cefr":"B2","type":"idiom"},{"id":"idiom_1308","en":"oil the wheels","definition":"Make a process easier and faster.","ko":"일이 더 쉽고 빠르게 진행되게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1309","en":"be all over sb like a rash","definition":"Follow someone everywhere and give them too much attention.","ko":"누군가를 어디든 따라다니며 너무 많은 관심을 주다.","cefr":"B2","type":"idiom"},{"id":"idiom_1310","en":"send shivers down one's spine","definition":"Make you feel very scared or creeped out.","ko":"아주 무섭거나 소름 끼치게 만들다.","cefr":"B2","type":"idiom"},{"id":"idiom_1311","en":"c'est la vie","definition":"This is life; you must accept it.","ko":"인생이란 그런 거야; 받아들여야 해.","cefr":"B2","type":"idiom"},{"id":"idiom_1312","en":"too much information","definition":"You are sharing more personal details than I want to hear.","ko":"너무 개인적인 얘기를 너무 자세히 말하고 있어.","cefr":"B2","type":"idiom"},{"id":"idiom_1313","en":"on the one hand, on the other hand","definition":"You show two different sides of a situation or two different opinions.","ko":"상황의 두 가지 면이나 두 가지 의견을 말하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1314","en":"take sb for a ride","definition":"To trick someone and get money or an advantage from them.","ko":"누군가를 속여서 돈이나 이득을 챙기다.","cefr":"B2","type":"idiom"},{"id":"idiom_1315","en":"tough it out","definition":"To keep going and not give up, even when it is hard.","ko":"힘들어도 계속 버티며 포기하지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1316","en":"hard up","definition":"Having very little money.","ko":"돈이 거의 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_1317","en":"get the shock of one's life","definition":"To feel extremely surprised and shocked.","ko":"인생에서 가장 큰 충격을 받다.","cefr":"B2","type":"idiom"},{"id":"idiom_1318","en":"meet sb halfway","definition":"To agree to a fair compromise with someone.","ko":"서로 공평하게 타협하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1319","en":"be hard put to","definition":"To find it very difficult to do something.","ko":"무언가를 하기가 매우 어렵다.","cefr":"B2","type":"idiom"},{"id":"idiom_1320","en":"a contradiction in terms","definition":"A phrase that does not make sense because the words conflict.","ko":"단어들이 서로 맞지 않아서 말이 안 되는 표현.","cefr":"B2","type":"idiom"},{"id":"idiom_1321","en":"be an old hand at sth","definition":"To be very experienced at doing something.","ko":"무언가에 아주 경험이 많다.","cefr":"B2","type":"idiom"},{"id":"idiom_1322","en":"take one's eye off the ball","definition":"To stop paying attention and make a mistake.","ko":"집중을 멈춰서 실수하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1323","en":"the fact of the matter is","definition":"It means the real truth is this.","ko":"진짜 사실은 이거라는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1324","en":"knock into shape","definition":"It means to improve something so it works well.","ko":"무언가를 더 좋게 고쳐서 잘 되게 만든다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1325","en":"have plenty of strings to one's bow","definition":"It means to have many different skills or ways to succeed.","ko":"여러 가지 기술이나 성공할 방법이 많다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1326","en":"gardening leave","definition":"It means paid time off work after you leave a job, before your contract ends.","ko":"퇴사한 뒤 계약이 끝나기 전까지, 월급을 받으면서 쉬는 기간이라는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1327","en":"be no joke","definition":"It means something is serious and not funny or easy.","ko":"심각해서 농담이 아니고, 쉽지 않다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1328","en":"baptism of fire","definition":"It means a first experience that is difficult and tests you.","ko":"처음 겪는 일이 아주 힘들어서 너를 시험하는 경험이라는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1329","en":"point the way to","definition":"It means to show the direction or best way to do something.","ko":"방향이나 가장 좋은 방법을 보여 준다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1330","en":"set in motion","definition":"It means to start something so it begins to happen.","ko":"무언가가 일어나기 시작하게 만들다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1331","en":"give or take","definition":"It means approximately, plus or minus a small amount.","ko":"대략, 조금 더하거나 빼서라는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1332","en":"the spitting image","definition":"someone looks exactly like another person.","ko":"누군가가 다른 사람과 똑같이 닮았다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1333","en":"go off the rails","definition":"to lose control and start behaving in a bad or crazy way.","ko":"통제력을 잃고 나쁘거나 이상하게 행동하기 시작하다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1334","en":"read sb's mind","definition":"to know what someone is thinking without them saying it.","ko":"말하지 않아도 상대가 무슨 생각을 하는지 알다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1335","en":"as dry as dust","definition":"very boring and not interesting.","ko":"아주 지루하고 재미없다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1336","en":"be barking up the wrong tree","definition":"to look in the wrong place or blame the wrong person.","ko":"잘못된 곳을 찾거나, 잘못된 사람을 탓한다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1337","en":"set the wheels in motion","definition":"to start a process that will lead to something happening.","ko":"무언가가 일어나게 되는 과정을 시작한다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1338","en":"come up trumps","definition":"to succeed or work out very well.","ko":"성공하거나 결과가 아주 잘 나오다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1339","en":"prick one's ears up","definition":"to listen carefully because something sounds important or interesting.","ko":"중요하거나 흥미로운 것 같아서 귀를 기울여 잘 듣는다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1340","en":"grey vote","definition":"older people as a group who vote in elections.","ko":"선거에서 투표하는 노년층 유권자들을 말해요.","cefr":"B2","type":"idiom"},{"id":"idiom_1341","en":"give sth a miss","definition":"to choose not to do something.","ko":"무언가를 하지 않기로 선택한다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1342","en":"a smart move","definition":"A choice that is wise and likely to bring good results.","ko":"현명한 선택이고 좋은 결과를 가져올 가능성이 큰 선택.","cefr":"B2","type":"idiom"},{"id":"idiom_1343","en":"as stiff as a ramrod","definition":"Very straight and not relaxed.","ko":"아주 똑바르고 긴장해서 편하지 않은 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_1344","en":"golden hello","definition":"A large payment given to someone when they start a new job.","ko":"새 직장을 시작할 때 받는 큰 돈(입사 보너스).","cefr":"B2","type":"idiom"},{"id":"idiom_1345","en":"play to the gallery","definition":"To act in a way that tries to impress people instead of being honest.","ko":"솔직하기보다 사람들에게 잘 보이려고 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1346","en":"the bigger they are, the harder they fall","definition":"Important or powerful people can fail badly too.","ko":"중요하거나 힘 있는 사람도 크게 실패할 수 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_1347","en":"play sb for a fool","definition":"To trick someone and make them look stupid.","ko":"누군가를 속여서 바보처럼 보이게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1348","en":"pride comes before a fall","definition":"If you are too proud, you may make a mistake and fail.","ko":"너무 자만하면 실수해서 실패할 수 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_1349","en":"laissez-faire","definition":"A style of control that gives people freedom and few rules.","ko":"사람들에게 자유를 주고 규칙을 거의 두지 않는 방식.","cefr":"B2","type":"idiom"},{"id":"idiom_1350","en":"too clever by half","definition":"Trying to be smart in a way that is annoying or not really smart.","ko":"똑똑한 척을 너무 해서 짜증 나거나, 사실 별로 똑똑하지 않은 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1351","en":"blood, sweat and tears","definition":"Very hard work and great effort over a long time.","ko":"오랜 시간 동안 아주 힘들게 한 노력.","cefr":"B2","type":"idiom"},{"id":"idiom_1352","en":"be given the go-ahead","definition":"to be officially allowed to start something","ko":"공식적으로 시작해도 된다는 허가를 받다.","cefr":"B2","type":"idiom"},{"id":"idiom_1353","en":"suck it and see","definition":"to try something and see if it works","ko":"일단 해 보고 되는지 확인하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1354","en":"play the fool","definition":"to act silly or stupid on purpose","ko":"일부러 바보처럼 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1355","en":"part and parcel","definition":"a normal and necessary part of something","ko":"어떤 것의 정상적이고 꼭 필요한 부분.","cefr":"B2","type":"idiom"},{"id":"idiom_1356","en":"at the top of the ladder","definition":"in the highest position in a job or group","ko":"직장이나 집단에서 가장 높은 자리.","cefr":"B2","type":"idiom"},{"id":"idiom_1357","en":"the good old days","definition":"a time in the past that people remember as better","ko":"사람들이 더 좋았다고 기억하는 옛날.","cefr":"B2","type":"idiom"},{"id":"idiom_1358","en":"fair's fair","definition":"rules should be the same for everyone","ko":"공평하게 해야 한다; 규칙은 모두에게 같아야 한다.","cefr":"B2","type":"idiom"},{"id":"idiom_1359","en":"i wouldn't trust sb as far as i could throw them","definition":"I do not trust that person at all","ko":"그 사람을 전혀 믿지 못하겠다.","cefr":"B2","type":"idiom"},{"id":"idiom_1360","en":"sb's face doesn't fit","definition":"someone is not accepted by a group, even if they are good","ko":"실력이 있어도 그 집단에서 받아들여지지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1361","en":"a wolf in sheep's clothing","definition":"a person who seems kind but is really dangerous or dishonest","ko":"겉으로는 착해 보이지만 사실은 위험하거나 거짓된 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_1362","en":"as silent as the grave","definition":"completely quiet, with no sound at all.","ko":"완전히 조용해서 아무 소리도 없는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1363","en":"in the wake of sb","definition":"following someone, or happening after them.","ko":"누군가를 따라가거나, 그 사람 뒤에 이어서 일어나는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1364","en":"play a waiting game","definition":"to wait and be patient until the right time to act.","ko":"때를 기다리며 인내하면서 기다리다.","cefr":"B2","type":"idiom"},{"id":"idiom_1365","en":"the dice are loaded against sb","definition":"someone has an unfair disadvantage, so it is hard for them to win.","ko":"누군가에게 불리해서, 이기기 아주 어려운 상태이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1366","en":"get the all-clear","definition":"to get official permission or confirmation that it is safe to continue.","ko":"계속해도 안전하다는 공식 허가나 확인을 받다.","cefr":"B2","type":"idiom"},{"id":"idiom_1367","en":"cry wolf","definition":"to warn about danger that is not real, so people stop believing you.","ko":"진짜가 아닌 위험을 경고해서, 사람들이 더 이상 믿지 않게 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_1368","en":"the kiss of death","definition":"something that causes a plan or business to fail.","ko":"계획이나 사업을 망하게 만드는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1369","en":"drop the ball","definition":"to make a mistake or fail to do something important.","ko":"실수하거나 중요한 일을 하지 못하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1370","en":"pull rank","definition":"to use your higher position to make someone do what you want.","ko":"더 높은 지위를 이용해서 남에게 네가 원하는 대로 하게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1371","en":"run its course","definition":"to continue until it naturally ends.","ko":"자연스럽게 끝날 때까지 계속되다.","cefr":"B2","type":"idiom"},{"id":"idiom_1372","en":"men in grey suits","definition":"powerful officials who make decisions quietly, often in government or business.","ko":"정부나 회사에서 조용히 결정을 내리는 힘 있는 사람들.","cefr":"B2","type":"idiom"},{"id":"idiom_1373","en":"a cog in the machine","definition":"a small part of a big system, with little power to change things.","ko":"큰 시스템의 작은 부분이라서, 바꿀 힘이 거의 없는 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_1374","en":"harder than one would bargained for","definition":"more difficult than you expected.","ko":"예상했던 것보다 더 어렵다.","cefr":"B2","type":"idiom"},{"id":"idiom_1375","en":"a game plan","definition":"a clear plan for what you will do to succeed.","ko":"성공하기 위해 무엇을 할지 정한 분명한 계획.","cefr":"B2","type":"idiom"},{"id":"idiom_1376","en":"a square meal","definition":"a good, filling meal.","ko":"좋고 배부르게 먹을 수 있는 한 끼.","cefr":"B2","type":"idiom"},{"id":"idiom_1377","en":"can't cut the mustard","definition":"not good enough to meet the needed standard.","ko":"필요한 수준에 못 미쳐서 충분히 좋지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1378","en":"up to scratch","definition":"good enough and at the right standard.","ko":"기준에 맞게 충분히 좋다.","cefr":"B2","type":"idiom"},{"id":"idiom_1379","en":"variety is the spice of life","definition":"life is more enjoyable when you try different things.","ko":"여러 가지를 해 보면 삶이 더 즐겁다.","cefr":"B2","type":"idiom"},{"id":"idiom_1380","en":"make a name for","definition":"become well known and respected for something.","ko":"무엇으로 유명해지고 인정받다.","cefr":"B2","type":"idiom"},{"id":"idiom_1381","en":"piping hot","definition":"very hot, especially food or drink.","ko":"아주 뜨거운 것, 특히 음식이나 음료.","cefr":"B2","type":"idiom"},{"id":"idiom_1382","en":"be on the fiddle","definition":"to be in prison","ko":"감옥에 있다","cefr":"B2","type":"idiom"},{"id":"idiom_1383","en":"listen with half an ear","definition":"to listen without paying much attention","ko":"대충 듣다, 별로 신경 쓰지 않고 듣다","cefr":"B2","type":"idiom"},{"id":"idiom_1384","en":"be sb's heart's desire","definition":"to be the thing someone wants most","ko":"누군가가 가장 원하는 것이다","cefr":"B2","type":"idiom"},{"id":"idiom_1385","en":"split hairs","definition":"to argue about very small details","ko":"아주 작은 것까지 따지며 말다툼하다","cefr":"B2","type":"idiom"},{"id":"idiom_1386","en":"touch base","definition":"to contact someone briefly to share or get information","ko":"잠깐 연락해서 소식이나 정보를 주고받다","cefr":"B2","type":"idiom"},{"id":"idiom_1387","en":"outstay one's welcome","definition":"to stay too long and make people uncomfortable","ko":"너무 오래 머물러서 남을 불편하게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1388","en":"line one's own pockets","definition":"to secretly take money for yourself, often dishonestly","ko":"(보통 부정하게) 몰래 자기 주머니를 채우다","cefr":"B2","type":"idiom"},{"id":"idiom_1389","en":"play it cool","definition":"to stay calm and not show strong feelings","ko":"침착하게 굴고 감정을 드러내지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_1390","en":"grass roots","definition":"connected to ordinary people in a community, not leaders","ko":"지도자가 아니라 평범한 사람들과 관련된","cefr":"B2","type":"idiom"},{"id":"idiom_1391","en":"hit sb hard","definition":"to affect someone very badly or strongly","ko":"누군가에게 아주 크게 나쁜 영향을 주다","cefr":"B2","type":"idiom"},{"id":"idiom_1392","en":"be in the public eye","definition":"to be seen and talked about by many people, like a famous person","ko":"많은 사람들에게 알려져서 늘 주목을 받다","cefr":"B2","type":"idiom"},{"id":"idiom_1393","en":"throw money down the drain","definition":"to waste money on something useless","ko":"쓸데없는 데 돈을 낭비하다","cefr":"B2","type":"idiom"},{"id":"idiom_1394","en":"take heart","definition":"to feel more hopeful and brave","ko":"희망을 갖고 용기를 내다","cefr":"B2","type":"idiom"},{"id":"idiom_1395","en":"it takes two to tango","definition":"both people are responsible for a problem or fight","ko":"문제나 싸움은 둘 다 책임이 있다","cefr":"B2","type":"idiom"},{"id":"idiom_1396","en":"don't even go there","definition":"do not talk about that topic because it will cause trouble","ko":"그 얘기는 꺼내지 마 (문제가 생기니까)","cefr":"B2","type":"idiom"},{"id":"idiom_1397","en":"make one's blood boil","definition":"to make you very angry","ko":"아주 화나게 만들다","cefr":"B2","type":"idiom"},{"id":"idiom_1398","en":"be in over one's head","definition":"to be in a situation that is too difficult for you","ko":"감당하기 너무 어려운 상황에 있다","cefr":"B2","type":"idiom"},{"id":"idiom_1399","en":"shell-shocked","definition":"very shocked and upset after something scary or sudden","ko":"무섭거나 갑작스러운 일 뒤에 크게 충격받고 멍한","cefr":"B2","type":"idiom"},{"id":"idiom_1400","en":"settle a score","definition":"to get revenge for something done to you","ko":"복수하다","cefr":"B2","type":"idiom"},{"id":"idiom_1401","en":"get a foot in the door","definition":"to get a small chance to enter a job or group","ko":"(일이나 단체에) 들어갈 작은 기회를 얻다","cefr":"B2","type":"idiom"},{"id":"idiom_1402","en":"bite the hand that feeds one","definition":"To hurt or criticize someone who helps you.","ko":"도와주는 사람을 해치거나 비판하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1403","en":"on the rocks","definition":"Having serious problems, especially in a relationship or plan.","ko":"특히 관계나 계획에 심각한 문제가 있는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1404","en":"call to arms","definition":"A strong request for people to fight or take action.","ko":"사람들에게 싸우거나 행동하라고 강하게 요청하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1405","en":"do a hatchet job on","definition":"To write or say something very unfair and very negative about someone.","ko":"누군가에 대해 아주 불공평하고 아주 나쁘게 말하거나 쓰는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1406","en":"rest on one's laurels","definition":"To stop trying because you are proud of past success.","ko":"과거의 성공에 만족해서 더 노력하지 않는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1407","en":"have friends in high places","definition":"To know important people who can help you.","ko":"도와줄 수 있는 중요한 사람들을 아는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1408","en":"bury one's head in the sand","definition":"To ignore a problem and hope it goes away.","ko":"문제를 무시하고 저절로 사라지길 바라는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1409","en":"where there's a will there's a way","definition":"If you really want to do something, you can find a way to do it.","ko":"정말 하고 싶으면 방법을 찾을 수 있다는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_1410","en":"fringe benefits","definition":"Extra things you get from a job besides your salary.","ko":"월급 말고도 직장에서 받는 추가 혜택.","cefr":"B2","type":"idiom"},{"id":"idiom_1411","en":"batten down the hatches","definition":"To prepare carefully for trouble or danger.","ko":"문제나 위험에 대비해 꼼꼼히 준비하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1412","en":"be given the sack","definition":"to lose your job because your employer fires you","ko":"회사에서 해고되어 직장을 잃는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1413","en":"not break the bank","definition":"to not cost too much money","ko":"돈이 너무 많이 들지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1414","en":"a leopard can't change its spots","definition":"people cannot easily change their true character","ko":"사람은 본성을 쉽게 바꾸지 못한다는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_1415","en":"weather the storm","definition":"to survive a very difficult time and keep going","ko":"아주 힘든 시간을 견디고 계속 나아가다.","cefr":"B2","type":"idiom"},{"id":"idiom_1416","en":"see the point","definition":"to understand why something is important or makes sense","ko":"왜 중요한지, 왜 말이 되는지 이해하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1417","en":"not know whether one is coming or going","definition":"to feel very confused and not know what to do","ko":"아주 혼란스러워서 무엇을 해야 할지 모이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1418","en":"open the door to","definition":"to create a chance for something new to happen","ko":"새로운 일이 일어날 기회를 만들다.","cefr":"B2","type":"idiom"},{"id":"idiom_1419","en":"wade through","definition":"to read or deal with something long and difficult","ko":"길고 어려운 것을 읽거나 처리하느라 애쓰다.","cefr":"B2","type":"idiom"},{"id":"idiom_1420","en":"rock hard","definition":"very hard and solid","ko":"아주 단단하고 딱딱한 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1421","en":"be one in the eye for sb","definition":"to be an annoying or embarrassing defeat for someone.","ko":"누군가에게 짜증 나거나 창피한 패배가 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_1422","en":"back on track","definition":"working well again after a problem or delay.","ko":"문제나 지연 뒤에 다시 잘 돌아가다.","cefr":"B2","type":"idiom"},{"id":"idiom_1423","en":"act the fool","definition":"to behave in a silly way.","ko":"바보처럼 어리석게 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1424","en":"be one's heart's desire","definition":"the thing someone wants most of all.","ko":"누군가가 가장 원하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1425","en":"amid mounting calls","definition":"while more and more people are asking for something to happen.","ko":"점점 더 많은 사람들이 어떤 일이 일어나길 요구하는 가운데.","cefr":"B2","type":"idiom"},{"id":"idiom_1426","en":"throw in the sponge","definition":"to give up and stop trying.","ko":"포기하고 그만두다.","cefr":"B2","type":"idiom"},{"id":"idiom_1427","en":"have half a mind to","definition":"to be thinking about doing something, but not sure yet.","ko":"아직 확실하진 않지만 뭔가를 할까 생각하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1428","en":"be head and shoulders above sb","definition":"much better than someone else.","ko":"다른 사람보다 훨씬 더 낫다.","cefr":"B2","type":"idiom"},{"id":"idiom_1429","en":"wait in the wings","definition":"ready and waiting to take action when needed.","ko":"필요할 때 바로 나설 준비를 하고 기다리다.","cefr":"B2","type":"idiom"},{"id":"idiom_1430","en":"as a matter of course","definition":"as a normal habit, without needing to think about it.","ko":"당연한 습관처럼, 따로 생각하지 않고.","cefr":"B2","type":"idiom"},{"id":"idiom_1431","en":"bumper to bumper","definition":"Traffic is so heavy that cars move very slowly.","ko":"차가 너무 많아서 아주 천천히 움직이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1432","en":"have one's hand in the till","definition":"To steal money from the place where you work.","ko":"직장에서 돈을 훔치다.","cefr":"B2","type":"idiom"},{"id":"idiom_1433","en":"let sleeping dogs lie","definition":"Do not talk about an old problem because it may cause trouble again.","ko":"옛날 문제를 꺼내지 마라. 다시 문제가 될 수 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_1434","en":"be centre stage","definition":"To be the main focus of attention.","ko":"가장 큰 관심을 받는 중심이 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_1435","en":"a fait accompli","definition":"Something is already decided and cannot be changed.","ko":"이미 결정되어서 바꿀 수 없는 일.","cefr":"B2","type":"idiom"},{"id":"idiom_1436","en":"wild horses couldn't make me","definition":"Nothing can force me to do it.","ko":"무슨 일이 있어도 나는 그렇게 못 한다.","cefr":"B2","type":"idiom"},{"id":"idiom_1437","en":"that's about the size of it","definition":"That is the main point and it is correct.","ko":"그게 핵심이고 맞는 말이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1438","en":"have a good mind to","definition":"To feel like you want to do something, often something a bit angry.","ko":"뭔가 하고 싶다는 마음이 들다(보통 좀 화가 나서).","cefr":"B2","type":"idiom"},{"id":"idiom_1439","en":"round the clock","definition":"All day and all night, without stopping.","ko":"하루 종일 밤낮없이, 쉬지 않고.","cefr":"B2","type":"idiom"},{"id":"idiom_1440","en":"pandora's box","definition":"A small action can cause many new problems.","ko":"작은 행동이 많은 새 문제를 불러올 수 있는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1441","en":"come to a standstill","definition":"to stop completely and not move or progress","ko":"완전히 멈추고 더 이상 움직이거나 진행하지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_1442","en":"give the green light","definition":"to give permission to start something","ko":"무언가를 시작해도 된다고 허락하다","cefr":"B2","type":"idiom"},{"id":"idiom_1443","en":"money for old rope","definition":"easy money for very little work","ko":"거의 일하지 않고 쉽게 버는 돈","cefr":"B2","type":"idiom"},{"id":"idiom_1444","en":"feather one's own nest","definition":"to use a job or position to get money or benefits for yourself","ko":"직업이나 지위를 이용해 자기만 이익을 챙기다","cefr":"B2","type":"idiom"},{"id":"idiom_1445","en":"on the straight and narrow","definition":"living an honest life and following the rules","ko":"정직하게 살고 규칙을 지키며 살다","cefr":"B2","type":"idiom"},{"id":"idiom_1446","en":"go out on the town","definition":"to go out at night to have fun in bars, clubs, or restaurants","ko":"밤에 밖에 나가 술집, 클럽, 식당 등에서 즐겁게 놀다","cefr":"B2","type":"idiom"},{"id":"idiom_1447","en":"be like ships that pass in the night","definition":"to meet briefly and not really connect or spend time together","ko":"잠깐 만나기만 하고 제대로 어울리거나 시간을 함께 보내지 못하다","cefr":"B2","type":"idiom"},{"id":"idiom_1448","en":"be quids in","definition":"to be making a profit or in a good financial situation","ko":"이익을 보고 있거나 돈 상황이 좋다","cefr":"B2","type":"idiom"},{"id":"idiom_1449","en":"bluff one's way","definition":"to succeed by pretending you know what you are doing","ko":"아는 척하며 속여서 성공하다","cefr":"B2","type":"idiom"},{"id":"idiom_1450","en":"shoot sb down in flames","definition":"to strongly criticize and completely reject someone's idea","ko":"누군가의 생각을 아주 강하게 비판하고 완전히 거절하다","cefr":"B2","type":"idiom"},{"id":"idiom_1451","en":"a dead duck","definition":"someone or something has no chance of success.","ko":"성공할 가능성이 전혀 없는 사람이나 것","cefr":"B2","type":"idiom"},{"id":"idiom_1452","en":"have a good head for sth","definition":"to be naturally good at a skill or subject.","ko":"어떤 기술이나 과목을 타고나게 잘하다","cefr":"B2","type":"idiom"},{"id":"idiom_1453","en":"make a pig's ear of sth","definition":"to do something very badly or make a mess of it.","ko":"무언가를 아주 못해서 망치다","cefr":"B2","type":"idiom"},{"id":"idiom_1454","en":"neat and tidy","definition":"clean and well organized, with everything in the right place.","ko":"깨끗하고 정돈되어 있으며 제자리에 잘 정리된","cefr":"B2","type":"idiom"},{"id":"idiom_1455","en":"cold cash","definition":"money in coins or notes, not a card or check.","ko":"카드나 수표가 아닌, 동전이나 지폐로 된 현금","cefr":"B2","type":"idiom"},{"id":"idiom_1456","en":"out of the question","definition":"completely impossible and not allowed.","ko":"절대 불가능하고 허용되지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_1457","en":"see life","definition":"to have many experiences and learn about the world.","ko":"많은 경험을 하며 세상을 배우다","cefr":"B2","type":"idiom"},{"id":"idiom_1458","en":"be under no illusions","definition":"to know the truth and not believe false hopes.","ko":"현실을 잘 알고 헛된 기대를 하지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_1459","en":"get the red card","definition":"to be sent off in a sports game for breaking the rules.","ko":"규칙을 어겨 스포츠 경기에서 퇴장당하다","cefr":"B2","type":"idiom"},{"id":"idiom_1460","en":"fighting fit","definition":"very healthy and strong, ready for action.","ko":"아주 건강하고 튼튼해서 바로 활동할 준비가 된","cefr":"B2","type":"idiom"},{"id":"idiom_1461","en":"push all the right buttons","definition":"to say or do the exact things that make someone happy or agree with you.","ko":"누군가를 기쁘게 하거나 내 말에 동의하게 만드는 딱 맞는 말이나 행동을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1462","en":"scare the life out of","definition":"to frighten someone very much.","ko":"누군가를 아주 많이 놀라게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1463","en":"rig an election","definition":"to cheat in voting so the result is not fair.","ko":"투표를 속여서 결과가 공정하지 않게 만들다.","cefr":"B2","type":"idiom"},{"id":"idiom_1464","en":"hit and miss","definition":"sometimes good and sometimes bad; not reliable.","ko":"어떨 때는 좋고 어떨 때는 나쁜; 믿기 어려운.","cefr":"B2","type":"idiom"},{"id":"idiom_1465","en":"not have two pennies to rub together","definition":"to have no money at all.","ko":"돈이 전혀 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_1466","en":"the sword of damocles","definition":"a serious danger that could happen at any time.","ko":"언제든지 일어날 수 있는 큰 위험.","cefr":"B2","type":"idiom"},{"id":"idiom_1467","en":"set the scene","definition":"to describe the situation at the start so people understand what happens next.","ko":"처음에 상황을 설명해서 다음 일을 이해하게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1468","en":"sort (out) the sheep from the goats","definition":"to separate the good people or things from the bad ones.","ko":"좋은 사람이나 것과 나쁜 사람이나 것을 가려내다.","cefr":"B2","type":"idiom"},{"id":"idiom_1469","en":"nobody in their right mind","definition":"no sensible person would do that.","ko":"제정신인 사람이라면 아무도 그렇게 하지 않는다.","cefr":"B2","type":"idiom"},{"id":"idiom_1470","en":"play it safe","definition":"to be careful and avoid risk.","ko":"조심해서 위험을 피하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1471","en":"fall on hard times","definition":"to become poor and have a difficult life for a period of time","ko":"한동안 가난해지고 힘든 시기를 겪다.","cefr":"B2","type":"idiom"},{"id":"idiom_1472","en":"like nailing jelly to a wall","definition":"very hard to do because the thing keeps changing or will not stay still","ko":"계속 바뀌거나 가만히 있지 않아서 하기가 매우 어렵다.","cefr":"B2","type":"idiom"},{"id":"idiom_1473","en":"not be one's thing","definition":"to not like something or not be good at it","ko":"그것을 좋아하지 않거나 잘하지 못하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1474","en":"necessity is the mother of invention","definition":"when you really need something, you find a new way to do it","ko":"정말 필요하면 새로운 방법을 찾아낸다.","cefr":"B2","type":"idiom"},{"id":"idiom_1475","en":"hang fire","definition":"to wait and not act yet","ko":"아직 행동하지 말고 기다리다.","cefr":"B2","type":"idiom"},{"id":"idiom_1476","en":"a wild-goose chase","definition":"a search that wastes time because it will not succeed","ko":"성공하지 못해서 시간만 낭비하는 헛수고.","cefr":"B2","type":"idiom"},{"id":"idiom_1477","en":"the gloves are off","definition":"people stop being polite and start fighting or competing strongly","ko":"이제 예의는 그만두고 본격적으로 싸우거나 강하게 경쟁한다.","cefr":"B2","type":"idiom"},{"id":"idiom_1478","en":"give sb a wide berth","definition":"to stay away from someone or something dangerous or unpleasant","ko":"위험하거나 불쾌한 사람이나 것을 피해서 멀리하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1479","en":"be heavy-going","definition":"slow and hard to get through because it is boring or difficult","ko":"지루하거나 어려워서 진행이 느리고 읽거나 하기 힘들다.","cefr":"B2","type":"idiom"},{"id":"idiom_1480","en":"under the counter","definition":"sold secretly and illegally, not in the normal way","ko":"정상적인 방법이 아니라 몰래 불법으로 팔다.","cefr":"B2","type":"idiom"},{"id":"idiom_1481","en":"silent partner","definition":"a person who invests money in a business but does not take part in running it","ko":"사업에 돈을 투자하지만 운영에는 참여하지 않는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_1482","en":"no end of","definition":"a very large amount of something","ko":"어떤 것의 아주 많은 양","cefr":"B2","type":"idiom"},{"id":"idiom_1483","en":"can't lay one's hands on sth","definition":"to be unable to find something","ko":"무언가를 찾지 못하다","cefr":"B2","type":"idiom"},{"id":"idiom_1484","en":"see red","definition":"to suddenly become very angry","ko":"갑자기 매우 화가 나다","cefr":"B2","type":"idiom"},{"id":"idiom_1485","en":"be on a collision course","definition":"to be heading toward a serious disagreement or conflict","ko":"심각한 의견 충돌이나 갈등으로 가는 중이다","cefr":"B2","type":"idiom"},{"id":"idiom_1486","en":"have a one-track mind","definition":"to think about only one thing all the time","ko":"항상 한 가지 생각만 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1487","en":"send sb packing","definition":"to tell someone to leave, usually because they are not wanted","ko":"원하지 않아서 누군가에게 떠나라고 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1488","en":"give sb a big hand","definition":"to applaud someone loudly","ko":"누군가에게 큰 박수를 치다","cefr":"B2","type":"idiom"},{"id":"idiom_1489","en":"drop a clanger","definition":"to say or do something embarrassing by mistake","ko":"실수로 창피한 말이나 행동을 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1490","en":"heads will roll","definition":"people will be punished or lose their jobs because of a serious mistake","ko":"큰 실수 때문에 사람들이 벌을 받거나 직장을 잃게 될 것이다","cefr":"B2","type":"idiom"},{"id":"idiom_1491","en":"tempt fate","definition":"to do something risky that could cause bad luck or trouble.","ko":"나쁜 일이나 문제를 부를 수 있는 위험한 일을 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1492","en":"between one and me","definition":"a secret that only you and one other person know.","ko":"너와 다른 한 사람만 아는 비밀","cefr":"B2","type":"idiom"},{"id":"idiom_1493","en":"be beyond the pale","definition":"to be completely unacceptable or shocking.","ko":"완전히 용납할 수 없거나 충격적이다","cefr":"B2","type":"idiom"},{"id":"idiom_1494","en":"after one's own heart","definition":"someone you like because they have the same tastes as you.","ko":"취향이 같아서 마음에 드는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_1495","en":"take one's mind off it","definition":"to do something so you stop thinking about a problem.","ko":"문제를 생각하지 않게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1496","en":"poacher turned gamekeeper","definition":"a person who used to do something wrong but now stops others from doing it.","ko":"예전에 나쁜 일을 했지만 지금은 다른 사람들이 못 하게 막는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_1497","en":"what is the world coming to?","definition":"said when you feel shocked or upset about how bad things are becoming.","ko":"세상이 점점 나빠지는 것 같아 충격이거나 속상할 때 하는 말","cefr":"B2","type":"idiom"},{"id":"idiom_1498","en":"blow one's own trumpet","definition":"to talk proudly about yourself and your achievements.","ko":"자기와 자기 성과를 자랑스럽게 말하다","cefr":"B2","type":"idiom"},{"id":"idiom_1499","en":"dead to the world","definition":"sleeping very deeply and not noticing anything.","ko":"아주 깊게 자서 아무것도 못 느끼다","cefr":"B2","type":"idiom"},{"id":"idiom_1500","en":"be not half","definition":"used to say something is very good or very bad (often in a surprised way).","ko":"(놀라면서) 아주 좋거나 아주 나쁘다고 말할 때 쓰는 표현","cefr":"B2","type":"idiom"},{"id":"idiom_1501","en":"mind one's ps and qs","definition":"Be very polite and careful about your behavior.","ko":"아주 예의 바르고 행동을 조심하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1502","en":"a last-ditch attempt","definition":"A final try when nothing else has worked.","ko":"다른 방법이 다 안 될 때 하는 마지막 시도.","cefr":"B2","type":"idiom"},{"id":"idiom_1503","en":"at the cutting edge","definition":"Using the newest and most advanced ideas or technology.","ko":"가장 최신이고 가장 앞선 아이디어나 기술을 쓰는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1504","en":"the sb from hell","definition":"A very bad or difficult person.","ko":"아주 나쁘거나 다루기 힘든 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_1505","en":"from the cradle to the grave","definition":"From birth until death.","ko":"태어날 때부터 죽을 때까지.","cefr":"B2","type":"idiom"},{"id":"idiom_1506","en":"bring to the table","definition":"Offer useful skills, ideas, or resources to a group.","ko":"그룹에 도움이 되는 기술, 아이디어, 자원 등을 제공하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1507","en":"go haywire","definition":"Stop working correctly and become out of control.","ko":"제대로 작동을 멈추고 통제할 수 없게 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_1508","en":"whatever floats one's boat","definition":"Do what you like; it's your choice.","ko":"네가 좋으면 그걸로 돼; 네 선택이야.","cefr":"B2","type":"idiom"},{"id":"idiom_1509","en":"sb's hands are tied","definition":"Be unable to act because rules or other people stop you.","ko":"규칙이나 다른 사람 때문에 행동할 수 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_1510","en":"steal a march on sb","definition":"Get an advantage over someone by acting first or more cleverly.","ko":"먼저 또는 더 영리하게 행동해서 남보다 유리해지다.","cefr":"B2","type":"idiom"},{"id":"idiom_1511","en":"out of hand","definition":"It becomes out of control.","ko":"통제할 수 없게 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_1512","en":"bring to book","definition":"To make someone answer for what they did wrong.","ko":"잘못한 일에 대해 책임을 지게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1513","en":"reach for the stars","definition":"To aim for very big goals.","ko":"아주 큰 목표를 세우다.","cefr":"B2","type":"idiom"},{"id":"idiom_1514","en":"learn the hard way","definition":"To learn something after a bad experience.","ko":"나쁜 경험을 한 뒤에 배우다.","cefr":"B2","type":"idiom"},{"id":"idiom_1515","en":"get the flak","definition":"To receive a lot of angry criticism.","ko":"많은 화난 비판을 받다.","cefr":"B2","type":"idiom"},{"id":"idiom_1516","en":"be torn","definition":"To feel unable to choose between two options.","ko":"두 가지 중에서 선택을 못 하고 마음이 흔들리다.","cefr":"B2","type":"idiom"},{"id":"idiom_1517","en":"sticking point","definition":"The main problem that stops progress.","ko":"진행을 막는 가장 큰 문제.","cefr":"B2","type":"idiom"},{"id":"idiom_1518","en":"eleventh-hour","definition":"Happening at the last possible moment.","ko":"마지막 순간에 일어나는.","cefr":"B2","type":"idiom"},{"id":"idiom_1519","en":"play into sb's hands","definition":"To do something that helps your opponent without meaning to.","ko":"의도하지 않게 상대에게 도움이 되는 일을 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1520","en":"for good reason","definition":"Because there is a clear and sensible reason.","ko":"분명하고 타당한 이유가 있어서.","cefr":"B2","type":"idiom"},{"id":"idiom_1521","en":"be built on sand","definition":"If something is built on sand, it is based on weak ideas and will probably fail.","ko":"무언가가 모래 위에 지어졌다면, 약한 생각에 바탕을 두어서 아마 실패할 거라는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1522","en":"spick and span","definition":"If a place is spick and span, it is very clean and tidy.","ko":"어떤 장소가 spick and span이면, 아주 깨끗하고 정돈되어 있다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1523","en":"one can't teach an old dog new tricks","definition":"One can't teach an old dog new tricks means it is hard for older people to change their habits.","ko":"one can't teach an old dog new tricks는 나이가 많은 사람은 습관을 바꾸기 어렵다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1524","en":"the boys in blue","definition":"The boys in blue means the police.","ko":"the boys in blue는 경찰을 뜻해요.","cefr":"B2","type":"idiom"},{"id":"idiom_1525","en":"not have a cat in hell's chance","definition":"Not have a cat in hell's chance means to have no chance at all.","ko":"not have a cat in hell's chance는 전혀 가능성이 없다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1526","en":"an old flame","definition":"An old flame is someone you loved in the past.","ko":"an old flame은 예전에 사랑했던 사람을 뜻해요.","cefr":"B2","type":"idiom"},{"id":"idiom_1527","en":"be falling apart at the seams","definition":"If something is falling apart at the seams, it is in very bad condition and breaking down.","ko":"무언가가 falling apart at the seams이면, 상태가 아주 나빠서 여기저기 망가지고 있다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1528","en":"sing from the same hymn sheet","definition":"To sing from the same hymn sheet means to agree and say the same things as others.","ko":"sing from the same hymn sheet는 다른 사람들과 의견이 같고 같은 말을 한다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1529","en":"beyond one's wildest dreams","definition":"Beyond one's wildest dreams means much better than you ever imagined.","ko":"beyond one's wildest dreams는 상상했던 것보다 훨씬 더 좋다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1530","en":"an armchair critic","definition":"A person who criticizes something but does not do it themselves.","ko":"an armchair critic은 자기는 하지 않으면서 남을 비판만 하는 사람이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1531","en":"there are plenty more fish in the sea","definition":"There are other good people or chances, so don't be too sad about one loss.","ko":"there are plenty more fish in the sea는 다른 좋은 사람이나 기회가 많으니 한 번의 실패로 너무 슬퍼하지 말라는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1532","en":"de facto","definition":"True in fact, even if not official.","ko":"de facto는 공식은 아니지만 실제로는 그렇다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1533","en":"ring the changes","definition":"To make small changes or try different ways to do something.","ko":"ring the changes는 작은 변화를 주거나 다른 방법을 시도해 보는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1534","en":"have stars in one's eyes","definition":"To have big dreams and be very excited, sometimes unrealistically.","ko":"have stars in one's eyes는 큰 꿈을 꾸고 아주 들떠 있는데, 때로는 현실적이지 않을 때도 있다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1535","en":"in a tight corner","definition":"In a difficult situation with few choices.","ko":"in a tight corner는 선택이 거의 없는 어려운 상황에 있다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1536","en":"as sick as a parrot","definition":"Very disappointed and upset.","ko":"as sick as a parrot는 아주 실망하고 속상하다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1537","en":"live on borrowed time","definition":"To continue living or existing when you might not have much time left.","ko":"live on borrowed time은 오래 못 갈 것 같은데도 계속 버티거나 존재한다는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1538","en":"that's a turn-up for the books","definition":"That is a very surprising and unexpected event.","ko":"that's a turn-up for the books는 아주 놀랍고 예상 밖의 일이라는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1539","en":"think twice","definition":"To think carefully before you do something.","ko":"think twice는 행동하기 전에 신중하게 생각하라는 뜻이에요.","cefr":"B2","type":"idiom"},{"id":"idiom_1540","en":"get one's tongue round sth","definition":"to be able to say a difficult word or phrase clearly","ko":"어려운 단어나 문장을 또렷하게 말할 수 있다","cefr":"B2","type":"idiom"},{"id":"idiom_1541","en":"an inside job","definition":"a crime done by someone inside the group or company","ko":"그 그룹이나 회사 안에 있는 사람이 저지른 범죄","cefr":"B2","type":"idiom"},{"id":"idiom_1542","en":"as happy as larry","definition":"very happy and pleased","ko":"아주 행복하고 기분이 좋은","cefr":"B2","type":"idiom"},{"id":"idiom_1543","en":"at one fell swoop","definition":"all at once, in one action","ko":"한 번에, 한 번의 행동으로","cefr":"B2","type":"idiom"},{"id":"idiom_1544","en":"cross that bridge when one come to it","definition":"to deal with a problem only when it happens","ko":"문제가 생겼을 때 그때 가서 해결하다","cefr":"B2","type":"idiom"},{"id":"idiom_1545","en":"plus ça change","definition":"things change, but they stay the same in some ways","ko":"바뀌는 것 같아도 어떤 점은 그대로다","cefr":"B2","type":"idiom"},{"id":"idiom_1546","en":"run out of steam","definition":"to lose energy or motivation and stop working well","ko":"기운이나 의욕이 떨어져서 더 이상 잘 못 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1547","en":"think outside the box","definition":"to think in a new and creative way","ko":"새롭고 창의적으로 생각하다","cefr":"B2","type":"idiom"},{"id":"idiom_1548","en":"stick in my mind","definition":"to stay in my memory for a long time","ko":"오랫동안 기억에 남다","cefr":"B2","type":"idiom"},{"id":"idiom_1549","en":"mind how one go","definition":"to be careful how you act or where you go","ko":"행동이나 가는 길을 조심하다","cefr":"B2","type":"idiom"},{"id":"idiom_1550","en":"join the ranks of","definition":"to become a member of a group, often a job or organization","ko":"어떤 집단(직업/조직)의 일원이 되다","cefr":"B2","type":"idiom"},{"id":"idiom_1551","en":"teach sb a lesson","definition":"to punish someone so they learn not to do something again","ko":"다시는 그러지 않게 벌을 주어 교훈을 주다","cefr":"B2","type":"idiom"},{"id":"idiom_1552","en":"drop a bombshell","definition":"to suddenly give shocking news","ko":"충격적인 소식을 갑자기 말하다","cefr":"B2","type":"idiom"},{"id":"idiom_1553","en":"stick two fingers up at sth","definition":"to show you do not care about a rule or authority in a rude way","ko":"규칙이나 권위에 무례하게 반항하며 신경 안 쓰는 태도를 보이다","cefr":"B2","type":"idiom"},{"id":"idiom_1554","en":"hold one's tongue","definition":"to stay silent and not say what you want to say","ko":"말하고 싶은 걸 참다, 침묵하다","cefr":"B2","type":"idiom"},{"id":"idiom_1555","en":"be in a dream world","definition":"to think in an unrealistic way and not see the real situation","ko":"현실적이지 않게 생각하고 현실을 못 보다","cefr":"B2","type":"idiom"},{"id":"idiom_1556","en":"be going great guns","definition":"to be doing very well and making fast progress","ko":"아주 잘되고 있고 빠르게 발전하다","cefr":"B2","type":"idiom"},{"id":"idiom_1557","en":"it's not over until the fat lady sings","definition":"you cannot be sure of the result until the very end","ko":"끝까지 가 봐야 결과를 안다","cefr":"B2","type":"idiom"},{"id":"idiom_1558","en":"crystal clear","definition":"very easy to understand","ko":"아주 분명해서 이해하기 쉬운","cefr":"B2","type":"idiom"},{"id":"idiom_1559","en":"in one's own time","definition":"at your own pace, without being rushed","ko":"서두르지 않고 자기 속도로","cefr":"B2","type":"idiom"},{"id":"idiom_1560","en":"do a runner","definition":"to run away suddenly to avoid trouble or paying.","ko":"문제나 돈 내는 것을 피하려고 갑자기 도망가는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1561","en":"be batting a thousand","definition":"to be very successful and not making mistakes.","ko":"아주 성공적이고 실수가 없는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1562","en":"toe the line","definition":"to follow the rules or do what you are told.","ko":"규칙을 따르거나 시키는 대로 하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1563","en":"on balance","definition":"when you consider everything, overall.","ko":"모든 것을 생각해 보면, 전체적으로.","cefr":"B2","type":"idiom"},{"id":"idiom_1564","en":"prince charming","definition":"the perfect man someone dreams of marrying.","ko":"누군가가 결혼하고 싶다고 꿈꾸는 완벽한 남자.","cefr":"B2","type":"idiom"},{"id":"idiom_1565","en":"go bust","definition":"to fail in business and lose all your money.","ko":"사업이 망해서 돈을 다 잃는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1566","en":"fat chance","definition":"used to say something is very unlikely.","ko":"그럴 가능성이 거의 없다는 뜻으로 하는 말.","cefr":"B2","type":"idiom"},{"id":"idiom_1567","en":"rags to riches","definition":"a story of someone going from very poor to very rich.","ko":"아주 가난했다가 아주 부자가 되는 이야기.","cefr":"B2","type":"idiom"},{"id":"idiom_1568","en":"scrimp and save","definition":"to spend as little money as possible and save carefully.","ko":"돈을 최대한 아끼고 조심해서 저축하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1569","en":"be on the blink","definition":"not working properly; broken or failing.","ko":"제대로 작동하지 않는 것; 고장 난 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1570","en":"make sb's toes curl","definition":"to make someone feel very shocked or embarrassed.","ko":"누군가를 아주 충격받게 하거나 창피하게 만드는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1571","en":"might as well be hung for a sheep as a lamb","definition":"if you are going to be punished anyway, you may as well do the bigger thing.","ko":"어차피 벌을 받을 거라면, 더 큰 일도 하는 게 낫다는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_1572","en":"push the envelope","definition":"to try to do something new and more advanced than before.","ko":"새롭고 더 발전된 것을 시도하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1573","en":"a flash in the pan","definition":"something that looks successful at first but quickly fails.","ko":"처음엔 성공한 것 같지만 금방 실패하는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1574","en":"catch some z's","definition":"to sleep for a short time.","ko":"잠깐 자다; 잠깐 눈을 붙이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1575","en":"in dribs and drabs","definition":"in small amounts, not all at once.","ko":"조금씩, 한꺼번에가 아니라.","cefr":"B2","type":"idiom"},{"id":"idiom_1576","en":"be two of a kind","definition":"to be very similar to someone else.","ko":"다른 사람과 아주 비슷한 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1577","en":"when all's said and done","definition":"after everything is considered; in the end.","ko":"모든 것을 다 생각해 보면; 결국.","cefr":"B2","type":"idiom"},{"id":"idiom_1578","en":"as thick as two short planks","definition":"very stupid (rude).","ko":"아주 멍청한 (무례한) 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_1579","en":"a crowd-puller","definition":"something that attracts a lot of people.","ko":"사람을 많이 끌어모으는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1580","en":"play sb at their own game","definition":"to beat someone by using the same tricks they use on others.","ko":"다른 사람이 쓰는 똑같은 속임수로 그 사람을 이기는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1581","en":"go down a storm","definition":"to be very successful and get a lot of praise.","ko":"아주 크게 성공해서 칭찬을 많이 받는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1582","en":"dead in the water","definition":"stopped and unable to continue or succeed.","ko":"멈춰서 더 이상 계속하거나 성공할 수 없는 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_1583","en":"battle of wills","definition":"a situation where two people both refuse to change their minds.","ko":"두 사람이 둘 다 마음을 바꾸지 않아서 버티는 상황.","cefr":"B2","type":"idiom"},{"id":"idiom_1584","en":"the name of the game","definition":"the most important thing to do to succeed.","ko":"성공하려면 가장 중요한 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1585","en":"highly strung","definition":"very nervous and easily upset.","ko":"아주 예민하고 긴장해서 쉽게 화가 나는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1586","en":"be dealt a lousy hand","definition":"to be given a bad situation in life that is hard to change.","ko":"바꾸기 힘든 나쁜 상황을 인생에서 받게 되는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1587","en":"put one's foot down","definition":"to say no firmly and refuse to allow something.","ko":"단호하게 안 된다고 말하고 허락하지 않는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1588","en":"down the line","definition":"in the future or later.","ko":"미래에, 나중에.","cefr":"B2","type":"idiom"},{"id":"idiom_1589","en":"beg the question","definition":"to raise a question that needs to be answered.","ko":"답해야 할 질문을 새로 생기게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1590","en":"drop into one's lap","definition":"Something good happens to you without you trying for it.","ko":"노력하지 않았는데도 좋은 일이 갑자기 생기는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1591","en":"dead wood","definition":"People or things that are useless and should be removed.","ko":"쓸모없어서 없애야 하는 사람이나 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1592","en":"no hard feelings","definition":"Used to say you are not angry and you forgive someone.","ko":"화나지 않았고 용서한다는 뜻으로 하는 말.","cefr":"B2","type":"idiom"},{"id":"idiom_1593","en":"reinvent the wheel","definition":"To make something again in a new way when it already exists.","ko":"이미 있는 것을 두고 새로 다시 만들려고 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1594","en":"have sth burning a hole in one's pocket","definition":"To really want to spend money quickly.","ko":"돈을 빨리 쓰고 싶어서 참기 힘들다.","cefr":"B2","type":"idiom"},{"id":"idiom_1595","en":"let bygones be bygones","definition":"To forget old arguments and be friendly again.","ko":"예전 다툼은 잊고 다시 좋게 지내다.","cefr":"B2","type":"idiom"},{"id":"idiom_1596","en":"do a u-turn","definition":"To change your decision or opinion to the opposite.","ko":"결정이나 의견을 반대로 바꾸다.","cefr":"B2","type":"idiom"},{"id":"idiom_1597","en":"keep sb on the edge of their seat","definition":"To make someone feel very excited and want to know what happens next.","ko":"사람을 아주 긴장되고 신나게 해서 다음이 궁금하게 만들다.","cefr":"B2","type":"idiom"},{"id":"idiom_1598","en":"be like a dog with two tails","definition":"To be extremely happy and excited.","ko":"너무 행복하고 신이 난 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_1599","en":"end of (story)","definition":"Used to say something is finished and will not change.","ko":"이제 끝이고 바뀌지 않는다는 말.","cefr":"B2","type":"idiom"},{"id":"idiom_1600","en":"pick holes in sth","definition":"to find small faults in something and criticize it a lot","ko":"무언가의 작은 흠을 찾아서 많이 비판하다","cefr":"B2","type":"idiom"},{"id":"idiom_1601","en":"joined-up thinking","definition":"thinking that connects different parts of a problem so everything works together","ko":"문제의 여러 부분을 연결해서 전체가 함께 잘 돌아가게 하는 생각","cefr":"B2","type":"idiom"},{"id":"idiom_1602","en":"trim one's sails","definition":"to change your plans or behavior to fit a new situation","ko":"새 상황에 맞게 계획이나 행동을 바꾸다","cefr":"B2","type":"idiom"},{"id":"idiom_1603","en":"mind one's step","definition":"be careful where you walk or what you do","ko":"걸을 때나 행동할 때 조심하다","cefr":"B2","type":"idiom"},{"id":"idiom_1604","en":"have blood on one's hands","definition":"to be responsible for killing or hurting people","ko":"사람을 죽이거나 다치게 한 일에 책임이 있다","cefr":"B2","type":"idiom"},{"id":"idiom_1605","en":"give me a break","definition":"stop bothering me or stop being unfair; give me a rest","ko":"그만 좀 해라/좀 봐줘라; 나 좀 쉬게 해줘","cefr":"B2","type":"idiom"},{"id":"idiom_1606","en":"tread on sb's toes","definition":"to upset someone by doing or saying something that offends them","ko":"말이나 행동으로 상대를 불쾌하게 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1607","en":"bone dry","definition":"completely dry, with no water at all","ko":"완전히 말라서 물기가 전혀 없다","cefr":"B2","type":"idiom"},{"id":"idiom_1608","en":"be back to square one","definition":"to be back at the start again after losing progress","ko":"진전이 없어져서 다시 처음으로 돌아가다","cefr":"B2","type":"idiom"},{"id":"idiom_1609","en":"full of the joys of spring","definition":"very happy, lively, and full of energy","ko":"아주 신나고 활기차고 에너지가 넘치다","cefr":"B2","type":"idiom"},{"id":"idiom_1610","en":"win one's spurs","definition":"to earn respect or a good position by doing something brave or successful","ko":"용감하거나 성공적인 일로 존경이나 좋은 자리를 얻다","cefr":"B2","type":"idiom"},{"id":"idiom_1611","en":"penny-pinching","definition":"trying very hard not to spend money","ko":"돈을 쓰지 않으려고 아주 아끼다","cefr":"B2","type":"idiom"},{"id":"idiom_1612","en":"hot off the press","definition":"very new and just released","ko":"아주 새로 나온, 막 공개된","cefr":"B2","type":"idiom"},{"id":"idiom_1613","en":"non sequitur","definition":"a comment that does not connect to what was just said","ko":"방금 한 말과 전혀 이어지지 않는 말","cefr":"B2","type":"idiom"},{"id":"idiom_1614","en":"same difference","definition":"it does not matter because the result is the same","ko":"결과가 같아서 상관없다","cefr":"B2","type":"idiom"},{"id":"idiom_1615","en":"tell me about it","definition":"I feel the same way; I understand exactly","ko":"나도 그래; 완전 이해해","cefr":"B2","type":"idiom"},{"id":"idiom_1616","en":"be a chapter of accidents","definition":"a series of bad luck and mistakes","ko":"불운과 실수가 계속 이어지는 일","cefr":"B2","type":"idiom"},{"id":"idiom_1617","en":"right off the bat","definition":"immediately, at the start","ko":"바로, 시작하자마자","cefr":"B2","type":"idiom"},{"id":"idiom_1618","en":"half-measures","definition":"actions that are too small or weak to solve a problem","ko":"문제를 해결하기엔 너무 약한 조치","cefr":"B2","type":"idiom"},{"id":"idiom_1619","en":"sit on one's hands","definition":"to do nothing and not help when you should","ko":"해야 할 때 아무것도 하지 않고 가만히 있다","cefr":"B2","type":"idiom"},{"id":"idiom_1620","en":"no strings attached","definition":"Something is offered with no special conditions or hidden costs.","ko":"특별한 조건이나 숨은 비용 없이 무언가가 제공되는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1621","en":"be cool with","definition":"To be okay with something and accept it.","ko":"무언가에 괜찮다고 생각하고 받아들이는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1622","en":"go the whole hog","definition":"To do something as much as possible and not stop halfway.","ko":"가능한 한 최대한으로 하고, 중간에 멈추지 않는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1623","en":"up to the minute","definition":"Having the newest information right now.","ko":"바로 지금의 가장 최신 정보를 가지고 있는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1624","en":"a trojan horse","definition":"A person or thing that seems helpful but is secretly harmful.","ko":"도움이 되는 것처럼 보이지만, 몰래 해를 끼치는 사람이나 물건이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1625","en":"behind one's back","definition":"Without someone knowing, usually in a dishonest way.","ko":"상대가 모르게, 보통은 정직하지 않게 하는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1626","en":"make sb's life a misery","definition":"To make someone's life very unhappy for a long time.","ko":"오랫동안 누군가의 삶을 아주 불행하게 만드는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1627","en":"there's a lot to be said for","definition":"There are many good reasons to choose or do something.","ko":"그것을 선택하거나 하는 데 좋은 이유가 많이 있다는 뜻이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1628","en":"bare-faced lies","definition":"Very obvious lies that are easy to see.","ko":"누가 봐도 뻔해서 쉽게 들키는 거짓말이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1629","en":"of like mind","definition":"Having the same opinion as someone else.","ko":"다른 사람과 같은 의견을 가지고 있는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1630","en":"the elephant in the room","definition":"An obvious problem that everyone knows about but no one talks about.","ko":"모두가 알고 있지만 아무도 말하지 않는 뻔한 문제이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1631","en":"saddled with debt","definition":"Having a lot of debt that is hard to pay back.","ko":"갚기 힘든 빚이 많이 있는 상태이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1632","en":"throw sb a curveball","definition":"To surprise someone with a difficult problem or change.","ko":"어려운 문제나 변화를 갑자기 던져서 누군가를 놀라게 하는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1633","en":"harden one's heart","definition":"To stop feeling sympathy and become cold or unkind.","ko":"동정심을 멈추고 차갑거나 불친절해지는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1634","en":"go down a treat","definition":"To be liked a lot and be very successful.","ko":"사람들이 아주 좋아해서 크게 성공하는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1635","en":"as if (he) owned the place","definition":"Acting too confident, like you are in charge in a place that is not yours.","ko":"자기 장소도 아닌데, 자기가 주인인 것처럼 너무 자신 있게 행동하는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1636","en":"can't see the wood for the trees","definition":"To focus on small details and miss the main point.","ko":"작은 세부사항에만 집중해서 큰 핵심을 놓치는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1637","en":"live out of a suitcase","definition":"To travel a lot and keep your things in a suitcase instead of a home.","ko":"집에 정착하지 못하고 여행을 많이 해서, 짐을 늘 여행가방에 넣어 두고 사는 것이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1638","en":"a catch-22 situation","definition":"A situation where you cannot do something because the rules make it impossible.","ko":"규칙 때문에 불가능해서, 뭘 하고 싶어도 할 수 없는 상황이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1639","en":"all in all","definition":"Overall, when you consider everything.","ko":"전체적으로, 모든 것을 고려하면이라는 뜻이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1640","en":"one's heart is in one's boots","definition":"You feel very scared or worried.","ko":"아주 무섭거나 걱정돼요.","cefr":"B2","type":"idiom"},{"id":"idiom_1641","en":"over my dead body","definition":"I will never allow that to happen.","ko":"나는 절대 그 일이 일어나게 두지 않을 거야.","cefr":"B2","type":"idiom"},{"id":"idiom_1642","en":"the long arm of the law","definition":"The police will find you and catch you.","ko":"경찰이 너를 찾아서 잡을 거야.","cefr":"B2","type":"idiom"},{"id":"idiom_1643","en":"the chattering classes","definition":"People who talk a lot about politics and society, often in the media.","ko":"정치와 사회에 대해 많이 말하는 사람들(주로 미디어에서).","cefr":"B2","type":"idiom"},{"id":"idiom_1644","en":"don't get me wrong","definition":"Please understand me correctly; I do not mean something bad.","ko":"내 말을 오해하지 말아 줘; 나쁜 뜻이 아니야.","cefr":"B2","type":"idiom"},{"id":"idiom_1645","en":"in the driving seat","definition":"You are in control and making the decisions.","ko":"네가 상황을 통제하고 결정을 내려.","cefr":"B2","type":"idiom"},{"id":"idiom_1646","en":"be blown away by sth","definition":"To be very impressed or amazed by something.","ko":"무언가에 아주 감탄하거나 놀라다.","cefr":"B2","type":"idiom"},{"id":"idiom_1647","en":"public enemy number one","definition":"The person or thing that everyone hates and blames the most.","ko":"모두가 가장 미워하고 가장 많이 탓하는 사람이나 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1648","en":"be all in the mind","definition":"It is only in your thoughts, not a real problem.","ko":"그건 생각 속 문제일 뿐이고, 실제 문제는 아니야.","cefr":"B2","type":"idiom"},{"id":"idiom_1649","en":"as quiet as a mouse","definition":"Very quiet and not making any noise.","ko":"아주 조용해서 소리가 거의 안 나요.","cefr":"B2","type":"idiom"},{"id":"idiom_1650","en":"corner the market","definition":"to control almost all sales of a product so others cannot compete","ko":"어떤 상품의 판매를 거의 다 장악해서 다른 사람이 경쟁 못 하게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1651","en":"strike at the heart of","definition":"to attack the most important part of something","ko":"무언가의 가장 중요한 부분을 공격하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1652","en":"castles in the air","definition":"dreams or plans that are not realistic","ko":"현실적이지 않은 꿈이나 계획.","cefr":"B2","type":"idiom"},{"id":"idiom_1653","en":"play for time","definition":"to delay something so you can gain more time","ko":"시간을 벌기 위해 일부러 늦추다.","cefr":"B2","type":"idiom"},{"id":"idiom_1654","en":"given half a chance","definition":"if someone had a small opportunity, they would do it","ko":"조금만 기회가 있어도 그렇게 할 거라는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_1655","en":"double whammy","definition":"two bad things happen at the same time","ko":"나쁜 일이 두 가지가 동시에 일어나는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1656","en":"rome wasn't built in a day","definition":"big things take time and cannot be done quickly","ko":"큰 일은 시간이 걸리고 빨리 할 수 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_1657","en":"prey on one's mind","definition":"to keep worrying you and stay in your thoughts","ko":"계속 걱정돼서 머릿속에서 떠나지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1658","en":"run the gauntlet","definition":"to face a lot of criticism or attacks from many people","ko":"많은 사람에게서 비판이나 공격을 많이 받다.","cefr":"B2","type":"idiom"},{"id":"idiom_1659","en":"worship at the altar of","definition":"to admire or value one thing above everything else","ko":"한 가지를 다른 모든 것보다 더 중요하게 여기다.","cefr":"B2","type":"idiom"},{"id":"idiom_1660","en":"into the bargain","definition":"in addition to what was already included or expected.","ko":"이미 포함되었거나 예상했던 것에 더해서.","cefr":"B2","type":"idiom"},{"id":"idiom_1661","en":"nearest and dearest","definition":"the people in your family and your closest friends.","ko":"가족과 가장 가까운 친구들.","cefr":"B2","type":"idiom"},{"id":"idiom_1662","en":"join forces with","definition":"work together with someone to do something.","ko":"누군가와 함께 힘을 합쳐서 일하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1663","en":"learn sth off by heart","definition":"learn something so well that you can say it from memory.","ko":"외워서 말할 수 있을 만큼 아주 잘 배우다.","cefr":"B2","type":"idiom"},{"id":"idiom_1664","en":"sweep sth under the carpet","definition":"hide a problem and pretend it is not there.","ko":"문제를 숨기고 없는 척하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1665","en":"go their own ways","definition":"separate and live or do things in different ways.","ko":"헤어져서 각자 다른 방식으로 살거나 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1666","en":"watch with half an eye","definition":"watch something without paying full attention.","ko":"집중하지 않고 대충 보다.","cefr":"B2","type":"idiom"},{"id":"idiom_1667","en":"fall off the radar","definition":"stop being seen or heard from for a while.","ko":"한동안 소식이 끊기다.","cefr":"B2","type":"idiom"},{"id":"idiom_1668","en":"time will tell","definition":"we will know the result in the future.","ko":"결과는 나중에 알게 될 거다.","cefr":"B2","type":"idiom"},{"id":"idiom_1669","en":"epic proportions","definition":"very big or extreme in size or amount.","ko":"규모나 정도가 아주 크거나 극단적인.","cefr":"B2","type":"idiom"},{"id":"idiom_1670","en":"golden handshake","definition":"a large payment given to someone when they leave a job, usually when they retire.","ko":"직장을 떠날 때(보통 은퇴할 때) 받는 큰 퇴직금.","cefr":"B2","type":"idiom"},{"id":"idiom_1671","en":"drive like a maniac","definition":"to drive very fast and dangerously.","ko":"아주 빠르고 위험하게 운전하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1672","en":"one is teaching one's grandmother to suck eggs","definition":"to try to teach someone something they already know very well.","ko":"이미 아주 잘 아는 사람에게 가르치려 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1673","en":"learn by rote","definition":"to learn something by repeating it many times, without really understanding it.","ko":"이해하지 않고 여러 번 반복해서 외우다.","cefr":"B2","type":"idiom"},{"id":"idiom_1674","en":"if it ain't broke, don't fix it","definition":"if something works well, do not change it.","ko":"잘 돌아가는 것은 바꾸지 마라.","cefr":"B2","type":"idiom"},{"id":"idiom_1675","en":"shoot oneself in the foot","definition":"to do something that harms your own plans or chances.","ko":"자기 계획이나 기회를 스스로 망치다.","cefr":"B2","type":"idiom"},{"id":"idiom_1676","en":"a loose cannon","definition":"a person who is unpredictable and may cause trouble.","ko":"예측할 수 없어서 문제를 일으킬 수 있는 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_1677","en":"a cushy number","definition":"an easy job or situation with good pay or benefits.","ko":"일이 쉽고 월급이나 혜택이 좋은 자리.","cefr":"B2","type":"idiom"},{"id":"idiom_1678","en":"have a heart","definition":"to show kindness and pity, especially when someone is suffering.","ko":"불쌍히 여기고 친절하게 대하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1679","en":"a mine of information","definition":"a person who knows a lot and can give many useful facts.","ko":"아는 것이 많아서 유용한 정보를 많이 알려 줄 수 있는 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_1680","en":"burst a blood vessel","definition":"To become extremely angry.","ko":"아주 화가 나다.","cefr":"B2","type":"idiom"},{"id":"idiom_1681","en":"there's more to sth than meets the eye","definition":"A situation is not as simple as it looks at first.","ko":"상황이 처음 보기만큼 단순하지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1682","en":"that's sb all over","definition":"That behavior is very typical of that person.","ko":"그 행동은 그 사람답다.","cefr":"B2","type":"idiom"},{"id":"idiom_1683","en":"be getting nowhere","definition":"To make no progress.","ko":"전혀 진전이 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_1684","en":"sick to death of sth","definition":"To be very tired of something and not want it anymore.","ko":"무언가가 너무 지겨워서 더는 하고 싶지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1685","en":"hit the spot","definition":"To be exactly what you want or need at that moment.","ko":"그 순간에 딱 원하던 것이 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_1686","en":"come out fighting","definition":"To react strongly and fight back right away.","ko":"바로 강하게 반응하며 맞서다.","cefr":"B2","type":"idiom"},{"id":"idiom_1687","en":"an albatross around one's neck","definition":"A heavy problem or responsibility that is hard to get rid of.","ko":"없애기 힘든 큰 문제나 책임.","cefr":"B2","type":"idiom"},{"id":"idiom_1688","en":"make ends meet","definition":"To have just enough money to pay for basic needs.","ko":"기본 생활비를 겨우 마련하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1689","en":"have a window","definition":"To have a short break in your work schedule.","ko":"일정 중에 잠깐 시간이 나다.","cefr":"B2","type":"idiom"},{"id":"idiom_1690","en":"dead and buried","definition":"Something is finished and will not happen again.","ko":"완전히 끝나서 다시는 일어나지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1691","en":"it does exactly what it says on the tin","definition":"It works exactly as the label or description says.","ko":"설명대로 정확히 작동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1692","en":"be a minefield","definition":"A situation is very risky and easy to cause trouble in.","ko":"아주 위험해서 문제를 일으키기 쉬운 상황이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1693","en":"from the word go","definition":"From the very beginning.","ko":"처음부터.","cefr":"B2","type":"idiom"},{"id":"idiom_1694","en":"be the breadwinner","definition":"To be the person who earns most or all of the money for a family.","ko":"가족의 주된 생계 책임자이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1695","en":"lose face","definition":"To feel embarrassed and lose respect from other people.","ko":"창피를 당해 체면이 깎이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1696","en":"one's heart goes out to sb","definition":"To feel very sorry for someone.","ko":"누군가가 너무 안쓰럽다.","cefr":"B2","type":"idiom"},{"id":"idiom_1697","en":"as poor as a church mouse","definition":"To have no money at all.","ko":"돈이 전혀 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_1698","en":"within an inch of one's life","definition":"Very badly or almost to death.","ko":"아주 심하게, 거의 죽을 정도로.","cefr":"B2","type":"idiom"},{"id":"idiom_1699","en":"work like a dog","definition":"to work very hard for a long time","ko":"오랫동안 아주 열심히 일하다","cefr":"B2","type":"idiom"},{"id":"idiom_1700","en":"ahead of its time","definition":"more modern or advanced than people expected at that time","ko":"그 당시 사람들의 예상보다 더 현대적이거나 앞선","cefr":"B2","type":"idiom"},{"id":"idiom_1701","en":"cut and run","definition":"to leave suddenly to avoid trouble or danger","ko":"문제나 위험을 피하려고 갑자기 떠나다","cefr":"B2","type":"idiom"},{"id":"idiom_1702","en":"at stake","definition":"at risk and could be lost or harmed","ko":"위험에 처해 있어서 잃거나 다칠 수 있는","cefr":"B2","type":"idiom"},{"id":"idiom_1703","en":"stick one's neck out","definition":"to take a risk by saying or doing something brave","ko":"용감하게 말하거나 행동해서 위험을 감수하다","cefr":"B2","type":"idiom"},{"id":"idiom_1704","en":"the penny drops","definition":"you suddenly understand something after not understanding it","ko":"처음엔 몰랐던 것을 갑자기 이해하다","cefr":"B2","type":"idiom"},{"id":"idiom_1705","en":"get a new lease of life","definition":"to feel better and more energetic again","ko":"다시 기분이 좋아지고 활력이 생기다","cefr":"B2","type":"idiom"},{"id":"idiom_1706","en":"all right on the night","definition":"things will be okay when it really matters, even if there are problems before","ko":"전에 문제가 있어도, 정말 중요한 순간에는 괜찮을 거라는 뜻","cefr":"B2","type":"idiom"},{"id":"idiom_1707","en":"eat like a pig","definition":"to eat in a messy, rude way and too much","ko":"지저분하고 무례하게, 그리고 너무 많이 먹다","cefr":"B2","type":"idiom"},{"id":"idiom_1708","en":"take a nosedive","definition":"to fall or drop quickly and strongly","ko":"빠르고 크게 떨어지다","cefr":"B2","type":"idiom"},{"id":"idiom_1709","en":"as keen as mustard","definition":"very eager and excited to do something.","ko":"무언가를 하고 싶어서 아주 신나고 의욕적인","cefr":"B2","type":"idiom"},{"id":"idiom_1710","en":"leave sb high and dry","definition":"to leave someone without help or support.","ko":"누군가를 도움이나 지원 없이 곤란하게 두다","cefr":"B2","type":"idiom"},{"id":"idiom_1711","en":"make a mountain out of a molehill","definition":"to make a small problem seem like a very big one.","ko":"작은 문제를 아주 큰 문제처럼 만들다","cefr":"B2","type":"idiom"},{"id":"idiom_1712","en":"do time","definition":"to spend time in prison.","ko":"감옥에서 시간을 보내다","cefr":"B2","type":"idiom"},{"id":"idiom_1713","en":"good riddance (to bad rubbish)","definition":"said when you are happy that a bad person or thing is gone.","ko":"나쁜 사람이나 나쁜 일이 사라져서 속이 시원할 때 하는 말","cefr":"B2","type":"idiom"},{"id":"idiom_1714","en":"that's all we need","definition":"said when something bad happens and it makes a situation worse.","ko":"나쁜 일이 생겨서 상황이 더 나빠졌을 때 하는 말","cefr":"B2","type":"idiom"},{"id":"idiom_1715","en":"eat sb for breakfast","definition":"to defeat someone very easily.","ko":"누군가를 아주 쉽게 이기다","cefr":"B2","type":"idiom"},{"id":"idiom_1716","en":"it's all systems go","definition":"everything is ready to start and people are moving quickly.","ko":"모든 준비가 끝나서 바로 시작할 수 있는 상태","cefr":"B2","type":"idiom"},{"id":"idiom_1717","en":"a mere pittance","definition":"a very small amount of money.","ko":"아주 적은 돈","cefr":"B2","type":"idiom"},{"id":"idiom_1718","en":"play god","definition":"to act like you have the power to decide who lives or dies.","ko":"사람의 생사를 결정할 수 있는 것처럼 행동하다","cefr":"B2","type":"idiom"},{"id":"idiom_1719","en":"have the upper hand","definition":"to be in a stronger position than someone else","ko":"다른 사람보다 더 유리한 위치에 있다","cefr":"B2","type":"idiom"},{"id":"idiom_1720","en":"get one's teeth into sth","definition":"to start working on something with a lot of interest and effort","ko":"어떤 일을 큰 흥미와 노력으로 본격적으로 시작하다","cefr":"B2","type":"idiom"},{"id":"idiom_1721","en":"one may well ask","definition":"used to say that a question is reasonable to ask","ko":"그 질문은 충분히 할 만하다고 말할 때 쓰는 표현","cefr":"B2","type":"idiom"},{"id":"idiom_1722","en":"not know the half of it","definition":"used to say someone does not understand how bad or serious something is","ko":"상황이 얼마나 나쁘거나 심각한지 잘 모른다는 뜻","cefr":"B2","type":"idiom"},{"id":"idiom_1723","en":"the life and soul of the party","definition":"a person who is very fun and makes everyone enjoy a party","ko":"파티에서 아주 재미있고 분위기를 띄우는 사람","cefr":"B2","type":"idiom"},{"id":"idiom_1724","en":"ride high","definition":"to be very successful and confident","ko":"아주 성공해서 자신감이 넘치다","cefr":"B2","type":"idiom"},{"id":"idiom_1725","en":"drive a hard bargain","definition":"to negotiate strongly to get the best price or deal","ko":"최고의 가격이나 조건을 얻으려고 강하게 흥정하다","cefr":"B2","type":"idiom"},{"id":"idiom_1726","en":"be a bundle of nerves","definition":"to feel very nervous and worried","ko":"아주 긴장하고 걱정하다","cefr":"B2","type":"idiom"},{"id":"idiom_1727","en":"big fish in a small pond","definition":"an important person in a small place, but not important in a bigger place","ko":"작은 곳에서는 중요한 사람이지만 큰 곳에서는 그렇지 않은 사람","cefr":"B2","type":"idiom"},{"id":"idiom_1728","en":"note of discord","definition":"a sign of disagreement that spoils a friendly situation","ko":"친근한 분위기를 망치는 불화나 의견 충돌의 신호","cefr":"B2","type":"idiom"},{"id":"idiom_1729","en":"as dead as a dodo","definition":"completely gone and not used anymore.","ko":"완전히 사라져서 더 이상 쓰이지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_1730","en":"cry buckets","definition":"to cry a lot.","ko":"아주 많이 울다","cefr":"B2","type":"idiom"},{"id":"idiom_1731","en":"pay over the odds","definition":"to pay much more than something is worth.","ko":"값어치보다 훨씬 더 비싸게 돈을 내다","cefr":"B2","type":"idiom"},{"id":"idiom_1732","en":"take the words right out of my mouth","definition":"you say exactly what I was going to say.","ko":"내가 하려던 말을 네가 똑같이 말했어","cefr":"B2","type":"idiom"},{"id":"idiom_1733","en":"straight from the horse's mouth","definition":"from the original person who knows the truth.","ko":"진실을 아는 당사자에게서 직접 들은 것","cefr":"B2","type":"idiom"},{"id":"idiom_1734","en":"hit the jackpot","definition":"to have great luck or success.","ko":"큰 행운이나 큰 성공을 얻다","cefr":"B2","type":"idiom"},{"id":"idiom_1735","en":"fiddle while rome burns","definition":"to do something small and useless while a big problem is happening.","ko":"큰 문제가 생겼는데도 작고 쓸모없는 일만 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1736","en":"if and it's a big if","definition":"only if something happens, and it is not likely.","ko":"그 일이 일어나야만 가능한데, 그럴 가능성이 낮다는 뜻","cefr":"B2","type":"idiom"},{"id":"idiom_1737","en":"it's not rocket science","definition":"it is not very difficult to understand or do.","ko":"그건 이해하거나 하기가 그렇게 어렵지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_1738","en":"do oneself the world of good","definition":"to help you feel much better.","ko":"기분이나 상태가 훨씬 좋아지게 해 주다","cefr":"B2","type":"idiom"},{"id":"idiom_1739","en":"hustle and bustle","definition":"busy activity and noise in a place.","ko":"어떤 곳에서 바쁘게 움직이고 시끄러운 분위기.","cefr":"B2","type":"idiom"},{"id":"idiom_1740","en":"take the wind out of sb's sails","definition":"to make someone feel less confident or excited.","ko":"누군가의 자신감이나 신나는 마음을 꺾다.","cefr":"B2","type":"idiom"},{"id":"idiom_1741","en":"blow one's mind","definition":"to surprise you a lot and make you feel amazed.","ko":"너무 놀라서 감탄하게 만들다.","cefr":"B2","type":"idiom"},{"id":"idiom_1742","en":"water under the bridge","definition":"something from the past that is no longer important.","ko":"이제는 중요하지 않은 과거의 일.","cefr":"B2","type":"idiom"},{"id":"idiom_1743","en":"live on a shoestring","definition":"to live with very little money.","ko":"돈이 아주 적게 있는 상태로 살다.","cefr":"B2","type":"idiom"},{"id":"idiom_1744","en":"as clear as crystal","definition":"very easy to understand.","ko":"아주 이해하기 쉽다.","cefr":"B2","type":"idiom"},{"id":"idiom_1745","en":"sleeping partner","definition":"a business partner who invests money but does not take part in daily work.","ko":"돈은 투자하지만 매일 일에는 참여하지 않는 사업 파트너.","cefr":"B2","type":"idiom"},{"id":"idiom_1746","en":"pull the strings","definition":"to secretly control what happens, often from behind the scenes.","ko":"뒤에서 몰래 일을 조종하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1747","en":"the conventional wisdom","definition":"the common belief that most people accept as true.","ko":"대부분의 사람들이 사실이라고 믿는 일반적인 생각.","cefr":"B2","type":"idiom"},{"id":"idiom_1748","en":"bone to pick","definition":"a complaint or issue you want to talk about with someone.","ko":"누군가에게 말하고 싶은 불만이나 문제.","cefr":"B2","type":"idiom"},{"id":"idiom_1749","en":"of one's own making","definition":"Something bad that happens because of your own actions.","ko":"자기 행동 때문에 생긴 (나쁜) 일.","cefr":"B2","type":"idiom"},{"id":"idiom_1750","en":"mind one's own business","definition":"Do not ask about other people's private things.","ko":"남의 사적인 일에 끼어들지 말다.","cefr":"B2","type":"idiom"},{"id":"idiom_1751","en":"an albatross around sb's neck","definition":"A big problem that is hard to get rid of.","ko":"없애기 힘든 큰 문제.","cefr":"B2","type":"idiom"},{"id":"idiom_1752","en":"go the extra mile","definition":"Do more than is expected to help.","ko":"기대하는 것보다 더 많이 도와주다.","cefr":"B2","type":"idiom"},{"id":"idiom_1753","en":"cry one's heart out","definition":"Cry a lot because you are very sad.","ko":"너무 슬퍼서 많이 울다.","cefr":"B2","type":"idiom"},{"id":"idiom_1754","en":"take to the next level","definition":"Make something much better than before.","ko":"무언가를 이전보다 훨씬 더 좋게 만들다.","cefr":"B2","type":"idiom"},{"id":"idiom_1755","en":"not the whole picture","definition":"Not all the facts; only part of the story.","ko":"전체 사실이 아니라 일부만 말한 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1756","en":"the halcyon days","definition":"A happy time in the past that people remember fondly.","ko":"사람들이 그리워하는 행복했던 옛날.","cefr":"B2","type":"idiom"},{"id":"idiom_1757","en":"go down like a lead balloon","definition":"Be received very badly and make people unhappy or unimpressed.","ko":"반응이 아주 나빠서 사람들을 불쾌하게 하거나 감동시키지 못하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1758","en":"life in the slow lane","definition":"A calm, simple life without rushing.","ko":"서두르지 않는 차분하고 단순한 삶.","cefr":"B2","type":"idiom"},{"id":"idiom_1759","en":"live in each other's pockets","definition":"to spend almost all your time together and have little space from each other.","ko":"거의 모든 시간을 함께 보내서 서로에게 개인 시간이 거의 없는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1760","en":"all in good time","definition":"it will happen later, at the right time.","ko":"나중에, 알맞은 때에 일어날 거라는 뜻.","cefr":"B2","type":"idiom"},{"id":"idiom_1761","en":"no prizes for guessing sth","definition":"it is very easy to guess something.","ko":"무언가를 맞히는 게 아주 쉬울 때 쓰는 말.","cefr":"B2","type":"idiom"},{"id":"idiom_1762","en":"be like two peas in a pod","definition":"to be very similar to each other.","ko":"서로 아주 비슷한 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1763","en":"of the same mind","definition":"to agree with someone about something.","ko":"어떤 일에 대해 누군가와 의견이 같은 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1764","en":"do sb the world of good","definition":"to help someone a lot and make them feel better.","ko":"누군가에게 큰 도움이 되고 기분을 좋게 해 주는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1765","en":"not lose sleep over sth","definition":"to not worry about something.","ko":"어떤 일을 걱정하지 않는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1766","en":"be (skating) on thin ice","definition":"to be in a risky situation and close to getting in trouble.","ko":"위험한 상황에 있고 곧 문제를 일으킬 수 있는 상태.","cefr":"B2","type":"idiom"},{"id":"idiom_1767","en":"take years off sb","definition":"to make someone look or feel younger.","ko":"누군가를 더 젊어 보이거나 더 젊게 느끼게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1768","en":"have two left feet","definition":"to be very bad at dancing or moving in a coordinated way.","ko":"춤을 아주 못 추거나 몸을 잘 못 움직이는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1769","en":"domino effect","definition":"a chain reaction where one event causes many others.","ko":"한 일이 다른 일들을 계속 일으키는 연쇄 반응.","cefr":"B2","type":"idiom"},{"id":"idiom_1770","en":"have one's best interests at heart","definition":"to truly want what is best for someone.","ko":"진심으로 그 사람에게 가장 좋은 것을 바라다.","cefr":"B2","type":"idiom"},{"id":"idiom_1771","en":"rub shoulders with sb","definition":"to meet and spend time with people, often important or famous ones.","ko":"사람들(특히 중요한/유명한 사람들)을 만나고 함께 시간을 보내다.","cefr":"B2","type":"idiom"},{"id":"idiom_1772","en":"all-singing, all-dancing","definition":"having many impressive features and doing many things.","ko":"기능이 아주 많고 화려한 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1773","en":"be two a penny","definition":"to be very common and easy to find.","ko":"아주 흔해서 쉽게 찾을 수 있는 것.","cefr":"B2","type":"idiom"},{"id":"idiom_1774","en":"go by the board","definition":"to be lost, ruined, or no longer used.","ko":"망가지거나 없어지거나 더 이상 쓰이지 않게 되다.","cefr":"B2","type":"idiom"},{"id":"idiom_1775","en":"hit the right note","definition":"to say or do something that feels correct and pleasing to people.","ko":"사람들이 듣기에 딱 맞고 기분 좋게 말하거나 행동하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1776","en":"live to tell the tale","definition":"to survive a dangerous experience and be able to talk about it later.","ko":"위험한 일을 겪고도 살아남아 나중에 이야기할 수 있다.","cefr":"B2","type":"idiom"},{"id":"idiom_1777","en":"come into one's own","definition":"to become successful or confident, especially after time or change.","ko":"시간이 지나거나 환경이 바뀐 뒤에 성공하거나 자신감이 생기다.","cefr":"B2","type":"idiom"},{"id":"idiom_1778","en":"see the joke","definition":"to understand why something is funny","ko":"왜 웃긴지 이해하다","cefr":"B2","type":"idiom"},{"id":"idiom_1779","en":"live life to the full","definition":"to enjoy life as much as possible","ko":"인생을 최대한 즐기다","cefr":"B2","type":"idiom"},{"id":"idiom_1780","en":"upset the apple cart","definition":"to cause trouble by changing a plan or situation","ko":"계획이나 상황을 바꿔서 문제를 일으키다","cefr":"B2","type":"idiom"},{"id":"idiom_1781","en":"gas guzzler","definition":"a vehicle that uses a lot of fuel","ko":"연료를 많이 먹는 차","cefr":"B2","type":"idiom"},{"id":"idiom_1782","en":"a whizz kid","definition":"a very smart young person, especially with technology","ko":"아주 똑똑한 젊은 사람(특히 기술에 강한)","cefr":"B2","type":"idiom"},{"id":"idiom_1783","en":"eat like a horse","definition":"to eat a lot of food","ko":"음식을 아주 많이 먹다","cefr":"B2","type":"idiom"},{"id":"idiom_1784","en":"flog a dead horse","definition":"to keep trying to do something that will not work","ko":"안 될 일을 계속 하려고 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1785","en":"uneasy peace","definition":"a calm situation where people still do not fully trust each other","ko":"겉으로는 조용하지만 서로 완전히 믿지 못하는 평화","cefr":"B2","type":"idiom"},{"id":"idiom_1786","en":"not take no for an answer","definition":"to refuse to accept 'no' and keep trying until you get what you want","ko":"거절을 받아들이지 않고 원하는 것을 얻을 때까지 계속 하다","cefr":"B2","type":"idiom"},{"id":"idiom_1787","en":"sick and tired","definition":"very annoyed and unhappy because something has happened too many times","ko":"너무 자주 일어나서 정말 짜증 나고 지치다","cefr":"B2","type":"idiom"},{"id":"idiom_1788","en":"steal the show","definition":"to get all the attention and be the best part of a show or event","ko":"모든 관심을 받고 가장 돋보이다","cefr":"B2","type":"idiom"},{"id":"idiom_1789","en":"the bottom drops out of the market","definition":"prices suddenly fall a lot and people stop buying","ko":"가격이 갑자기 크게 떨어지고 사람들이 사지 않다","cefr":"B2","type":"idiom"},{"id":"idiom_1790","en":"fair enough","definition":"You say this to show you accept what someone says or decides.","ko":"상대의 말이나 결정을 받아들인다는 뜻으로 하는 말","cefr":"B2","type":"idiom"},{"id":"idiom_1791","en":"in broad daylight","definition":"In the daytime when everyone can see.","ko":"대낮에, 사람들이 다 볼 수 있을 때","cefr":"B2","type":"idiom"},{"id":"idiom_1792","en":"a living death","definition":"A life that feels very unhappy and hopeless.","ko":"아주 불행하고 희망이 없는 삶","cefr":"B2","type":"idiom"},{"id":"idiom_1793","en":"to cap it all","definition":"Used to add one last bad thing after other bad things.","ko":"안 좋은 일들이 이어진 뒤에 마지막으로 더 안 좋은 일을 덧붙일 때 쓰는 말","cefr":"B2","type":"idiom"},{"id":"idiom_1794","en":"see reason","definition":"To start thinking in a sensible way and accept the truth.","ko":"이성적으로 생각하기 시작하고 사실을 받아들이다","cefr":"B2","type":"idiom"},{"id":"idiom_1795","en":"tick all the boxes","definition":"To meet all the needs or requirements.","ko":"필요한 조건을 모두 만족하다","cefr":"B2","type":"idiom"},{"id":"idiom_1796","en":"all hands on deck","definition":"Everyone must help because there is a lot to do.","ko":"할 일이 많아서 모두가 도와야 한다.","cefr":"B2","type":"idiom"},{"id":"idiom_1797","en":"a black mark","definition":"A bad record that makes you look untrustworthy or wrong.","ko":"사람들이 너를 믿기 어렵게 만드는 나쁜 기록이다.","cefr":"B2","type":"idiom"},{"id":"idiom_1798","en":"not give sb the time of day","definition":"To ignore someone and treat them as unimportant.","ko":"누군가를 무시하고 중요하지 않게 대하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1799","en":"enter into the spirit of sth","definition":"To join in and enjoy an activity or celebration.","ko":"활동이나 축제에 함께 참여하고 즐기다.","cefr":"B2","type":"idiom"},{"id":"idiom_1800","en":"a ballpark figure","definition":"an approximate number, not exact.","ko":"정확하지 않은 대략적인 숫자.","cefr":"B2","type":"idiom"},{"id":"idiom_1801","en":"mum's the word","definition":"don't tell anyone; keep it secret.","ko":"아무에게도 말하지 말고 비밀로 해라.","cefr":"B2","type":"idiom"},{"id":"idiom_1802","en":"below the belt","definition":"unfair and cruel, especially in an argument.","ko":"특히 말다툼에서 불공평하고 잔인하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1803","en":"done to a turn","definition":"cooked perfectly, not too much and not too little.","ko":"너무 익지도 덜 익지도 않게 완벽하게 익다.","cefr":"B2","type":"idiom"},{"id":"idiom_1804","en":"rolling in the aisles","definition":"laughing very hard.","ko":"아주 크게 웃다.","cefr":"B2","type":"idiom"},{"id":"idiom_1805","en":"one's own flesh and blood","definition":"your close family members, like your children or parents.","ko":"자기와 아주 가까운 가족, 예를 들면 부모나 자녀.","cefr":"B2","type":"idiom"},{"id":"idiom_1806","en":"movers and shakers","definition":"important people who have power and influence.","ko":"권력과 영향력이 있는 중요한 사람들.","cefr":"B2","type":"idiom"},{"id":"idiom_1807","en":"hammer out an agreement","definition":"work hard to reach a deal after discussion.","ko":"논의한 뒤 열심히 노력해서 합의에 이르다.","cefr":"B2","type":"idiom"},{"id":"idiom_1808","en":"see the light","definition":"finally understand the truth or change your mind.","ko":"마침내 진실을 이해하거나 마음을 바꾸다.","cefr":"B2","type":"idiom"},{"id":"idiom_1809","en":"dog in the manger","definition":"someone who will not use something and will not let others use it either.","ko":"자기는 쓰지 않으면서 남도 못 쓰게 하는 사람.","cefr":"B2","type":"idiom"},{"id":"idiom_1810","en":"teething troubles","definition":"Small problems that happen when something is new.","ko":"새로운 것을 시작할 때 생기는 작은 문제들.","cefr":"B2","type":"idiom"},{"id":"idiom_1811","en":"live a charmed life","definition":"To be very lucky and avoid bad things.","ko":"아주 운이 좋아서 나쁜 일을 피하며 살다.","cefr":"B2","type":"idiom"},{"id":"idiom_1812","en":"kick oneself","definition":"To feel very sorry about something you did or did not do.","ko":"한 일(또는 안 한 일)을 아주 후회하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1813","en":"be heavy going","definition":"To be difficult and not enjoyable to do or understand.","ko":"하기나 이해하기가 어렵고 재미가 없다.","cefr":"B2","type":"idiom"},{"id":"idiom_1814","en":"as red as a beetroot","definition":"Very red in the face, usually from embarrassment.","ko":"보통 창피해서 얼굴이 아주 빨개지다.","cefr":"B2","type":"idiom"},{"id":"idiom_1815","en":"hit the mark","definition":"To be exactly right or correct.","ko":"정확히 맞다.","cefr":"B2","type":"idiom"},{"id":"idiom_1816","en":"a twinkle in one's father's eye","definition":"A time before someone was born.","ko":"누군가가 태어나기 전의 때.","cefr":"B2","type":"idiom"},{"id":"idiom_1817","en":"get one's goat","definition":"To annoy someone a lot.","ko":"누군가를 아주 짜증 나게 하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1818","en":"give and take","definition":"A fair exchange where each side accepts some compromise.","ko":"서로 조금씩 양보하는 공평한 주고받기.","cefr":"B2","type":"idiom"},{"id":"idiom_1819","en":"put one's hand on one's heart","definition":"To say something honestly and sincerely.","ko":"정직하고 진심으로 말하다.","cefr":"B2","type":"idiom"},{"id":"idiom_1820","en":"a fighting chance","definition":"a small but real chance to succeed.","ko":"작지만 진짜로 있는 성공 가능성.","cefr":"B2","type":"idiom"},{"id":"idiom_1821","en":"stand one's ground","definition":"to refuse to move or change your opinion, even when pressured.","ko":"압박을 받아도 물러서지 않고 의견을 바꾸지 않다.","cefr":"B2","type":"idiom"},{"id":"idiom_1822","en":"a heart of gold","definition":"a very kind and generous nature.","ko":"아주 친절하고 너그러운 성격.","cefr":"B2","type":"idiom"},{"id":"idiom_1823","en":"hold all the cards","definition":"to have all the power or advantage in a situation.","ko":"상황에서 모든 힘이나 유리함을 가지다.","cefr":"B2","type":"idiom"},{"id":"idiom_1824","en":"that makes two of us","definition":"I feel the same way as you.","ko":"나도 너와 똑같이 느껴.","cefr":"B2","type":"idiom"},{"id":"idiom_1825","en":"take sb to the cleaner's","definition":"to cheat someone and take their money unfairly.","ko":"누군가를 속여서 부당하게 돈을 빼앗다.","cefr":"B2","type":"idiom"},{"id":"idiom_1826","en":"leave no stone unturned","definition":"to search everywhere and try every possible way.","ko":"어디든 다 찾아보고 가능한 모든 방법을 다 해보다.","cefr":"B2","type":"idiom"},{"id":"idiom_1827","en":"win by a landslide","definition":"to win an election or vote by a very large amount.","ko":"아주 큰 차이로 이기다.","cefr":"B2","type":"idiom"},{"id":"idiom_1828","en":"fall from grace","definition":"to lose respect and a good position because of bad behavior.","ko":"나쁜 행동 때문에 존경과 좋은 지위를 잃다.","cefr":"B2","type":"idiom"},{"id":"idiom_1829","en":"plunge into chaos","definition":"to suddenly become very confused and out of control.","ko":"갑자기 매우 혼란스럽고 통제 불능이 되다.","cefr":"B2","type":"idiom"},{"id":"phrasal-verb_0001","en":"abide by","definition":"to accept and follow a rule, law, decision, or instruction","ko":"규칙, 법, 결정, 지시를 받아들이고 따르다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0002","en":"account for","definition":"to give a reason or explanation for something that has happened or for something you have done.","ko":"일어난 일이나 자신이 한 일에 대한 이유나 설명을 제공하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0003","en":"act (up) on","definition":"to do something as a result of information, advice, or a suggestion you have received.","ko":"받은 정보, 조언, 제안에 따라 행동하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0004","en":"act out","definition":"to behave badly or show your feelings through inappropriate or disruptive actions, especially when upset or seeking attention","ko":"특히 속상하거나 관심을 받고 싶을 때 부적절하거나 방해되는 행동으로 감정을 드러내거나 나쁘게 행동하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0005","en":"act up","definition":"to behave badly or cause trouble, especially when trying to get attention. Often used to talk about children.","ko":"나쁘게 행동하거나 문제를 일으키다, 특히 관심을 끌기 위해서. 주로 아이들에게 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0006","en":"add on","definition":"to include an extra amount or item in the total, especially in calculations or when paying for something.","ko":"특히 계산이나 결제 시, 전체 금액이나 항목에 추가 금액이나 품목을 포함하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0007","en":"add up","definition":"to calculate the total of several numbers or amounts; to make sense or be reasonable when everything is considered.","ko":"여러 숫자나 금액의 합계를 계산하다; 모든 것을 고려했을 때 이치에 맞거나 타당하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0008","en":"air out","definition":"To let fresh air into something to make it smell better or get rid of bad smells.","ko":"냄새를 제거하거나 신선한 공기를 들이기 위해 무언가를 환기하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0009","en":"allow for","definition":"to consider or include something when making plans or calculating something.","ko":"계획을 세우거나 계산할 때 무언가를 고려하거나 포함시키다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0010","en":"allow in","definition":"to let someone enter a place.","ko":"누군가가 장소에 들어갈 수 있도록 허락하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0011","en":"ally with","definition":"to join or cooperate with a person or group for a common purpose, usually to achieve a goal or face a challenge together","ko":"공통의 목적을 달성하거나 함께 도전에 맞서기 위해 사람이나 그룹과 함께 하거나 협력하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0012","en":"answer for","definition":"to take responsibility for or be held accountable for someone or something, especially when something has gone wrong.","ko":"특히 잘못된 일이 생겼을 때, 누군가 또는 무언가에 대해 책임을 지거나 책임을 져야 함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0013","en":"ask for","definition":"To say what you want or need; to make a request for something.","ko":"원하거나 필요한 것을 말하다; 무언가를 요청하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0014","en":"ask in","definition":"to invite someone to come inside your home or another place you are in.","ko":"누군가를 집이나 자신이 있는 곳 안으로 들이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0015","en":"ask out","definition":"To invite someone to go on a romantic date with you.","ko":"누군가를 데이트에 초대하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0016","en":"ask round","definition":"To invite someone to come to your home, usually for a meal, drink, or to spend time together. A similar phrase is 'ask over'.","ko":"누군가를 보통 식사, 음료 또는 함께 시간을 보내기 위해 집에 초대하다. 유사한 표현으로는 'ask over'가 있다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0017","en":"attend to","definition":"to deal with or take care of someone or something that needs your attention.","ko":"주의가 필요한 사람이나 일을 처리하다, 돌보다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0018","en":"auction off","definition":"to sell something to the person who offers the most money, usually at a public event called an auction.","ko":"일반적으로 경매라고 하는 공개 행사에서 가장 많은 돈을 제시한 사람에게 무언가를 판매하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0019","en":"average out","definition":"To result in a number or amount that is the average when you add several numbers together and divide by how many there are.","ko":"여러 숫자를 더해서 그 개수로 나누었을 때의 평균값이나 금액이 되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0020","en":"back away","definition":"To move slowly backwards from someone or something, usually because you are scared or want to avoid danger.","ko":"누군가나 무언가로부터 천천히 뒤로 물러나다. 보통 두렵거나 위험을 피하고 싶을 때 사용함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0021","en":"back down","definition":"to stop arguing or fighting and accept that you cannot win or continue; to give up your position in a disagreement.","ko":"논쟁이나 싸움을 그만두고 이길 수 없거나 계속할 수 없음을 받아들임; 의견 충돌에서 자신의 입장을 양보함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0022","en":"back off","definition":"to move away from a person or object, especially when told to or when it is safer; Synonym: 'back away'","ko":"관여하는 것을 멈추거나 어떤 일에 대해 누군가를 귀찮게 하는 것을 멈추다. 주로 사람이나 주제를 방해하지 말라고 할 때 사용합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0023","en":"back out","definition":"To decide not to do something you agreed to do, or to withdraw from a plan, agreement, or commitment.","ko":"동의했던 일을 하지 않기로 하거나, 계획·약속·계약 등에서 물러나다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0024","en":"back up","definition":"to support what you say by giving proof, facts, or evidence","ko":"막히거나 장애물이 생겨 흐름이나 이동이 멈추거나 느려지는 것. 배관, 배수구, 교통 등에서 자주 일어납니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0025","en":"bail out","definition":"to help someone or something out of a difficult situation, especially by giving money or practical support.","ko":"특히 돈이나 실질적인 지원을 해줌으로써 누군가나 무언가를 어려운 상황에서 도와주다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0026","en":"bowl over","definition":"to greatly surprise or impress someone","ko":"누군가를 크게 놀라게 하거나 감동시키다. 'bowled over' 되면 보통 긍정적으로 크게 놀라거나 충격을 받는다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0027","en":"bang out","definition":"to produce something quickly and often noisily, especially by hitting keys or playing an instrument forcefully","ko":"무엇인가를 빠르고 종종 시끄럽게 생산하다. 특히 키를 두드리거나 악기를 세게 연주할 때 사용함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0028","en":"bang up","definition":"to damage or break something by hitting it or treating it roughly","ko":"거칠게 다루거나 부딪혀서 손상시키거나 부수다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0029","en":"barge in","definition":"To enter a place suddenly and without being invited, often in a rude or noisy way.","ko":"장소에 갑자기 초대받지 않고 (종종 무례하거나 시끄럽게) 들어오다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0030","en":"be after","definition":"to be trying to find, get, or catch someone or something","ko":"누구나 무엇을 찾거나 얻으려고 하거나 잡으려고 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0031","en":"be on","definition":"to be happening or shown, especially on television, radio, or at the theater","ko":"특히 TV, 라디오, 극장에서 상영되거나 방송되고 있다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0032","en":"bear down","definition":"to push or press down firmly on someone or something with your strength or weight","ko":"특히 어려울 때, 모든 노력과 집중을 사용하여 무언가를 끝내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0033","en":"bear up","definition":"to remain strong and positive in a difficult situation, or to support someone or something so they do not collapse or fail.","ko":"어려운 상황에서도 강인하고 긍정적으로 남아 있거나, 누군가 또는 무언가가 무너지거나 실패하지 않도록 돕는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0034","en":"bear upon","definition":"to be connected to something or to have an effect on something.","ko":"무언가와 관련되거나 영향을 미치다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0035","en":"beat down","definition":"to make someone agree to a lower price when you are buying something; to successfully bargain for a discount.","ko":"누구나 무엇 위에 아주 강하게, 특히 태양이나 비가 쏟아지거나 내리쬐는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0036","en":"beat in (to)","definition":"To teach someone something by repeating it many times, often in a strict or forceful way. It means to make sure someone learns something by practicing or hearing it again and again.","ko":"어떤 것을 누군가에게 여러 번 반복하고, 때때로 엄격하거나 강압적으로 가르치는 것. 반복 연습이나 말을 통해 반드시 배우게 한다는 뜻이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0037","en":"beat out","definition":"to make a strong or regular rhythm by hitting something, especially in music","ko":"특히 음악에서 무언가를 치며 강하거나 일정한 리듬을 만드는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0038","en":"beat up","definition":"to hurt someone by hitting them many times, usually in a fight.","ko":"주로 싸움에서, 누군가를 여러 번 때려 다치게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0039","en":"beef up","definition":"to make something stronger, more effective, or more impressive","ko":"무엇인가를 더 강하게, 효과적으로, 인상적으로 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0040","en":"beg off","definition":"To politely say you cannot do something you were invited or expected to do.","ko":"초대받거나 기대되었던 일을 정중하게 못 한다고 말하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0041","en":"belly out","definition":"When something, like a sail or a piece of fabric, is pushed outward and filled with air or wind, so that it sticks out in a round shape.","ko":"돛이나 천과 같은 것이 바람이나 공기로 바깥쪽으로 밀려 둥글게 부풀어 오르는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0042","en":"belt along","definition":"to move very quickly, especially along a road or path","ko":"특히 도로나 길을 아주 빠르게 움직이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0043","en":"belt out","definition":"to sing a song or play music very loudly and with a lot of energy","ko":"노래나 음악을 매우 크고 에너지 넘치게 부르거나 연주하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0044","en":"bet on","definition":"to risk money or something valuable by guessing the result of an event, usually a game, race, or other competition; or to strongly expect that something will happen.","ko":"주로 경기, 경주, 또는 다른 대회의 결과를 추측하여 돈이나 귀중한 것을 걸거나, 어떤 일이 일어날 것이라고 강하게 기대하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0045","en":"bite off","definition":"To use your teeth to remove a part of something by biting it.","ko":"이를 사용해 무언가의 일부분을 물어 떼어내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0046","en":"blab out","definition":"To tell a secret or private information to other people, especially when you should keep it to yourself. Synonym: 'spill the beans'.","ko":"비밀이나 개인적인 정보를 남들에게 말하다, 특히 자신만 알고 있어야 할 때. 유의어: '누설하다'.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0047","en":"black out","definition":"to hide or remove information so that people cannot see or hear it, especially in media, documents, or broadcasts.","ko":"갑자기 전기가 끊기거나, 외부에서 빛이 보이지 않게 창문을 가리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0048","en":"blank out","definition":"to deliberately forget or stop thinking about something, often because it is unpleasant or difficult to remember","ko":"정보가 보이거나 읽히지 않도록 덮거나, 제거하거나, 지우는 것 (종종 프라이버시나 보안상의 이유로).","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0049","en":"blare out","definition":"to make a very loud and unpleasant noise, usually from speakers or electronic devices.","ko":"보통 스피커나 전자기기에서 매우 크고 불쾌한 소리를 내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0050","en":"blast off","definition":"(for a rocket or spacecraft) to leave the ground and go up into space","ko":"물이나 공기처럼 강한 힘을 사용하여 표면에서 무언가를 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0051","en":"blaze away","definition":"to do something with a lot of energy and enthusiasm, often quickly and without stopping.","ko":"누군가나 무언가에게 반복적으로, 특히 격렬하게 총을 쏘다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0052","en":"blend in","definition":"to look or behave like the people or things around you so that you are not noticed as different","ko":"자신이 주변의 사람이나 사물처럼 보여지거나 행동해서 다르게 보이지 않도록 하는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0053","en":"blink away","definition":"to quickly open and close your eyes to try to make tears or something else go away from your eyes, usually so others don't notice your feelings.","ko":"다른 사람이 자신의 감정을 눈치채지 못하게 하기 위해 눈을 빠르게 깜빡여 눈물이나 다른 것을 없애려는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0054","en":"block off","definition":"To stop people or things from passing through an area by putting something in the way.","ko":"무엇인가를 놓아 사람이나 사물이 지나다니지 못하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0055","en":"block up","definition":"to completely fill or cover a space so that nothing can go through it","ko":"아무것도 통과할 수 없도록 공간을 완전히 채우거나 덮다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0056","en":"blossom out","definition":"to grow or develop in a noticeable and positive way, especially by becoming more confident, attractive, or skilled.","ko":"두드러지고 긍정적인 방식으로 성장하거나 발전하다. 특히 더 자신감 있고, 매력적이거나, 능숙해지는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0057","en":"blot out","definition":"to hide or cover something so that it cannot be seen, especially by marking over it or blocking it from view","ko":"볼 수 없게 하거나 가려서 보이지 않게 하다, 특히 표시하거나 시야를 차단하여","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0058","en":"blow off","definition":"To be removed or forced away by strong force, especially the wind or an explosion. It can also mean to ignore or not meet someone, especially in a casual or unfriendly way.","ko":"강한 힘, 특히 바람이나 폭발에 의해 떨어져 나가거나 날아가다. 또한 누군가를 무시하거나 약속 장소에 일부러 나오지 않는다는 뜻도 있다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0059","en":"blow out","definition":"to go out or be extinguished because of a strong current of air","ko":"보통 내부 손상이나 결함(예: 전기 문제)으로 인해 갑자기 작동을 멈추다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0060","en":"blow over","definition":"If something bad, like a problem or argument, blows over, it slowly goes away and people forget about it.","ko":"누군가를 충격이나 놀라움에 빠뜨리다. 보통 매우 놀랍거나 인상적이기 때문임.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0061","en":"blow up","definition":"to make something explode or to destroy something with an explosion","ko":"사진, 그림, 이미지를 더 크게 만들어서 특히 더 많은 세부 사항을 볼 수 있도록 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0062","en":"blubber out","definition":"to say something while crying so much that it is hard to understand you.","ko":"너무 많이 울어서 알아듣기 힘들게 무언가를 말하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0063","en":"blurt out","definition":"to suddenly say something without thinking, often because you are excited or nervous","ko":"흥분하거나 긴장해서 생각 없이 갑자기 무언가를 말하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0064","en":"board up","definition":"To cover windows or doors of a building with wooden boards, usually to protect it or keep people out.","ko":"건물의 창문이나 문을 나무판으로 덮어 보호하거나 사람들이 들어오는 것을 막다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0065","en":"bob about","definition":"to move gently up and down in water or air, usually without a specific direction or purpose. Synonym: 'bob around'.","ko":"특정한 방향이나 목적 없이 물이나 공기에서 부드럽게 위아래로 움직이다. 유의어: '둥둥 떠다니다'.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0066","en":"boil down","definition":"to make a liquid thicker and more concentrated by heating it so that some of the water goes away as steam.","ko":"복잡한 상황, 아이디어, 문제를 가장 중요한 점이나 기본적인 의미로 단순화하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0067","en":"boil over","definition":"For liquids: to flow over the side of a container when it gets too hot and starts to bubble too much.","ko":"누군가가 'boil over' 하면 갑자기 매우 화가 나서 더 이상 분노를 억제할 수 없게 됩니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0068","en":"bolt out (of)","definition":"To suddenly and quickly leave a place, usually because of surprise, fear, or urgency.","ko":"놀람, 두려움, 긴급함 때문에 갑자기 빠르게 장소를 떠나다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0069","en":"book up","definition":"to reserve or fill all available places, seats, or tickets for an event or location, so that nothing is left.","ko":"행사나 장소의 모든 자리, 좌석, 표 등을 예약하거나 가득 채워 아무것도 남지 않게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0070","en":"boom out","definition":"(For a sound) to be very loud and powerful, so it can be heard clearly and from far away.","ko":"(소리가) 매우 크고 강력하여 멀리서도 또렷하게 들리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0071","en":"boot out","definition":"to force someone or something to leave a place, usually because they are not wanted there.","ko":"원하지 않기 때문에 누군가나 무언가를 강제로 내쫓다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0072","en":"border on","definition":"To be next to or very close to something; to share a boundary with something.","ko":"무엇에 인접해 있거나 매우 가까이 있다; 경계를 공유하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0073","en":"boss around","definition":"to keep telling someone what to do in an annoying or controlling way, often when you have no right to do so.","ko":"짜증스럽거나 통제하려는 방식으로 계속해서 누군가에게 무엇을 하라고 시키는 것, 종종 그럴 권리가 없음에도.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0074","en":"botch up","definition":"to do something badly or carelessly so that it is not done well","ko":"어떤 일을 엉성하거나 부주의하게 해서 잘못하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0075","en":"bottle up","definition":"To keep your feelings or emotions hidden inside and not express them.","ko":"감정이나 기분을 속에 감추고 표현하지 않는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0076","en":"bottom out","definition":"To reach the lowest or worst level, usually before beginning to improve again.","ko":"최저 또는 최악의 수준에 도달하고, 보통 그 후에 다시 호전되기 시작하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0077","en":"bow down","definition":"To physically bend your upper body forward, usually to show respect or submission. Often used when talking about showing respect to someone important or powerful.","ko":"주로 존경이나 복종을 나타내기 위해 상체를 앞으로 굽히는 것. 보통 중요하거나 권력 있는 사람에게 존경을 표할 때 사용된다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0078","en":"bow down (to)","definition":"To accept someone else's power or authority over you, often because you feel you have no choice.","ko":"다른 사람의 권력이나 권위에 어쩔 수 없이 복종하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0079","en":"bow out (of)","definition":"to leave a job, activity, or situation, especially because you want to or it is the right time to stop.","ko":"특히 원해서 또는 그만둘 적절한 시기여서 직장, 활동, 상황에서 물러나다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0080","en":"box in","definition":"To limit someone's choices or freedom so they can't do what they want.","ko":"누군가의 선택이나 자유를 제한해서 원하는 것을 하지 못하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0081","en":"box up","definition":"to put someone or something into a small or restricted space, or to make someone feel trapped or confined.","ko":"물건을 박스에 넣다, 보통 옮기거나 정리하기 위해서.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0082","en":"branch out","definition":"to start doing something different from what you usually do, especially in work or hobbies","ko":"보통 하던 일과는 다른, 새로운 일을 시작하다(특히 일이나 취미에서)","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0083","en":"break away","definition":"to leave a group or organization because you want to be independent or do something different.","ko":"누군가 또는 무언가의 구속에서 도망치거나 스스로를 해방시키는 것. ‘break free’와 유사함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0084","en":"break down","definition":"When a machine or vehicle breaks down, it stops working because there is a problem or it is damaged.","ko":"특히 어려운 상황에서 갑자기 울기 시작하거나 감정을 제어하지 못하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0085","en":"break in","definition":"to enter a place (usually by force) without permission, often to steal something","ko":"새로운 것을 사용할 때 편해질 때까지 사용하다. 주로 신발이나 옷에 쓰인다. 동물, 특히 말을 길들이는 의미도 있다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0086","en":"break into","definition":"to suddenly start doing something, like laughing, singing, or talking, without warning","ko":"불법적으로(특히 힘을 써서) 건물, 차 혹은 다른 곳에 침입하다; 또는 갑자기 무언가를 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0087","en":"break off","definition":"to suddenly stop doing something, especially speaking or an activity, before it is finished","ko":"무언가의 일부를 나머지로부터 떼어내거나 분리하다, 보통 부러뜨리거나 잡아당겨서","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0088","en":"break out","definition":"to start suddenly and unexpectedly, especially something such as a fight, a fire, or laughter.","ko":"특히 힘이나 교묘한 계획을 사용하여 장소에서 탈출하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0089","en":"break through","definition":"to force your way through a barrier or an obstacle, especially when it is difficult to pass.","ko":"특히 지나가기 힘든 장애물이나 장벽을 힘으로 뚫고 나가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0090","en":"break up","definition":"to divide something into smaller parts or pieces; or to end a relationship or event.","ko":"회의, 수업 또는 다른 조직된 행사를 끝내어 사람들이 집에 갈 수 있도록 하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0091","en":"breathe in","definition":"To take air into your lungs through your nose or mouth.","ko":"코나 입을 통해 폐로 공기를 들이마시는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0092","en":"breathe out","definition":"To let air go from your lungs through your nose or mouth; the opposite of breathing in.","ko":"폐에서 코나 입을 통해 공기를 내보내는 것; 들숨의 반대.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0093","en":"breeze through","definition":"To finish something very quickly and easily, without much effort. Synonym: 'sail through'.","ko":"별다른 노력 없이 매우 빠르고 쉽게 무언가를 끝내다. 유의어: ‘손쉽게 해내다’.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0094","en":"bridge over","definition":"To build or create something (like a bridge or another connection) to go over a gap, obstacle, or difficulty and connect two sides.","ko":"간격, 장애물, 어려움을 넘고 양쪽을 연결하기 위해 다리나 다른 연결 고리를 건설하거나 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0095","en":"brim over","definition":"to be so full that it goes over the edge; to overflow (physically or with emotion). Similar to 'brim with'.","ko":"너무 가득 차서 넘치다; (물리적 또는 감정적으로) 넘쳐흐르다. '가득 차다'와 유사.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0096","en":"bring about","definition":"to cause something to happen or to make something change","ko":"무엇을 야기하다; 초래하다; 가져오다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0097","en":"bring around","definition":"to convince someone to change their opinion or agree with an idea or plan","ko":"누군가를 설득해서 의견을 바꾸거나 아이디어/계획에 동의하게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0098","en":"bring down","definition":"to make someone or something lose power, strength, or happiness; to cause someone or something to fall or fail.","ko":"누군가 혹은 무엇인가의 권력, 힘, 행복을 잃게 하다; 누군가 또는 무엇가를 쓰러뜨리거나 실패하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0099","en":"bring in","definition":"to earn or make money for a business or organization","ko":"누군가를 활동, 그룹에 참여시키거나, 무언가를 도와달라고 요청하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0100","en":"bring off","definition":"to succeed in doing something difficult; to achieve something successfully","ko":"어려운 일을 해내다; 성공적으로 달성하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0101","en":"bring on","definition":"to make something or someone appear, or to cause something to happen, especially quickly or sooner than expected.","ko":"무엇이나 누군가를 등장시키거나 어떤 일이 발생하도록 하다, 특히 예상보다 빠르게.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0102","en":"bring out","definition":"to make a new product available for people to buy; to launch or publish something new.","ko":"무언가를 눈에 띄게 하거나 쉽게 보이게 하다, 또는 사람들이 알아차리게 뭔가를 보여주다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0103","en":"bring up","definition":"to start talking about a subject or topic in a conversation or discussion","ko":"대화나 토론에서 주제나 화제를 꺼내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0104","en":"bristle at","definition":"To react with anger or annoyance to something someone says or does.","ko":"누군가가 말하거나 행동하는 것에 화나거나 짜증내며 반응하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0105","en":"brush down","definition":"to remove dust, dirt, or crumbs from someone or something using a brush or your hand.","ko":"솔이나 손으로 먼지, 먼지, 부스러기를 사람이나 사물에서 털어내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0106","en":"brush off","definition":"To ignore someone or treat their ideas, opinions, or requests as unimportant.","ko":"누군가를 무시하거나 그 사람의 생각, 의견, 요청을 중요하지 않게 대하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0107","en":"brush on","definition":"to put something, like a liquid, onto a surface using a brush","ko":"붓이나 솔로 액체 등을 표면에 바르다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0108","en":"brush up","definition":"to review or practice something you learned before, so you don't forget it or can use it better.","ko":"예전에 배웠던 것을 잊지 않거나 더 잘 사용하기 위해 복습하거나 연습하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0109","en":"bubble over","definition":"To be so full of joy or excitement that it is very easy for others to see or feel your happiness.","ko":"기쁨이나 흥분이 가득 차서 다른 사람들이 쉽게 그 행복을 느낄 수 있는 상태.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0110","en":"bubble up","definition":"to appear or rise to the surface as bubbles, especially when something is heated; can also mean when a feeling or idea slowly becomes stronger and more noticeable","ko":"거품이 표면으로 나타나거나 올라오다, 특히 무언가를 가열할 때; 또는 감정이나 아이디어가 천천히 더 강해지고 뚜렷해질 때도 사용","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0111","en":"buck up","definition":"to cheer up or become more positive, especially after feeling sad or discouraged","ko":"우울하거나 낙담한 후에 기운을 차리거나 더 긍정적으로 변하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0112","en":"buckle down","definition":"to start working very hard and seriously on something, especially after not working hard before.","ko":"그동안 열심히 하지 않았던 일에 매우 열심히, 진지하게 몰두하기 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0113","en":"buckle under","definition":"To be unable to cope with pressure, stress, or demands, and therefore give in or fail.","ko":"압박, 스트레스, 요구를 견디지 못하고 결국 굴복하거나 실패하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0114","en":"budget for","definition":"to plan how much money you will spend on something and save or set aside that amount for it.","ko":"무엇에 얼마를 쓸지 계획하고 그 금액을 따로 떼어두는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0115","en":"bugger off","definition":"slang, British English. To tell someone to go away or leave immediately, usually in a rude or annoyed way.","ko":"속어, 영국 영어. 누구에게 즉시 떠나라고, 보통 무례하거나 짜증 난 방식으로 말하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0116","en":"build in","definition":"to include someone or something as a necessary part of a plan, system, or arrangement","ko":"계획, 시스템 또는 배열의 필수적인 부분으로 누군가 또는 무언가를 포함하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0117","en":"build on","definition":"To use something as a base or starting point in order to make progress or add more to it.","ko":"무언가를 기반이나 출발점으로 삼아 더 발전시키거나 추가하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0118","en":"build up","definition":"to gradually increase in amount, size, or strength, or to make something do this; to prepare for an important event by gradually creating excitement or tension.","ko":"양, 크기, 힘 등이 점차 증가하다, 또는 그렇게 만들다; 점차적인 기대감이나 긴장을 조성해 중요한 사건을 준비하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0119","en":"build upon","definition":"to use what you already have or what has already been done as a base to make something better or achieve more.","ko":"이미 가지고 있거나 이미 이루어진 것을 바탕으로 더 나은 것을 만들거나 더 많은 것을 성취하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0120","en":"bulge out","definition":"to stick out or swell outward because something is inside or pushing from inside","ko":"안에 무언가가 있거나 안에서 밀어내서 밖으로 튀어나오거나 부풀어 오르다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0121","en":"bum about","definition":"to spend time doing nothing important or to relax and wander without a particular purpose, often with someone. Synonym: 'bum around'","ko":"아무 중요한 일 없이 시간을 보내거나 특별한 목적 없이 누군가와 함께 편하게 이리저리 돌아다니다. 동의어: '빈둥거리다'","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0122","en":"bump into","definition":"to meet someone unexpectedly, or to accidentally touch or hit someone or something.","ko":"누군가를 우연히 만나다, 또는 실수로 누군가나 무언가에 부딪히다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0123","en":"bump off","definition":"slang. To kill someone, usually in a secret or violent way.","ko":"속어. 보통 은밀하거나 폭력적으로 누군가를 죽이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0124","en":"bump up","definition":"To increase the level, amount, or status of someone or something, often unexpectedly or suddenly.","ko":"누군가나 무언가의 수준, 양, 지위를 흔히 예상치 못하게 또는 갑작스럽게 올리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0125","en":"bunch up","definition":"To move things or people close together so there is less space between them.","ko":"물건이나 사람을 서로 가까이 모이게 하여 공간을 줄이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0126","en":"bundle up","definition":"to put on warm clothes to protect yourself from cold weather","ko":"여러 가지를 하나의 뭉치나 꾸러미로 묶다. 보통 더 쉽게 운반하거나 정리하기 위함이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0127","en":"bunk off","definition":"(British English) to leave school or work early or not go there, without permission, usually to avoid doing something you do not want to do.","ko":"(영국식 영어) 학교나 직장을 허락 없이 일찍 떠나거나 가지 않는 것. 보통 하고 싶지 않은 일을 피하려고 그렇게 함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0128","en":"burn down","definition":"to be destroyed or destroy something completely by fire so that only the basic structure or nothing at all is left","ko":"불에 완전히 타서 구조만 남거나 아무것도 남지 않게 되다, 또는 무언가를 완전히 불에 태워 없애다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0129","en":"burn off","definition":"to get rid of something, often calories or fat, by using energy, usually through physical activity or exercise.","ko":"운동이나 신체 활동을 통해 에너지를 사용하여 칼로리나 지방 등을 없애는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0130","en":"burn out","definition":"to use something so much that it stops working or is destroyed by excessive heat or overuse, especially when talking about machines or engines.","ko":"무엇인가를 너무 많이 사용해서, 특히 기계나 엔진이 과열되거나 과도하게 사용되어 더 이상 작동하지 않거나 파손되는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0131","en":"burn up","definition":"to travel or drive somewhere very fast, especially in a car or other vehicle.","ko":"특히 활동하거나 운동을 해서 많은 에너지를 소모하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0132","en":"burst in on","definition":"to suddenly enter a place and interrupt someone or something when they are busy or in the middle of doing something.","ko":"누군가가 바쁘거나 무언가를 하고 있을 때 갑자기 들어와 방해하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0133","en":"burst out","definition":"to suddenly start saying something or making a loud sound, often because of strong emotion","ko":"어디에서 갑자기 매우 빠르게 튀어나오다, 거의 폭발처럼","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0134","en":"bush out","definition":"If a plant or part of a plant bushes out, it grows more leaves, branches, or stems, making it thicker and fuller in appearance.","ko":"식물이나 그 일부가 잎, 가지 또는 줄기를 더 많이 내어 더 풍성하고 두꺼워 보이게 자라는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0135","en":"bust up","definition":"to break or destroy something, often by making it come apart into smaller pieces.","ko":"무언가를 부수거나 파괴하여 더 작은 조각으로 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0136","en":"bustle about","definition":"to move around a place quickly and with energy, usually because you are busy doing things","ko":"무엇인가를 하느라 바쁘게 한 장소를 빠르고 에너지 있게 돌아다니다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0137","en":"butt in","definition":"to suddenly interrupt someone while they are speaking, often when it is not your turn or you are not invited to join the conversation","ko":"누군가가 말하고 있을 때 갑자기 끼어드는 것. 보통 자신 차례가 아니거나 초대받지 않은 대화에 참여할 때 사용됨","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0138","en":"butter up","definition":"to say nice things to someone or praise them a lot because you want them to do something for you or treat you well","ko":"무언가를 부탁하거나 잘 대해주길 바라는 마음으로 누군가에게 아첨하거나 지나치게 칭찬하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0139","en":"buy in","definition":"to buy a large amount of something to keep for later use, usually to make sure you don't run out","ko":"나중에 사용하기 위해 어떤 것을 대량으로 미리 사 두다. 주로 떨어지지 않으려고 함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0140","en":"buy into","definition":"to purchase a share or part of something, like a business or an investment, so you become a part-owner along with others.","ko":"비즈니스나 투자와 같은 것의 일부를 구매하여 다른 사람들과 공동 소유주가 되는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0141","en":"buy off","definition":"To give someone money or gifts to persuade them not to take action against you, usually to avoid trouble or to ignore something wrong.","ko":"문제를 피하거나 잘못된 일을 무시하게 하려고, 누군가에게 돈이나 선물을 주어 자신에게 불리한 행동을 하지 않도록 설득하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0142","en":"buy out","definition":"To buy someone's share in a business or property so that you become the only owner.","ko":"사업이나 재산에서 누군가의 지분을 사들여 유일한 소유자가 되는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0143","en":"buy up","definition":"to buy all or most of something available, so that there is little or none left for other people.","ko":"다른 사람들이 살 수 없도록 모든 것 또는 대부분을 사들이는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0144","en":"buzz off","definition":"To go away or leave, often used in an informal or unfriendly way to tell someone to go away.","ko":"어디론가 가거나 떠나다. 누구에게 가라고 말할 때 비격식적이거나 불친절하게 사용함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0145","en":"cage in","definition":"To keep someone or something inside a closed space, like a cage, so they can’t get out.","ko":"누군가나 무엇인가를 우리 같은 닫힌 공간 안에 가두어 밖으로 나가지 못하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0146","en":"call for","definition":"To go to a place to collect or pick up someone or something, usually to take them somewhere else.","ko":"무엇이 필요하다고 요구하거나 필요하다고 말하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0147","en":"call in","definition":"to ask someone to come for help, advice, or a meeting","ko":"주변에 있을 때 예상치 못하게 잠깐 누군가를 방문하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0148","en":"call off","definition":"To decide not to do something that was planned, especially an event or activity.","ko":"특히 행사나 활동 등 계획된 것을 하지 않기로 결정하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0149","en":"call on","definition":"to ask someone to do something, such as answer a question or help with a task","ko":"누군가에게 질문에 답하거나 과제를 도와달라고 요청하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0150","en":"call out","definition":"to say something loudly so people can hear, often to get someone's attention or give information","ko":"누구나 들을 수 있게 크게 말하다, 주로 주의를 끌거나 정보를 전달하기 위해 사용됨","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0151","en":"call up","definition":"to telephone someone","ko":"컴퓨터 화면에서 정보를 표시하거나 찾다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0152","en":"calm down","definition":"to become or make someone become less angry, upset, or excited; to relax and feel peaceful again","ko":"화나거나 흥분한 상태에서 진정하다, 또는 누군가를 진정시키다; 다시 평온해지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0153","en":"camp out","definition":"to sleep or stay outside, usually in a tent, for a short time, especially for fun.","ko":"일반적으로 텐트에서 짧은 기간 동안 야외에서 자거나 머무르는 것, 특히 재미로.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0154","en":"cancel out","definition":"to remove or reduce the effect of something so that it has no real impact","ko":"어떤 것의 효과를 없애거나 줄여서 실제 영향이 없도록 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0155","en":"cap off","definition":"To finish or complete something in a special or impressive way.","ko":"특별하거나 인상적인 방식으로 무언가를 마무리하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0156","en":"care for","definition":"to feel affection for someone or to like someone a lot","ko":"누군가 또는 무언가를 돌보고 안전하고 건강하게 또는 좋은 상태로 있도록 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0157","en":"carry away","definition":"to take something or someone from a place, often by force or suddenly","ko":"무엇이나 누군가를, 종종 강제로 또는 갑자기 한 장소에서 데려가다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0158","en":"carry off","definition":"to do something successfully, especially something difficult or unexpected.","ko":"특히 어렵거나 예상치 못한 일을 성공적으로 해내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0159","en":"carry on","definition":"to continue doing something, especially after being interrupted or to keep a tradition or activity going","ko":"불평하거나 울거나 소란을 피우면서 흥분되고 시끄럽거나 바보같이 행동하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0160","en":"carry out","definition":"to complete or do something, especially a task, plan, or order.","ko":"특히 과제, 계획, 명령 등을 완수하거나 수행하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0161","en":"carry over","definition":"to move something from one time or situation to another later one, usually because it could not be done before.","ko":"무엇인가를 한 시간이나 상황에서 나중의 시간이나 상황으로 옮기는 것, 보통 이전에 할 수 없었기 때문에.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0162","en":"carry through","definition":"To finish something that you have started, especially when it is difficult.","ko":"특히 어렵더라도 시작한 일을 끝까지 해내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0163","en":"cart away","definition":"To take or remove someone or something from a place, usually by using a vehicle or with some effort.","ko":"보통 차량이나 노력을 들여 사람이나 물건을 한 곳에서 치우거나 옮기는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0164","en":"carve up","definition":"to divide something into parts, often in a way that is unfair or not careful","ko":"무언가를 여러 부분으로 나누다, 종종 불공정하거나 부주의하게","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0165","en":"cascade down","definition":"To flow or fall down quickly and in large amounts, like water going down a surface.","ko":"물이 표면을 따라 흘러내리듯이, 빠르고 많은 양으로 쏟아져 내리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0166","en":"cash in","definition":"To exchange something, like an investment or a policy, for its money value.","ko":"투자나 보험 등 어떤 것을 돈으로 교환하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0167","en":"cash in on","definition":"to take advantage of a situation in order to make money or get a benefit, often in an opportunistic way","ko":"돈을 벌거나 이익을 얻기 위해 상황을 (기회주의적으로) 이용하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0168","en":"cash out","definition":"To exchange something, like an investment, shares, or casino chips, for money. It is also used when you take your money out from an account or a game and stop participating.","ko":"투자, 주식, 카지노 칩 등과 같은 것을 현금으로 바꾸는 것. 계좌나 게임에서 돈을 인출하고 참여를 멈출 때도 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0169","en":"cast about","definition":"To try to find something or someone, often by searching in different ways or thinking carefully. Synonym: 'cast around'.","ko":"무엇이나 누군가를 찾으려고 여러 방법으로 시도하거나 신중하게 생각하며 노력하다. 유의어: '찾아보다'.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0170","en":"cast down","definition":"to feel very sad, disappointed, or discouraged","ko":"매우 슬프거나 실망하거나 낙담하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0171","en":"cast off","definition":"To get rid of something or someone that you no longer want or need. Similar to 'throw away' or 'let go'.","ko":"더 이상 원하지 않거나 필요하지 않은 것, 사람을 버리거나 내보내는 것. '버리다', '놓아주다'와 유사.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0172","en":"cast out","definition":"to force someone to leave a group, place, or community; to make someone go away because they are no longer wanted.","ko":"누군가를 그룹, 장소 또는 공동체에서 내쫓다; 더 이상 원하지 않아서 떠나게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0173","en":"catch on","definition":"To become popular or fashionable among people.","ko":"무언가를 이해하거나 깨닫다. 종종 시간이 좀 지난 후에.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0174","en":"catch out","definition":"to find someone making a mistake or not telling the truth, often by surprise","ko":"누군가가 실수하거나 거짓말을 하고 있는 것을 종종 놀라게 하며 들키게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0175","en":"catch up","definition":"to do something that you have not had time to do earlier, so that you reach the same level as others or as you should be.","ko":"이전에 할 시간이 없었던 일을 해서 다른 사람들과 같은 수준에 도달하거나 마땅히 해야 할 수준에 도달하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0176","en":"catch up with","definition":"to reach the same level or position as someone or something, especially after being behind for a while","ko":"한동안 뒤처진 후 누군가나 무언가와 같은 수준이나 위치에 도달하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0177","en":"cave in","definition":"To finally agree to do what someone wants after resisting or refusing before.","ko":"무언가가 무너진다는 것은, 더 이상 무게를 지탱할 수 없어 갑자기 무너져 내리거나 붕괴되는 것을 의미합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0178","en":"center on","definition":"To have something as its main subject or focus.","ko":"무엇을 주요 주제나 초점으로 삼다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0179","en":"chain up","definition":"to fasten or secure a person, animal, or object with a chain so they cannot move or be taken away.","ko":"사람, 동물, 또는 물건을 움직이지 못하거나 가져갈 수 없게 사슬로 묶어 두다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0180","en":"chalk up","definition":"To achieve or collect something, like a point, a win, or an accomplishment, especially as a result or record of success.","ko":"특히 성공의 결과나 기록으로 점수, 승리, 성과 등을 이루거나 쌓아올리는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0181","en":"chance on","definition":"To find or discover something by accident, without planning to.","ko":"계획 없이 우연히 무언가를 발견하거나 찾다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0182","en":"change over","definition":"to switch or move from using one thing to using another; to stop doing or using something and start something else instead.","ko":"한 가지를 사용하는 것에서 다른 것으로 바꾸다; 무엇인가를 그만두고 대신 다른 것을 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0183","en":"charge up","definition":"To fill something with energy, or to make someone excited and enthusiastic.","ko":"무언가에 에너지를 채우거나 누군가를 신나고 열정적으로 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0184","en":"chase after","definition":"to run or go quickly after someone or something in order to catch them.","ko":"누군가와 연애 관계를 원해서 그 사람을 따라다니다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0185","en":"chase away","definition":"to make someone or something leave a place because you don't want them there","ko":"원하지 않아서 누군가나 무언가를 어떤 장소에서 떠나게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0186","en":"chat up","definition":"to talk to someone in a friendly or flirtatious way, often because you are interested in them romantically or want to get to know them better.","ko":"누군가에게 친근하게 또는 호감이 있다는 듯이 말을 거는 것. 주로 이성적으로 관심이 있거나 더 잘 알고 싶을 때 사용한다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0187","en":"check in","definition":"to register your arrival at a place, such as a hotel or airport","ko":"호텔이나 공항 등 장소에 도착해 등록하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0188","en":"check into","definition":"to look at, research, or find out information about something or someone, to make sure it's true or correct.","ko":"무엇이나 누구에 대해 조사하거나 정보를 얻어 사실인지, 정확한지 확인하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0189","en":"check off","definition":"To mark an item or person on a list to show that it has been dealt with or completed. Synonym: 'tick off'","ko":"항목이나 사람을 목록에서 표시하여 완료 또는 처리했음을 나타내다. 동의어: '체크하다', '표시하다'.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0190","en":"check out","definition":"to pay for your items at a store and finish your shopping; it can also mean to look at or examine something.","ko":"호텔에서 머무른 후 요금을 지불하고 떠나다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0191","en":"check up on","definition":"To look at or find out information about someone or something to make sure everything is okay or correct.","ko":"누군가나 무언가가 괜찮은지, 올바른지 확인하기 위해 정보를 찾아보다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0192","en":"cheer up","definition":"to help someone feel happier, especially when they are sad","ko":"특히 슬퍼할 때 누군가를 더 행복하게 도와주다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0193","en":"chew out","definition":"To speak to someone angrily because they did something wrong; to strongly tell someone off.","ko":"누군가에게 잘못한 일로 화내며 심하게 혼내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0194","en":"chew over","definition":"To think carefully about something or discuss it with others before making a decision.","ko":"결정하기 전에 어떤 것에 대해 신중하게 생각하거나 다른 사람들과 논의하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0195","en":"chill out","definition":"To relax, calm down, or stop stressing about something.","ko":"긴장을 풀거나, 진정하거나, 어떤 일에 대한 스트레스를 멈추다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0196","en":"chime in","definition":"To join a conversation by adding your opinion or comments, especially when others are already talking.","ko":"다른 사람들이 이미 이야기하고 있을 때, 의견이나 코멘트를 더해 대화에 끼어들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0197","en":"chip at","definition":"To remove small pieces from something, usually by hitting or cutting, often gradually.","ko":"보통 두드리거나 자르면서 점차적으로 무언가에서 작은 조각을 떼어내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0198","en":"chip in","definition":"to give some money together with other people for a shared purpose, like a present or a group meal.","ko":"여러 사람이 함께 돈을 모아 선물이나 단체 식사 같은 공동의 목적을 위해 내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0199","en":"choke down","definition":"to force yourself to eat or swallow something, even if you really don't like the taste or feel sick","ko":"맛이 없거나 속이 안 좋아도 억지로 먹거나 삼키다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0200","en":"choke up","definition":"to fill something so much that nothing can pass through; to block something completely.","ko":"무언가를 가득 채워 아무것도 통과할 수 없게 하다; 완전히 막다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0201","en":"chop down","definition":"To cut something, usually a tree, so that it falls to the ground, usually using an ax or similar tool.","ko":"보통 도끼나 비슷한 도구로 나무 등을 잘라서 넘어뜨리는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0202","en":"chop off","definition":"to remove something by cutting it with a sharp tool, such as a knife or an axe","ko":"칼이나 도끼 같은 날카로운 도구로 무엇인가를 잘라내어 제거하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0203","en":"chop up","definition":"To cut something into small pieces, usually with a knife or other sharp tool.","ko":"보통 칼이나 다른 날카로운 도구로 어떤 것을 작은 조각으로 자르다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0204","en":"chuck out","definition":"To throw something away because you do not need it anymore, or to make someone leave a place.","ko":"더 이상 필요하지 않아서 무엇인가를 버리거나, 누군가를 장소에서 내쫓는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0205","en":"churn out","definition":"to produce something quickly and in large amounts, often without much care or attention to quality","ko":"품질에 크게 신경 쓰지 않고 무언가를 빠르고 대량으로 생산하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0206","en":"churn up","definition":"to move something in a way that makes it messy or causes a lot of movement, often mixing or disturbing it, especially in water or soil.","ko":"어떤 것을 어지럽히거나 많이 움직여 섞이거나 뒤섞이게 하는 것, 특히 물이나 흙에서.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0207","en":"circle around","definition":"To move or walk in a circle around someone or something.","ko":"누구나 무엇의 주위를 원을 그리며 움직이거나 걷다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0208","en":"clam up","definition":"to suddenly stop talking or refuse to speak, often because you are nervous or do not want to reveal something","ko":"긴장하거나 무언가를 밝히고 싶지 않아서 갑자기 말을 멈추거나 말하기를 거부하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0209","en":"clamp down","definition":"to take strict action to stop something that is wrong or not allowed","ko":"잘못되었거나 허용되지 않은 것을 막기 위해 엄격하게 조치하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0210","en":"clap on","definition":"To put something on quickly and without much care or attention.","ko":"무심코, 빠르게 무언가를 착용하거나 바르다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0211","en":"clean out","definition":"To take or use up all of someone's money or belongings, often suddenly or unexpectedly.","ko":"누군가의 돈이나 소지품을 모두 가져가거나 써버리다. 종종 갑자기 또는 예상치 못하게 발생한다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0212","en":"clean up","definition":"to make yourself or something else look neat, tidy, or more presentable","ko":"특히 사업이나 행사에서 많은 돈을 벌거나 큰 성공을 거두다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0213","en":"clear away","definition":"to remove things from a place, especially to make it tidy or ready for something else","ko":"특히 정리하거나 다른 것을 준비하기 위해 장소에서 물건을 치우다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0214","en":"clear out","definition":"to remove all the things from a place, usually to make it tidy or empty","ko":"원하지 않거나 떠나야 하기 때문에 누군가 또는 무언가를 장소에서 나가게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0215","en":"clear up","definition":"to make something less confusing or easier to understand; to solve a problem or answer a question.","ko":"무언가를 덜 혼란스럽게 하거나 이해하기 쉽게 만들다; 문제를 해결하거나 질문에 답하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0216","en":"climb down","definition":"to move carefully down from a higher place to a lower one, especially by using your hands and feet","ko":"특히 손과 발을 사용하여 높은 곳에서 낮은 곳으로 조심스럽게 내려오다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0217","en":"climb on","definition":"to get up onto something, usually by using your hands and feet, like a vehicle, animal, or structure.","ko":"대개 손과 발을 사용하여 차량, 동물, 구조물 등에 올라타는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0218","en":"climb up","definition":"to move upwards by using your hands and feet, especially on something like a ladder, stairs, wall, or tree.","ko":"사다리, 계단, 벽, 나무와 같은 것 위를 손과 발을 이용해 위로 올라가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0219","en":"clock in","definition":"To officially record the time you arrive at work, usually by using a special machine or computer system.","ko":"대개 특별한 기기나 컴퓨터 시스템을 사용하여 공식적으로 출근 시간을 기록하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0220","en":"clock off","definition":"To officially record the time you finish work, usually by using a machine or a system at your workplace. Similar phrases: 'clock out', 'punch out'.","ko":"직장 내 기기나 시스템을 이용해 퇴근 시간을 공식적으로 기록하다. 비슷한 표현: '퇴근 체크하다', '퇴근 처리하다'.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0221","en":"clock up","definition":"To reach or achieve a large total of something, such as time, distance, or numbers, especially over a period of time.","ko":"특정 기간에 시간, 거리, 숫자 등의 많은 합계를 달성하거나 누적하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0222","en":"clog up","definition":"To block or fill something so much that nothing can move through it easily.","ko":"무언가가 너무 많이 막히거나 가득 차서 쉽게 통과할 수 없게 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0223","en":"close down","definition":"to stop operating a business, shop, or factory, usually permanently.","ko":"대개 영구적으로 사업, 가게, 공장의 운영을 중단하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0224","en":"close in","definition":"To move nearer to someone or something, often to capture or surround them.","ko":"누군가 또는 무언가에게 다가가다. 종종 포위하거나 잡기 위해서.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0225","en":"close off","definition":"To stop yourself from sharing your feelings, or to not let others get close to you emotionally.","ko":"사람들이 들어가거나 사용할 수 없도록 장소의 접근을 막거나 차단하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0226","en":"close out","definition":"to finish or bring something to an end so that no more activity can happen, usually by officially ending it or preventing new additions.","ko":"어떤 일을 공식적으로 끝내거나 더 이상의 추가가 불가능하도록 하여 더 이상 활동이 일어나지 않게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0227","en":"close up","definition":"to make an opening or space shut completely; to seal or block something that was open","ko":"열려 있던 공간이나 틈을 완전히 닫다; 열려 있던 것을 봉하거나 막다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0228","en":"cloud over","definition":"To become covered with clouds, making the sky look darker and blocking the sun.","ko":"구름이 끼어 하늘이 어두워지고 태양이 가려지는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0229","en":"clown around","definition":"to behave in a silly or playful way, often to make others laugh","ko":"다른 사람을 웃기기 위해 바보 같거나 장난스럽게 행동하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0230","en":"clue in","definition":"to give someone the necessary information about something; to let someone know what is happening","ko":"누군가에게 필요한 정보를 제공하다; 무슨 일이 벌어지고 있는지 알려주다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0231","en":"clutter up","definition":"to fill a place with too many things, making it messy and hard to use.","ko":"너무 많은 물건으로 공간을 채워 지저분하고 사용하기 어렵게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0232","en":"collide with","definition":"to hit something or someone by accident while moving, usually causing damage or a crash.","ko":"움직이는 중에 실수로 무언가나 누군가와 부딪혀 일반적으로 손상이나 사고를 유발하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0233","en":"color in","definition":"to fill an outlined shape, drawing, or picture with color using crayons, pencils, or markers","ko":"크레용, 색연필, 마커 등으로 테두리가 그려진 도형, 그림, 그림책에 색을 칠하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0234","en":"comb out","definition":"to carefully remove tangles or unwanted things (like dirt or gum) from hair using a comb.","ko":"빗을 사용하여 머리카락의 엉킴이나 원하지 않는 것들(예: 먼지나 껌 등)을 조심스럽게 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0235","en":"come about","definition":"to happen, especially by chance or as a result of something","ko":"일어나다, 발생하다 (특히 우연히나 어떤 결과로)","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0236","en":"come across","definition":"to find or meet someone or something by chance; to discover something unexpectedly.","ko":"남들에게 어떤 인상을 주거나 그렇게 보이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0237","en":"come after","definition":"To be the next person or thing in a line, order, or position after someone or something else.","ko":"누구나 무엇 다음 줄, 순서 또는 위치에서 다음이 되는 사람이나 사물.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0238","en":"come along","definition":"to improve, progress, or develop in a good way","ko":"대개 동반자로서 누구와 함께 어딘가에 가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0239","en":"come around","definition":"To visit someone's home or a particular place, usually for a short time or for social reasons.","ko":"처음에는 반대하거나 거부했지만 결국 어떤 것에 동의하거나 받아들이게 됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0240","en":"come away","definition":"to go somewhere with someone, especially to spend time together away from your usual place","ko":"누군가와 함께 어딘가로 가다, 특히 평소 장소에서 벗어나 함께 시간을 보내기 위해","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0241","en":"come away (from)","definition":"to separate or break off from something","ko":"무엇에서 분리되거나 떨어져 나가다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0242","en":"come by","definition":"to find or get something, especially by chance.","ko":"짧은 시간 동안, 보통 비공식적으로 어디를 방문하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0243","en":"come down","definition":"to criticize or punish someone very strongly","ko":"더 높은 곳에서 떨어지다, 특히 하늘에서 비나 눈이 내릴 때 사용","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0244","en":"come in","definition":"To achieve a specific place or rank in a race, competition, or event.","ko":"다시 인기를 얻거나 유행하게 되다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0245","en":"come in for","definition":"to receive something unpleasant, such as criticism, blame, or trouble","ko":"비판, 비난 또는 곤란과 같이 불쾌한 것을 받다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0246","en":"come into","definition":"to receive something, usually money or property, unexpectedly or because someone has died, like through inheritance.","ko":"예상치 못하게 또는 누군가 죽은 후(주로 상속을 통해) 돈이나 재산을 받다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0247","en":"come near","definition":"to move close to someone or something; to approach a person, place, or object.","ko":"무엇을 거의 하거나 경험할 뻔하다; 실제로 하지는 않았지만 거의 할 뻔했다는 뜻","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0248","en":"come off","definition":"to become separated or detached from something, usually by accident.","ko":"특정한 방식(특히 성공적으로 또는 의도한 대로)으로 일어나다, 이루어지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0249","en":"come on","definition":"When a machine or a piece of equipment comes on, it starts working or it turns on automatically.","ko":"향상되다, 발전하다, 긍정적으로 진전되다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0250","en":"come out","definition":"To be published, released, or made available to the public.","ko":"최종적으로 특정한 결과나 모습을 가지게 되다; 어떤 식으로 마무리되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0251","en":"come over","definition":"to seem or appear in a particular way to others; the impression you give to people. Synonym: 'come across'.","ko":"다른 사람들에게 특정한 방식으로 보이거나 인상을 주다. 동의어: 'come across'.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0252","en":"come through","definition":"to be received, completed, or to happen successfully, especially after waiting for it or expecting it.","ko":"특히 출입구나 문을 통과해 한쪽에서 다른 쪽으로 들어가거나 지나가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0253","en":"come to","definition":"to wake up or become conscious again after being unconscious.","ko":"의식을 잃었다가 다시 깨어나거나 의식을 되찾다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0254","en":"come up","definition":"to move towards someone or a higher place, or to approach","ko":"태양이나 다른 천체가 떠오른다는 것은 지평선 위로 올라와 눈에 보이는 것을 의미합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0255","en":"come up with","definition":"to think of an idea, plan, answer, or solution; or to manage to get something (like money) when needed","ko":"아이디어, 계획, 답변, 해결책을 생각해내다; 또는 필요할 때 (돈과 같은) 무언가를 마련하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0256","en":"come up to","definition":"to walk towards someone, usually to start a conversation or get their attention","ko":"누군가에게 다가가다, 보통 대화를 시작하거나 주의를 끌기 위함","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0257","en":"come upon","definition":"to find or discover someone or something by chance, without planning to.","ko":"우연히, 계획 없이 누군가나 무언가를 발견하거나 만나게 되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0258","en":"come with","definition":"to be included as a part of something, or to be accompanied by someone or something.","ko":"어떤 것의 일부로 포함되거나, 누군가 또는 무언가와 함께 따라오다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0259","en":"concentrate on","definition":"To give your full attention or effort to a person, task, or thing.","ko":"사람이나 과제, 사물에 모든 주의나 노력을 기울이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0260","en":"condole with","definition":"To show sympathy or express your sadness to someone who has experienced something difficult or sad, usually after a loss.","ko":"슬픈 일이나 힘든 일을 겪은 사람에게 동정심을 보이거나 슬픔을 표현하는 것, 보통 상실 후에 사용함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0261","en":"confer with","definition":"to talk seriously with someone in order to exchange ideas or get advice before making a decision","ko":"결정을 내리기 전에 누군가와 진지하게 이야기하며 아이디어를 교환하거나 조언을 구하는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0262","en":"conform to","definition":"to follow rules, standards, or expectations; to do what is required by laws or customs.","ko":"규칙, 기준 또는 기대를 따르다; 법률이나 관습에 의해 요구되는 것을 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0263","en":"conjure up","definition":"to make something appear as if by magic, or to bring an image, idea, or memory to your mind","ko":"마치 마법처럼 무언가를 나타나게 하거나, 이미지·생각·추억 등을 마음속에 떠올리게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0264","en":"conk out","definition":"to suddenly stop working or to fall asleep quickly because you are very tired","ko":"갑자기 작동을 멈추거나 매우 피곤해서 금방 잠드는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0265","en":"contract in","definition":"to officially agree to take part in something, usually by signing an agreement or contract.","ko":"대개 계약서에 서명함으로써 공식적으로 어떤 일에 참여하기로 동의하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0266","en":"contract out","definition":"To pay another person or company to do a job instead of doing it yourself.","ko":"스스로 하지 않고 다른 사람이나 회사에 돈을 주고 일을 맡기다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0267","en":"cook out","definition":"to prepare and cook food outdoors, especially on a grill or barbecue.","ko":"특히 그릴이나 바비큐에서 음식을 야외에서 준비하고 요리하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0268","en":"cook up","definition":"to invent or create a story, excuse, or plan, often in a clever or dishonest way","ko":"이야기, 변명 또는 계획을 종종 영리하거나 부정직한 방식으로 지어내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0269","en":"cool down","definition":"to become calmer and less angry or upset; to relax after feeling strong emotions.","ko":"더 이상 뜨겁지 않게 되거나 무언가를 덜 뜨겁게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0270","en":"cool off","definition":"to become less interested, less excited, or less passionate about something or someone than before","ko":"이전보다 어떤 것 또는 누군가에 대해 덜 관심을 갖거나, 흥분하거나, 열정적이지 않게 되다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0271","en":"cop out","definition":"To avoid doing something you should do, often because it's difficult or uncomfortable.","ko":"어렵거나 불편하다는 이유로 해야 할 일을 피하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0272","en":"copy out","definition":"to write or type something exactly as it is from another source, like a book, onto a different piece of paper or document.","ko":"책과 같은 다른 자료에서 내용을 정확하게 다른 종이나 문서에 베껴 쓰거나 타이핑하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0273","en":"cotton on","definition":"To finally understand or realize something, especially after being confused at first.","ko":"처음에는 혼란스러웠지만 결국 무언가를 이해하거나 깨닫다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0274","en":"cough up","definition":"to give or hand over something, especially money, usually unwillingly.","ko":"특히 돈을, 마지못해 내놓다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0275","en":"count down","definition":"To say or think numbers in reverse order (for example: 10, 9, 8, 7, ... 1, 0) in order to prepare for something special that will happen at zero.","ko":"특별한 일이 0에 일어날 때 준비하기 위해 숫자를 거꾸로(예: 10, 9, 8, 7, ... 1, 0) 말하거나 생각하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0276","en":"count off","definition":"To say numbers out loud one after another, usually in order, so each person in a group has a different number.","ko":"그룹의 각 사람이 다른 번호를 받을 수 있게, 순서대로 한 명씩 차례로 숫자를 크게 말하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0277","en":"count on","definition":"to trust someone to do something or to depend on someone to help you","ko":"누군가가 무언가를 해줄 것이라고 믿거나, 누군가에게 의지하는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0278","en":"count out","definition":"To decide that someone or something is not included or will not be successful or possible.","ko":"누군가 또는 무언가가 포함되지 않거나 성공하거나 가능하지 않다고 결정하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0279","en":"couple on","definition":"to connect or attach one thing to another, often so they work together","ko":"한 물건을 다른 것에 연결하거나 부착하여 함께 작동하게 함","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0280","en":"couple up","definition":"to start a romantic relationship or become a couple with someone","ko":"누군가와 연애를 시작하거나 커플이 되다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0281","en":"cover for","definition":"to do someone else’s work or take their place, especially to help them avoid trouble or when they are absent","ko":"다른 사람의 일을 대신 하거나, 특히 곤경을 피하게 도와주거나 부재 중일 때 그 자리를 대신함","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0282","en":"cover up","definition":"To hide the truth or try to keep something a secret, especially something wrong or bad.","ko":"진실을 숨기거나, 특히 잘못된 것이나 나쁜 것을 비밀로 하려 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0283","en":"crack down","definition":"to take strong action to stop people from doing something bad or illegal","ko":"사람들이 나쁘거나 불법적인 일을 하지 못하도록 강력한 조치를 취하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0284","en":"crack up","definition":"to suddenly start laughing a lot because something is very funny","ko":"무언가가 매우 웃겨서 갑자기 크게 웃기 시작하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0285","en":"crank out","definition":"To produce something in large amounts, usually quickly and not with much care.","ko":"보통 빠르고 정성 들이지 않고 대량으로 무언가를 만들어내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0286","en":"crank up","definition":"to increase the level, amount, or intensity of something, especially sound, energy, or activity, often with a machine or device","ko":"특히 소리, 에너지, 활동 등을 (기계나 장치를 통해) 수준, 양, 강도를 높이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0287","en":"crawl in","definition":"To get into bed very slowly and quietly, usually because you are tired.","ko":"피곤해서 매우 천천히 조용히 침대에 들어가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0288","en":"creep up","definition":"to slowly and quietly move closer to someone or something, usually to surprise them","ko":"누군가나 무언가에게 천천히 조용히 다가가 보통 깜짝 놀라게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0289","en":"crop up","definition":"to happen or appear suddenly or unexpectedly, especially a problem or issue.","ko":"특히 문제나 이슈가 갑자기 또는 예기치 않게 발생하거나 나타나다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0290","en":"cross off","definition":"To remove someone or something from a list by drawing a line through it, often because it is no longer needed, or the task is done.","ko":"더 이상 필요 없거나 일이 끝났을 때, 이름에 줄을 그어 목록에서 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0291","en":"crowd out","definition":"To prevent someone or something from having enough space or opportunity because there are too many others present.","ko":"다른 이들이 너무 많아서 누군가나 무언가가 충분한 공간이나 기회를 갖지 못하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0292","en":"cry for","definition":"to shout loudly or call out because you want someone or something to help you; to ask for something urgently, often by making a lot of noise or showing strong emotions.","ko":"누군가 또는 무언가에게 도움을 원해서 크게 소리치거나 부르는 것; 강한 감정이나 큰 소리로 급히 무언가를 요구하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0293","en":"cry out for","definition":"If something cries out for something, it really needs or deserves it. It means there is a very strong need for something.","ko":"무언가가 무언가를 '절실하게 필요로 한다'는 것은 그것이 정말로 필요하거나 마땅히 받아야 함을 의미합니다. 매우 강한 필요가 있다는 뜻입니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0294","en":"curl up","definition":"to sit or lie down with your arms and legs close to your body, usually to feel comfortable or warm","ko":"몸을 편안하거나 따뜻하게 하기 위해 팔과 다리를 몸 가까이 모으고 앉거나 눕다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0295","en":"cut across","definition":"to go through an area instead of following the main or usual route, usually to make a journey shorter or faster.","ko":"보통이나 주된 경로 대신 어떤 구역을 가로질러가서, 보통 더 빠르거나 짧은 길을 선택하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0296","en":"cut away","definition":"to remove parts of something by cutting little by little","ko":"조금씩 잘라서 일부를 제거하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0297","en":"cut down","definition":"to use or do less of something, especially something that is not healthy or is expensive.","ko":"도끼나 톱과 같은 도구로 무언가를 잘라서 땅에 쓰러뜨리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0298","en":"cut in","definition":"to suddenly move in front of someone or something, usually in traffic or a line, without waiting your turn","ko":"누군가가 말하는 도중에 갑자기 끼어들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0299","en":"cut off","definition":"to remove a part of something by cutting it with a tool or object","ko":"특히 기계나 서비스가 갑자기 작동을 멈추다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0300","en":"cut out","definition":"to stop the operation of a device or machine by turning it off or disconnecting it","ko":"무언가를 그만두다; 주로 행동을 멈추라고 명령할 때 사용한다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0301","en":"cut through","definition":"To go directly through a place to save time instead of taking a longer way around.","ko":"더 멀리 돌아가지 않고 시간을 아끼려고 어떤 장소를 바로 통과하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0302","en":"cut up","definition":"to divide something into smaller pieces using a knife or another sharp tool.","ko":"칼, 가위 또는 다른 도구를 사용하여 무언가를 더 작은 조각으로 자르다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0303","en":"date from","definition":"to have started to exist at a particular time in the past.","ko":"과거의 특정 시점에 존재하기 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0304","en":"deal out","definition":"to give or distribute something to several people, usually in equal parts or pieces","ko":"무엇인가를 여러 사람에게, 보통 똑같이 나누어 주다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0305","en":"default on","definition":"to fail to pay money that you owe, especially on a loan or debt","ko":"특히 대출이나 빚 같은 돈을 갚지 않다, 채무 불이행하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0306","en":"depend on","definition":"To trust or need someone or something for help, support, or to get something done.","ko":"도움, 지원, 또는 무언가를 해내기 위해 누군가나 무언가를 신뢰하거나 필요로 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0307","en":"die away","definition":"To become gradually quieter or weaker until it stops or disappears.","ko":"점차 조용해지거나 약해지다가 멈추거나 사라지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0308","en":"die out","definition":"to disappear completely, usually because something is no longer used or living things no longer exist","ko":"무엇인가가 더 이상 사용되지 않거나 생명체가 더 이상 존재하지 않아 완전히 사라지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0309","en":"dig in","definition":"to start eating food eagerly or with enthusiasm.","ko":"음식을 열정적으로 또는 신나게 먹기 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0310","en":"dig into","definition":"to start to do something with energy or enthusiasm, or to start eating food eagerly; it can also mean to search carefully through something.","ko":"열정이나 에너지를 가지고 무언가를 시작하다, 음식을 열심히 먹기 시작하다; 혹은 어떤 것을 꼼꼼히 뒤지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0311","en":"dig out","definition":"To find something that has been hidden, stored, or forgotten, usually after searching for it.","ko":"숨겨지거나 보관되었거나 잊혔던 것을, 보통 찾아본 후에 발견하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0312","en":"dig up","definition":"to remove something from the ground by digging, or to discover hidden information, objects, or facts","ko":"무언가를 땅에서 파내거나, 숨겨진 정보·물건·사실을 발견하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0313","en":"dine out","definition":"to eat a meal in a restaurant instead of at home.","ko":"집이 아닌 식당에서 식사하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0314","en":"disagree with","definition":"If food or drink disagrees with you, it makes you feel sick or gives you an upset stomach.","ko":"음식이나 음료가 몸에 맞지 않으면 속이 불편하거나 탈이 날 수 있습니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0315","en":"dish out","definition":"To give or spread something, like information, ideas, or comments, to many people—often quickly or without much thought.","ko":"음식을 사람들에게 나눠주다, 보통 접시에 담아 주는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0316","en":"do away with","definition":"to remove or stop using something, usually because it is no longer needed or wanted","ko":"더 이상 필요 없거나 원하지 않아서 어떤 것을 없애거나 사용을 중지하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0317","en":"do up","definition":"to decorate, repair, or fasten something, or to make something look nicer or newer","ko":"무언가를 장식하거나, 수리하거나, 잠그거나, 더 예쁘거나 새롭게 보이게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0318","en":"dope up","definition":"to give drugs, especially strong or illegal drugs, to a person or an animal, usually to affect how they feel or act.","ko":"특히 강하거나 불법적인 약물을 사람이나 동물에게 주어 감정이나 행동에 영향을 미치게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0319","en":"double over","definition":"To suddenly bend your body forward at the waist, often because you are laughing very hard or feeling a lot of pain.","ko":"아주 심하게 웃거나 많은 고통을 느껴 갑자기 허리에서 몸을 앞으로 굽히는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0320","en":"double up","definition":"To use something in twice the amount, or to do something twice as much, often as a way to increase your chances or results. In gambling, it means to bet your winnings from a previous bet.","ko":"방, 좌석, 자원 등을 다른 사람과 (특히 모두에게 충분하지 않을 때) 함께 사용하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0321","en":"doze off","definition":"to fall asleep, especially for a short time or without planning to","ko":"특히 잠깐이거나 계획하지 않게 잠들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0322","en":"drag down","definition":"to make someone or something less successful, happy, or effective, often by causing problems or bringing them to a lower level.","ko":"문제를 일으키거나 하락시키면서 누군가나 무언가를 덜 성공적이거나 행복하거나 효과적으로 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0323","en":"drag in","definition":"To involve someone in a situation or discussion, often when they do not want to be part of it.","ko":"누군가를 상황이나 토론에, 종종 원하지 않을 때 끌어들이는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0324","en":"drag on","definition":"If something drags on, it continues for a long time and feels like it will never end.","ko":"무엇인가가 계속되면 아주 오랫동안 지속되어 끝나지 않을 것 같은 느낌이 듭니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0325","en":"drag out","definition":"If something drags out, it continues for much longer than expected, often making people feel bored or impatient.","ko":"무언가가 예상보다 훨씬 오래 계속되어 사람들이 지루하거나 조급해지는 경우를 말합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0326","en":"drag up","definition":"To mention or talk about something from the past, especially something that is better left forgotten or that causes discomfort.","ko":"과거의 일을 언급하거나 이야기하다, 특히 잊는 것이 낫거나 불편함을 주는 일에 대해.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0327","en":"draw away","definition":"To move back or distance yourself from someone or something.","ko":"누구나 무엇으로부터 물러나거나 거리를 두다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0328","en":"draw in","definition":"to pull something, such as your breath or a body part, inward or closer to your body.","ko":"누군가나 무언가를 가까이 오거나 참여하도록 유인하거나 초대하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0329","en":"draw near","definition":"to get closer in distance or time to someone or something","ko":"누구/무엇에 거리나 시간이 가까워지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0330","en":"draw out","definition":"to gently make someone say something that they might not want to share, such as information, feelings, or ideas.","ko":"필요하거나 예상했던 것보다 더 오래 지속되게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0331","en":"draw up","definition":"to prepare and write an official document, such as a contract or a list","ko":"더 자신감 있게 보이거나 존경을 나타내기 위해 똑바로 서거나 앉다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0332","en":"dream up","definition":"To think of a new idea or plan, especially something unusual or creative.","ko":"특히 독특하거나 창의적인 새로운 아이디어나 계획을 생각해내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0333","en":"dredge up","definition":"to talk about or remember something unpleasant or embarrassing from the past, especially when others would prefer to forget it.","ko":"다른 사람들이 잊고 싶어하는 과거의 불쾌하거나 당황스러운 일을 언급하거나 기억하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0334","en":"dress down","definition":"to wear more casual or informal clothes than usual, especially in a place where more formal clothes are normally expected","ko":"보통보다 더 캐주얼하거나 비공식적인 옷을 입는 것, 특히 일반적으로 더 격식 있는 옷이 기대되는 곳에서","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0335","en":"dress up","definition":"to put on special or formal clothes, or to wear a costume to look like someone or something else","ko":"특별하거나 정장의 옷을 입거나 다른 사람이나 무언가처럼 보이기 위해 의상을 입다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0336","en":"drift away","definition":"To slowly become less close to someone, usually because you spend less time together or have less in common.","ko":"보통 함께 보내는 시간이 줄거나 공통점이 줄어들어 누군가와 점점 멀어지는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0337","en":"drift off","definition":"to slowly fall asleep without realizing it","ko":"자기도 모르게 천천히 잠이 들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0338","en":"drill in","definition":"To teach someone something by repeating it many times until they remember it.","ko":"누군가에게 어떤 것을 여러 번 반복해서 기억하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0339","en":"drink down","definition":"To swallow a drink completely, often in one go.","ko":"음료를 한 번에 완전히 마시다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0340","en":"drink in","definition":"To look at or experience something with great enjoyment, paying close attention to it.","ko":"어떤 것을 큰 즐거움으로 바라보거나 경험하며, 세심하게 감상하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0341","en":"drink up","definition":"To finish all of your drink. If you drink up, you drink the entire glass or cup until it is empty.","ko":"음료를 모두 마시다. drink up은 컵이나 잔의 음료를 완전히 다 마시는 것을 뜻함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0342","en":"drive around","definition":"to travel by car with no specific destination, just exploring or passing time","ko":"특정 목적지 없이 그냥 자동차로 이곳저곳 돌아다님, 탐험하거나 시간 보내기 위해","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0343","en":"drive away","definition":"to make someone or something leave, usually because you do not want them nearby","ko":"보통 가까이에 두고 싶지 않아 누군가나 무언가를 내쫓다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0344","en":"drive off","definition":"to leave a place by driving away in a car or another vehicle.","ko":"자동차나 다른 탈것을 타고 장소를 떠나다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0345","en":"drive out","definition":"To make someone or something leave a place by force or strong pressure.","ko":"누군가 또는 무언가를 힘이나 강한 압력으로 어떤 장소에서 내쫓다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0346","en":"drive up","definition":"to arrive at a place while driving a car or another vehicle","ko":"자동차나 다른 차량을 운전해서 어떤 장소에 도착하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0347","en":"drone on","definition":"to talk for a long time in a dull, monotonous, and boring way","ko":"오래도록 단조롭고 지루하게 이야기하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0348","en":"drool over","definition":"To look at something or someone with great desire or admiration, often wanting it very much.","ko":"무엇이나 누구를 매우 원하거나 동경의 눈으로 바라보다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0349","en":"drop away","definition":"to gradually become fewer or smaller in number or amount","ko":"점차 수나 양이 줄어들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0350","en":"drop behind","definition":"to move more slowly than others in a group and end up at the back.","ko":"그룹에서 다른 사람들보다 더 천천히 움직여 뒤에 남게 되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0351","en":"drop by","definition":"to visit someone or a place for a short time without making a plan in advance; to come and see someone casually.","ko":"미리 약속하지 않고 잠깐 누군가를 방문하다; 가볍게 들르다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0352","en":"drop down","definition":"To move or fall from a higher position to a lower position.","ko":"더 높은 위치에서 더 낮은 위치로 이동하거나 떨어지는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0353","en":"drop off","definition":"to become less in amount, level, or number; to decrease or decline","ko":"양, 수준, 수가 줄어들다; 감소하다, 하락하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0354","en":"drop out","definition":"To leave school, a course, or an activity before you have finished it.","ko":"학교, 과정 또는 활동을 끝내기 전에 그만두다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0355","en":"drown out","definition":"To make so much noise that another sound cannot be heard.","ko":"다른 소리가 들리지 않을 정도로 큰 소음을 내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0356","en":"drum out","definition":"To force someone to leave an organization or group, especially in a public way, usually because they did something wrong.","ko":"특히 공개적으로, 주로 잘못된 행동 때문에 누군가를 조직이나 그룹에서 내쫓다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0357","en":"drum up","definition":"To try to get more support, customers, or interest for something by making people aware of it.","ko":"사람들에게 알림으로써 더 많은 지지, 고객 또는 관심을 얻으려고 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0358","en":"dry out","definition":"to remove moisture from something, making it completely dry.","ko":"무언가에서 수분을 제거하여 완전히 마르게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0359","en":"dwindle away","definition":"To gradually become smaller, fewer, or weaker until it almost disappears.","ko":"점차 작아지거나, 적어지거나, 약해져서 거의 사라지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0360","en":"ease off","definition":"To stop putting so much pressure or stress on someone or something; to become less strict or demanding.","ko":"누군가나 무언가에 너무 많은 압박이나 스트레스를 주는 것을 멈추다; 덜 엄격하거나 요구가 줄어들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0361","en":"eat at","definition":"to bother or worry someone for a long time, or to slowly damage something over time","ko":"오랫동안 누군가를 괴롭히거나 걱정하게 하거나, 시간이 지나면서 천천히 무언가를 손상시키다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0362","en":"eat away","definition":"To slowly destroy or damage something, especially by a chemical process or over time.","ko":"화학 작용이나 시간이 지나면서 천천히 무언가를 파괴하거나 손상시키다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0363","en":"eat in","definition":"to have a meal at home instead of going to a restaurant or cafe","ko":"식당이나 카페에 가지 않고 집에서 식사하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0364","en":"eat out","definition":"to have a meal at a restaurant or café instead of at home","ko":"집이 아닌 식당이나 카페에서 식사하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0365","en":"eat up","definition":"to finish all the food on your plate; to eat everything that is given to you","ko":"특히 돈, 자원, 시간 등을 매우 빠르게 사용하거나 소비하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0366","en":"ebb away","definition":"to slowly decrease, disappear, or become weaker over time.","ko":"시간이 지나면서 서서히 줄어들거나, 사라지거나, 약해지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0367","en":"edge in","definition":"to move into a place or position slowly and carefully, often when it is crowded or difficult to enter","ko":"혼잡하거나 들어가기 힘든 곳에 천천히 조심스럽게 이동하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0368","en":"egg on","definition":"to strongly encourage someone to do something, especially something risky or unwise","ko":"특히 위험하거나 현명하지 않은 행동을 하게 강하게 부추기다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0369","en":"embark on","definition":"To start something new, especially something important or exciting, like a project or journey.","ko":"특히 중요한 일이나 흥미로운 새로운 일(프로젝트나 여행 등)을 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0370","en":"end up","definition":"to finally do something after a series of actions or events, often without planning it.","ko":"여러 행동이나 사건 끝에, 종종 계획하지 않았던 무언가를 결국 하게 되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0371","en":"even out","definition":"to make the surface of something smooth, flat, or equal by removing bumps or differences","ko":"울퉁불퉁하거나 차이점을 제거하여 어떤 것의 표면을 매끄럽고 평평하거나 동일하게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0372","en":"even up","definition":"to make something flat, straight, or the same height, especially by removing uneven parts. Similar to 'even out'.","ko":"특히 울퉁불퉁한 부분을 제거하여 평평하거나 곧게 또는 같은 높이가 되게 만들다. 'even out'과 유사하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0373","en":"excel at","definition":"to be very good or skilled at something, much better than most people","ko":"무엇인가를 매우 잘하거나 능숙하여 대부분의 사람들보다 훨씬 뛰어남","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0374","en":"extend to","definition":"to make something longer or bigger so that it reaches something else; to stretch something out toward something.","ko":"무언가를 더 길거나 크게 만들어서 다른 것에 닿게 하는 것; 무언가를 다른 것 쪽으로 뻗는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0375","en":"face up","definition":"to accept and deal with a difficult situation or problem bravely, instead of avoiding it.","ko":"어려운 상황이나 문제를 피하지 않고 용감하게 받아들이고 대처하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0376","en":"factor in","definition":"To include or take something into account when you are making a decision or planning something.","ko":"결정이나 계획을 할 때 어떤 것을 포함하거나 고려하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0377","en":"fade away","definition":"to slowly disappear or become less noticeable until it is gone.","ko":"서서히 사라지거나 덜 눈에 띄게 되어 없어지는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0378","en":"fall away","definition":"To gradually come off, become separated, or disappear.","ko":"점차 떨어지거나, 분리되거나, 사라지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0379","en":"fall behind","definition":"To not keep up with others or with a schedule; to not do or pay something on time.","ko":"다른 사람이나 일정에 뒤쳐지다; 무언가를 제때 하지 않거나 지불하지 않다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0380","en":"fall down","definition":"to accidentally drop to the ground from standing or walking, usually by losing your balance.","ko":"서 있거나 걷다가 보통 균형을 잃어 우연히 땅에 넘어지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0381","en":"fall for","definition":"To easily believe something that is not true; to be tricked or deceived by something.","ko":"누구에게 사랑에 빠지거나 강한 로맨틱한 감정을 갖기 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0382","en":"fall in","definition":"to start spending time with a particular group of people, often by chance","ko":"특정 사람들과 (우연히) 어울리기 시작하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0383","en":"fall into","definition":"to belong to or be included in a particular group, type, or category.","ko":"특정 그룹, 유형 또는 범주에 속하거나 포함되는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0384","en":"fall off","definition":"to decrease, become less, or decline","ko":"감소하다, 줄어들다, 하락하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0385","en":"fall out","definition":"to have an argument or disagreement and stop being friendly with someone.","ko":"누군가와 의견 충돌이나 다툼으로 사이가 멀어지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0386","en":"fall over","definition":"to suddenly lose balance and go down to the ground","ko":"갑자기 균형을 잃고 넘어지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0387","en":"fall through","definition":"If something falls through, it means a plan or arrangement does not happen or fails at the last moment.","ko":"무언가가 무산된다는 것은 계획이나 약속이 마지막 순간에 이루어지지 않거나 실패한다는 것을 의미합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0388","en":"fall under","definition":"To be included in a particular group, type, or category.","ko":"특정 그룹, 유형 또는 범주에 포함되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0389","en":"fan out","definition":"To spread out from a central point like the shape of a fan.","ko":"중심점에서 부채처럼 펼쳐지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0390","en":"farm out","definition":"To give a task or job to another person or company to do, instead of doing it yourself.","ko":"직접 하지 않고, 다른 사람이나 회사에 작업이나 임무를 맡기다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0391","en":"fatten up","definition":"to feed someone or an animal more food so they become fatter, usually for a specific reason.","ko":"누구나 동물을 더 많이 먹여 더 뚱뚱해지게 하다. 보통 특별한 목적을 위해.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0392","en":"feed in","definition":"To regularly put or add something into a system, machine, or process.","ko":"무엇인가를 정기적으로 시스템, 기계, 과정에 넣거나 추가하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0393","en":"feed on","definition":"to eat or get nourishment from someone or something, usually used when talking about animals and what they eat regularly.","ko":"주로 동물과 그들이 정기적으로 먹는 음식에 대해 말할 때, 누군가 또는 무언가로부터 먹거나 영양을 얻는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0394","en":"feel for","definition":"to understand and share someone’s feelings, especially when they are having a difficult time; to show sympathy or empathy for someone","ko":"누군가가 힘든 시간을 보낼 때 그 감정을 이해하고 공감하다; 누군가에게 동정이나 공감을 보이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0395","en":"feel like","definition":"to want to do something or be in the mood for something","ko":"무언가를 하고 싶거나 그런 기분이 들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0396","en":"feel out","definition":"To carefully ask questions or talk to someone to understand their opinion or attitude about something, usually before making a decision.","ko":"보통 결정을 내리기 전에 어떤 것에 대한 누군가의 의견이나 태도를 이해하기 위해 조심스럽게 질문하거나 말을 건네다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0397","en":"fence in","definition":"To surround someone or something with a fence or barrier, so they are inside and cannot get out easily. It can also mean to make someone feel restricted.","ko":"누군가나 무언가를 울타리나 장벽으로 둘러싸서 그 안에 있게 하고 쉽게 나갈 수 없게 하는 것. 또한 누군가를 제한된 느낌이 들게 하기도 함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0398","en":"fend for","definition":"to take care of yourself without help from others","ko":"다른 사람의 도움 없이 스스로 돌보다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0399","en":"fend off","definition":"To stop someone or something from harming or attacking you; to defend yourself against someone or something.","ko":"누군가 또는 무언가가 해치거나 공격하는 것을 막다; 누군가 또는 무언가에게서 자신을 방어하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0400","en":"fiddle with","definition":"to touch, move, or play with something, often because you are bored or nervous, usually without any real purpose.","ko":"지루하거나 긴장해서 주로 특별한 목적 없이 무엇인가를 만지거나, 움직이거나, 갖고 노는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0401","en":"fight down","definition":"To control or stop a strong feeling or reaction, especially something difficult like emotions or urges.","ko":"강한 감정이나 반응, 특히 감정이나 충동 같은 어려운 것을 억누르거나 제어하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0402","en":"fight off","definition":"To try hard to stop or get rid of something that is attacking or bothering you.","ko":"당신을 공격하거나 괴롭히는 무언가를 막거나 없애기 위해 열심히 애쓰다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0403","en":"figure out","definition":"to find the answer to something or understand how something works","ko":"무언가의 답을 찾거나 어떻게 작동하는지 이해하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0404","en":"file away","definition":"to put documents or papers in a specific place, especially in a folder or cabinet, so you can find them later.","ko":"문서나 서류를 나중에 찾을 수 있도록 특정한 장소(특히 폴더, 캐비닛)에 보관하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0405","en":"fill in","definition":"to give someone all the necessary information or details about something they missed or don’t know about","ko":"다른 사람이 없을 때 그 사람의 업무나 자리를 잠시 대신하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0406","en":"fill out","definition":"to complete a form or document by adding information; to write the necessary information in the spaces on a form.","ko":"차차 체중이 늘고 좀 더 무거워지며, 종종 더 건강하거나 둥글게 보이는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0407","en":"fill up","definition":"To eat a lot of something so that you feel full and don't want to eat anything more.","ko":"특히 액체나 다른 물질로 무언가를 가득 채우거나 완전히 차게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0408","en":"film over","definition":"to become covered with a thin layer, often making something less clear or difficult to see through","ko":"얇은 막으로 덮여 뭔가 덜 분명하거나 투명하게 보기 어려워지는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0409","en":"filter out","definition":"To remove something unwanted from a substance, group, or information by using a filter or a similar method.","ko":"필터나 유사한 방법을 사용하여 원하지 않는 것을 물질, 집단 또는 정보에서 제거하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0410","en":"find out","definition":"to discover or learn something, usually by looking for information or by being told","ko":"무언가를 발견하거나 알게 되다, 보통 정보를 찾아보거나 누가 알려줬을 때","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0411","en":"finish off","definition":"to complete something that you have been doing, especially the last part of it","ko":"특히 마지막 부분을 포함하여 하던 일을 완성하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0412","en":"finish up","definition":"to arrive or be in a place at the end, often by accident or without planning. It is similar to 'end up.'","ko":"종종 우연히 또는 계획 없이, 결국 어떤 장소에 도착하거나 있게 되다. 'end up'과 유사함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0413","en":"fire up","definition":"To make someone feel excited, enthusiastic, or motivated.","ko":"누군가를 흥분시키거나, 열정적이거나, 동기를 부여하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0414","en":"firm up","definition":"To make something stronger, more solid, or more certain.","ko":"무언가를 더 강하거나, 단단하게 또는 확실하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0415","en":"fit in","definition":"to be suitable for or to match well with something","ko":"무엇인가에 알맞거나 잘 어울리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0416","en":"fit out","definition":"To supply a person or thing with the equipment, clothing, or furniture they need for a specific purpose.","ko":"특정 목적을 위해 사람이나 사물에 필요한 장비, 옷, 가구 등을 공급하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0417","en":"fizzle out","definition":"to slowly end, lose energy, or stop being interesting or effective.","ko":"천천히 끝나거나, 힘을 잃거나, 더 이상 흥미롭거나 효과적이지 않게 되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0418","en":"flag down","definition":"to wave your hand or use a signal to get the attention of a driver or vehicle and make them stop","ko":"손을 흔들거나 신호를 보내 운전자나 차량의 주의를 끌어 세우게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0419","en":"flake off","definition":"to come off or break away from a surface in small, thin pieces","ko":"표면에서 작은 얇은 조각으로 떨어져 나오다, 벗겨지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0420","en":"flame up","definition":"to suddenly start burning more strongly or catch fire.","ko":"갑자기 더 세게 타오르거나 불이 붙다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0421","en":"flare out","definition":"When something flares out, it becomes wider or spreads outward, often at the bottom. You can also use it to describe making something wider at the edges.","ko":"무언가가 더 넓어지거나 바깥쪽으로 퍼지는 것(종종 아래쪽에서). 끝부분을 더 넓게 만드는 것도 의미할 수 있습니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0422","en":"flare up","definition":"If something flares up, it suddenly becomes worse or more intense, especially something negative like an illness, pain, or a conflict.","ko":"무엇인가가 (특히 질병, 통증, 갈등 등 부정적인 것이) 갑자기 악화되거나 심해지는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0423","en":"flatten out","definition":"to make something completely flat or smooth","ko":"무엇인가를 완전히 평평하거나 매끄럽게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0424","en":"flip out","definition":"to suddenly become very angry, upset, or excited, often in a way that is hard to control","ko":"갑자기 매우 화를 내거나, 흥분하거나, 당황해서 통제하기 어려운 상태가 되다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0425","en":"flirt with","definition":"to think about doing something, but without being very serious about it","ko":"진지하지 않게 어떤 일을 할까 생각해보다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0426","en":"flood in","definition":"to arrive or enter in large numbers, quickly and all at once","ko":"많은 수가 빠르게 한꺼번에 도착하거나 들어오다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0427","en":"flow away","definition":"to move away or be carried away, usually by water or another liquid leaving a place.","ko":"주로 물이나 액체에 의해 어떤 장소에서 멀리 이동하거나 흘러가 버리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0428","en":"flow from","definition":"to move or come out of something in a steady stream, like a liquid or gas.","ko":"액체나 기체처럼 무언가에서 일정하게 흘러나오거나 움직이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0429","en":"fluff up","definition":"To shake or arrange something soft, like a pillow or cushion, so it looks bigger and feels softer.","ko":"베개나 쿠션처럼 부드러운 것을 흔들거나 정리해서 더 커 보이고 더 부드럽게 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0430","en":"flush down","definition":"To use a large amount of water to move something away, usually down a pipe or drain.","ko":"대량의 물을 사용해 무언가를 (대개 파이프나 배수구로) 흘려 보내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0431","en":"fly by","definition":"To describe time passing very quickly, especially when you are busy or enjoying yourself.","ko":"특히 바쁘거나 즐거울 때 시간이 매우 빨리 지나가는 것을 나타냄.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0432","en":"fly on","definition":"to keep flying or moving forward in the air, often without stopping or changing direction.","ko":"멈추거나 방향을 바꾸지 않고 계속 공중에서 날아가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0433","en":"fob off","definition":"To make someone accept something or someone that you do not want, often by tricking them or being dishonest.","ko":"원하지 않는 것 또는 사람을 속이거나 부정직하게 다른 사람에게 떠맡기다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0434","en":"focus on","definition":"To give your full attention to a person or thing.","ko":"사람이나 사물에 온전히 주의를 기울이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0435","en":"fog up","definition":"to become or make something covered with small drops of water, making it hard to see through","ko":"작은 물방울로 덮여서 잘 보이지 않게 되다 또는 그렇게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0436","en":"foist off","definition":"to give or sell something unwanted or fake to someone by pretending it is valuable or genuine","ko":"가치 있거나 진짜인 척 하며 원하지 않거나 가짜인 물건을 남에게 넘기거나 파는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0437","en":"fold up","definition":"to close or stop a business or activity, often because it is not successful.","ko":"무언가를 여러 번 접어서 더 작고 단정한 형태로 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0438","en":"follow out","definition":"to go outside right after someone or something leaves a place","ko":"누군가 또는 무언가가 장소를 떠난 직후 따라 밖으로 나가다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0439","en":"follow through","definition":"to finish something that you have started and make sure to do all the steps needed.","ko":"시작한 일을 끝까지 마무리하고 모든 필요한 단계를 확실히 수행하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0440","en":"follow up on","definition":"to check, get more information, or take further action about something or someone after an initial contact or event","ko":"처음 연락이나 사건 후에 어떤 사람이나 일에 대해 추가 확인하거나 정보를 얻거나 후속 조치를 취하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0441","en":"fool around","definition":"to spend time doing silly or unimportant things instead of being serious or working","ko":"파트너가 아닌 사람과 연애 또는 성적인 관계를 갖다; 관계에서 바람피우다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0442","en":"force out","definition":"To make someone leave their job, position, or organization when they don't want to.","ko":"누군가가 원하지 않더라도 말하게 하거나 행동하게 하다; 애써서 무언가를 내보내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0443","en":"fork out","definition":"to pay money for something, usually when you do not want to or think it's too much","ko":"싫거나 너무 많다고 생각하면서 돈을 내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0444","en":"foul up","definition":"To make a mistake or do something incorrectly, causing a problem.","ko":"실수를 하거나 무언가를 잘못해서 문제를 일으키다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0445","en":"freak out","definition":"To become very scared, angry, or excited about something. It often means to react very strongly or emotionally, sometimes in a way that is hard to control.","ko":"무언가에 대해 매우 두려워하거나, 화를 내거나, 흥분하다. 종종 매우 강하게 또는 감정적으로, 때로는 통제하기 어려울 정도로 반응하는 것을 의미한다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0446","en":"freshen up","definition":"to make someone or something look or feel cleaner, newer, or more presentable.","ko":"누구나 무엇인가를 더 깨끗하고, 새롭고, 보기 좋게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0447","en":"frighten away","definition":"To make someone or something go away because they are scared or afraid.","ko":"누군가나 무언가가 무서워서 떠나게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0448","en":"fritter away","definition":"to waste time, money, or resources on unimportant things instead of using them carefully.","ko":"중요하지 않은 것에 시간, 돈, 자원을 낭비하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0449","en":"frost over","definition":"to become covered with a thin layer of frost or ice, usually because of cold weather.","ko":"추운 날씨로 인해 얇은 서리나 얼음으로 덮이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0450","en":"frown (up) on","definition":"to disapprove of something or someone; to think that something is wrong or not acceptable.","ko":"무엇이나 누구를 못마땅하게 여기다; 무언가가 잘못됐거나 받아들일 수 없다고 생각하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0451","en":"gang up","definition":"To join together as a group to criticize, attack, or oppose someone.","ko":"누군가를 비난하거나 공격하거나 반대하기 위해 무리 지어 행동하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0452","en":"gas up","definition":"to fill a vehicle's tank with gasoline (petrol)","ko":"차량의 연료 탱크에 휘발유를 넣다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0453","en":"gather up","definition":"To collect or pick up different things and bring them together into one place.","ko":"여러 가지를 모아서 한 곳에 모으다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0454","en":"gear up","definition":"to get ready or prepare for something that is going to happen, or to help someone or something get ready.","ko":"다가올 일에 대비하거나, 누군가 또는 무언가를 준비시키다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0455","en":"get about","definition":"to move from place to place, especially by walking or traveling.","ko":"특히 걷거나 여행하여 여기저기 이동하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0456","en":"get across","definition":"To explain something clearly so that other people understand it.","ko":"다른 사람들이 이해할 수 있도록 명확하게 설명하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0457","en":"get along","definition":"To have a good and friendly relationship with someone.","ko":"누군가와 좋은 친근한 관계를 가지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0458","en":"get around","definition":"When news or information gets around, it means that many people hear about it and it spreads quickly.","ko":"규칙, 문제 또는 어떤 일을 막는 사람을 피하거나 극복하는 방법을 찾다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0459","en":"get around to","definition":"to finally do something that you have been intending to do but have been too busy or have delayed","ko":"바쁘거나 미루고 있었던 일을 드디어 하게 되다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0460","en":"get at","definition":"to reach or access someone or something, especially with effort","ko":"누군가를 반복적으로 비난하거나 귀찮게 하다, 주로 짜증나게","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0461","en":"get away","definition":"to leave a place or situation to take a short break or vacation, especially to relax or escape stress","ko":"누군가 또는 무언가로부터 도망치거나, 머물고 싶지 않은 곳에서 떠나는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0462","en":"get away with","definition":"to do something wrong or illegal and not be caught or punished for it","ko":"잘못된 일이나 불법적인 일을 하고도 잡히거나 처벌받지 않다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0463","en":"get down","definition":"to move from a higher place to a lower one, usually by climbing or stepping down from something.","ko":"몸을 낮추거나 특히 네 발로 기어가거나 더 낮은 자세로 이동하여 보거나 손이 닿게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0464","en":"get in","definition":"to be accepted or allowed to join a group, organization, or place, such as a school, club, or event.","ko":"장소, 건물, 차량 또는 구역에 들어가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0465","en":"get into","definition":"to be accepted as a member of a school, college, university, or program","ko":"옷을 입다; 어떤 것을 입다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0466","en":"get off","definition":"to feel excited or experience a strong feeling, often from using drugs or something thrilling","ko":"편지나 소포를 (보통 우편으로) 보내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0467","en":"get on","definition":"to describe time moving forward or passing, especially faster than expected.","ko":"버스, 기차, 비행기와 같은 탈것을 타다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0468","en":"get onto","definition":"to finally understand or realize something, especially after some time or effort.","ko":"특히 어느 정도 시간이나 노력을 들인 후에 무엇을 결국 이해하거나 깨닫다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0469","en":"get out","definition":"to avoid doing something you do not want to do, or to escape from an unpleasant duty or situation.","ko":"특히 비밀이어야 할 일이 대중에게 알려지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0470","en":"get over","definition":"to recover from something difficult, such as an illness, disappointment, or emotional pain","ko":"질병, 실망, 감정적 아픔 등 어려운 일을 극복하거나 회복하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0471","en":"get over with","definition":"to finish something unpleasant as soon as possible so you don't have to worry about it anymore.","ko":"불쾌한 일을 더 이상 걱정하지 않도록 최대한 빨리 끝내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0472","en":"get through","definition":"to finish or successfully complete something, especially something difficult or time-consuming","ko":"특히 전화나 다른 소통 수단을 통해 누군가와 연락이 닿다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0473","en":"get to","definition":"to make someone upset, annoyed, or bothered","ko":"누군가를 속상하게 하거나 짜증나게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0474","en":"get up","definition":"to move from lying down or sitting to a standing position","ko":"행사나 활동과 같은 무언가를 준비하거나 조직하는 것. 필요한 사람이나 재료를 모아서 하는 경우가 많음.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0475","en":"give away","definition":"To give something to someone without asking for money; to make a gift of something.","ko":"비밀이어야 할 것을 알리다; 고의로 또는 실수로 무언가를 공개하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0476","en":"give in","definition":"When something gives in, it collapses, breaks, or stops working because it cannot handle any more pressure or force.","ko":"저항을 멈추고 결국 다른 사람이 원하는 것을 하기로 동의하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0477","en":"give off","definition":"To produce or release something such as a smell, light, heat, or feeling.","ko":"냄새, 빛, 열, 느낌 등을 내뿜거나 방출하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0478","en":"give out","definition":"to give something to each person in a group; to distribute.","ko":"남은 것이 없어서 다 써버리거나 작동을 멈추다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0479","en":"give up","definition":"to stop owning, doing, or keeping something; to let go of something you have","ko":"너무 어렵거나 성공하지 못할 것 같아서 무엇인가를 시도하는 것을 멈추는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0480","en":"glance over","definition":"to look at something quickly, especially to get a general idea of what it is about","ko":"특히 내용을 대략적으로 파악하기 위해 무언가를 빠르게 훑어보다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0481","en":"glaze over","definition":"If someone's eyes glaze over, they suddenly look bored or not interested, usually because they are tired or not paying attention.","ko":"누군가의 눈이 멍해진다면, 그들은 갑자기 지루해 보이거나 관심이 없어 보이며, 보통 피곤하거나 집중하지 않을 때 그렇다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0482","en":"glide by","definition":"To move smoothly, quietly, and effortlessly past someone or something.","ko":"누군가 또는 무언가 곁을 부드럽고 조용하며 수월하게 지나가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0483","en":"gloss over","definition":"to avoid talking about the details of something or to make something seem less important or serious than it really is","ko":"어떤 것의 세부사항을 말하는 것을 피하거나 실제보다 덜 중요하거나 심각하게 보이도록 하는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0484","en":"gnaw at","definition":"To keep biting or chewing something repeatedly, or to make someone feel worried or anxious for a long time.","ko":"무언가를 반복적으로 갉거나 물어뜯다, 또는 오랫동안 누군가를 걱정하거나 불안하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0485","en":"go about","definition":"to start or continue doing something, especially in a particular way or method","ko":"특정한 방식이나 방법으로 무언가를 시작하거나 계속하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0486","en":"go after","definition":"to try to catch, follow, or get someone or something","ko":"누군가나 무언가를 잡으려고 시도하다, 따라가다, 얻으려고 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0487","en":"go against","definition":"to oppose, disagree with, or act in a way that is not the same as someone or something","ko":"반대하거나, 동의하지 않거나, 누군가 또는 무언가와 다르게 행동하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0488","en":"go along","definition":"to continue or make progress with something over time","ko":"누군가의 의견이나 계획에 자주 반박이나 질문 없이 동의하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0489","en":"go around","definition":"To avoid or bypass someone or something, especially if it is an obstacle or problem.","ko":"사람들 사이에 전해지다; 특히 정보나 뉴스가 널리 퍼지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0490","en":"go away","definition":"to disappear, leave, or stop existing","ko":"사라지다, 없어지다, 존재하지 않게 되다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0491","en":"go by","definition":"to use a particular name or title that people call you","ko":"특정 규칙, 지침, 지시에 따라 행동하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0492","en":"go down","definition":"to be swallowed, eaten, or accepted by someone's stomach, especially when talking about food or medicine.","ko":"양, 수준, 가치가 줄어들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0493","en":"go for","definition":"to choose or prefer someone or something because you like them or it.","ko":"누구나 무엇을 좋아해서 선택하거나 선호하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0494","en":"go into","definition":"to start discussing or explaining something in detail","ko":"특정 직업, 사업, 또는 학문 분야에 종사하기 시작하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0495","en":"go off","definition":"If something electrical or mechanical goes off, it stops working or turns off suddenly.","ko":"특정한 방식으로 일어나다, 특히 성공적으로 또는 계획대로.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0496","en":"go on","definition":"to continue doing something, or to move forward to a place.","ko":"작동을 시작하다; 켜지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0497","en":"go out","definition":"When something such as a light or a fire goes out, it stops shining or burning.","ko":"누군가와 사귀거나 연애 관계를 맺어 주기적으로 함께 시간을 보내는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0498","en":"go over","definition":"to look at something or check it carefully to make sure everything is correct or understood","ko":"모든 것이 올바르거나 이해되었는지 확인하기 위해 무언가를 꼼꼼하게 확인하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0499","en":"go past","definition":"to move by someone or something without stopping; to pass by.","ko":"누구나 무엇을 멈추지 않고 지나가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0500","en":"go through","definition":"to experience or deal with something, especially something difficult or unpleasant","ko":"무엇인가를 처음부터 끝까지 꼼꼼하게 살펴보거나 확인하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0501","en":"go to","definition":"to attend or visit a place or event, such as a school, meeting, or other location.","ko":"학교, 모임 등 장소나 행사에 참석하거나 방문하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0502","en":"go under","definition":"To use a different name so that people know you by it, often for privacy or professional reasons.","ko":"특히 물속으로 표면 아래로 사라지다; 재정적으로 파산하다, 실패하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0503","en":"go up","definition":"to move or climb to a higher place or level","ko":"불에 의해 빠르게 파괴되다; 완전히 타버리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0504","en":"go with","definition":"to match, look good together, or be a suitable combination with something else.","ko":"다른 것 대신 하나를 선택하거나 고르다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0505","en":"gobble up","definition":"to eat something very quickly and completely","ko":"무언가를 매우 빠르고 완전히 먹다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0506","en":"gouge out","definition":"to remove something by digging or scooping it out, often leaving a hole or gap.","ko":"파내거나 긁어내어 무엇인가를 제거하다. 종종 구멍이나 빈 공간이 남는다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0507","en":"grind away","definition":"To work very hard for a long time, especially when the task is boring or difficult.","ko":"특히 지루하거나 어려운 일을 오랫동안 매우 열심히 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0508","en":"grope for","definition":"To try to find something by feeling with your hands because you cannot see it easily.","ko":"잘 보이지 않아 손으로 더듬으며 무언가를 찾으려 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0509","en":"gross out","definition":"To gross someone out means to make them feel very disgusted or sick because something is unpleasant, dirty, or disturbing.","ko":"누군가를 역겹게 하다란 어떤 불쾌하고 더럽거나 불안한 것으로 인해 매우 역겹거나 메스껍게 만드는 것을 의미합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0510","en":"grow over","definition":"To slowly cover something as plants or vegetation spread on it.","ko":"식물이나 풀 등이 퍼져 천천히 무언가를 덮다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0511","en":"grow up","definition":"To change from being a child to being an adult; to become more mature.","ko":"어린이에서 어른이 되다; 더 성숙해지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0512","en":"guide on","definition":"To help someone find the right way or make the right decision by giving advice or direction.","ko":"조언이나 방향을 제시하여 누군가가 올바른 길을 찾거나 올바른 결정을 내리도록 돕다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0513","en":"gun down","definition":"to shoot someone, usually with a gun, especially in a violent or sudden way.","ko":"누군가를 (보통 총으로) 갑자기 혹은 폭력적으로 쏴 죽이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0514","en":"hammer in","definition":"to make someone remember or learn something by repeating it many times.","ko":"여러 번 반복해서 누군가가 기억하거나 배우도록 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0515","en":"hammer out","definition":"To discuss something in detail and try hard to reach an agreement or solution, usually after a lot of debate or discussion.","ko":"어떤 문제를 자세히 논의하고, 오랜 협의 끝에 합의나 해결책을 찾으려 애쓰다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0516","en":"hand down","definition":"To give something, like a possession or tradition, to someone in a younger generation, usually within a family.","ko":"가족 내에서 주로 어린 세대에게 소유물이나 전통을 물려주다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0517","en":"hand out","definition":"to give something to each person in a group.","ko":"그룹의 각 사람에게 무언가를 나누어 주다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0518","en":"hand over","definition":"To give something to someone else, usually because they ask for it or you are required to do so.","ko":"보통 요청받거나 요구되어 무언가를 다른 사람에게 넘겨주다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0519","en":"hang around","definition":"To spend time in a place or with people, usually without doing anything special.","ko":"특별한 일 없이 어떤 장소나 사람들과 시간을 보내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0520","en":"hang in","definition":"To keep trying and not give up, even when things are difficult. It means to stay strong and patient during tough times.","ko":"힘들어도 포기하지 않고 계속 노력하는 것. 어려운 시기에 강인하게 인내심을 갖는 것을 의미합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0521","en":"hang on","definition":"to hold something or someone tightly and not let go, often because you don't want to lose them or it.","ko":"무언가나 누군가를 꽉 잡고 놓지 않는 것, 대개 잃고 싶지 않아서.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0522","en":"hang up","definition":"to put something, like clothes or a picture, on a hook or hanger so that it is suspended above the ground.","ko":"옷이나 그림 등을 걸이에 걸어서 땅 위에 매달아 놓다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0523","en":"hash out","definition":"To discuss something carefully and thoroughly in order to solve a problem or make an agreement.","ko":"문제를 해결하거나 합의를 보기 위해 어떤 것을 신중하고 철저하게 논의하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0524","en":"haul off","definition":"to take away someone or something, especially using force or a vehicle.","ko":"특히 힘이나 차량을 사용하여 누군가나 무언가를 끌고 가다, 데려가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0525","en":"haul up","definition":"to stop moving, usually a vehicle, in order to take a break or rest for a short time","ko":"보통 차량이 잠깐 쉬거나 휴식을 위해 멈추다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0526","en":"have on","definition":"To be wearing clothes or accessories, or to have something scheduled.","ko":"옷이나 액세서리를 착용하고 있거나, 일정이 잡혀 있다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0527","en":"haze over","definition":"to become covered with something (like mist or fog) so that it is hard to see clearly","ko":"안개나 연기 등으로 덮여서 명확하게 보이지 않게 되다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0528","en":"head off","definition":"To stop someone or something from going in a certain direction, often to prevent something from happening.","ko":"(어딘가로) 떠나다, 출발하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0529","en":"head up","definition":"To be the leader of a team, group, or organization.","ko":"팀, 그룹, 조직의 리더가 되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0530","en":"hear out","definition":"To listen carefully until someone has finished saying everything they want to say.","ko":"누군가가 말하고 싶은 모든 것을 다 말할 때까지 주의 깊게 듣다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0531","en":"heat up","definition":"to become more intense, active, or exciting, especially in a situation or competition","ko":"무언가를 따뜻하게 또는 뜨겁게 만들다, 혹은 따뜻해지거나 뜨거워지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0532","en":"hedge in","definition":"To surround or limit someone or something, making them feel trapped or unable to act freely.","ko":"누군가나 무언가를 둘러싸거나 제한하여 갇히거나 자유롭게 행동할 수 없다고 느끼게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0533","en":"help out","definition":"to assist someone with a task or in a difficult situation","ko":"누군가의 일이나 어려운 상황을 도와주다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0534","en":"hem in","definition":"To surround someone or something closely and prevent them from moving freely; to make someone feel trapped or restricted.","ko":"누군가 또는 무언가를 가까이에서 둘러싸서 자유롭게 움직이지 못하게 하다; 누군가가 갇혀 있거나 제한되어 있다고 느끼게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0535","en":"hide out","definition":"to stay in a place where you cannot be found, usually because you are trying to escape from someone or something.","ko":"누군가 또는 무언가에게서 피하려고 발견되지 않는 곳에 머무르는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0536","en":"hike up","definition":"to suddenly increase the price, amount, or level of something, especially in a way that seems too much or unfair","ko":"무엇(특히 옷)을 더 편하게 하거나 더러워지지 않게 위로 끌어올리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0537","en":"hinge on","definition":"To depend completely on someone or something; if something hinges on something else, it will only happen or be successful if that other thing happens.","ko":"누군가 또는 무언가에 전적으로 달려 있다; 어떤 일이 다른 것에 달려 있다면, 그 일이 있어야만 성공하거나 일어난다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0538","en":"hire out","definition":"To allow someone to use your property or your services in exchange for money; to rent something or yourself to others.","ko":"자신의 재산이나 서비스를 돈을 받고 남에게 제공하다; 무언가나 자기 자신을 빌려주거나 임대하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0539","en":"hitch up","definition":"to fasten or connect something (like an animal, trailer, or equipment) to another thing so they can move together.","ko":"무엇인가(동물, 트레일러, 장비 등)을 다른 것에 연결하거나 묶어 같이 움직일 수 있게 하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0540","en":"hold down","definition":"to physically keep someone, an animal, or something in a lower position so they cannot move up or escape","ko":"누군가 또는 무언가가 더 나아가거나, 성공하거나, 발전하는 것을 막다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0541","en":"hold in","definition":"to stop yourself from showing or expressing a feeling or emotion.","ko":"누군가 또는 무언가를 바로 사용하지 않고, 미래의 필요를 위해 따로 보관하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0542","en":"hold off","definition":"to stop someone or something from approaching or attacking; to delay or prevent something from happening for a while","ko":"무엇을 하기 전에 보류하거나 기다리다. 더 생각이 필요하거나 더 좋은 시기를 기다릴 때 사용함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0543","en":"hold on","definition":"To wait; stay on the phone and not hang up. It's often used when you want someone to wait for a short time, especially during a phone call.","ko":"어려운 상황에서도 계속 버티고 포기하지 않는 것; 힘든 시기에 기다리거나 강인함을 유지하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0544","en":"hold onto","definition":"to keep something and not give it away or get rid of it","ko":"무언가를 주거나 버리지 않고 계속 갖고 있는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0545","en":"hold out","definition":"to continue working or be strong enough for a period of time, especially when it is difficult or unexpected.","ko":"팔이나 들고 있는 것을 누군가 또는 무언가를 향해 내밀다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0546","en":"hold over","definition":"To use something (like a secret, mistake, or threat) that you know about someone so you can control or influence them.","ko":"무엇인가를 연기하거나 나중으로 미루는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0547","en":"hold up","definition":"to remain strong or continue to cope well during difficult situations or stress","ko":"누군가 혹은 무언가를 지연시키다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0548","en":"hole up","definition":"to stay in a place to hide or be safe, usually for a while","ko":"어디에 숨어 있거나 안전하기 위해 (보통 잠시 동안) 한 곳에 머물다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0549","en":"holler out","definition":"to shout something loudly, especially to get someone's attention","ko":"누군가의 주의를 끌기 위해 무언가를 크게 외치다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0550","en":"hollow out","definition":"to remove the inside part of something so that it becomes empty inside","ko":"무엇의 내부를 제거하여 속이 비게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0551","en":"home in","definition":"To focus your attention closely on a particular person or thing.","ko":"특정 사람이나 사물에 집중해서 주의를 기울이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0552","en":"hook on","definition":"To become very interested in or start liking something so much that you want it all the time.","ko":"무엇인가에 매우 관심을 가지거나 너무 좋아해서 항상 원하게 되는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0553","en":"hook up","definition":"to connect a person or device to a machine or system so it can work or function","ko":"사람이나 기기를 기계나 시스템에 연결하여 작동하게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0554","en":"hop out","definition":"to get out of a vehicle or place quickly and often energetically","ko":"차량이나 장소에서 빠르고 종종 힘차게 내리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0555","en":"horn in","definition":"to interrupt or join a conversation, activity, or situation where you are not invited or welcome.","ko":"초대받지 않았거나 환영받지 않는 대화, 활동 또는 상황에 끼어들거나 참여하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0556","en":"horse around","definition":"To play in a silly, noisy, or rough way, especially instead of doing something serious.","ko":"특히 진지하게 해야 할 일을 대신해서 장난을 치거나 시끄럽게 놀거나 거칠게 노는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0557","en":"hose down","definition":"To wash someone or something by spraying water from a hose onto them. People often hose down things or places to clean them or cool them off.","ko":"호스로 물을 뿌려서 누군가나 무언가를 씻다. 주로 청소하거나 식히기 위해 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0558","en":"hunch over","definition":"To bend your upper body forward and round your shoulders, usually because you are tired, feeling pain, or trying to see something better.","ko":"보통 피곤하거나 통증을 느끼거나 더 잘 보려고 상체를 앞으로 굽히고 어깨를 둥글게 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0559","en":"hunker down","definition":"to stay in a safe place for a period of time, usually to protect yourself or wait for something to finish","ko":"일정 기간 동안 안전한 곳에 머무르며, 보통 자신을 보호하거나 무언가가 끝나기를 기다리는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0560","en":"hunt down","definition":"to search for someone or something very determinedly until you find and catch them, usually because they have done something wrong or are difficult to find","ko":"누군가 또는 무언가를 매우 집요하게 찾아서 결국 찾아내고 잡는 것, 보통 잘못을 저질렀거나 찾기 힘든 경우에 사용함","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0561","en":"hush up","definition":"To keep something secret, especially to prevent people from knowing about something bad or embarrassing.","ko":"특히 나쁘거나 창피한 일이 알려지지 않도록 무엇인가를 비밀로 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0562","en":"ice over","definition":"to become completely covered with a layer of ice.","ko":"완전히 얼음층으로 덮이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0563","en":"intrude into","definition":"to enter or get involved in something where you are not wanted or where you do not belong, especially in someone else's private matters.","ko":"특히 다른 사람의 사적인 일 등, 자신이 원치 않거나 어울리지 않는 일에 들어가거나 관여하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0564","en":"invite out","definition":"To ask someone to join you for a social activity, often as a date or to spend time together outside of the usual environment.","ko":"누군가에게 함께 사회적 활동을 하자고 요청하는 것. 종종 데이트나 평소와 다른 환경에서 시간을 보내기 위함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0565","en":"iron out","definition":"To solve or fix small problems or disagreements, especially so that everything can go smoothly.","ko":"모든 것이 순조롭게 진행되도록 작은 문제나 의견 차이를 해결하거나 바로잡다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0566","en":"jack up","definition":"To lift something up using a special device called a jack, usually to repair or check something underneath.","ko":"특수 장치인 잭을 사용하여 무언가를 들어올리는 것, 보통 그 아래를 수리하거나 확인하기 위함임.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0567","en":"jazz up","definition":"To make something look or seem more lively, exciting, or attractive.","ko":"무언가를 더 생기 있게, 흥미롭게, 매력적으로 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0568","en":"jot down","definition":"to write something quickly so you don't forget it","ko":"잊지 않도록 급히 적다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0569","en":"jump off","definition":"to quickly push yourself away from a surface or object and go down to the ground.","ko":"표면이나 물체에서 재빨리 몸을 밀어내어 땅으로 내려가는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0570","en":"jump out","definition":"If something jumps out, it is very easy to notice because it is clear, obvious, or different from everything else.","ko":"무언가가 눈에 띈다면, 그것은 명확하거나 뚜렷하거나 다른 것들과 달라서 매우 쉽게 알아차릴 수 있습니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0571","en":"jut out","definition":"If something juts out, it means it sticks out farther than the surface or edge around it.","ko":"무언가가 튀어나와 있다면, 그것은 주위의 표면이나 가장자리보다 더 앞으로 나와 있다는 의미입니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0572","en":"keel over","definition":"To suddenly fall to the ground, usually because of fainting, illness, or exhaustion.","ko":"실신, 질병 또는 탈진으로 인해 갑자기 쓰러지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0573","en":"keep away","definition":"To stay at a distance from someone or something, usually to avoid danger or trouble. Similar to 'stay away.'","ko":"일반적으로 위험이나 문제를 피하기 위해 누구나 무엇에서 거리를 두는 것. '멀리하다'와 비슷함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0574","en":"keep down","definition":"to prevent someone or something from increasing, rising, or growing; to control or limit.","ko":"음식이나 음료를 먹은 후 구토를 참거나 토하지 않도록 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0575","en":"keep in","definition":"To make sure someone or something stays inside a place and does not go out.","ko":"누군가나 무언가가 밖으로 나가지 않고 실내에 머물도록 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0576","en":"keep off","definition":"to not touch or go onto a particular area or thing","ko":"특정한 곳이나 물건을 만지거나 들어가지 않는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0577","en":"keep on","definition":"to allow someone to continue working in their job or in a particular position, instead of asking them to leave","ko":"누군가를 계속 일하게 하거나 자리를 유지하도록 허용하다, 해고하지 않고","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0578","en":"keep out","definition":"To stop someone or something from entering a place.","ko":"누군가 또는 무언가가 어떤 장소에 들어오는 것을 막다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0579","en":"keep up","definition":"to continue to do something at the same level, speed, or standard; to not stop or let it decrease","ko":"누군가가 밤에 잠을 자지 못하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0580","en":"kick about","definition":"To spend time with someone in a relaxed way, or to move around from place to place without any special plan. It is similar to 'hang out.'","ko":"누군가와 편하게 시간을 보내거나, 특별한 계획 없이 여기저기 돌아다니는 것. '어울리다'와 비슷한 표현.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0581","en":"kick around","definition":"to treat someone or something in a bad or unfair way, especially repeatedly and without respect","ko":"어떤 것이 가장 좋은지 알아보기 위해 보통 편안하게 다양한 아이디어나 제안을 이야기하고 공유하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0582","en":"kick down","definition":"To break or force something open by kicking it.","ko":"발로 차서 무언가를 부수거나 억지로 여는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0583","en":"kick in","definition":"to start to have an effect or begin to work, especially after a short delay.","ko":"짧은 지연 후에 효과가 나타나거나 작동하기 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0584","en":"kick off","definition":"To start or begin something, especially an event or activity. This phrase comes from football (soccer), where the game begins with a 'kick off.'","ko":"무엇인가를 시작하다, 특히 행사나 활동을. 이 표현은 축구에서 유래되었습니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0585","en":"kick out","definition":"to force something out of a place by using your foot to kick it.","ko":"누군가가 잘못을 해서 어떤 장소에서 내쫓다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0586","en":"kick up","definition":"to cause something, like dust or a ball, to move upwards by kicking it","ko":"먼지나 공과 같은 것을 발로 차서 위로 올리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0587","en":"kill off","definition":"to completely destroy or remove a group of living things, usually by causing their death, so that none or very few remain","ko":"일반적으로 죽음을 초래함으로써 생물 집단을 완전히 파괴하거나 없애서 거의 남지 않거나 아예 남지 않게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0588","en":"kit out","definition":"to provide someone with all the clothes, tools, or equipment they need for a particular purpose","ko":"특정 목적을 위해 필요한 모든 옷, 도구, 장비를 누군가에게 제공하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0589","en":"knock about","definition":"to treat something roughly, or to handle something in a careless way so that it may get damaged.","ko":"무언가를 거칠게 다루거나 부주의하게 다루어 손상될 수 있게 하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0590","en":"knock against","definition":"to accidentally hit or bump into someone or something, usually by mistake","ko":"실수로 누군가나 무언가에 부딪히거나 치는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0591","en":"knock off","definition":"to finish or complete something quickly and easily, often because it does not take much time or effort.","ko":"특히 브랜드 제품을 불법으로 복제하거나 생산하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0592","en":"knock out","definition":"to make something stop working or to damage something so it cannot be used","ko":"누군가를 세게 쳐서 기절시키다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0593","en":"knock over","definition":"to make something fall to the ground by hitting it accidentally.","ko":"무언가를 실수로 쳐서 넘어뜨리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0594","en":"knock up","definition":"to make someone pregnant","ko":"임신시키다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0595","en":"knuckle down","definition":"To start working very hard, especially when you should have been working harder before.","ko":"특히 전에 더 열심히 했어야 했을 때 아주 열심히 일하기 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0596","en":"knuckle under","definition":"to give in to someone’s authority or demands, even if you don't want to.","ko":"원하지 않아도 누군가의 권위나 요구에 굴복하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0597","en":"lace up","definition":"to tie the laces on shoes, boots, or other clothing that uses laces.","ko":"신발, 부츠, 또는 끈이 달린 옷의 끈을 묶다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0598","en":"land up","definition":"To finally be in a particular place, situation, or condition, often without planning it.","ko":"종종 계획하지 않은 특정 장소, 상황 또는 상태에 결국 있게 되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0599","en":"lap up","definition":"To drink or eat something eagerly using the tongue, especially used for animals.","ko":"특히 동물이 혀로 무엇인가를 열심히 핥아서 먹거나 마시다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0600","en":"lash out","definition":"to suddenly speak or act angrily towards someone or something","ko":"누군가 또는 무언가에게 갑자기 화를 내거나 공격적으로 행동하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0601","en":"last out","definition":"To survive or continue to exist through a difficult situation or for as long as necessary.","ko":"어려운 상황을 견디거나 필요한 만큼 살아남거나 계속 존재하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0602","en":"latch on","definition":"To finally understand something or realize an idea after some time.","ko":"누군가 또는 무언가를 아주 꼭 붙잡다(주로 지지나 위안이 필요할 때); 또는 무언가나 누군가에 매우 관심을 가지거나 집착하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0603","en":"laugh at","definition":"To find something funny and show it by laughing, often making fun of a person or thing.","ko":"무언가를 재미있게 여겨 웃음으로 나타내며, 종종 사람이나 사물을 놀리는 경우가 많다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0604","en":"laugh away","definition":"To make something seem less serious or important by joking or laughing about it.","ko":"농담이나 웃음으로 어떤 일을 덜 심각하거나 중요하지 않게 보이게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0605","en":"lay down","definition":"to create or officially state a rule, law, or principle that others should follow","ko":"다른 사람들이 따라야 할 규칙, 법, 원칙을 만들거나 공식적으로 정하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0606","en":"lay in","definition":"To collect and keep something, like food or supplies, so you will have enough when you need it later.","ko":"음식이나 생필품처럼 나중에 필요할 때를 대비해 미리 모아두고 저장하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0607","en":"lay into","definition":"to criticize or attack someone or something angrily","ko":"누군가나 무언가를 화나게 비난하거나 공격하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0608","en":"lay off","definition":"to stop doing something, especially if it is bothering or annoying someone.","ko":"보통 더 이상 줄 일이 없어서 고용을 중단하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0609","en":"lay out","definition":"to explain something clearly, usually by presenting the main facts, plan, or details in an organized way","ko":"주요 사실, 계획 또는 세부 정보를 체계적으로 제시하여 명확하게 설명하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0610","en":"lay up","definition":"If someone is laid up, they must stay in bed because they are sick or injured.","ko":"누군가가 병이나 부상으로 침대에 누워 있어야 할 때 사용합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0611","en":"lead on","definition":"To make someone believe something that is not true, especially by pretending to like them or be interested in a relationship, when you do not really mean it.","ko":"실제로 관심이 없으면서 호감이나 연애 감정이 있는 척 하여, 누군가를 잘못 믿게 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0612","en":"lead up","definition":"To be in charge of a group, project, or activity; to act as the main person responsible for something. Synonym: 'head up'.","ko":"그룹이나 프로젝트, 활동을 이끌거나 주된 책임자가 되는 것. 동의어: '이끌다'.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0613","en":"leak out","definition":"When a liquid slowly escapes or seeps from a place where it is supposed to stay.","ko":"액체가 머물러 있어야 할 곳에서 천천히 새어나올 때.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0614","en":"lean against","definition":"to rest your body on someone or something for support","ko":"누군가나 무언가에 몸을 기대어 지탱하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0615","en":"leap out","definition":"To be easily seen or very noticeable, especially because it is different or stands out.","ko":"무엇에서 갑자기 뛰어나오거나 빠르게 움직이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0616","en":"leave behind","definition":"to forget or intentionally not take something with you when you leave a place","ko":"어딘가를 떠날 때 물건을 깜빡 잊거나 일부러 챙기지 않는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0617","en":"leave off","definition":"to stop doing something, especially for a while or before finishing","ko":"무엇을 (특히 잠시 동안이나 완료하기 전에) 멈추다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0618","en":"leave out","definition":"To not include someone or something; to skip or omit them from a group, list, or activity.","ko":"누구나 무엇을 포함하지 않다; 그룹, 목록, 활동에서 빠뜨리거나 생략하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0619","en":"let down","definition":"to disappoint someone by not doing what they expected or hoped for","ko":"기대하거나 바라던 대로 하지 않아 누군가를 실망시키다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0620","en":"let in","definition":"to allow someone or something to enter a place","ko":"누군가 또는 무언가가 장소에 들어오도록 허락하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0621","en":"let on","definition":"To tell someone a secret or reveal information that was supposed to be kept private.","ko":"누군가에게 비밀을 말하거나 비밀로 해야 할 정보를 드러내는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0622","en":"let out","definition":"to end or finish, especially when an event or activity is over and people are allowed to leave","ko":"옷의 솔기를 조정하여 크기를 더 크게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0623","en":"let up","definition":"To stop putting so much pressure on someone or something; to be less strict or intense.","ko":"누군가나 무언가에 너무 많은 압박을 가하는 것을 멈추다; 덜 엄격하거나 덜 강렬해지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0624","en":"level off","definition":"To make a surface flat and even, so there are no bumps or high areas.","ko":"표면을 평평하고 고르게 만들어 울퉁불퉁하거나 높은 부분이 없게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0625","en":"lie about","definition":"to relax or rest in a place, usually doing nothing important.","ko":"보통 중요한 일 없이 한 곳에서 편하게 쉬거나 휴식하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0626","en":"lie down","definition":"to put your body in a flat or horizontal position, usually to rest or sleep","ko":"눕다 (대개 쉬거나 잠을 자려고 몸을 수평 자세로 누이다)","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0627","en":"lie in","definition":"to exist or be found in something; to be the reason or cause of something","ko":"무엇에 존재하거나 발견되는 것; 무엇의 원인이나 이유가 되는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0628","en":"lift off","definition":"To rise into the air, especially when something like a rocket or plane leaves the ground.","ko":"로켓이나 비행기 같은 것이 땅에서 떠올라서 하늘로 오르는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0629","en":"lift out","definition":"to take something out of a place by picking it up, usually carefully","ko":"무엇인가를 조심스럽게 들어서 장소에서 꺼내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0630","en":"lift up","definition":"to make someone feel happier or more positive","ko":"누군가를 더 행복하거나 긍정적으로 느끼게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0631","en":"light up","definition":"to make something start to burn or to switch on a light so that a place becomes brighter","ko":"무언가에 불을 붙이거나, 조명을 켜서 장소를 밝게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0632","en":"lighten up","definition":"to make something brighter, or to become brighter or less dark","ko":"무엇인가를 더 밝게 만들거나, 더 밝아지거나 덜 어두워지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0633","en":"limber up","definition":"to do gentle exercises or stretches to prepare your body for physical activity and to become more flexible","ko":"운동이나 스트레칭 등으로 신체활동 전 몸을 준비하고 유연하게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0634","en":"line up","definition":"To arrange for people or things to take part in an event or activity; to organize or schedule participants.","ko":"사람이나 물건이 행상 등에 참여하도록 준비하거나 조직하다; 참가자를 일정에 맞게 배정하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0635","en":"linger over","definition":"to spend a long time on something, usually because you are relaxing or enjoying it, instead of hurrying.","ko":"서두르지 않고 보통 느긋하게 즐기거나 휴식을 취하면서 어떤 일에 오랜 시간을 보내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0636","en":"link up","definition":"to connect or join things or people so they can work together or be related in some way.","ko":"사물이나 사람을 서로 연결하거나 합쳐서 함께 일하거나 어떤 식으로든 관련될 수 있게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0637","en":"listen in","definition":"to secretly listen to a conversation that you are not supposed to hear","ko":"들어서는 안 되는 대화를 몰래 듣다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0638","en":"live down","definition":"To be able to forget or recover from something embarrassing or bad that you have done, so that people stop talking about it.","ko":"창피하거나 나쁜 일을 하고 나서, 사람들이 더 이상 그것에 대해 말하지 않을 만큼 잊거나 극복하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0639","en":"live on","definition":"To continue to exist or to remain alive after someone or something else has gone or ended.","ko":"누군가나 무언가가 사라지거나 끝난 후에도 계속 존재하거나 살아남다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0640","en":"live out","definition":"to spend the rest of your life in a particular way or place","ko":"남은 인생을 특정한 방식이나 장소에서 보내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0641","en":"live up to","definition":"to be as good as something or someone expects; to fulfill expectations or standards","ko":"기대나 기준을 충족하다; 기대에 부응하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0642","en":"live with","definition":"To accept something difficult or unpleasant and continue your life despite it.","ko":"어려운 일이나 불쾌한 일을 받아들이고 그럼에도 계속 살아가는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0643","en":"liven up","definition":"to make something more lively, fun, or interesting","ko":"무언가를 더 활기차고, 재미있고, 흥미롭게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0644","en":"load up","definition":"to fill something or someone with as much as possible; to put a lot of things into or onto something or someone.","ko":"무엇이나 누구를 최대한 가득 채우다; 많은 것을 무엇이나 누구에게 싣거나 넣다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0645","en":"lock away","definition":"to put someone or something in a safe place and lock it, so it cannot be taken or used by others","ko":"누군가 또는 어떤 것을 안전한 곳에 두고, 자물쇠를 채워 다른 사람이 가져가거나 사용하지 못하게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0646","en":"lock out","definition":"to prevent someone from entering a place by locking the door, often used when workers cannot go to work during a strike","ko":"누군가가 들어오지 못하도록 문을 잠그다. 주로 파업 중에 직원들이 출근하지 못하도록 할 때 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0647","en":"lock up","definition":"to make sure a building, room, or object is securely fastened with a lock, usually to keep it safe or to prevent anyone from getting in","ko":"안전을 위해 또는 아무도 들어오지 못하게 건물, 방 또는 물건에 자물쇠를 확실히 잠그다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0648","en":"log in","definition":"to enter your username and password to access an account, website, or computer system.","ko":"계정, 웹사이트, 컴퓨터 시스템에 접속하기 위해 사용자 이름과 비밀번호를 입력하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0649","en":"log off","definition":"To disconnect yourself from a computer, website, or app, so that you are no longer signed in.","ko":"컴퓨터, 웹사이트 또는 앱에서 로그아웃하여 더 이상 로그인 상태가 아니게 된다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0650","en":"look after","definition":"to take care of someone or something and make sure they are safe and well.","ko":"누군가 또는 무언가를 돌보고 안전하고 건강하게 지내도록 하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0651","en":"look around","definition":"to walk through a place to see what is there, often to explore or find something interesting","ko":"장소를 돌아다니며 무엇이 있는지 살펴보다. 종종 탐험하거나 흥미로운 것을 찾기 위한 행동.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0652","en":"look at","definition":"to direct your eyes toward someone or something, usually to see, check, or examine it","ko":"누군가나 무언가를 보기 위해 시선을 돌리다, 보거나 확인하거나 조사하기 위해","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0653","en":"look away","definition":"to turn your eyes to another direction so you are no longer looking at someone or something","ko":"누군가나 무언가를 더 이상 보지 않기 위해 시선을 다른 방향으로 돌리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0654","en":"look for","definition":"to try to find someone or something","ko":"누군가 또는 무언가를 찾으려고 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0655","en":"look into","definition":"to try to find out more about something; to investigate or examine a problem, situation, or issue","ko":"무언가에 대해 더 알아보려고 하다; 문제, 상황, 사안을 조사하거나 검토하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0656","en":"take after","definition":"to look or behave like an older relative, usually a parent.","ko":"부모나 조부모 등 나이 많은 가족을 닮거나 행동이 비슷하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0657","en":"look on","definition":"To watch something happen without getting involved or taking part.","ko":"참여하거나 개입하지 않고 무언가를 지켜보다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0658","en":"look out","definition":"to be careful and watch for possible danger or something important","ko":"가능한 위험이나 중요한 것에 조심하고 주의하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0659","en":"look to","definition":"to rely on or expect help, advice, or solutions from someone or something; to focus your attention on someone or something for support or guidance","ko":"누군가나 무언가에게 도움이나 조언, 해결책을 기대하거나 의지하다; 지원이나 안내를 바라며 누군가나 무언가에 주의를 집중하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0660","en":"look up","definition":"to try to find information about someone or something, especially in a book, on the internet, or in a list","ko":"누구나 무엇에 대한 정보를 찾으려고 하다, 특히 책, 인터넷, 목록에서","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0661","en":"look up to","definition":"To admire or respect someone, often because you want to be like them.","ko":"누군가를 존경하거나 우러러보다. 종종 그 사람처럼 되고 싶어서.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0662","en":"loosen up","definition":"to become more relaxed or to help your body or muscles become less tense","ko":"더 편안해지거나 몸이나 근육이 덜 긴장하도록 돕다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0663","en":"lounge about","definition":"To spend time relaxing and doing very little, usually in a comfortable way. This means someone is not being active and is just taking it easy. Synonym: 'lounge around'.","ko":"편안하게 거의 아무것도 하지 않으면서 시간을 보내는 것. 즉, 활동적이지 않고 그냥 쉬는 것을 의미한다. 유의어: '빈둥거리다', '뒹굴다'.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0664","en":"mail out","definition":"To send letters, documents, or packages to people using the post office.","ko":"편지, 문서 또는 소포를 우체국을 이용해 보내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0665","en":"make for","definition":"to go towards a place; to move in the direction of somewhere.","ko":"어디론가를 향해 가다; 어떤 방향으로 움직이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0666","en":"make out","definition":"to be able to see, hear, or understand something, often with difficulty","ko":"상황에서 성공하거나 잘 해내다; 특정 분야에서 잘하거나 못하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0667","en":"make over","definition":"to change or improve the appearance of something or someone","ko":"무엇이나 누군가의 외모를 바꾸거나 개선하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0668","en":"make up","definition":"to invent or create something, especially a story, excuse, or explanation that is not true; or to prepare or put something together","ko":"다툼이나 오해 후에 다시 친구가 되다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0669","en":"map out","definition":"To plan something in detail or decide how it will happen before you do it.","ko":"무언가를 시작하기 전에 자세히 계획하거나, 어떻게 진행될지 미리 결정하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0670","en":"march on","definition":"to keep going forward or continue without stopping, especially despite challenges or the passage of time.","ko":"특히 도전이나 시간의 흐름에도 불구하고 계속 앞으로 나아가거나 멈추지 않고 계속하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0671","en":"march out","definition":"to walk in a determined and confident way to a place, often as a group, especially into a public area where people can see you","ko":"결연하고 자신감 있게 (종종 단체로) 사람들이 볼 수 있는 공개된 장소로 걸어가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0672","en":"mark down","definition":"To lower the price of something, usually in a store.","ko":"보통 상점에서 무언가의 가격을 내리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0673","en":"mark off","definition":"To check or cross out items from a list to show they have been completed or dealt with.","ko":"항목이 완료되었거나 처리되었음을 나타내기 위해 목록에서 체크하거나 지우다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0674","en":"mark out","definition":"to show or draw the edges or limits of an area or space.","ko":"영역이나 공간의 경계 또는 한계를 표시하거나 그리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0675","en":"mark up","definition":"to increase the price of something, usually to make a profit","ko":"주로 이익을 위해 무언가의 가격을 올리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0676","en":"matter to","definition":"to be important or have value for someone.","ko":"누군가에게 중요하거나 가치가 있다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0677","en":"measure out","definition":"To separate and give a specific amount of something, usually by using a tool or container.","ko":"일반적으로 도구나 용기를 사용하여 어떤 것의 특정 양을 분리하여 제공하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0678","en":"measure up","definition":"to be good enough, or as good as someone or something else","ko":"충분히 좋거나, 다른 사람이나 것만큼 좋다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0679","en":"meddle with","definition":"To try to change or influence something that is not your responsibility, often causing problems. It can also mean touching or handling something that you shouldn't.","ko":"자신의 책임이 아닌 일에 간섭하거나 영향을 미치려 하여 종종 문제를 일으키는 것. 또한 만지거나 건드리면 안 되는 것을 만진다는 의미도 있다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0680","en":"meet up with","definition":"to arrange to see and spend time with someone, usually for a social reason.","ko":"보통 사교를 목적으로 누군가와 만나 시간을 보내기로 약속하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0681","en":"mellow out","definition":"to become more calm, relaxed, or less strict, often as a result of time or experience","ko":"시간이나 경험의 결과로 더 차분해지거나, 느긋해지거나, 덜 엄격해지는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0682","en":"melt down","definition":"to heat something solid until it becomes liquid, usually so it can be reused or reshaped.","ko":"무언가 고체를 가열하여 액체로 만드는 것, 보통 재사용이나 재형성을 위해서.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0683","en":"melt off","definition":"To lose weight gradually, often so that it seems to disappear naturally or easily.","ko":"체중이 점차 자연스럽거나 쉽게 사라지는 것처럼 줄어드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0684","en":"mess about","definition":"to spend time doing things that are not important or not serious; to waste time instead of doing what you should do. Synonym: 'mess around'","ko":"중요하지 않거나 심각하지 않은 일을 하며 시간을 보내다; 해야 할 일을 하지 않고 시간을 낭비하다. 동의어: '빈둥거리다'","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0685","en":"mess up","definition":"to make a mistake or do something badly; to ruin or spoil something by accident.","ko":"실수하거나 일을 망치다; 실수로 무엇인가를 망가뜨리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0686","en":"mill about","definition":"To walk or move around a place without any clear purpose or direction.","ko":"뚜렷한 목적이나 방향 없이 장소를 거닐거나 돌아다니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0687","en":"mist over","definition":"When something, like glasses or windows, becomes covered with tiny drops of water, making it hard to see through. This usually happens because of sudden changes in temperature or humidity. 'Mist up' is a more common way to say this.","ko":"안경이나 창문처럼 어떤 것이 작은 물방울로 덮여서 잘 보이지 않게 되는 것. 주로 갑작스러운 온도나 습도 변화로 인해 발생합니다. 보통 ‘김이 서리다’라고 합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0688","en":"mix in","definition":"to join or combine with a group of people or things, or to add something so that it becomes part of a mixture","ko":"사람이나 사물의 그룹에 합류하거나 섞이거나, 무언가를 추가하여 혼합물의 일부가 되게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0689","en":"mix up","definition":"to confuse things or people, or to put things in the wrong order by mistake","ko":"사물이나 사람을 헷갈리거나, 실수로 잘못된 순서로 두다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0690","en":"monkey around","definition":"to behave in a silly or playful way, often wasting time instead of doing something important","ko":"중요한 일을 하지 않고, 장난치거나 허비하는 행동을 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0691","en":"moon about","definition":"to be sad and wander around because you are missing someone or something.","ko":"누군가 또는 무언가가 그리워서 슬퍼하며 방황하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0692","en":"mop up","definition":"to clean liquid or a mess from a surface using a mop, cloth, or something similar","ko":"걸레, 대걸레 등으로 표면에 있는 액체나 오염을 닦아내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0693","en":"mope around","definition":"To move around slowly and sadly, often because you are upset or unhappy about something.","ko":"무언가에 속상하거나 불행해서 천천히 슬프게 돌아다니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0694","en":"mouth off","definition":"to speak in a rude, disrespectful, or loud way, often complaining or saying what you think when you shouldn’t.","ko":"무례하고, 불손하게, 또는 시끄럽게 말하다. 자주 불평하거나, 말하지 말아야 할 때 자신의 생각을 말하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0695","en":"move around","definition":"to change your location frequently, especially by going from one place to another","ko":"특히 한 장소에서 다른 장소로 자주 이동하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0696","en":"move in","definition":"to start living in a new house, apartment, or place","ko":"새 집, 아파트, 장소에서 살기 시작하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0697","en":"move in on","definition":"to approach someone or something closely, often in order to take control, get involved, or take action.","ko":"누군가나 무언가에 가까이 다가가서 통제하거나 개입하거나 행동하려는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0698","en":"move on","definition":"to stop focusing on something from the past and continue with your life or next activity","ko":"과거의 일에 집착하지 않고 자신의 인생이나 다음 활동을 계속하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0699","en":"move over","definition":"To change your position or move something to the side so there is space for someone or something else.","ko":"누군가 또는 무언가를 위해 자신의 위치를 바꾸거나 무언가를 옆으로 옮기는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0700","en":"move up","definition":"to change the position of someone or something to a higher place or a higher level, or to advance forward","ko":"누군가나 무언가의 위치를 더 높은 곳이나 더 높은 수준으로 옮기거나 앞으로 나아가게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0701","en":"mow down","definition":"to hit, knock over, or kill someone or something, usually by using a vehicle or weapon","ko":"차량이나 무기를 사용하여 사람이나 사물을 치거나 넘어뜨리거나 죽이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0702","en":"muck about","definition":"to spend time doing things that are not important, often just for fun or without any clear purpose. Similar to: 'muck around'.","ko":"중요하지 않은 일을 하며 시간을 보내다. 대개 재미로 하거나 뚜렷한 목적 없이. 'muck around'와 비슷함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0703","en":"muck up","definition":"to do something badly or make a mistake that ruins a situation or task.","ko":"어떤 일을 잘못하거나 실수해서 상황이나 과제를 망치다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0704","en":"mull over","definition":"to think about something carefully for a period of time before making a decision","ko":"결정을 내리기 전에 어떤 것을 신중하게 오랫동안 생각하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0705","en":"muscle into","definition":"To push your way into a place, activity, or situation, especially when you are not welcome or without being invited.","ko":"환영받지 않거나 초대받지 않았는데도 억지로 장소나 활동, 상황에 들어가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0706","en":"muster up","definition":"to gather or find a quality, feeling, or strength inside yourself, especially when it is difficult","ko":"특히 힘들 때 자신 안에서 어떤 자질, 감정, 힘 등을 모으거나 찾아내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0707","en":"nail down","definition":"To make something certain or definite, usually by deciding on final details.","ko":"보통 최종 세부 사항을 정해 어떤 것을 확실하게 하거나 확정하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0708","en":"narrow down","definition":"to reduce the number of options or possibilities, making something more specific or easier to choose.","ko":"선택지나 가능성을 줄여서 더 구체적이거나 선택하기 쉽도록 하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0709","en":"nip off","definition":"To quickly remove or cut a small piece from something, usually by pinching or snipping.","ko":"무엇인가에서 작은 조각을 빠르게 떼어내거나 자르는 것, 보통 손가락이나 가위로.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0710","en":"nod off","definition":"to fall asleep, especially when you are sitting down, often without meaning to","ko":"특히 앉아 있을 때, 원하지 않았는데도 깜빡 졸다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0711","en":"nose out","definition":"To discover or find something, especially something hidden or secret, by searching carefully.","ko":"특히 숨겨져 있거나 비밀인 것을 꼼꼼히 찾아내거나 발견하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0712","en":"offer up","definition":"to present or give something, often in a formal or respectful way, especially as a sign of thanks, worship, or respect.","ko":"감사, 예배, 존경의 표시로 어떤 것을 공식적이거나 정중하게 바치다 또는 드리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0713","en":"ooze out","definition":"To slowly come out of someone or something in a thick or sticky way, like a liquid.","ko":"액체처럼 걸쭉하거나 끈적한 형태로 누군가 또는 무언가에서 천천히 흘러나오다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0714","en":"open up","definition":"To start something so people can use it or to begin operation of a place, such as a shop or office.","ko":"특히 기회, 일자리, 옵션 등이 이용 가능해지는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0715","en":"operate on","definition":"to perform a medical surgery on someone or something; to use skills, usually medical, to fix something inside a person, animal, or device","ko":"누군가 또는 무언가에게 의학적 수술을 시행하다; 보통 의학적 기술을 사용하여 사람, 동물 또는 기기의 내부를 고치다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0716","en":"opt out","definition":"to decide not to take part in something or not to be included in it","ko":"어떤 일에 참여하지 않거나 포함되지 않기로 결정하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0717","en":"originate in","definition":"To start or begin in a particular place, situation, or thing.","ko":"특정 장소, 상황 또는 사물에서 시작하거나 기원하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0718","en":"pack on","definition":"To gain weight quickly or in a short period of time, especially from eating a lot.","ko":"특히 많이 먹어서 짧은 기간에 체중이 빠르게 늘다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0719","en":"pair off","definition":"To join with another person to make a group of two, often for an activity or event.","ko":"활동이나 이벤트를 위해 다른 사람과 짝을 이루다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0720","en":"pal up","definition":"to become friends with someone or start spending time together as friends","ko":"누군가와 친구가 되거나 친구처럼 함께 시간을 보내기 시작하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0721","en":"palm off","definition":"To trick someone into accepting something unwanted or not valuable.","ko":"원하지 않거나 가치 없는 것을 남에게 속여서 넘기다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0722","en":"pan out","definition":"If something pans out, it means it turns out well or is successful, especially after some effort or waiting.","ko":"무언가가 '잘 풀리다'란 노력을 하거나 기다린 끝에 일이 잘 되거나 성공적으로 끝난다는 의미입니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0723","en":"pare down","definition":"to reduce something by removing unnecessary parts, making it smaller or simpler","ko":"불필요한 부분을 제거하여 더 작거나 단순하게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0724","en":"part with","definition":"to give something away or to let something go, even if you don't really want to","ko":"정말로 원하지 않아도 무언가를 내어주거나 놓아주다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0725","en":"partition off","definition":"to separate part of a space or area from the rest by putting up a wall or dividers","ko":"벽이나 칸막이를 세워 공간의 일부를 나누거나 분리하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0726","en":"partner off","definition":"to join with another person to form a pair, especially for an activity or event","ko":"주로 활동이나 행사에서 다른 사람과 짝을 이루다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0727","en":"pass around","definition":"To give something to each person in a group so everyone can have or see it.","ko":"모두가 가질 수 있거나 볼 수 있도록 그룹의 각 사람에게 무엇인가를 돌리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0728","en":"pass away","definition":"A polite or gentle way to say that someone has died.","ko":"누군가가 사망했다는 것을 공손하거나 부드럽게 표현하는 방법.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0729","en":"pass off","definition":"To pretend that someone or something is something else, usually to trick others.","ko":"누군가나 무언가를 다른 것으로 가장하여 보통 다른 사람을 속이려는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0730","en":"pass on","definition":"to give something, such as information, a message, or an object, to someone else so they can have it or know it","ko":"정보, 메시지, 물건 등을 다른 사람에게 주어 그 사람이 갖거나 알 수 있게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0731","en":"pass on sth","definition":"to choose not to accept or take part in something; to decline an offer, invitation, or opportunity.","ko":"무엇을 받아들이거나 참여하지 않기로 선택하다; 제안, 초대, 기회를 거절하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0732","en":"pass out","definition":"to suddenly become unconscious and fall down, usually because of heat, lack of air, or feeling unwell","ko":"보통 더위, 산소 부족, 몸이 좋지 않아서 갑자기 의식을 잃고 쓰러지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0733","en":"pass up","definition":"to choose not to accept an opportunity, gift, or offer","ko":"기회나 선물, 제안을 받아들이지 않기로 선택하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0734","en":"patch up","definition":"To fix a relationship or a problem after a disagreement or argument.","ko":"다툼이나 논쟁 후 관계나 문제를 수습하거나 바로잡다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0735","en":"pay off","definition":"to give someone all the money you owe them, often when they finish working for you","ko":"무언가가 결실을 맺는다는 것은 당신의 노력, 투자, 또는 일이 좋은 결과나 보상을 가져온다는 뜻입니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0736","en":"pay out","definition":"to give a large amount of money to someone or for something, usually as a payment, prize, or compensation.","ko":"대개 지급, 상금, 보상으로 누군가에게 큰 금액을 주다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0737","en":"pay up","definition":"to give someone the full amount of money you owe, especially if you don't want to or it is difficult.","ko":"특히 원하지 않거나 어렵더라도 빚진 돈을 모두 갚다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0738","en":"peck at","definition":"To eat only a small amount of food, usually without interest or enjoyment, like a bird does.","ko":"새처럼 관심이나 즐거움 없이 음식의 아주 적은 양만 먹는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0739","en":"peel off","definition":"to take the outer layer or covering off something, such as clothes or the skin of a fruit or vegetable.","ko":"옷이나 과일 또는 채소의 껍질 등 무엇의 겉면이나 덮개를 벗기다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0740","en":"peg down","definition":"To fix or secure something to the ground using pegs, like making sure a tent or cover stays in place.","ko":"보통 세부사항이나 합의를 확정하여 어떤 것을 확실하고, 명확하고, 분명하게 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0741","en":"pelt along","definition":"To move very quickly, especially by running or driving fast.","ko":"특히 뛰거나 빨리 운전하면서 매우 빠르게 움직이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0742","en":"perk up","definition":"to make someone feel more lively, energetic, or cheerful; or to become more active and alert","ko":"누군가를 더 활기차고, 에너지가 넘치고, 명랑하게 만들다; 또는 더 활발하고 민첩해지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0743","en":"persist in","definition":"to keep doing something, especially when it is difficult or when others want you to stop","ko":"어렵거나 다른 사람들이 그만두길 원할 때에도 계속 무언가를 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0744","en":"phase in","definition":"to slowly start using or introducing something new in stages instead of all at once","ko":"새로운 것을 한 번에가 아니라 여러 단계에 걸쳐 천천히 사용하거나 도입하기 시작하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0745","en":"phase out","definition":"to gradually stop using or providing something","ko":"무엇을 점진적으로 사용하지 않거나 제공하지 않게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0746","en":"pick at","definition":"To criticize someone or something repeatedly, often about small or unimportant things.","ko":"대개 흥미나 식욕 없이 음식을 조금만 먹는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0747","en":"pick out","definition":"to choose or recognize something from a group of things or people","ko":"여러 물건이나 사람들 중에서 어떤 것을 고르거나 알아보다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0748","en":"pick up","definition":"to buy something casually or without much planning, usually while doing something else.","ko":"특히 누군가가 슬프거나 피곤할 때 더 기분이 좋아지거나 행복해지게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0749","en":"pig out","definition":"to eat much more food than you need, especially in a greedy way","ko":"특히 탐욕스럽게 필요한 것보다 훨씬 많이 먹다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0750","en":"pile up","definition":"To increase in quantity or amount, usually in a way that makes something hard to manage.","ko":"양이 늘어나서 관리하기 힘들어지는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0751","en":"pin down","definition":"to make someone or something stay in one place or to make someone give a clear answer or decision","ko":"누군가나 무언가를 한 곳에 머물게 하거나, 누군가로부터 명확한 답변이나 결정을 얻어내는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0752","en":"pin up","definition":"To fasten something to a wall or board using a pin, thumbtack, or similar object.","ko":"핀이나 압정으로 무언가를 벽이나 보드에 붙이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0753","en":"pine away","definition":"To become very sad and weak because you miss someone or something a lot for a long time.","ko":"누군가나 무언가를 오랫동안 많이 그리워해서 매우 슬프고 약해지는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0754","en":"pipe down","definition":"To stop making noise or talking; to be quiet.","ko":"소리내거나 말하는 것을 멈추다; 조용히 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0755","en":"pipe up","definition":"to suddenly start talking, especially when you were silent before or when everyone else is quiet","ko":"전에는 조용히 있다가 갑자기 말하기 시작하다, 또는 모두가 조용할 때 갑자기 말하기 시작하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0756","en":"pitch in","definition":"to help out or join in with others to do a task, especially by contributing effort or assistance.","ko":"특히 노력이나 도움을 제공하여 다른 사람들과 함께 일을 돕거나 참여하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0757","en":"place down","definition":"to gently put something onto a surface.","ko":"무언가를 조심스럽게 표면에 내려놓다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0758","en":"plaster over","definition":"to cover something, such as a hole or crack in a wall, with plaster to make it smooth and hidden","ko":"벽의 구멍이나 균열 등을 석고로 덮어 매끄럽고 보이지 않게 만드는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0759","en":"play along","definition":"to pretend to agree or cooperate with someone, usually to avoid problems or to make things easier","ko":"문제를 피하거나 일을 쉽게 하기 위해 누군가에게 동의하는 척하거나 협조하는 척하는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0760","en":"play around","definition":"to act in a silly or playful way and not be serious","ko":"장난치거나 진지하지 않게 행동하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0761","en":"play down","definition":"To make something seem less important, serious, or bad than it really is.","ko":"어떤 것을 실제보다 덜 중요하거나 심각하거나 나쁘게 보이도록 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0762","en":"play off","definition":"To make two or more people or groups compete against each other, usually to gain an advantage for yourself.","ko":"보통 자신의 이익을 위해 두 명 이상의 사람이나 집단을 서로 경쟁하게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0763","en":"play up","definition":"to emphasize or make something or someone seem more important, impressive, or better than they really are.","ko":"무엇이나 누구를 실제보다 더 중요하거나 인상적이거나 뛰어나게 보이도록 강조하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0764","en":"pluck at","definition":"to gently pull or tug repeatedly at something, often because you are nervous, bored, or distracted.","ko":"긴장하거나, 지루하거나, 산만해서 무언가를 부드럽게 혹은 반복적으로 잡아당기다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0765","en":"plump up","definition":"To make something, like a pillow or cushion, look fuller or softer by shaking or patting it.","ko":"베개나 쿠션 등을 두드리거나 흔들어서 더 푹신하게 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0766","en":"point out","definition":"to show or mention something or someone so that others notice or understand it","ko":"다른 사람들이 알거나 이해할 수 있도록 무언가나 누군가를 보여주거나 언급하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0767","en":"poke around","definition":"to look for something in a place by searching through things in a casual or curious way","ko":"어떤 것을 찾기 위해 장소를 이리저리 뒤지거나 호기심으로 살펴보다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0768","en":"poke out","definition":"If something pokes out, it sticks out or comes out a little from behind or inside something else.","ko":"어떤 것이 튀어나오면, 그것은 다른 것에서 약간 밖으로 나오거나 드러나 보입니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0769","en":"polish off","definition":"To finish something quickly and completely, especially food or tasks.","ko":"특히 음식이나 과제를 빠르고 완전히 끝내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0770","en":"polish up","definition":"to make something better, cleaner, or more skillful through practice or effort","ko":"연습이나 노력으로 무언가를 더 잘하거나, 깨끗하게 하거나, 능숙하게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0771","en":"pop in","definition":"To quickly visit a place for a short time.","ko":"어딘가에 잠깐 들르다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0772","en":"pop out","definition":"to leave a place for a short time, usually to do something quickly and then come back","ko":"어딘가를 잠깐 다녀오다, 보통 빨리 어떤 일을 하고 다시 돌아오다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0773","en":"pop up","definition":"to appear or happen suddenly, often when you do not expect it","ko":"예상치 못할 때 갑자기 나타나거나 발생하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0774","en":"portion out","definition":"to divide something into parts and give each person an equal share","ko":"무언가를 나누어 각 사람에게 똑같은 몫을 주다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0775","en":"potter around","definition":"to spend time in a relaxed way, doing small and unimportant things, usually without any real purpose","ko":"진짜 목적 없이, 작은 일들을 하면서 느긋하게 시간을 보내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0776","en":"pour out","definition":"to express your true feelings or thoughts in a very open and emotional way, especially by talking to someone you trust","ko":"무언가에서 많은 양이나 숫자가 빠르게 쏟아져 나오다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0777","en":"prepare for","definition":"To get ready for something that will happen, or to help someone get ready for something.","ko":"곧 일어날 일에 대비하거나, 누군가가 그것에 대비하도록 돕는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0778","en":"press down","definition":"to push something or someone downward, usually using your hand or another object.","ko":"손이나 다른 물건으로 무엇이나 누군가를 아래로 누르다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0779","en":"press on","definition":"to keep going with something, especially when it is difficult or after a pause.","ko":"특히 어렵거나 잠시 멈춘 후에도 계속하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0780","en":"press out","definition":"To use force or pressure to remove something from an object, usually by squeezing or flattening.","ko":"보통 짜거나 눌러서 물건에서 무언가를 힘이나 압력으로 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0781","en":"progress to","definition":"to move forward and reach a later or more advanced stage of something","ko":"앞으로 나아가서 더 늦거나 더 발전된 단계에 도달하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0782","en":"prop up","definition":"To support something by putting something under or behind it to keep it from falling down.","ko":"무언가가 넘어지지 않도록 아래나 뒤에 무언가를 대어 받쳐 주다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0783","en":"provide with","definition":"to give someone something that they need or want","ko":"누군가에게 필요한 것 또는 원하는 것을 주다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0784","en":"puff out","definition":"To swell, expand, or make something bigger by filling it with air or by tensing the muscles.","ko":"공기를 넣거나 근육을 긴장시켜 부풀다, 또는 무언가를 더 크게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0785","en":"puff up","definition":"To talk about someone or yourself in a way that makes them or you seem more important or impressive.","ko":"자신이나 다른 사람을 더 중요하거나 인상적으로 보이게 말하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0786","en":"pull away","definition":"To move farther from someone or something, either physically or emotionally.","ko":"누구나 또는 무엇에서 물리적 또는 감정적으로 멀어지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0787","en":"pull down","definition":"to destroy a building or structure, usually so that something else can be built in its place.","ko":"누군가를 불행하거나 슬프거나 기운이 빠지게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0788","en":"pull in","definition":"to attract a lot of people, attention, or money.","ko":"많은 사람들, 관심 또는 돈을 끌어들이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0789","en":"pull off","definition":"to succeed in doing something difficult or unexpected","ko":"잡아당겨서 떼어내다, 끌어당겨 제거하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0790","en":"pull out","definition":"to withdraw or remove people or things from a place, especially in an official or organized way.","ko":"특히 공식적이거나 조직적인 방법으로 사람이나 물건을 장소에서 철수시키거나 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0791","en":"pull over","definition":"to move your vehicle to the side of the road and stop, usually for a short time.","ko":"차를 길가에 세우고 잠시 정차하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0792","en":"pull round","definition":"to start feeling better after being sick or having a difficult time. Similar to 'recover' or 'get better'.","ko":"아프거나 힘든 시간을 보낸 후에 다시 좋아지기 시작하다. '회복하다'와 비슷한 의미.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0793","en":"pull through","definition":"To get better after a serious illness or difficult situation; to survive or recover successfully.","ko":"심각한 병이나 어려운 상황을 극복하고 회복하다; 무사히 살아남다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0794","en":"pull up","definition":"to tell someone that they have done something wrong or to criticize them for their behavior","ko":"차를 어떤 장소로 몰고 가서 그곳에 세우다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0795","en":"punch in","definition":"To record the time you arrive at work, usually by using a time clock or a special machine. This is often done in workplaces to keep track of employees' working hours. Synonym: 'clock in'.","ko":"출근 시간을 기록하다. 보통 근태 기록기나 특수 기계를 사용하여 직원의 근무 시간을 관리할 때 사용한다. 동의어: '출근 체크하다'.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0796","en":"punch out","definition":"To officially record the end of your working hours by using a time clock at your workplace.","ko":"직장에서 근무시간 종료를 근태기 등으로 공식적으로 기록하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0797","en":"push around","definition":"To treat someone in a rude or bossy way, telling them what to do without respect.","ko":"누군가를 무례하거나 거만하게 대하며 존중 없이 명령하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0798","en":"push away","definition":"To move someone or something away from yourself by using your hands or body. It can also mean to avoid people emotionally or stop them from getting close to you.","ko":"손이나 몸을 이용해 누군가 또는 무언가를 자신으로부터 멀리 밀어내는 것. 또한 감정적으로 사람들을 회피하거나 가까워지지 못하게 하는 것을 의미할 수 있음.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0799","en":"push down","definition":"to press or move someone or something to a lower position, usually using your hand or another part of your body.","ko":"손이나 신체의 다른 부분을 사용하여 누군가 또는 무언가를 더 낮은 위치로 누르거나 움직이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0800","en":"push on","definition":"to continue moving forward or to make someone or something continue moving forward, especially when it is difficult","ko":"특히 어려울 때 계속 앞으로 나아가거나 누구 또는 무엇을 계속 앞으로 나아가게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0801","en":"push out","definition":"to make someone or something leave a place or position, often by using force or pressure.","ko":"누군가나 무언가를 힘이나 압력으로 장소나 지위에서 떠나게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0802","en":"push through","definition":"To succeed in making something happen or to move forward despite difficulties or obstacles.","ko":"어려움이나 장애에도 불구하고 무언가를 이루거나 앞으로 나아가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0803","en":"push up","definition":"to move something or someone to a higher position by using force from below","ko":"아래에서 힘을 주어 무언가나 누군가를 더 높은 위치로 옮기다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0804","en":"put across","definition":"to explain an idea, opinion, or message so that people understand it clearly","ko":"아이디어, 의견 또는 메시지를 사람들이 명확하게 이해할 수 있도록 설명하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0805","en":"put away","definition":"To eat a large amount of food, especially quickly or easily.","ko":"무엇인가를 제자리나 적절한 곳에 두어 정리되고 치워지게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0806","en":"put down","definition":"to write something on a list or record it in writing","ko":"상처주는 말을 하거나, 비판하거나 모욕해서 누군가를 덜 중요하게 느끼게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0807","en":"put in","definition":"to submit something such as an application, request, or order formally","ko":"무엇인가를 설치하거나 추가하여 사용할 준비가 되도록 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0808","en":"put off","definition":"to delay doing something or decide to do it at a later time","ko":"누군가가 누군가 또는 무언가를 싫어하거나 흥미를 잃게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0809","en":"put on","definition":"to trick or tease someone by making them believe something that is not true","ko":"옷이나 액세서리를 착용하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0810","en":"put out","definition":"to move something away from your body so that it is extended in front of you or to the side.","ko":"무언가를 대중이 볼 수 있도록 출판하거나 출시하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0811","en":"put through","definition":"to connect someone to another person on the phone","ko":"전화를 통해 누군가를 다른 사람에게 연결해 주다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0812","en":"put under","definition":"to give someone medicine (anesthesia) to make them sleep or unconscious, usually before surgery or a medical procedure","ko":"누군가를 잠들거나 의식을 잃게 하기 위해 약(마취제)을 투여하다. 보통 수술이나 의료 시술 전에 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0813","en":"put up","definition":"to let someone stay at your home for a short time, usually as a guest","ko":"무엇의 가격이나 비용을 올리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0814","en":"put up with","definition":"to accept or deal with someone or something unpleasant without complaining","ko":"불쾌한 사람이나 일을 불평하지 않고 받아들이거나 참다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0815","en":"puzzle out","definition":"to find the answer to something that is confusing or difficult to understand.","ko":"혼란스럽거나 이해하기 어려운 것의 답을 찾다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0816","en":"puzzle over","definition":"to spend time thinking carefully about something because it is difficult to understand or solve","ko":"이해하거나 해결하기 어려워서 어떤 것에 대해 신중하게 생각하는 데 시간을 들이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0817","en":"queue up","definition":"To stand in a line and wait for your turn to get or do something. This phrase is mostly used in British English.","ko":"무언가를 얻거나 하려고 자신의 차례를 기다리며 줄을 서는 것. 이 표현은 주로 영국식 영어에서 사용됩니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0818","en":"quiet down","definition":"To make someone or something less noisy, or to become less noisy and calmer.","ko":"누군가 또는 무언가를 덜 시끄럽게 만들거나, 더 조용해지고 차분해지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0819","en":"rack up","definition":"To collect or achieve a large number or amount of something over time, especially points, money, or achievements.","ko":"특히 점수, 돈, 성과 등을 시간에 걸쳐 많이 모으거나 달성하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0820","en":"raffle off","definition":"To give something away as a prize in a lottery, usually to raise money for a cause.","ko":"무언가를 경품으로 내놓아 복권 등으로 추첨하여 배포하다(보통 자선 모금 목적으로 사용됨).","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0821","en":"rail in","definition":"to put a fence, rail, or barrier around something to enclose or protect it","ko":"무언가를 둘러싸거나 보호하기 위해 울타리, 난간, 장벽 등을 설치하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0822","en":"rain down","definition":"to fall or be sent in large amounts onto someone or something, as if it were rain.","ko":"비처럼 대량으로 누군가 또는 무언가 위에 내리거나 쏟아지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0823","en":"rain out","definition":"To cancel or stop an outdoor event because it is raining.","ko":"비 때문에 야외 행사를 취소하거나 중단하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0824","en":"raise up","definition":"to lift something or someone to a higher position","ko":"무엇이나 누군가를 더 높은 위치로 들어올리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0825","en":"rake in","definition":"To earn or collect a large amount of money, often easily or quickly.","ko":"쉽거나 빠르게 많은 돈을 벌거나 모으다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0826","en":"rake off","definition":"to take a part of money or profits for yourself, often in a secret or dishonest way","ko":"돈이나 이익의 일부를 자신의 몫으로, 종종 비밀스럽거나 부정하게 챙기다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0827","en":"rake up","definition":"to mention, talk about, or draw attention to something unpleasant or embarrassing from the past that people may want to forget.","ko":"사람들이 잊고 싶어하는 과거의 불쾌하거나 난처한 일을 언급하거나 주목하게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0828","en":"ram down","definition":"to force someone to accept or learn something, especially in a way that is too strong or aggressive","ko":"무언가를 강한 힘이나 압력으로 아래로 밀어 넣거나 누르는 것, 빽빽하게 또는 단단하게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0829","en":"ramble on","definition":"to talk for a long time in a disorganized or boring way, often without getting to the point, especially about someone or something.","ko":"누구나 무엇에 대해 장황하고 산만하거나 지루하게, 요점 없이 오래 이야기하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0830","en":"ramp up","definition":"To gradually increase the amount, speed, or strength of something, especially in business or production.","ko":"특히 비즈니스나 생산에서 어떤 것의 양, 속도 또는 강도를 점진적으로 늘리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0831","en":"range in","definition":"To automatically focus on or aim at a specific target, especially by using technology or navigation systems.","ko":"특히 기술이나 내비게이션 시스템을 사용하여 특정 대상을 자동으로 초점 맞추거나 조준하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0832","en":"ratchet down","definition":"to gradually reduce the level or amount of something","ko":"무엇의 수준이나 양을 점차 줄이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0833","en":"ration out","definition":"to give people a limited or fixed amount of something, especially so it lasts longer or everyone gets a share.","ko":"사람들에게 어떤 것을 더 오래가게 하거나 모두가 나눠 갖게 하기 위해 제한된 양만 나누어 주다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0834","en":"rattle off","definition":"To say or list something quickly, without pausing or stopping, usually from memory.","ko":"멈추지 않고 보통 암기로 무언가를 빠르게 말하거나 나열하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0835","en":"rattle on","definition":"To keep talking for a long time in a way that is boring or not important, especially about something or someone.","ko":"특별히 중요하지 않거나 지루한 방식으로 오랫동안 이야기하다, 특히 어떤 것 또는 사람에 대해서.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0836","en":"reach into","definition":"to put your hand inside something, like a bag or a container, usually to get something out","ko":"무언가(가방이나 용기 등) 안에 손을 넣어 보통 무언가를 꺼내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0837","en":"reach out","definition":"To contact someone, usually for help, support, or to offer help.","ko":"누군가에게 연락하다. 보통 도움이나 지원을 요청하거나 제공하기 위해.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0838","en":"reel off","definition":"to say or list information, facts, or things quickly, usually from memory, and often without stopping or thinking much.","ko":"정보나 사실 등을 빠르게 (보통 암기해서) 말하다, 생각하지 않고 쉼 없이 나열하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0839","en":"reel out","definition":"to gradually let out something that is wound or rolled up, such as string, wire, or hose.","ko":"실, 철사, 호스와 같이 감겨 있던 것을 점차 풀어내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0840","en":"regard to","definition":"Used to introduce a topic or refer to something specific. It means 'about' or 'concerning' something.","ko":"특정 주제를 소개하거나 무언가를 언급할 때 사용됩니다. '~에 관하여' 또는 '~에 대해'라는 의미입니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0841","en":"rein in","definition":"To control or limit someone or something; to stop them from becoming too extreme or out of control.","ko":"누군가나 무언가를 통제하거나 제한하다; 너무 극단적이거나 통제불능이 되는 것을 막다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0842","en":"rely on","definition":"to depend on someone or something because you trust them or believe they will help or support you.","ko":"누군가 또는 무언가가 도와주거나 지원해줄 것이라고 믿고 의지하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0843","en":"renege on","definition":"to not do what you promised or agreed to do; to break a promise or agreement","ko":"약속이나 합의를 지키지 않다; 약속이나 합의를 어기다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0844","en":"rent out","definition":"to let someone use your property or something you own for a period of time in exchange for money","ko":"누군가에게 자신의 재산이나 소유물을 일정 기간 돈을 받고 빌려주다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0845","en":"rest on","definition":"to depend or be based on something.","ko":"무엇에 의존하거나 기반하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0846","en":"rev up","definition":"To make something go faster, become more active, or become more exciting.","ko":"무언가를 더 빠르게 하거나, 더 활발하게 하거나, 더 흥미롭게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0847","en":"revolve around","definition":"to have someone or something as the main or most important focus or purpose; to be centered on something or someone.","ko":"누군가나 무언가를 주요 초점 또는 목적(중심)으로 삼다; ~을 중심으로 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0848","en":"rid of","definition":"to remove or get free from someone or something you don't want.","ko":"원하지 않는 사람이나 것을 제거하거나 벗어나다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0849","en":"ride away","definition":"To leave a place by traveling on something like a bicycle, horse, or motorbike.","ko":"자전거, 말, 오토바이 등 무언가를 타고 자리를 떠나다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0850","en":"ride out","definition":"To stay strong and get through a difficult or unpleasant situation until it ends.","ko":"힘들고 불쾌한 상황이 끝날 때까지 강하게 버티다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0851","en":"rig up","definition":"to quickly put together or build something using whatever materials are available, usually for a short-term use.","ko":"손에 있는 재료로 급히 무언가를 조립하거나 만들어내다. 보통 임시로 사용하기 위해서이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0852","en":"right on","definition":"Used to show strong agreement with someone or to say that what they said is exactly right.","ko":"누군가에게 강한 동의를 보이거나 그 말이 정확하다는 것을 표현할 때 사용합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0853","en":"ring out","definition":"to make a loud, clear sound that can be easily heard, especially suddenly or in a quiet place.","ko":"조용한 장소나 갑자기, 쉽게 들릴 수 있는 크고 또렷한 소리를 내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0854","en":"ring up","definition":"to enter the price of goods and record a sale on a cash register, usually in a store","ko":"가게에서 계산기(포스기)에 상품의 가격을 입력하고 판매를 기록하는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0855","en":"rinse off","definition":"To quickly wash someone or something with clean water to remove soap, dirt, or another substance.","ko":"비누, 먼지 또는 다른 물질을 제거하기 위해 누군가나 무언가를 깨끗한 물로 빠르게 씻어내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0856","en":"rip off","definition":"to charge someone too much money or cheat them, especially by selling something at a very high price","ko":"누군가에게 너무 비싼 값을 청구하거나, 특히 물건을 매우 비싼 가격에 팔아 속이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0857","en":"rip up","definition":"To tear something into small pieces, usually with your hands.","ko":"무언가를 손으로 작은 조각으로 찢다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0858","en":"rise up","definition":"to fight back or take action against people in power, usually to protest or change something unfair","ko":"권력자들에 맞서 싸우거나 부당한 것을 바꾸기 위해 행동에 나서다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0859","en":"roar off","definition":"to leave a place very quickly and noisily, usually in a vehicle.","ko":"보통 차량으로, 매우 빠르고 시끄럽게 장소를 떠나다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0860","en":"roll in","definition":"To arrive in large numbers or amounts, often continuously or unexpectedly.","ko":"많이, 자주 계속적이거나 예상치 못하게 도착하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0861","en":"roll off","definition":"To say or repeat something quickly and easily from memory, often without much effort.","ko":"무언가를 기억에서 빠르고 쉽게, 종종 아무런 노력 없이 말하거나 반복하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0862","en":"roll out","definition":"to make something flat by unrolling it, or to make something available for the first time, like a product or service.","ko":"무언가를 펼쳐서 평평하게 만들거나, 신제품이나 서비스를 처음으로 출시하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0863","en":"roll over","definition":"to delay or move a payment, contract, or debt to a later date.","ko":"지불, 계약 또는 부채를 나중 날짜로 연기하거나 미루다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0864","en":"roll up","definition":"To fold or turn something over and over to make it into the shape of a tube or bundle.","ko":"무언가를 여러 번 접거나 말아서 관이나 다발 모양으로 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0865","en":"rope in","definition":"To persuade or trick someone into taking part in something, especially when they didn't really want to.","ko":"누군가를 설득하거나 속여서 어떤 일에 참여하게 하다, 특히 그 사람이 원하지 않았을 때.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0866","en":"rope off","definition":"to close or block an area using a rope, so that people cannot enter it","ko":"사람들이 들어가지 못하게 밧줄로 구역을 막거나 차단하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0867","en":"rough up","definition":"to hurt someone by hitting or using violence, often to scare or threaten them.","ko":"누군가를 때리거나 폭력을 사용하여 해치다. 주로 겁주거나 위협하기 위해 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0868","en":"round down","definition":"To make a number or amount lower by changing it to the nearest whole number less than or equal to it.","ko":"숫자나 금액을 그 값 이하의 가장 가까운 정수로 낮추는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0869","en":"round off","definition":"To change a number to the nearest whole number, often to make it simpler or easier to use.","ko":"만족스럽거나 적합한 방식으로 무언가를 마무리하다; 아름답게 완성하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0870","en":"round out","definition":"To make something complete or finished by adding one last thing.","ko":"마지막으로 무언가를 추가하여 완성하거나 마무리하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0871","en":"round up","definition":"to gather people or things together in one place","ko":"사람이나 물건을 한 곳에 모으다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0872","en":"rout out","definition":"to force someone or something to leave a place, usually by searching for them or making them go out","ko":"누군가 또는 무언가를 찾아내거나 내보내어 억지로 그 장소에서 떠나도록 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0873","en":"rub down","definition":"to gently massage or clean something by rubbing it, usually to help someone relax or to clean the surface of something","ko":"누군가를 편안하게 해주거나 표면을 깨끗이 하기 위해, 부드럽게 문질러 마사지하거나 닦는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0874","en":"rub off","definition":"To remove something from a surface by rubbing it with your hand or a cloth.","ko":"손이나 천으로 문질러 표면에서 무언가를 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0875","en":"rub out","definition":"to remove marks, writing, or drawings from a surface by rubbing it with your hand, an eraser, or something similar.","ko":"손, 지우개 또는 비슷한 것으로 표면의 자국, 글씨 또는 그림을 문질러서 지우다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0876","en":"rule out","definition":"To decide that something is not possible or not suitable, or to reject an option or person from consideration.","ko":"무엇인가가 가능하지 않거나 적합하지 않다고 판단하거나, 고려 대상에서 옵션이나 사람을 제외하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0877","en":"run across","definition":"to find or meet someone or something by chance.","ko":"누군가나 무언가를 우연히 만나거나 발견하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0878","en":"run around","definition":"to be very busy, moving from one place to another to do many tasks","ko":"많은 일을 하려고 여기저기 바쁘게 돌아다니다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0879","en":"run away","definition":"to leave a place or person suddenly, especially to escape from a difficult or dangerous situation.","ko":"특히 어려운 상황이나 위험한 상황에서 벗어나기 위해 장소나 사람을 갑자기 떠나다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0880","en":"run down","definition":"to use something until there is nothing left or until it stops working","ko":"너무 많이 일하거나 자기관리를 하지 않아 매우 피곤하고, 약하거나 기력이 없는 상태를 나타냄.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0881","en":"run for","definition":"If a performance, event, or show runs for a certain period, it means it is available or continues happening for that amount of time.","ko":"공연, 행사, 쇼가 일정 기간 동안 진행된다는 것은 그 기간 동안 이용 가능하거나 계속된다는 것을 의미합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0882","en":"run into","definition":"to reach or experience a large amount of something, usually a problem or a high cost","ko":"주로 문제나 많은 비용 등, 큰 양의 어떤 것에 도달하거나 경험하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0883","en":"run off","definition":"to flow or drain away from a surface, especially liquids like water.","ko":"누군가나 무언가를 쫓아서 그 장소를 떠나게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0884","en":"run on","definition":"To keep talking for a long time, usually in a boring or annoying way, especially without stopping or getting to the point.","ko":"예상보다 더 오래 계속되거나 멈추지 않고 지속되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0885","en":"run out","definition":"to finish all of something so that none is left.","ko":"무언가를 모두 써서 남는 것이 없게 되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0886","en":"run over","definition":"To hit someone or something with a vehicle and drive over it.","ko":"너무 많아서 무언가의 가장자리 밖으로 넘치거나 흘러나오는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0887","en":"run through","definition":"to use up or spend something, such as money or resources, very quickly","ko":"돈이나 자원 등을 매우 빠르게 다 써버리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0888","en":"run up","definition":"to cause a debt, bill, or cost to increase quickly, usually by spending a lot of money (especially on credit or bills)","ko":"빚, 청구서, 비용 등을 (주로 신용카드나 청구서로) 빠르게 늘리다, 많은 돈을 써서 늘리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0889","en":"rush along","definition":"To move quickly from one place to another because you are in a hurry.","ko":"서두르기 때문에 한 장소에서 다른 장소로 빠르게 이동하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0890","en":"sail through","definition":"To complete something, like a test or process, very easily and successfully, with little difficulty.","ko":"시험이나 과정과 같은 일을 매우 쉽게, 성공적으로, 거의 어려움 없이 끝내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0891","en":"save up","definition":"to keep money over time so you can buy something in the future","ko":"미래에 무언가를 사기 위해 돈을 모으다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0892","en":"scale down","definition":"To reduce the size, amount, or extent of something.","ko":"무언가의 크기, 양, 범위를 줄이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0893","en":"scale up","definition":"to make something bigger or increase it in size, amount, or importance, especially in a planned way","ko":"특히 계획적으로 무언가를 더 크거나, 양이나 중요성을 증가시키는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0894","en":"scare away","definition":"To make someone or something go away by making them feel afraid.","ko":"누군가나 무언가를 겁을 주어 쫓아내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0895","en":"scoop out","definition":"To remove something from inside a container or place using a spoon or similar tool.","ko":"숟가락이나 비슷한 도구로 용기나 장소 안에서 무언가를 꺼내는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0896","en":"scoop up","definition":"To quickly pick up or gather something, usually with your hands or a tool.","ko":"무엇인가를 손이나 도구로 재빠르게 집거나 모으다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0897","en":"scrape by","definition":"to manage to get by or survive with just enough, often with difficulty; to have barely enough money, resources, or success to get through a situation","ko":"간신히 넘기다, 겨우겨우 살아가다; 돈이나 자원이 부족한 상황에서 가까스로 버티거나 살아남다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0898","en":"scratch out","definition":"To remove something, like a word or name, by drawing a line through it.","ko":"단어나 이름 등을 줄을 그어 지우다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0899","en":"screen off","definition":"To separate someone or something from an area by using a screen or a divider, so they are hidden or blocked from view.","ko":"누군가나 무언가를 스크린이나 칸막이로 구분해서 보이지 않게 하거나 차단하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0900","en":"screw up","definition":"To make a mistake or do something badly, causing a problem or failure.","ko":"실수하거나 일을 망쳐서 문제나 실패를 일으키는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0901","en":"scrunch up","definition":"to squeeze or crush something into a smaller, often wrinkled or messy shape","ko":"무언가를 작은 주름지거나 지저분한 모양으로 압착하거나 구기다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0902","en":"seal off","definition":"to block or close an area or object so that nothing can enter or leave","ko":"아무것도 들어오거나 나가지 못하도록 구역이나 물체를 봉쇄하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0903","en":"see through","definition":"to realize that someone is lying or not being sincere","ko":"어려운 시기에 문제를 해결할 때까지 돈이나 격려 등으로 누군가를 도와주거나 지지하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0904","en":"seek out","definition":"to look carefully for someone or something, especially when it is hard to find.","ko":"특히 찾기 어려운 사람이나 것을 신중하게 찾다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0905","en":"sell off","definition":"To quickly sell something, usually at a low price, because it is no longer needed or you want to get rid of it.","ko":"더 이상 필요 없거나 처분하려고 보통 낮은 가격에 무언가를 빨리 파는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0906","en":"sell out","definition":"To sell all of something so that there is none left.","ko":"누군가를 배신하거나, 보통 돈이나 승인과 같은 개인적 이득을 위해 자신의 가치를 포기하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0907","en":"sell up","definition":"to sell all your possessions, property, or business, often because you are moving or starting a new life elsewhere.","ko":"자신의 모든 소유물이나 재산, 사업을 모두 파는 것, 보통 이사를 가거나 새로운 삶을 시작할 때 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0908","en":"send around","definition":"to share something with a group of people, usually by physically giving it to each person or by sending it to each member of a group","ko":"무언가를 그룹 사람들과 공유하다. 보통 각자에게 직접 전달하거나 각 구성원에게 보내는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0909","en":"send for","definition":"to ask someone to come to help or do something, usually by sending a message or making a request","ko":"주로 메시지나 요청을 보내어 누군가를 오도록 하거나, 무언가를 가져오게 요청하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0910","en":"send in","definition":"to submit something, like a form, assignment, or application, by post or online for someone to review or process","ko":"양식, 과제, 신청서 등을 우편이나 온라인으로 제출하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0911","en":"send on","definition":"to forward something, like a message, letter, or parcel, to another person or place","ko":"메시지, 편지, 소포 등을 다른 사람이나 장소로 전달(전송)하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0912","en":"send out","definition":"to give or deliver something, like messages, invitations, or information, to many people at once.","ko":"메시지, 초대장 또는 정보를 여러 사람에게 한 번에 전달하거나 발송하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0913","en":"set about","definition":"to attack someone physically or verbally","ko":"무엇인가를 시작하다, 특히 노력이나 계획이 필요한 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0914","en":"set down","definition":"To write something, usually to record information or ideas so you don’t forget them.","ko":"들고 있던 것을 표면에 내려놓다; 조심스럽게 내려두다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0915","en":"set off","definition":"to start a journey or leave for a place.","ko":"특히 갑자기 어떤 일이 일어나거나 시작되도록 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0916","en":"set out","definition":"to arrange or display things in an organized way, often so they can be seen or used easily","ko":"물건을 보기 쉽고 사용하기 쉽도록 정리해서 배열하거나 배치하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0917","en":"set up","definition":"to arrange, organize, or prepare something, such as an event, a piece of equipment, or a business","ko":"누군가를 속여서 죄를 뒤집어씌우다, 특히 그 사람이 하지도 않은 일로 곤란하게 만들거나 비난받게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0918","en":"settle down","definition":"To become calm and quiet, or to help someone or something become calm and quiet.","ko":"차분하고 조용해지거나, 누군가나 무언가를 차분하고 조용하게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0919","en":"settle on","definition":"To finally choose or decide on something after considering different options.","ko":"여러 가지 선택지를 고려한 후 결국 어떤 것을 선택하거나 결정하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0920","en":"shack up","definition":"to live together with someone as a couple, usually without being married","ko":"보통 결혼하지 않고 커플로서 함께 살다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0921","en":"shake off","definition":"To get rid of someone or something that is bothering you or holding you back.","ko":"귀찮거나 방해가 되는 사람이나 것을 떨쳐내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0922","en":"shake up","definition":"to move something quickly up and down or side to side so that the contents mix together well","ko":"누군가를 갑자기 놀라게 하거나 충격을 주어 당황하게, 걱정하게, 불안하게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0923","en":"shape up","definition":"to improve or develop in a good way; to progress well.","ko":"좋은 방향으로 개선되거나 발전하다; 잘 진행되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0924","en":"shine at","definition":"To do something very well or be very good at a particular activity.","ko":"무언가를 매우 잘 하거나 특정 활동에서 매우 뛰어나다는 의미입니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0925","en":"shoot down","definition":"To fire a weapon at something, like an aircraft, so that it falls to the ground; often used when talking about military situations.","ko":"무기 등으로 비행기 같은 것을 쏴서 떨어뜨리다; 주로 군사 상황에서 사용함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0926","en":"shoot for","definition":"To try to achieve or reach a specific goal or result.","ko":"특정 목표나 결과를 이루려고 노력하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0927","en":"shoot up","definition":"to rise or increase very quickly in a short time","ko":"아주 짧은 시간에 매우 빠르게 오르다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0928","en":"shoulder into","definition":"to push your way into a place or group using your shoulders, usually to get past people or into a crowded area","ko":"어깨로 밀치며 사람들 사이로 밀고 들어가다(보통 붐비는 곳이나 군중 속으로)","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0929","en":"shout out","definition":"to say something loudly, often so everyone can hear","ko":"모두가 들을 수 있도록 무언가를 크게 말하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0930","en":"shovel in","definition":"To quickly put a lot of something, especially food, into your mouth or another place without much care.","ko":"특히 음식을 빠르게, 신경 쓰지 않고 입이나 다른 곳에 많이 집어넣다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0931","en":"show off","definition":"to try to get people's attention by displaying something or by behaving in a way that makes others notice you, usually because you are proud of it.","ko":"무언가를 자랑하거나, 사람들의 관심을 끌기 위해 일부러 행동하는 것 (보통 자랑스러워서).","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0932","en":"show up","definition":"to arrive at a place where you are expected, especially for an event, appointment, or meeting.","ko":"숨겨져 있거나 잘 보이지 않던 것이 보이거나 눈에 띄게 되다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0933","en":"shrink from","definition":"to avoid doing something because it is unpleasant or difficult, often by hesitating or pulling back.","ko":"불쾌하거나 어려운 일을 피하기 위해 망설이거나 물러서는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0934","en":"shrivel up","definition":"To become dry, smaller, and wrinkled, usually because of losing water.","ko":"물기를 잃어 말라서 작아지고 주름지는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0935","en":"shrug off","definition":"To ignore something or someone because you think it or they are not important.","ko":"중요하지 않다고 생각하여 무엇이나 누구를 무시하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0936","en":"shut away","definition":"To keep someone in a place where they cannot leave, often for a long time, usually because of punishment or to protect them or others.","ko":"누군가를 벌이나 보호를 위해 오랫동안 밖으로 나갈 수 없는 곳에 가두다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0937","en":"shut down","definition":"to turn something off or stop it from working, usually a machine, computer, or business.","ko":"보통 기계, 컴퓨터, 사업체 등을 끄거나 중지시키는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0938","en":"shut in","definition":"to keep someone or something inside a place and not let them leave, usually by closing a door or barrier.","ko":"누군가 또는 무언가를 안에 두고 나가지 못하게 하다. 보통 문이나 장애물을 닫아서 막는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0939","en":"shut off","definition":"to turn something off so it stops working or flowing, like water, electricity, or a machine.","ko":"누군가나 무언가를 다른 사람들과의 연결이나 접촉에서 차단하거나 고립시키다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0940","en":"shut out","definition":"To not let someone or something be involved or enter a place, group, or activity.","ko":"누군가나 무언가가 어떤 장소, 그룹, 활동에 참여하거나 들어오지 못하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0941","en":"shut up","definition":"To stop talking or to make someone or something stop talking or making noise.","ko":"말을 멈추거나 누군가 또는 무언가가 말하거나 소리 내는 것을 멈추게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0942","en":"shy away from","definition":"to avoid someone or something, especially because you feel nervous, unsure, or not confident.","ko":"긴장하거나 자신이 없어서 누군가나 무언가를 피하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0943","en":"sidle up","definition":"to approach someone quietly or slowly, often so that you are not noticed right away","ko":"누군가에게 조용히 또는 천천히 다가가서 바로 눈에 띄지 않도록 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0944","en":"sign away","definition":"to give up your rights, property, or ownership of something by signing a legal document.","ko":"법적 문서에 서명함으로써 권리, 재산, 소유권 등을 포기하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0945","en":"sign in","definition":"to write your name or information to show you have arrived at a place, such as a hotel, office, or event. Synonym: 'check in'","ko":"호텔, 사무실, 행사장 등 도착했음을 표시하기 위해 이름이나 정보를 작성하는 것. 동의어: '체크인하다'","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0946","en":"sign on","definition":"to officially agree to become part of a team, group, or activity, usually by signing a form or contract.","ko":"보통 양식이나 계약서에 서명함으로써 공식적으로 팀, 그룹 또는 활동의 일원이 되기로 동의하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0947","en":"sign over","definition":"To officially give ownership or legal rights of something, like property or a business, to someone else by signing documents.","ko":"문서에 서명하여 재산이나 사업과 같은 소유권이나 법적 권리를 공식적으로 다른 사람에게 넘기는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0948","en":"sign up","definition":"to officially put your name on a list to join or participate in something, such as a course, event, or membership.","ko":"공식적으로 명단에 이름을 올려 수업, 행사 또는 멤버십과 같은 것에 참여하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0949","en":"sing along","definition":"to sing at the same time as music or with another person, usually matching the words and tune.","ko":"음악이나 다른 사람과 동시에, 보통 가사와 멜로디에 맞춰 노래하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0950","en":"single out","definition":"to choose one person or thing from a group for special attention, often in a way that is different from others","ko":"그룹에서 한 사람이나 사물을 특별히 주목하여 선택하다. 종종 다른 사람들과는 다르게 함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0951","en":"sink in","definition":"If an idea or information sinks in, it means you start to really understand or realize it.","ko":"어떤 생각이나 정보가 ‘이해되다’는 것은, 그것을 진짜로 이해하거나 깨닫기 시작한다는 뜻입니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0952","en":"siphon off","definition":"To take something, usually liquid or money, away from one place or use, often in a secret or dishonest way.","ko":"보통 액체나 돈을 한 곳이나 용도에서 빼내가는 것, 보통 비밀스럽거나 부정직한 방법으로 사용함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0953","en":"sit by","definition":"to watch something happen without trying to stop it; to not take action when you could help or change the situation.","ko":"무언가가 일어나도 막으려 하지 않고, 도울 수 있음에도 아무런 행동을 취하지 않는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0954","en":"sit down","definition":"to move from a standing position to a sitting position, usually on a chair or another surface","ko":"일어서 있는 자세에서 앉는 자세로 이동하는 것, 보통 의자나 다른 표면에 앉는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0955","en":"sit in","definition":"to attend a meeting, class, or event as an observer or guest, not as a main participant","ko":"회의, 수업, 행사 등에 주 참가자가 아닌 관찰자나 손님으로 참석하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0956","en":"sit out","definition":"To not take part in an activity or event, usually so you can rest or watch instead.","ko":"보통 쉬거나 지켜보기 위해 어떤 활동이나 행사에 참여하지 않다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0957","en":"sit up","definition":"to move from lying down to a sitting position, or to straighten your back and sit with good posture","ko":"누운 자세에서 앉는 자세로 움직이거나, 등을 곧게 펴고 바른 자세로 앉다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0958","en":"size up","definition":"To carefully look at a person or situation in order to understand or judge them.","ko":"사람이나 상황을 이해하거나 판단하기 위해 신중하게 관찰하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0959","en":"skate over","definition":"To avoid talking about or dealing with something in detail, usually because it's difficult or uncomfortable.","ko":"어렵거나 불편해서 어떤 내용을 자세하게 언급하지 않고 대충 넘어가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0960","en":"skim off","definition":"To remove something from the surface or top of a liquid, or to take a portion for yourself in a way that is not always honest.","ko":"액체의 표면이나 윗부분에서 무언가를 제거하거나, 항상 정직하지 않은 방식으로 자기 몫을 챙기는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0961","en":"skim over","definition":"to quickly look through written information without reading every word, usually to get the general idea or find important points.","ko":"어떤 것의 표면을 거의 건드리지 않으면서 그 위나 표면을 빠르고 부드럽게 스치듯 움직이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0962","en":"skimp over","definition":"To talk about or deal with something too quickly or not give it enough attention, often to avoid discussing it fully.","ko":"무엇인가를 너무 빠르게 이야기하거나 충분한 관심을 기울이지 않고 다루는 것. 보통 완전한 논의를 피하려고 할 때 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0963","en":"skip over","definition":"to pass by or ignore something or someone, especially when going through a list or a group of things; to not pay attention to or select something.","ko":"특히 목록이나 그룹을 살펴볼 때 무언가나 누군가를 건너뛰거나 무시하다; 주의를 기울이지 않거나 선택하지 않다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0964","en":"slap on","definition":"to put something on quickly and without much care, usually something like clothes, make-up, or cream","ko":"옷, 화장품, 크림 등을 빠르고 대충 바르거나 입다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0965","en":"sleep in","definition":"to stay in bed and wake up later than usual in the morning","ko":"아침에 평소보다 늦게 일어나 침대에 더 오래 머무는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0966","en":"sleep off","definition":"to sleep in order to feel better after having too much alcohol, food, or feeling very tired","ko":"술, 음식 등을 과하게 먹거나 매우 피곤할 때 잠을 자서 회복하는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0967","en":"sleep on","definition":"to wait until the next day to think more carefully before making a decision","ko":"더 신중하게 결정하기 위해 다음 날까지 기다리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0968","en":"sleep over","definition":"To spend the night at someone else's house, usually as a guest.","ko":"보통 손님으로서 다른 사람의 집에서 하룻밤을 보내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0969","en":"slice up","definition":"to cut something into thin pieces or slices, usually with a knife.","ko":"무언가를 얇은 조각이나 슬라이스로 자르다, 보통 칼로.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0970","en":"slick down","definition":"to make hair smooth and flat, usually by using water or a styling product","ko":"물을 묻히거나 스타일링 제품을 사용하여 머리카락을 매끈하고 평평하게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0971","en":"slick up","definition":"to make someone or yourself look more neat, tidy, or stylish","ko":"누구나 자신을 더 단정하고 깔끔하며 멋지게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0972","en":"slide down","definition":"to move smoothly down the surface of something, like a pole or a banister, usually by sitting or holding on and letting gravity take you down","ko":"폴대나 난간과 같은 표면을 앉거나 잡고 중력에 몸을 맡겨 부드럽게 아래로 이동하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0973","en":"slim down","definition":"to become thinner by losing weight, usually by eating healthier or exercising","ko":"주로 더 건강하게 먹거나 운동하여 살이 빠져 날씬해지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0974","en":"slip away","definition":"to go by or disappear quickly, often without being noticed","ko":"알지 못하는 사이에 빠르게 지나가거나 사라지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0975","en":"slip in","definition":"to quickly and smoothly put on or enter something, such as clothes or a place, often without much effort","ko":"옷이나 장소 등에 빠르고 부드럽게, 큰 노력 없이 입거나 들어가다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0976","en":"slip off","definition":"To leave a place quietly or secretly, so other people do not notice.","ko":"다른 사람들이 눈치채지 못하게 조용히 또는 몰래 자리를 뜨다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0977","en":"slip on","definition":"to quickly put on an item of clothing, usually without much effort or care","ko":"옷을 대충 또는 빠르게 입다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0978","en":"slip up","definition":"to make a small mistake, often by accident","ko":"작은 실수를 하다, 종종 실수로","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0979","en":"slow down","definition":"to move, do something, or become less active at a lower speed or pace; to make something slower.","ko":"움직임이나 활동이 느려지거나 덜 활발해지다; 무엇인가를 느리게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0980","en":"smash up","definition":"to break something into pieces so it is badly damaged or destroyed, often violently.","ko":"무언가를 산산조각 내거나 심하게 부수거나 파괴하는 것, 종종 난폭하게.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0981","en":"smell out","definition":"To discover or find someone or something by using your sense of smell, often used about dogs or animals.","ko":"냄새를 맡아서 사람이나 사물을 찾아내다. 주로 개나 동물에 대해 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0982","en":"smell up","definition":"to make a place have a strong, usually unpleasant smell.","ko":"장소에 강하고 대개 불쾌한 냄새가 나게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0983","en":"smoke out","definition":"To force someone or something to leave a hiding place, usually by using smoke or another method that makes it uncomfortable to stay.","ko":"연기 등 불편한 수단을 사용해 누군가 또는 무언가를 은신처에서 나오도록 강요하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0984","en":"smooth out","definition":"to make something flat, even, or free of wrinkles or lumps by pressing or spreading it.","ko":"무언가를 누르거나 펼쳐서 평평하거나 주름, 혹이 없게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0985","en":"smooth over","definition":"To try to make a problem, argument, or bad situation seem less serious or easier to accept.","ko":"문제나 다툼, 나쁜 상황을 덜 심각하게 보이거나 더 받아들이기 쉽게 하려고 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0986","en":"snap at","definition":"to speak to someone suddenly and angrily, often because you are annoyed or stressed; can also mean to try to bite quickly.","ko":"누군가에게 갑자기 화가 난 듯 말하다. 짜증나거나 스트레스 받을 때 흔히 나타남. 또는 빠르게 물려고 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0987","en":"snap off","definition":"to quickly break a small, hard, or brittle part from something, usually with a sharp movement","ko":"보통 빠른 동작으로, 무언가의 작고 단단하거나 부서지기 쉬운 부분을 똑 부러뜨리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0988","en":"snap up","definition":"to buy or take something quickly because it is in demand or a good deal.","ko":"인기 있거나 좋은 거래라서 재빨리 사거나 차지하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0989","en":"snatch up","definition":"To quickly grab or take something, especially before someone else can get it.","ko":"다른 누군가가 차지하기 전에 재빨리 무엇인가를 잡거나 가져가는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0990","en":"sneak away","definition":"to leave a place or a group quietly and secretly, so that other people don't notice.","ko":"다른 사람들이 알아차리지 못하게 조용하고 은밀하게 장소나 모임을 떠나다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0991","en":"sneak in","definition":"To enter a place quietly and secretly, so that no one sees or hears you.","ko":"아무에게도 들키거나 보이지 않도록 조용히 비밀리에 장소에 들어가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0992","en":"sniff out","definition":"To find or discover something or someone, especially by using your sense of smell or by being very attentive.","ko":"특히 후각을 사용하거나 매우 주의 깊게 하여 무언가나 누군가를 찾아내거나 발견하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0993","en":"snip off","definition":"to cut something off by using scissors or a similar tool.","ko":"가위나 비슷한 도구로 무언가를 잘라내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0994","en":"snuff out","definition":"To stop a flame from burning, usually by putting something over it to remove the air.","ko":"보통 공기를 차단하기 위해 무언가를 덮어서 불꽃을 끄다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0995","en":"soak through","definition":"When a liquid passes through something and makes it completely wet.","ko":"액체가 무언가를 통과하여 완전히 젖게 만들 때.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0996","en":"soak up","definition":"To absorb something, like a liquid, experience, or information, either physically or in a figurative way.","ko":"액체나 경험, 정보 등을 물리적 또는 비유적으로 흡수하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0997","en":"sober up","definition":"to become less drunk or help someone become less drunk, usually after drinking too much alcohol.","ko":"술에 덜 취하게 되거나, 누군가가 덜 취하도록 도와주는 것. 보통 술을 많이 마신 후에 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0998","en":"sort out","definition":"to organize, fix, or solve a problem or situation","ko":"누군가가 문제를 일으키면, 특히 그들과 대화를 하거나 훈육하여 처리하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_0999","en":"sound off","definition":"to speak loudly and forcefully about your opinions, often complaining or criticizing something","ko":"자신의 의견을 시끄럽고 강하게 말하다, 종종 불평하거나 비판하는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1000","en":"sound out","definition":"To say each letter or part of a word slowly to help you read or understand it.","ko":"무엇에 대해 어떻게 생각하거나 느끼는지 알기 위해 누군가에게 질문하다 (주로 결정을 내리기 전에)","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1001","en":"spark off","definition":"to cause something to start suddenly, often a reaction, argument, or event","ko":"무언가를 갑자기 일으키다. 종종 반응이나 논쟁, 사건 등을 가리킴","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1002","en":"speak for","definition":"to express someone else's opinion or to represent someone or something by speaking on their behalf.","ko":"다른 사람의 의견을 표현하거나 누구 또는 무엇을 대신하여 말하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1003","en":"speak up","definition":"to express your opinions or concerns about someone or something clearly and with confidence, especially when others are afraid to do so","ko":"사람들이 더 잘 들을 수 있도록 더 크게 말하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1004","en":"speed up","definition":"to make someone or something go faster or happen more quickly","ko":"누군가 또는 무언가를 더 빠르게 하거나 일이 더 빨리 일어나게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1005","en":"spell out","definition":"to explain something clearly and in detail, so it is easy to understand","ko":"무언가를 명확하고 자세하게 설명하다, 쉽게 이해할 수 있도록","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1006","en":"spice up","definition":"To make something more exciting, lively, or interesting.","ko":"무언가를 더 신나고, 활기차고, 흥미롭게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1007","en":"spill out","definition":"to move out of a place in large numbers, especially when the space is too small; to flow or come out all at once.","ko":"특히 공간이 너무 작을 때 한 장소에서 많은 수가 한꺼번에 나오거나, 한 번에 흘러나오는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1008","en":"spill over","definition":"To go beyond the limits of a space, place, or situation and enter another. When a space is too full, what is in it moves into the next area.","ko":"공간, 장소 또는 상황의 한계를 넘어 다른 곳으로 넘쳐 흐르는 것. 공간이 너무 가득 차면 안의 것이 옆 공간으로 이동함.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1009","en":"spit out","definition":"to say something suddenly or angrily, often when you don't want to keep it inside any longer","ko":"삼키고 싶지 않아서 입에서 무언가를 밀어내는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1010","en":"splash around","definition":"To play or move in water, making it go everywhere.","ko":"물에서 놀거나 움직이면서 물을 여기저기 튀기다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1011","en":"split up","definition":"to separate people or things into different groups or parts; also to end a romantic relationship.","ko":"사람이나 사물을 다른 그룹이나 부분으로 나누다; 연인 관계를 끝내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1012","en":"spread out","definition":"to move things or people so they cover a larger area, or to move apart from each other","ko":"사물이나 사람을 더 넓은 공간에 펼치거나, 서로 떨어져 움직이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1013","en":"spread over","definition":"to cover the surface of something with another substance or to distribute something across an area or period of time.","ko":"다른 물질로 어떤 표면을 덮거나, 어떤 것을 일정한 구역이나 기간에 걸쳐 분산시키는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1014","en":"spring up","definition":"to appear or start to exist very quickly and suddenly, often unexpectedly.","ko":"매우 빠르고 갑자기, 종종 예상하지 못하게 나타나거나 존재하기 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1015","en":"square up","definition":"To pay what you owe or settle a bill or debt with someone.","ko":"빚이나 요금 등을 누군가에게 정산하다, 갚다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1016","en":"squeak by","definition":"to just barely succeed, survive, or manage with only the minimum necessary resources or effort","ko":"최소한의 자원이나 노력으로 간신히 성공하거나 살아남거나 버티다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1017","en":"squeeze out","definition":"To get something out of a container or place by pressing it tightly.","ko":"단단히 눌러 용기나 장소에서 무언가를 꺼내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1018","en":"stack up","definition":"to arrange things in a neat pile, one on top of another","ko":"물건을 하나씩 차곡차곡 쌓다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1019","en":"stamp out","definition":"to completely end or eliminate something, especially something bad, often using strong actions","ko":"나쁜 것을 완전히 끝내거나 없애다, 특히 강력한 조치를 사용하여","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1020","en":"stand by","definition":"to be ready and waiting for someone or something, especially in case you are needed or something is about to happen","ko":"특히 어려운 상황에서 누군가와 함께 있고 그들을 지지하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1021","en":"stand for","definition":"to accept or allow a particular type of behavior or situation, usually something you think is wrong or unpleasant","ko":"단어, 글자 또는 기호가 무엇을 의미할 때, 그것은 그 대상을 나타내거나 줄임말임을 뜻합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1022","en":"stand in","definition":"to take someone's place for a short time when they cannot do something themselves","ko":"누군가가 스스로 할 수 없을 때 잠시 그 사람을 대신하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1023","en":"stand out","definition":"to be very easy to see or notice because something is different or special","ko":"무언가가 다르거나 특별해서 눈에 잘 띄다, 두드러지게 보이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1024","en":"stand up","definition":"to make someone or something go from a sitting or lying position to a vertical or upright position","ko":"누군가가 도전하거나 비판할 때 자신이나 신념을 옹호하다; 압력, 반대 또는 어려움에 굴복하지 않다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1025","en":"stare down","definition":"To look directly at someone or something for so long and so confidently that they feel they have to look away.","ko":"누군가나 무언가를 자신감 있게 오래 쳐다봐서 결국 상대가 시선을 피하게 하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1026","en":"start out","definition":"to begin doing something, especially something new, or to begin a journey or career.","ko":"무엇인가를 (특히 새로운 것을) 시작하거나 여정이나 경력을 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1027","en":"start up","definition":"to make something begin working, especially a machine, engine, or computer.","ko":"특히 기계, 엔진, 컴퓨터 등을 작동시키기 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1028","en":"stash away","definition":"to hide or store something in a safe or secret place, especially for future use.","ko":"미래를 위해서 특히 무언가를 안전하거나 비밀스러운 곳에 숨기거나 보관하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1029","en":"stay away","definition":"To avoid someone or something, or not go near a person or place.","ko":"누군가나 무언가를 피하거나 사람이나 장소에 가까이 가지 않는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1030","en":"stay off","definition":"to not go on, touch, or use something; to avoid being on a place or using something.","ko":"어떤 것에 가지 않거나, 만지거나, 사용하지 않는 것; 어떤 장소에 있거나 무엇을 사용하는 것을 피하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1031","en":"stay on","definition":"to continue to be in a place or position after others have left or after you were expected to leave","ko":"다른 사람들이 떠난 후나 떠나야 할 시기 후에도 그 장소나 위치에 계속 남아 있는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1032","en":"stay over","definition":"to spend the night at someone else's place instead of going home.","ko":"집에 가지 않고 남의 집에서 하룻밤을 보내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1033","en":"stay up","definition":"to not go to sleep at your usual time; to remain awake longer than normal, especially at night","ko":"평소보다 늦게까지 자지 않고 깨어 있는 것; 특히 밤에 평소보다 오래 깨어 있는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1034","en":"step down","definition":"to leave an important job or official position, usually so someone else can take over","ko":"중요한 일자리나 공식 직책에서 물러나 보통 다른 사람이 맡을 수 있도록 하는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1035","en":"step in","definition":"to become involved in a situation, especially to help, solve a problem, or stop something bad from happening","ko":"상황에 개입하다, 특히 도와주거나, 문제를 해결하거나, 나쁜 일이 발생하는 것을 막기 위해","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1036","en":"step up","definition":"to increase the speed, amount, or effort of something; to do something more quickly or with greater intensity.","ko":"특히 중요한 일이 필요할 때 더 많은 책임을 지거나 행동에 나서다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1037","en":"stick about","definition":"to stay in a place and not leave, usually because you might be needed or something is expected to happen soon.","ko":"필요할 수도 있거나 곧 무언가가 일어날 것 같아서, 한 장소에 머무르며 떠나지 않는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1038","en":"stick by","definition":"To stay loyal and continue to support someone or something, especially in difficult times.","ko":"특히 어려운 시기에 누군가 혹은 무언가에게 충실하며 계속해서 지지하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1039","en":"stick out","definition":"To continue dealing with an unpleasant or difficult situation until it is finished, instead of quitting.","ko":"아주 눈에 띄거나 무언가의 표면에서 튀어나오다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1040","en":"stick to","definition":"To continue doing something or to keep using the same thing, without changing it.","ko":"무언가를 바꾸지 않고 계속해서 하거나 같은 것을 사용하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1041","en":"stick up","definition":"to support or defend someone or something, especially when they are being criticized or treated unfairly. Similar to 'stand up for'.","ko":"특히 은행이나 가게와 같은 공공 장소에서 무기를 들고 누군가를 위협하여 훔치는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1042","en":"stick with","definition":"To continue doing, using, or supporting something, and not change it.","ko":"무언가를 계속 하거나, 사용하거나, 지지하며 바꾸지 않는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1043","en":"stink out","definition":"To make a place smell very bad, usually so much that people don't want to stay there.","ko":"어떤 장소를 너무 고약하게 만들어 사람들이 머무르고 싶지 않게 하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1044","en":"stir up","definition":"To cause problems, strong emotions, or trouble, often by making people feel angry or excited.","ko":"사람들을 화나게 하거나 흥분하게 만들어 문제, 강한 감정, 혹은 소란을 일으키다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1045","en":"stop up","definition":"to fill or block a hole or opening so that nothing can pass through","ko":"아무것도 통과하지 못하도록 구멍이나 틈을 채우거나 막다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1046","en":"straighten out","definition":"to fix a problem or make something clear and organized","ko":"문제를 해결하거나 무언가를 명확하고 정리되게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1047","en":"straighten up","definition":"to make yourself or something stand or sit in a more upright, straight position","ko":"자신이나 무언가를 더 곧고 똑바로 된 자세로 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1048","en":"stretch along","definition":"to extend or spread over a long area next to something","ko":"무엇을 따라 길게 뻗어 있다, 긴 구역에 걸쳐 펼쳐지다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1049","en":"stretch out","definition":"to make something longer or to lie down with your body extended","ko":"무언가를 더 길게 만들거나 몸을 쭉 펴고 눕다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1050","en":"strike down","definition":"To cause someone to become very ill or to die suddenly, often due to illness or an unexpected event.","ko":"법, 규칙, 결정이 불법 또는 잘못되었다고 판단되어 공식적으로 종료되거나 폐지되는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1051","en":"strike off","definition":"To officially remove someone or something from a list, group, or record, often as a punishment or because they no longer qualify.","ko":"누군가나 무언가를 벌이나 자격 상실로 인해 공식적으로 명단, 그룹, 기록에서 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1052","en":"strike out","definition":"to fail or not succeed, especially after trying to do something","ko":"특히 혼자서, 다른 사람의 도움 없이 독립적으로 무언가를 시작하다 (일, 생활, 어디론가 가는 것 등).","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1053","en":"strike up","definition":"to begin something, such as a conversation, friendship, or music, often in a social situation.","ko":"대화, 우정, 음악 등 어떤 것을 시작하다. 주로 사회적 상황에서 쓰임.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1054","en":"strip down","definition":"To strongly criticize or scold someone, usually because they did something wrong.","ko":"의학적 이유나 준비를 위해 모든 또는 대부분의 옷을 벗다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1055","en":"subscribe to","definition":"to sign up to regularly receive or pay for something, like a magazine, a service, or a channel","ko":"정기적으로 잡지·서비스·채널 등을 받거나 이용하기 위해 가입하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1056","en":"suck in","definition":"To get involved in an unpleasant or difficult situation, often without wanting to.","ko":"빨아들이는 힘을 이용해 무언가를 입이나 몸 안으로 들이마시는 것(숨 쉬거나 마시는 것처럼).","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1057","en":"suck up","definition":"To say or do nice things to someone, usually someone in authority, because you want them to like you or give you something.","ko":"진공청소기가 먼지나 액체를 빨아들이듯, 흡입력을 사용하여 무언가를 공간이나 용기 안으로 빨아들이는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1058","en":"sum up","definition":"To find the total amount by adding numbers or amounts together. Synonym: 'add up'.","ko":"무엇에 대한 주요 내용이나 가장 중요한 정보를 간략히 말하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1059","en":"sweat off","definition":"To lose weight or remove something from your body by sweating, usually through exercise or being in a hot place.","ko":"운동을 하거나 뜨거운 곳에 있어 땀을 흘려 체중을 줄이거나 몸에서 무언가를 배출하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1060","en":"sweep aside","definition":"To quickly move someone or something out of the way, often with little concern.","ko":"누군가 또는 어떤 것을 신속하게 옆으로 치우다, 종종 별로 신경 쓰지 않고.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1061","en":"sweep away","definition":"To make someone feel very strong emotions, especially excitement or love, so that they forget everything else.","ko":"누군가에게 매우 강한 감정, 특히 흥분이나 사랑을 느끼게 하여 모든 것을 잊게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1062","en":"swell up","definition":"To become larger than normal, often because of injury, illness, or a reaction to something.","ko":"부상, 질병 또는 반응으로 인해 평소보다 더 커지다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1063","en":"swing out","definition":"to move something outward in an arc or wide motion, usually by moving your arm or hand away from your body.","ko":"팔이나 손을 몸에서 멀리 움직여 무언가를 활 모양으로 또는 넓게 밖으로 움직이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1064","en":"switch off","definition":"to stop a machine or device from working by turning a button or switch. A more common way to say this is 'turn off'.","ko":"버튼이나 스위치를 눌러 기계나 장치의 작동을 멈추는 것. 더 일반적으로는 'turn off'를 사용합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1065","en":"switch on","definition":"To make a machine or electronic device start working by pressing a button or turning a switch.","ko":"버튼을 누르거나 스위치를 켜서 기계나 전자기기를 작동시키다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1066","en":"switch over","definition":"to change from one thing to another, especially from using or doing one thing to using or doing something different.","ko":"특히 한 가지에서 다른 것으로 바꾸거나, 사용하거나 하던 것을 다르게 바꾸다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1067","en":"tag along","definition":"To go somewhere with someone when you haven't been specifically invited, often just to be with them.","ko":"특별히 초대받지 않았지만 누군가와 함께 가는 것, 주로 그들과 함께 있기 위해.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1068","en":"take away","definition":"To buy prepared food or drink from a restaurant or café and take it with you to eat somewhere else. This is similar to 'take out.'","ko":"누군가 또는 무언가를 장소나 상황에서 제거하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1069","en":"take down","definition":"to defeat or humiliate someone, especially by showing that they are not as important or skilled as they think","ko":"특히 벽이나 걸려 있는 곳에서 무언가를 내리거나 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1070","en":"take in","definition":"to understand or remember new information; to absorb knowledge","ko":"특히 지불이나 행사에서 돈을 모으거나 받다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1071","en":"take off","definition":"to leave the ground and begin to fly; to start flying","ko":"무언가(특히 옷이나 장소·전체에서 물건)을 벗거나 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1072","en":"take on","definition":"to hire or give someone a job; to employ someone.","ko":"특히 대회, 싸움, 경기 등에서 누구나 무엇에 맞서거나 도전하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1073","en":"take out","definition":"to remove something from a place or container.","ko":"누군가를 식사나 오락을 위해 (특히 데이트로) 초대하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1074","en":"take over","definition":"to start doing something that someone else was doing, or to begin to be in charge of something","ko":"다른 사람이 하던 일을 시작하거나, 무언가를 책임지게 되다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1075","en":"take to","definition":"to start doing something regularly, especially as a habit or because you enjoy it","ko":"습관적으로 또는 즐겨서 무언가를 규칙적으로 시작하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1076","en":"take up","definition":"to use or fill a particular amount of space, time, or attention.","ko":"새로운 것(취미, 활동, 일 등)을 시작하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1077","en":"talk about","definition":"to say things about someone or something; to have a conversation that includes someone or something as the subject","ko":"누군가 또는 무언가에 대해 이야기하다; 누군가 또는 무언가를 주제로 대화하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1078","en":"talk down","definition":"to speak to someone as if they are not as smart or capable as you are; to speak in a condescending way.","ko":"상대방이 덜 똑똑하거나 능력이 없는 것처럼 내려다보며 말하다; 거만하게 말하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1079","en":"talk into","definition":"to persuade someone to do something, often by giving them good reasons or encouragement","ko":"누군가에게 좋은 이유나 격려로 무엇인가를 하도록 설득하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1080","en":"talk out of","definition":"To persuade someone not to do something or to change their mind about doing something.","ko":"누군가가 어떤 일을 하지 않도록 설득하거나, 생각을 바꾸도록 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1081","en":"talk over","definition":"to discuss something carefully, especially in order to make a decision.","ko":"특히 결정을 내리기 위해 어떤 것을 신중하게 상의하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1082","en":"tangle with","definition":"to get into a fight, argument, or complicated situation with someone or something","ko":"누구나 무엇과 싸움, 논쟁 또는 복잡한 상황에 얽히다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1083","en":"tap out","definition":"to hit or touch something lightly several times, especially with your fingers, to create a rhythm or pattern.","ko":"특히 손가락으로 여러 번 가볍게 두드려 리듬이나 패턴을 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1084","en":"team up","definition":"to work together with someone to achieve a common goal","ko":"공통의 목표를 달성하기 위해 누군가와 함께 일하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1085","en":"tear away","definition":"To pull something away quickly and forcefully, often with effort.","ko":"무언가를 힘을 들여 빠르고 강하게 떼어내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1086","en":"tear down","definition":"To completely destroy or remove a building or structure.","ko":"건물이나 구조물을 완전히 부수거나 철거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1087","en":"tear into","definition":"to criticize someone very harshly or aggressively","ko":"누군가를 매우 거칠고 공격적으로 비판하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1088","en":"tear up","definition":"to break something into small pieces by pulling it apart, usually with your hands.","ko":"무엇인가를 손으로 잡아 찢어서 작은 조각으로 만드는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1089","en":"tell off","definition":"To speak angrily to someone because they have done something wrong.","ko":"누군가 잘못을 해서 화를 내며 말하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1090","en":"tell on","definition":"to inform someone in authority about another person's bad or wrong behavior, often to get them in trouble","ko":"다른 사람의 나쁜 행동을 권위자에게 알리다, 종종 그 사람이 곤란하게 하려고","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1091","en":"tense up","definition":"to become nervous or have your muscles become tight because you are worried or anxious","ko":"걱정하거나 불안해서 신경이 예민해지거나 근육이 경직되는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1092","en":"thin out","definition":"to make something less crowded or less thick by removing some parts or people","ko":"어떤 부분이나 사람을 제거하여 더 덜 붐비거나 더 덜 두껍게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1093","en":"think of","definition":"to remember or have someone or something in your mind; to consider someone or something.","ko":"누군가 또는 무언가를 기억하거나 마음에 두다; 누군가나 무언가를 고려하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1094","en":"think out","definition":"to carefully plan or consider all the details of something before making a decision or taking action","ko":"결정을 내리거나 행동하기 전에 모든 세부사항을 신중하게 계획하거나 고려하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1095","en":"think over","definition":"to spend some time considering something carefully before making a decision","ko":"결정을 내리기 전에 어떤 것을 신중하게 고려하는 데 시간을 보내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1096","en":"think up","definition":"to invent or imagine something, especially a new idea, excuse, or plan","ko":"특히 새로운 아이디어, 변명, 계획 등을 만들어내거나 상상하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1097","en":"thrash about","definition":"to move your body wildly and uncontrollably, often because you are upset, scared, or in pain.","ko":"당황하거나 무섭거나 아프기 때문에 몸을 격렬하고 통제 없이 움직이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1098","en":"throw away","definition":"To get rid of something that you do not want or need anymore by putting it in the trash.","ko":"더 이상 원하지 않거나 필요 없는 것을 쓰레기통에 버려 없애다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1099","en":"throw off","definition":"To get rid of an illness by recovering from it.","ko":"병을 회복하여 없애다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1100","en":"throw out","definition":"to make someone leave a place, such as a home, building, or event, often because they did something wrong","ko":"누군가가 잘못을 해서 집, 건물, 행사장 등에서 내보내는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1101","en":"throw up","definition":"To bring food or liquid out of your stomach and through your mouth, usually because you are sick. Synonym: 'vomit'.","ko":"보통 아플 때 음식이나 액체를 위에서 입으로 토하다. 동의어: '토하다'.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1102","en":"tick off","definition":"To put a mark (✓) next to something on a list to show it has been checked or completed. It is similar to 'check off'.","ko":"리스트에서 확인하거나 완료했음을 표시하기 위해 (✓) 표시를 하는 것. '체크하다'와 유사.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1103","en":"tidy up","definition":"to make a place or something clean and organized by putting things in their proper place","ko":"어떤 장소나 물건을 정리 정돈하여 깨끗하게 만드는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1104","en":"tie down","definition":"To limit someone's freedom or prevent them from doing what they want.","ko":"누군가의 자유를 제한하거나 원하는 것을 하지 못하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1105","en":"tie in","definition":"to be connected or go well together with something else","ko":"다른 것과 연결되거나 잘 어울리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1106","en":"tie up","definition":"To keep someone or something so busy or occupied that they cannot do anything else.","ko":"누군가 또는 무언가가 움직이지 못하도록 밧줄이나 끈으로 단단히 묶다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1107","en":"time off","definition":"Time off means a period when you are not working or do not have to go to school, often to rest or take care of personal things.","ko":"\"time off\"는 보통 휴식이나 개인적인 일 때문에 일이나 학교를 쉬는 기간을 의미합니다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1108","en":"time out","definition":"To stop what you are doing and take a short break, especially to rest or calm down.","ko":"하고 있는 일을 멈추고 짧은 휴식을 취하다, 특히 쉬거나 진정하기 위해.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1109","en":"tip off","definition":"to secretly give someone a warning or information, usually about something bad or illegal that is going to happen","ko":"누군가에게 비밀리에 경고나 정보를 주다. 주로 나쁘거나 불법적인 일이 일어날 때 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1110","en":"tip over","definition":"To accidentally or purposely make someone or something fall onto its side or upside down.","ko":"누군가나 무언가를 실수로 또는 일부러 옆으로 넘어뜨리거나 뒤집다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1111","en":"tire out","definition":"to make someone very tired or exhausted","ko":"누군가를 매우 피곤하게 하다; 진이 빠지게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1112","en":"tone down","definition":"to make something less strong, less forceful, or less extreme; to make something gentler or more moderate","ko":"무엇인가를 덜 강하게, 덜 극단적으로 만들다; 더 부드럽거나 온건하게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1113","en":"tone up","definition":"to make your muscles firmer, stronger, and look better by doing exercise","ko":"운동을 통해 근육을 더 단단하고 강하게 만들어 보기 좋게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1114","en":"top off","definition":"to finish something in a special or memorable way, especially by adding a final touch or event","ko":"특별하거나 기억에 남는 방식으로 뭔가를 마무리하다, 특히 마지막 터치나 이벤트를 추가함으로써","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1115","en":"toss away","definition":"To get rid of something or someone by throwing them away because you don't want or need them.","ko":"더 이상 원하지 않거나 필요하지 않아서 무언가나 누군가를 버리는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1116","en":"toss in","definition":"To quickly add or include something, often casually or without much preparation.","ko":"무언가를 빠르게 추가하거나 흔히 즉흥적으로 포함시키는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1117","en":"touch on","definition":"to mention or briefly talk about a subject in speech or writing","ko":"연설이나 글에서 어떤 주제를 언급하거나 간단히 이야기하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1118","en":"touch up","definition":"to make small changes or improvements to something, usually to improve its appearance or fix minor problems","ko":"주로 외관을 개선하거나 작은 문제를 고치기 위해 무언가에 약간의 수정이나 개선을 하는 것","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1119","en":"toy with","definition":"to think about or consider something casually, without making a serious decision","ko":"심각하게 결정하지 않고 가볍게 생각하거나 고려하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1120","en":"track down","definition":"to find someone or something after searching for them, especially when it is difficult.","ko":"특히 어렵게 누군가나 무언가를 찾아내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1121","en":"travel along","definition":"to move from one place to another by following a specific road, path, or route","ko":"특정한 도로, 길, 경로를 따라 이동하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1122","en":"trigger off","definition":"to cause something to start suddenly, usually a series of events or a reaction.","ko":"일련의 사건이나 반응과 같이 어떤 일의 갑작스러운 시작을 유발하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1123","en":"trim down","definition":"to make something smaller or less by removing extra parts; to reduce the size or amount of something","ko":"불필요한 부분을 제거하여 무언가를 더 작거나 덜하게 만들다; 크기나 양을 줄이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1124","en":"trip up","definition":"To make someone stumble or fall by catching their foot, or to make someone make a mistake.","ko":"누군가의 발을 걸어서 넘어지게 하거나, 실수를 하게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1125","en":"try for","definition":"to attempt to achieve or get something, usually a prize, award, or position.","ko":"보통 상, 상장 또는 직위를 얻으려고 시도하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1126","en":"try on","definition":"to put on a piece of clothing to see if it fits or looks good before you buy or wear it","ko":"옷을 입어보고 맞거나 어울리는지 확인하다 (구입이나 착용 전에)","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1127","en":"try out","definition":"to use or do something to see if you like it or if it works well.","ko":"팀, 그룹, 쇼의 일원이 되기 위해 경쟁하거나 오디션을 보다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1128","en":"tuck in","definition":"To start eating food with enthusiasm, especially when you are hungry. Often used informally at mealtimes.","ko":"특히 배가 고플 때, 열정을 가지고 식사를 시작하다. 식사 시간에 비공식적으로 자주 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1129","en":"tune in","definition":"To set your radio, TV, or other device to a particular channel or station so you can listen or watch a broadcast.","ko":"라디오, TV, 기타 기기를 특정 채널이나 방송국에 맞추어 방송을 듣거나 시청하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1130","en":"turn around","definition":"to change direction and go back the opposite way, or to make someone or something do this.","ko":"방향을 바꿔 반대 방향으로 가거나, 누군가나 무언가를 그렇게 하게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1131","en":"turn away","definition":"to move your body or face so that you are not looking at someone or something","ko":"누군가가 장소에 들어가거나 무언가에 참여하는 것을 거부하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1132","en":"turn down","definition":"to make something, like the volume or temperature, lower or less strong","ko":"볼륨이나 온도 등을 낮추거나 약하게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1133","en":"turn in","definition":"To give something to someone in authority or to the proper place, or to report someone to the authorities.","ko":"무언가를 권위자에게 제출하거나 올바른 장소에 내거나, 누군가를 당국에 신고하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1134","en":"turn off","definition":"to make someone lose interest in or dislike something or someone.","ko":"한 도로에서 나와 다른 도로로 들어서다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1135","en":"turn on","definition":"to make a device start working by switching a button or control; to start something such as a machine or light.","ko":"누군가가 처음으로 어떤 것에 관심을 갖게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1136","en":"turn out","definition":"to come together or gather for a public event or activity","ko":"특히 대량으로 무언가를 만들거나 생산하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1137","en":"turn over","definition":"to move someone or something so that the other side is facing up or visible","ko":"결정하기 전에 무언가를 신중하게 생각하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1138","en":"turn to","definition":"To start doing or using something, especially when you need help or a solution.","ko":"특히 도움이 필요하거나 해결책이 필요할 때 무언가를 시작하거나 사용하기 시작하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1139","en":"turn up","definition":"to discover or find something unexpectedly, especially during a search or investigation.","ko":"수색이나 조사 중에 예상치 못한 것을 발견하거나 찾아내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1140","en":"up to","definition":"To be doing or involved in something (often used to ask about someone's activities).","ko":"무엇을 하고 있거나 관여하고 있는 상태 (주로 누군가의 활동을 물을 때 사용됨).","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1141","en":"urge on","definition":"To strongly encourage someone to do something or to push them to take a particular action.","ko":"누군가가 어떤 행동을 하도록 강하게 격려하거나 특정 행동을 하도록 밀어붙이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1142","en":"use up","definition":"to finish or consume all of something so that nothing is left","ko":"어떤 것을 다 써버려서 아무 것도 남지 않게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1143","en":"usher in","definition":"to cause or introduce something new or important, especially when starting a new period, event, or change","ko":"특히 새로운 기간, 이벤트, 변화의 시작에 새로운 것이나 중요한 것을 가져오거나 도입하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1144","en":"usher out","definition":"to kindly guide or lead someone out of a place, such as a building or room","ko":"누군가를 친절하게 건물이나 방 밖으로 안내하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1145","en":"vomit up","definition":"to bring food or liquid from the stomach out through the mouth, usually because you are sick. 'Vomit up' means the same as 'throw up'.","ko":"보통 아플 때 위에서 음식이나 액체를 입을 통해 밖으로 토하다. 'Vomit up'은 'throw up'과 같은 뜻이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1146","en":"vote in","definition":"To choose someone or something for a position by voting in an official election.","ko":"공식 선거를 통해 누군가나 무언가를 직책에 선출하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1147","en":"vouch for","definition":"to say that you believe someone or something is good, honest, or true, usually based on your own experience","ko":"자신의 경험을 바탕으로 누군가 또는 무언가가 좋고, 정직하며, 진실하다고 말하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1148","en":"wait on","definition":"to serve someone, especially by bringing them food or drinks in a restaurant or at home","ko":"특히 식당이나 집에서 음식이나 음료를 가져다 주며 누군가를 시중들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1149","en":"wake up","definition":"to stop sleeping and become conscious; to make someone stop sleeping.","ko":"잠에서 깨고 의식이 돌아오다; 누군가를 깨우다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1150","en":"walk about","definition":"to walk or move around a place with no special purpose or direction, often just exploring or passing time. Synonym: 'walk around'.","ko":"특별한 목적이나 방향 없이 장소를 돌아다니며 걷거나 움직이다. 주로 탐방하거나 시간을 보내는 용도. 유의어: '돌아다니다'.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1151","en":"walk away","definition":"to leave a person, place, or situation by moving away, usually on foot, often because you don't want to deal with them or it anymore","ko":"사람이나 장소, 상황을 보통 도보로 떠나 더 이상 관여하고 싶지 않을 때 사용하는 표현","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1152","en":"walk off","definition":"to leave a place or situation suddenly and by walking, often without telling anyone","ko":"허락 없이 아무도 모르게 무언가를 가져가다, 보통 그것을 들고 떠남","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1153","en":"walk out","definition":"to leave a place or stop doing something because you are angry or do not agree with it; often used when people stop working as a form of protest (go on strike).","ko":"화나거나 동의하지 않아 장소를 떠나거나 무언가를 그만두는 것; 주로 사람들이 항의로 일손을 놓을 때(파업을 할 때) 사용됨.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1154","en":"walk over","definition":"to defeat someone or something very easily, without much effort","ko":"누구나 무엇을 아주 쉽게, 큰 노력 없이 이기다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1155","en":"wall in","definition":"To surround or enclose something or someone by building a wall around them.","ko":"벽을 세워서 누구나 무언가를 둘러싸거나 가두다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1156","en":"ward off","definition":"To prevent something unpleasant or dangerous from affecting you, especially by taking action.","ko":"특히 조치를 취하여 불쾌하거나 위험한 것이 자신에게 영향을 미치는 것을 막다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1157","en":"warm to","definition":"To gradually start liking someone or something, or to become more interested in them.","ko":"점차 누군가나 어떤 것에 호감이 생기거나 더 관심을 갖게 되다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1158","en":"warm up","definition":"to make a machine, device, or room reach a suitable or comfortable temperature before using it.","ko":"보통 데우거나 움직여서 무언가 혹은 누군가를 더 따뜻하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1159","en":"wash away","definition":"To remove dirt or something unwanted from a surface by using water.","ko":"물로 표면의 먼지나 원하지 않는 것을 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1160","en":"wash down","definition":"To drink something in order to help swallow food or medicine more easily.","ko":"음식이나 약을 더 쉽게 삼키기 위해 무언가를 마시다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1161","en":"wash off","definition":"To remove dirt, stains, or substances from the surface of something by using water or another liquid.","ko":"물이나 다른 액체를 사용하여 표면에 있는 먼지, 얼룩, 물질을 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1162","en":"wash out","definition":"to remove, damage, or destroy something by the force of water","ko":"누군가를 매우 피곤하게 만들다, 기운을 다 빼다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1163","en":"wash up","definition":"to clean your hands, face, or sometimes your body, usually with soap and water","ko":"(주로 영국 영어에서) 식사 후에 그릇, 컵, 커틀러리를 물과 비누로 닦다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1164","en":"watch out","definition":"to be careful and pay attention to possible danger or problems around you","ko":"주변의 위험이나 문제에 주의하고 조심하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1165","en":"watch over","definition":"to look after or protect someone or something to make sure they are safe","ko":"누군가나 무언가를 안전하게 지키거나 돌보다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1166","en":"water down","definition":"to make something weaker or less strong by adding water or by changing it, often to make it easier to accept or less powerful","ko":"물을 추가하거나 변경하여 어떤 것을 약하게 하거나 덜 강하게 만드는 것, 종종 더 쉽게 받아들이도록 하거나 덜 강력하게 하려는 목적","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1167","en":"wave off","definition":"To dismiss someone or something as not important, or to ignore them in a casual way.","ko":"누군가나 무언가를 중요하지 않다고 여기거나, 무심하게 무시하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1168","en":"wear away","definition":"to slowly remove or reduce something by long or repeated use, rubbing, or exposure.","ko":"오랜 사용, 반복된 마찰, 노출로 인해 무언가를 천천히 닳거나 줄어들게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1169","en":"wear down","definition":"To gradually make someone feel tired, weak, or less confident, or to make something become thinner or weaker by repeated use.","ko":"누군가를 점차 피곤하고 약하게 만들거나 자신감을 잃게 하거나, 반복적인 사용으로 무엇인가를 얇아지거나 약해지게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1170","en":"wear off","definition":"To gradually disappear or become less over time, especially after starting out strong.","ko":"시간이 지나면서 점차 사라지거나 약해지는 것, 특히 처음에는 강하게 시작할 때.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1171","en":"wear on","definition":"If time wears on, it seems to pass slowly, especially when you are waiting for something or feeling bored.","ko":"시간이 천천히 가는 것처럼 느껴질 때(특히 무언가를 기다리거나 지루할 때).","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1172","en":"wear out","definition":"To make someone very tired or to use something so much that it becomes unusable.","ko":"누군가를 매우 피곤하게 만들거나, 무언가를 너무 많이 사용해서 못 쓰게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1173","en":"weed out","definition":"To remove people or things that are not wanted or not good enough from a group.","ko":"원하지 않거나 충분히 좋지 않은 사람이나 사물을 그룹에서 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1174","en":"weigh down","definition":"to make someone feel worried, sad, or stressed because of problems or responsibilities","ko":"문제나 책임 때문에 누군가를 걱정하거나 슬프거나 스트레스를 받게 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1175","en":"weigh on","definition":"To make someone feel worried or anxious about something for a long time.","ko":"누군가를 오랫동안 걱정하거나 불안하게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1176","en":"weight down","definition":"To make something or someone heavy by putting weight on them, so they can't move or are harder to move.","ko":"무언가나 누군가를 움직이지 못하거나 더 어렵게 움직이도록 무게를 얹어 무겁게 만들다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1177","en":"well up","definition":"to suddenly start feeling a strong emotion, especially when you begin to cry or almost cry","ko":"갑자기 강한 감정이 북받쳐 오르다, 특히 울거나 울 뻔할 때","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1178","en":"wheel around","definition":"to turn quickly to face a different direction, especially by turning your body around","ko":"바퀴가 달린 것으로 누군가나 무언가(예: 휠체어나 카트)를 밀어서 이곳저곳으로 이동시키다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1179","en":"whip through","definition":"to finish something very quickly and easily, often without paying much attention to details","ko":"세부 사항에 신경 쓰지 않고 아주 빠르고 쉽게 무언가를 끝내다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1180","en":"whip up","definition":"to make or prepare something very quickly, especially food or something simple.","ko":"특히 음식이나 간단한 것을 아주 빠르게 만들거나 준비하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1181","en":"whirl around","definition":"to spin or turn quickly in a circle, or to make someone or something do this","ko":"빠르게 원을 그리며 돌다, 또는 누군가나 무언가를 그렇게 돌리다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1182","en":"whisk away","definition":"to take someone or something somewhere quickly and suddenly, often to a different place","ko":"누구나 무엇을 갑자기 빠르게 데려가거나 옮기다, 종종 다른 곳으로","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1183","en":"whisk by","definition":"to pass by someone or something very quickly and smoothly.","ko":"누구나 무엇 옆을 매우 빠르고 부드럽게 지나가다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1184","en":"whisk off","definition":"To quickly remove something from a surface or from someone, usually by brushing or wiping.","ko":"무엇인가를 표면이나 사람에게서 보통 털거나 닦아서 재빠르게 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1185","en":"whittle away","definition":"to gradually reduce or remove something, usually in small amounts","ko":"무언가를 서서히, 보통 적은 양씩 줄이거나 없애다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1186","en":"whizz along","definition":"To move very quickly, especially referring to vehicles or people traveling fast.","ko":"특히 차량이나 사람이 매우 빠르게 이동하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1187","en":"win over","definition":"to persuade someone to support you or to like your idea","ko":"누군가를 설득해서 내 편을 들게 하거나 내 생각을 좋아하게 만들다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1188","en":"wind up","definition":"to finish or bring something, such as an event or activity, to an end","ko":"시계와 같은 것을 작동시키기 위해 핸들이나 손잡이를 돌리다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1189","en":"wipe away","definition":"To remove something, such as liquid, dirt, or tears, by gently rubbing it with your hand or a cloth.","ko":"손이나 천으로 부드럽게 문질러 액체, 먼지, 눈물 등을 제거하는 것.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1190","en":"wipe out","definition":"to completely destroy or remove something so that nothing is left","ko":"아무 것도 남지 않도록 완전히 파괴하거나 제거하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1191","en":"wipe up","definition":"To clean a surface by removing liquid or dirt with a cloth or paper towel.","ko":"수건이나 종이 타월로 액체나 먼지를 닦아 표면을 깨끗하게 하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1192","en":"wolf down","definition":"To eat something very quickly and often greedily, as if you are very hungry.","ko":"매우 배고픈 것처럼 음식을 매우 빠르고 게걸스럽게 먹다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1193","en":"work at","definition":"To put effort and time into improving or achieving something, usually a skill, task, or goal.","ko":"보통 기술, 과제 또는 목표를 달성하거나 향상시키기 위해 노력과 시간을 들이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1194","en":"work off","definition":"To get rid of something, like stress, fat, or a debt, by doing physical activity or hard work.","ko":"운동이나 힘든 일을 통해 스트레스, 체지방, 빚 등을 해소하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1195","en":"work on","definition":"To spend time and effort trying to improve or complete something.","ko":"무엇인가를 향상시키거나 완성하려고 시간과 노력을 들이다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1196","en":"work out","definition":"to discover or understand the answer to a problem by thinking about it.","ko":"주로 헬스장이나 피트니스 루틴의 일부로 신체 운동을 하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1197","en":"work through","definition":"to deal with or solve something that is difficult or takes time by working step by step","ko":"어렵거나 시간이 오래 걸리는 일을 단계적으로 해결하거나 처리하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1198","en":"work up","definition":"to gradually prepare yourself to achieve or do something more difficult or challenging","ko":"더 어려운 일이나 도전에 점차 자신을 준비시키다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1199","en":"wrap up","definition":"To cover something or someone completely, usually with paper, cloth, or another material.","ko":"특히 과제나 행사를 끝내거나 완성하다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1200","en":"wring out","definition":"To remove extra liquid from something by twisting and squeezing it tightly.","ko":"무언가를 세게 비틀고 꽉 짜서 남은 물기를 제거하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1201","en":"write down","definition":"to put information on paper or in a notebook so you don't forget it","ko":"잊지 않으려고 정보를 종이나 노트에 적다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1202","en":"write in","definition":"to send a letter, email, or message to an organization or company, especially to give your opinion, ask a question, or request something.","ko":"자신의 의견을 말하거나, 질문하거나, 무언가를 요청하기 위해 조직이나 회사에 편지, 이메일, 메시지를 보내다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1203","en":"write off","definition":"to accept that something, especially money or an asset, cannot be recovered or used, usually because it has lost its value or cannot be collected","ko":"특히 돈이나 자산이 회수되거나 사용될 수 없음을 받아들이는 것, 보통 가치가 없거나 회수가 불가능하기 때문","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1204","en":"write on","definition":"to create a piece of writing that is about a particular person or subject.","ko":"특정 인물이나 주제에 대한 글을 쓰다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1205","en":"write out","definition":"to write something completely and clearly, especially so that it is easy to understand or official.","ko":"무엇인가를 완전히 그리고 명확하게 쓰다, 특히 이해하기 쉽거나 공식적으로 하기 위해.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1206","en":"write up","definition":"To create a detailed written version of something, such as notes, ideas, or reports. Usually, it means organizing information and putting it clearly into writing.","ko":"메모, 아이디어, 보고서 등을 자세히 문서로 작성하다. 보통 정보를 정리해서 명확하게 글로 옮기는 것을 의미한다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1207","en":"zero in","definition":"to pay very close attention to or focus specifically on a person or thing","ko":"사람이나 사물에 매우 집중하거나 특별히 주의를 기울이다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1208","en":"zip by","definition":"to move past someone or something very quickly","ko":"누군가나 무언가를 아주 빠르게 지나가다","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1209","en":"zip up","definition":"to close something, like a jacket or a bag, using a zipper.","ko":"재킷이나 가방과 같은 것을 지퍼로 잠그다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1210","en":"zoom along","definition":"To move very quickly in a vehicle, often making a lot of noise.","ko":"차량으로 매우 빠르게, 자주 큰 소음을 내며 이동하다.","cefr":"B2","type":"phrasal verb"},{"id":"phrasal-verb_1211","en":"zoom in","definition":"to make something appear closer or larger, especially with a camera or device, so you can see more details.","ko":"카메라나 장치를 사용해 무언가를 더 가까이 또는 크게 보여 더 많은 세부사항을 볼 수 있게 하다.","cefr":"B2","type":"phrasal verb"}];
